src/ui/style.css:
/* TheSevenSimulationRPG — 화면 목업 스타일
   팔레트는 형제 프로젝트(TheSevenRPG / TheSevenSimulation)와 공유 */

:root {
    /* Minigame art colors are independent of the surrounding monochrome UI. */
    --mg-ink: #172526;
    --mg-ink-rgb: 23, 37, 38;
    --mg-cream: #f7efd8;
    --mg-fog: #c4ccbd;
    --mg-line: #4a5d58;
    --mg-mint: #90ded1;
    --mg-sage: #b7d99b;
    --mg-honey: #eac48c;
    --mg-rose: #f2a29c;
    --mg-track: #394942;
    /* ── 표면 계단 [2026-09-14] ── 밝기 순 사다리 하나. 배경 · hover · 선택이 전부 여기서 값을 받는다.
       리터럴로 흩어져 있던 여덟 단계를 모은 것이다 — 같은 역할인데 값이 제각각이면 테마를 못 바꾼다.
       ⚙ 개발용 RGB 피커(`ui/devpalette.js`)는 이 여덟 개만 갈아 끼운다 → 화면 전체가 따라온다 */
    --surface-0: #000000;
    --surface-1: #040404;
    --surface-2: #050505;
    --surface-3: #070707;
    --surface-4: #0c0c0c;
    --surface-5: #0d0d0d;
    --surface-6: #0e0e0e;
    --surface-7: #141414;
    /* 채널 변수 — `rgba()` 는 hex 를 알파와 못 섞는다. 투명하게 깔리는 표면은 여기서 받는다 */
    --surface-0-rgb: 0, 0, 0;   /* 탭 열 · 상단바 · 패널 · 배경 아트 오버레이 */
    --veil-rgb: 6, 6, 6;        /* 아트 위에 덮는 어두운 베일 */
    --shadow-rgb: 0, 0, 0;      /* 그림자는 테마와 무관하게 검정이다 — 피커가 안 건드린다 */
    --tint-rgb: 255, 255, 255;  /* 빈 칸 · 채운 칸에 얹는 흰 기운 */

    /* 투명도 [2026-09-14] - 배경 아트가 UI 뒤로 얼마나 비치나. 세 축이 따로 논다:
       아트 자체 · 그 위 패널의 불투명도 · 가장자리를 누르는 비네트.
       'rgba(...)' 의 알파 자리는 calc() 를 받으므로 비네트는 배율 하나로 다섯 단을 한꺼번에 민다 */
    --art-opacity: .07;        /* #stage::before - 거점 아트(town.webp) */
    --vignette: 1;             /* #stage::after - 1 = 원래대로, 0 = 비네트 없음 */
    --chrome-alpha: 0;         /* 탭 열 · 상단바 · 브랜드 */
    --panel-alpha: 0;          /* 패널 */
    --panel-alpha-soft: 0;     /* 자원 줄 판 */

    /* 의미 이름은 사다리를 가리킨다 — 어느 단을 쓰는지가 한 줄로 읽힌다 */
    --bg-primary: var(--surface-0);
    --bg-secondary: var(--surface-0);
    --bg-tertiary: var(--surface-1);
    --bg-card: var(--surface-0);
    --bg-input: var(--surface-0);
    --border-primary: #343434;
    --border-secondary: #4e4e4e;
    --border-highlight: #707070;
    --border-dark: #1e1e1e;
    --text-primary: #ffffff;
    --text-secondary: #e3e3e3;
    --text-muted: #aaaaaa;
    --text-accent: #e03030;
    --color-success: #40d870;
    --color-warning: #f8b830;
    --color-error: #f04040;
    --color-info: #40a0f8;
    --color-progress: #ff8c00;   /* 진행 막대 — 건설 부지 · 상세의 랭크 눈금 (2026-09-23 사용자 지시 「주황색으로」). 희귀도 주황(--rarity-unique)과 값은 같아도 역할이 다르다 */
    --color-drop: #ff8c00;       /* 끌어 놓을 자리 — 영웅 띠 순서 옮기기의 삽입선 (2026-10-09 사용자 지시 「주황색으로」 · ADR-0571). 고른 표시(파랑 --color-info)와 갈린다 */
    --color-chosen: #ff8c00;     /* 굳은 선택 — 도서관 전직 패널의 전직한 갈래 테두리 (2026-10-12 사용자 지시 「주황색으로」 · ADR-0592). 언제든 풀리는 고른 표시(파랑 --color-info)와 갈린다 */

    /* ── 의미색 [2026-09-14] ── 화면 곳곳에 리터럴로 흩어져 있던 것을 역할 이름으로 모았다.
       값은 옮기기 전과 **한 개도 안 바뀌었다** — 표현만 토큰이 됐다.
       위 상태색 4종 · 죄종 7색(`mock.js:SINS`)은 별개 축이라 여기 없다 */

    /* 주 행동 버튼 — 브랜드 빨강 계열 */
    --btn-primary-bg: #3a1414;
    --btn-primary-bg-hover: #4a1a1a;
    --btn-primary-line: #7a2a2a;
    --btn-primary-fg: #ffb0b0;

    /* 되돌릴 수 없는 행동 — 해고 · 분해 (§3 「두 번 누르게 한다」) */
    --danger-bg: #2a1414;
    --danger-bg-hover: #3a1a1a;
    --danger-line: #6a2a2a;
    --danger-fg: #f0a0a0;
    --danger-cell-hover: #2e1616;
    --danger-veil-rgb: 42, 20, 20;

    /* 적 · 보스 · 전투불능 · 피해 */
    --enemy-line: #7a3030;
    --boss-line: #7a2a2a;
    --boss-bg: #1f1416;
    --downed-line: #5a2424;
    --hp-fill: #c03030;
    --accent-rgb: 224, 48, 48;  /* = --text-accent 의 채널. 보스 초상 글로우가 쓴다 */

    /* 정예 · 패시브 · 경고 — 금색 계열 */
    --elite-line: #6a4a1a;
    --elite-line-soft: #6a4a2a;
    --elite-bg: #1d1710;
    --elite-bg-unit: #1f1a16;
    --elite-fg: #d09040;
    /* 능력치 칩 — 청동 [2026-09-24 사용자 지시 · 시험 적용] 위 금색에서 채도를 뺐다 */
    --bronze-line: #7d6a48;
    --bronze-fg: #cdbb92;
    --fire-bg: #3a2c14;
    --warn-line: #5a4a1a;
    --warn-bg: #1d1a10;
    /* 도박장 릴 [2026-10-12 · ADR-0608] — 릴 띠는 검정이 아니라 **그을린 양피지빛 어둠**이다: 심볼 그림의 근검정 외곽선이 검정 바탕에선 녹아 사라진다.
       릴 사이 줄은 띠보다 어둡다 — 릴 셋이 따로 도는 북 셋으로 읽힌다 */
    --gb-reel: #1c1712;
    --gb-reel-gap: #070605;

    /* 아군 · 정보 · 경험치 — 푸른 계열 */
    --ally-line: #3060a0;
    --xp-fill: #6060c0;
    --info-fg: #8fb8ff;
    --info-fg-soft: #cfe0ff;
    --info-line: #46639e;
    --info-line-rgb: 70, 99, 158;
    --note-line: #1f4a6a;
    --note-bg: #101a24;

    /* 회복 · 완료 · 켜짐 — 초록 계열 */
    --heal-fg: #8fe6a8;
    /* 피해 종류 색 — 관전 로그의 피해 숫자 (ADR-0150). 독은 회복 민트와 떼려고 진한 풀색이다 */
    --dt-physical: #f08a3c;
    --dt-lightning: #f2d84a;
    --dt-cold: #5aaaf5;
    --dt-poison: #6cc24a;
    --dt-fire: #ee5140;
    /* 관전 연출 색 (ADR-0406) — 위 피해 종류 색 계열을 **채도를 낮춘** 값 · `-core` 는 조각의 밝은 속. 네온 · 번짐 빛을 안 쓴다 */
    --fx-physical: #cfae8a;
    --fx-physical-core: #f0e4d2;
    --fx-fire: #c65a3a;
    --fx-fire-core: #e9a868;
    --fx-cold: #6f9ec4;
    --fx-cold-core: #d6e6f1;
    --fx-lightning: #d4bd62;
    --fx-lightning-core: #f5eec8;
    --fx-poison: #739a48;
    --fx-poison-core: #b9d08e;
    --fx-ring: #b3a58f;
    /* 기본 공격 이펙트 (ADR-0501) — **무채색 하나**(옅은 은빛) · 피해 종류 색을 든 스킬 이펙트와 색으로 갈린다 */
    --fx-basic: #aab0b9;
    --fx-basic-core: #e6e9ee;
    /* 스킬마다 다른 생김새의 색 (ADR-0511 · fx.js:PALETTE) — 피해 종류 색 밖의 색 이름. 같은 규칙(채도를 낮춘 바탕 + 밝은 속 · 네온 없음 · ADR-0406).
       피해 숫자는 이 색과 무관하게 늘 피해 종류 색이다 · tiger = 백호참의 흰 심 + 하늘빛 띠(ADR-0509) */
    --fx-holy: #d9c78a;
    --fx-holy-core: #fbf4dc;
    --fx-blood: #a5463e;
    --fx-blood-core: #e8a89e;
    --fx-earth: #a2865c;
    --fx-earth-core: #e0cfa6;
    --fx-shadow: #725f93;
    --fx-shadow-core: #cdbde8;
    --fx-steel: #8e9db0;
    --fx-steel-core: #e4eaf1;
    --fx-wind: #93bf9e;
    --fx-wind-core: #e1f1df;
    --fx-tiger: #96cdec;
    --fx-tiger-core: #f4fbff;
    --fx-gold: #d4b062;
    --fx-gold-core: #f7e6b4;
    --fx-heal: #8fc79a;
    --fx-heal-core: #dcf0d8;
    --fx-bleed-rgb: 176, 44, 40;
    --fx-buff-rgb: 212, 176, 98;
    --fx-debuff-rgb: 92, 52, 120;
    --fx-barrier-rgb: 130, 168, 200;
    --done-line: #3a5a3a;
    --done-bg: #16201a;
    --toggle-bg: #14301c;
    --toggle-line: #2a6a3a;
    --toggle-fg: #a0f0b0;

    /* 전직 스킬 그림 칸의 바탕 [2026-09-22 · ADR-0301 · ⚠ 시험 적용] — 스킬 그림이 전부 색 없는 흰 실루엣이라
       기본 ↔ 전직 닮은 쌍(파이어볼 ↔ 메테오)을 가른다. 어두운 바탕 색 중 비어 있던 보라 · 검정 위에서 겨우 보이는 세기 */
    --adv-skill-bg: #160d1e;

    /* 등급색 — **SSOT 는 `data/hero_tier.csv` · `ui/mock.js:RARITY`**. 여기 값은 그 사본이다 (하나를 바꾸면 셋 다) */
    --rarity-normal: #D8D8D8;
    --rarity-magic: #4169E1;
    --rarity-rare: #FFD700;
    --rarity-epic: #B266FF;        /* 아이템만 — 영웅 등급엔 없다 (2026-10-24 · R342 · ADR-0767) */
    --rarity-legendary: #FF4D4D;   /* 아이템만 — 영웅 등급엔 없다 (ADR-0767) */
    --rarity-unique: #FF8C00;
    --rarity-unique-rgb: 255, 140, 0;

    /* 2026-08-27 — 하이브리드 폰트. 본문은 가독성 우선(Pretendard),
       브랜드 워드마크(.brand · 메뉴 로고)만 장르 분위기 글꼴이다 — 2026-10-16 사용자 지시로 픽셀 글꼴(Galmuri)을 걷고 Cinzel(로마 대문자 세리프) */
    --font-main: 'Pretendard', 'Malgun Gothic', sans-serif;
    --font-display: 'Cinzel', 'Times New Roman', serif;
    /* 2026-08-27 — 전체 확대(+약 20%). 장시간 응시하는 화면이라 판독성이 우선 */
    /* 2026-09-03 — 칸 안 초소형 라벨 한 단(약어 배지 · 마스터리 칸 · 페이퍼돌 라벨 · 라운드 트랙 …).
       9px 와 10px 리터럴이 열 군데 흩어져 있던 것을 **하나로 모았다** — 같은 역할인데 크기가 달랐다 */
    --fs-2xs: 9px;
    --fs-xs: 12px;
    --fs-sm: 13px;
    --fs-md: 15px;
    --fs-lg: 18px;
    --fs-xl: 24px;
    /* 영웅 띠 카드 폭 상한 · 카드 사이 (`.hs-card` · `.hero-strip`) — 띠 칸에 끝을 맞추는 판(도서관 전직 패널 · ADR-0852)이 같이 읽는다 */
    --hs-card-max: 120px;
    --hs-gap: 8px;
    /* 진형 보드 (2026-09-09 · SCREEN_DESIGN §4-1) — `--fm-slot` 은 칸 한 변이고
       영웅 띠 카드 하한(.hs-card min-width)과 같은 값이다: 빈 칸이 「영웅이 들어갈 자리」로 크기만으로 읽혀야 한다.
       **보드 높이는 랭크 최대(둘) 기준으로 고정**이라 템플릿을 바꿔도 패널이 안 흔들린다
       (「패널 크기는 상태에 흔들리지 않는다」 2026-08-28). 한 줄짜리(3)는 그 안에서 가운데에 선다.
       ⚠ 옛 경고(「키우면 보내기 버튼이 접힌다」)는 **패널이 탭 안에 있던 시절** 것이다 — 창이 된 뒤(ADR-0084)로는
         스테이지 목록·챕터 줄과 세로를 다투지 않는다. 이 값은 적 칸(4개)과 진형 축(3칸)이 **같이** 읽는다.
       **1600×800 한 장 기준 고정값**이다 (ADR-0087) */
    --fm-slot: 118px;
    /* 뒤 랭크가 내려가는 **한 단** [2026-09-21 사용자 지시 · ADR-0234] — 칸 한 변의 0.6배다 [2026-10-09 사용자 지시 · ADR-0577 — 0.35(ADR-0491)를 키웠다] —
       관전의 `--form-step`(0.22배)보다 넉넉하다: 고치는 화면이라 앞뒤가 한눈에 갈려야 한다.
       보드는 줄이 아니라 이 단으로 랭크를 말하므로 높이가 **칸 + 단** 하나다 */
    --fm-step: calc(var(--fm-slot) * 0.6);
    /* 칸 아래 랭크 라벨(전열 · 후열) 한 줄 + 칸과의 틈 [2026-09-21 · ADR-0269] — 보드 높이가 `칸 + 단 + 라벨` 이다 */
    --fm-lab-h: 20px;
    --fm-board-h: calc(var(--fm-slot) + var(--fm-step) + var(--fm-lab-h));
    /* 칸이 놓이는 **축의 폭** — 정원 최대(3칸)만큼 늘 잡아 둔다 (2026-09-09).
       랭크마다 칸 수가 달라도 이 폭 안에서 **가운데 정렬**되므로 2·1 이면 뒤 하나가 앞 둘 사이에 온다 —
       관전 아레나가 「수가 적은 랭크를 가운데」로 세우는 것(ADR-0053)과 같은 그림이 편성에서도 보인다 */
    --fm-axis: calc(var(--fm-slot) * 3 + 14px);

    /* 2026-09-01 — 초상 축소 보간. **스타일이 정한다**: 초상은 어디서나 원본보다 작게 그려지는데
       (구성 칩 26px ~ 시작 후보 카드 152px), 줄이는 방법이 스타일마다 달라야 한다.
       기본값은 손그림 쪽(보간 켬) — 신호(`<html data-face>`)가 아직 없어도 안전한 쪽으로 떨어진다.
       SCREEN_DESIGN §5 · 신호는 `mock.js:applyDocumentFace` 가 단다 */
    --face-render: auto;

    /* 2026-09-16 — 배경 축소 보간. 초상과 같은 문법이다: **정식 배경이 일러스트**라 `auto` 가 안전한 쪽이고
       (신호 `<html data-bg>` 가 없어도 붓질의 선이 안 끊긴다), 도트 스타일만 아래에서 뒤집는다.
       신호는 `mock.js:applyDocumentBg` 가 단다 · ADR-0152 */
    --bg-render: auto;
}
/* 배경 도트 스타일 — 보간하면 도트가 뭉간다. 기본값(일러스트)은 반대로 켜 두여야 축소할 때 선이 안 끊긴다
   (512를 26px 칸에 넣으면 20픽셀 중 1픽셀만 남는다 — 초상에서 겪은 것과 같은 함정).
   ⚠ 얼굴 쪽 형제 토큰은 `--face-render` 다. `gemini` · `gpt` 모두 손그림이라 **재정의가 없다**
      [2026-09-17 — `faces/pixel16/` 폴더가 사라져 `:root[data-face="pixel16"]` 규칙을 걷었다].
      ⚠ 스타일을 안 타는 자리 둘 — `#stage::before`(거점)는 계승 도트 한 벌뿐이라 `pixelated` 를 박고,
      `.ex-map`(탐험 지도)은 신규 카툰 아트라 아예 안 건다 (2026-09-04) */
:root[data-bg="pixel"] { --bg-render: pixelated; }

* { margin: 0; padding: 0; box-sizing: border-box; }

/* ───────── 게임 화면 기본기 ─────────
   문서가 아니라 게임 UI다. 클릭했을 때 글자 입력 커서(캐럿)·드래그 선택·포커스 링이
   뜨면 안 된다. 셋은 원인이 각각 달라서 따로 꺼야 한다. 스크롤바도 그리지 않는다(④) · 브라우저 메뉴도 안 띄운다(⑤). */

body {
    /* ① 드래그 선택 — 클릭·드래그로 글자가 파랗게 잡히는 것 */
    -webkit-user-select: none;
    user-select: none;
    /* ② 캐럿 — Edge 의 캐럿 브라우징(F7)이 켜지면 깜빡이는 입력 커서가 생긴다.
          입력 요소가 없어도 뜨므로 색을 투명으로 죽인다 */
    caret-color: transparent;
}

/* ③ 포커스 링 — 마우스 클릭에는 그리지 않되, 키보드 이동(Tab)에는 남긴다.
      :focus 를 통째로 없애면 키보드로 화면을 못 읽는다 */
:focus { outline: none; }
:focus-visible { outline: 1px solid var(--border-highlight); outline-offset: 1px; }

/* ④ 스크롤바 — 기본은 숨긴다(ADR-0097). 종의 고정 높이 목록만 오른쪽 막대를 표시한다(ADR-0984). */
* { scrollbar-width: none; }

/* ⑤ 브라우저 메뉴 — 우클릭 · 길게 누르기(모바일)에 뜨는 「이미지 저장 · 복사」 메뉴를 안 띄운다 [2026-09-14 사용자 지시 · SCREEN_DESIGN §2].
      둘로 막는다 — iOS 는 이 CSS 만 듣고(길게 눌러도 contextmenu 이벤트를 안 쏜다), 안드로이드 · 데스크톱은 이 CSS 를 몰라
      `app.js:boot` 의 contextmenu 한 줄이 막는다 */
* { -webkit-touch-callout: none; }

/* 실제로 눌리는 것에만 손가락 커서 — 안 눌리는 카드까지 주면 거짓 신호가 된다 */
summary { cursor: pointer; -webkit-tap-highlight-color: transparent; }

body {
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: var(--font-main);
    font-size: var(--fs-md);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

/* 배경 = 계승 거점 아트(town.webp). 패널 뒤에 깔리고 여백에서만 보인다.
   **한 장(#stage) 안에 깐다** [2026-09-14 사용자 지시 · ADR-0107] — 창 전체(`body` · `position: fixed`)에 `cover` 로 깔면
   크기가 한 장이 아니라 창을 따라, 세로로 긴 모바일에서 그림만 크게 확대됐다. 한 장 바깥 가장자리는 `body` 의 바닥색이다.
   경로는 이 CSS 파일 기준 상대경로 (src/ui/ → src/assets/)
   **읽는 것은 워터마크 띠를 잘라 낸 사본이다** (2026-09-11 사용자 지시) — 원본은 오른쪽 아래에 생성기 ✦ 가 박혀 있어
   창 비율에 따라 드러났다. 레시피 · 근거는 src/assets/art/README.md 「backgrounds/」
   ⚠ **거점은 배경 스타일을 안 탄다** — 도트 한 벌뿐이라 `pixel/` 을 직접 박았고, 그래서 보간도
   `--bg-render` 가 아니라 `pixelated` 고정이다. ⚠ 정식 배경이 일러스트가 된 뒤로 **거점만 도트로 남아 있다** —
   거점 일러스트가 나오면 이 두 줄을 같이 고친다 (`mock.js:TOWN_BG` 도 같은 경로를 박는다 · ADR-0152) */
#stage::before {
    content: ''; position: absolute; inset: 0; z-index: -2;
    background: url('../assets/art/backgrounds/pixel/town.webp') center top / cover no-repeat;
    image-rendering: pixelated;
    opacity: var(--art-opacity);
}
/* 가장자리·하단을 눌러 본문 대비를 지킨다 — 그림은 남기고 글자만 살린다 */
#stage::after {
    content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none;
    background:
        radial-gradient(ellipse at 50% 22%, rgba(var(--surface-0-rgb),calc(.10 * var(--vignette))) 0%, rgba(var(--surface-0-rgb),calc(.68 * var(--vignette))) 72%),
        linear-gradient(180deg, rgba(var(--surface-0-rgb),calc(.18 * var(--vignette))) 0%, rgba(var(--surface-0-rgb),calc(.55 * var(--vignette))) 55%, rgba(var(--surface-0-rgb),calc(.90 * var(--vignette))) 100%);
}

button { font-family: inherit; font-size: inherit; color: inherit; cursor: pointer; }

/* ───────── 셸 ───────── */

/* 한 장 (2026-09-10 · ADR-0087) — 화면은 **1600×800 한 장**이다. 크기의 SSOT 는 아래 `#stage` 한 곳이고
   `app.js:fitStage` 가 창에 맞춰 통째로 줄이고 늘린다(`transform`). 그래서 **창 크기를 읽는 단위(vw · vh · 미디어 쿼리)를 안 쓴다** —
   그것들은 한 장이 아니라 실제 창을 봐서 창마다 한 장 안의 크기가 흔들린다. 정책은 src/ui/README.md 「화면 크기 정책」.
   nav 폭 330 은 **메인이 줄어든 만큼**이다(아래 `.main` 의 zoom · ADR-0090) — 영어 라벨("Expedition")이 드는 하한 188 을 넉넉히 넘는다. */
html, body { height: 100%; overflow: hidden; }
#stage { position: absolute; left: 0; top: 0; width: 1600px; height: 800px; transform-origin: 0 0; }
/* 맞춘 뒤에 보인다 [2026-09-24 · ADR-0349] — app.js 는 module 이라 첫 그리기 뒤에 돈다. 그 사이 한 장이 원배율로 섰다가 줄어드는 게 보였다.
   `.fit` 은 `app.js:fitStage` 가 처음 맞출 때 건다 — 배율 공식을 여기 옮겨 적지 않는다 */
#stage:not(.fit) { visibility: hidden; }
/* 세로 창 막 [2026-09-27 · ADR-0371] — 터치 기기의 세로 창에서 창 전체를 덮는다. **한 장 밖**이라 배율을 안 타고, 크기는 실제 폰 화면 px 이다.
   켜고 끄는 것은 `app.js:fitStage` → `renderTurnGate`(`hidden`) */
.turn-gate {
    position: fixed; inset: 0; z-index: 1000;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px;
    padding: 24px; text-align: center;
    background: var(--bg-primary); color: var(--text-primary);
    font-family: var(--font-main); font-size: 18px;
}
.turn-gate[hidden] { display: none; }
.turn-gate .turn-icon { font-size: 44px; line-height: 1; color: var(--text-muted); }
.turn-gate button { min-width: 220px; padding: 10px 18px; font-size: 15px; border-radius: 4px; -webkit-tap-highlight-color: transparent; }
.turn-gate .turn-full { background: transparent; border: 1px solid var(--border-highlight); color: var(--text-primary); }
.turn-gate .turn-skip { background: none; border: none; color: var(--text-muted); text-decoration: underline; }
#app {
    display: grid;
    grid-template-columns: 330px 1fr;
    grid-template-rows: 48px 1fr;
    grid-template-areas: "brand topbar" "nav main";
    height: 100%;
}

.brand {
    grid-area: brand;
    /* 워드마크는 칸 가운데 — 칸 폭이 아래 왼쪽 탭 열과 같아 가운데 줄이 같다 (ADR-0895) */
    display: flex; align-items: center; justify-content: center; padding: 0 16px;
    background: rgba(var(--surface-0-rgb), var(--chrome-alpha));
    border-right: 1px solid var(--border-primary);
    border-bottom: 1px solid var(--border-primary);
    /* 워드마크는 그림 한 장(아래 .brand img) — 장르 글꼴(--font-display)은 그림이 못 뜰 때의 대체 글(alt)만 쓴다 · 굵게 · 자간을 벌려 대문자 세리프가 로고로 읽히게 */
    font-family: var(--font-display);
    font-size: var(--fs-lg); font-weight: 700; letter-spacing: 3px;
    /* flex 칸이라 「THE 」 끝 공백이 접혀 두 낱말이 붙었다 — 낱말 사이는 gap 이 든다 */
    gap: .4em;
}
.brand b { color: var(--text-accent); }
/* 워드마크 그림 (ADR-0883) — 칸 높이 가운데 · 줄 48px 안에 든다. D2 Min 은 돌 틀 안으로 따로 잡는다(D2 Min 절) */
.brand img { display: block; height: 36px; }

.topbar {
    grid-area: topbar;
    position: relative;   /* z-index 는 안 준다 — 쌓임 맥락을 만들면 상단바 안의 판이 창 레이어 아래로 갇힌다 (플래시는 한 장 직속 — ADR-0692) */
    display: flex; align-items: center; justify-content: space-between;
    gap: 24px; padding: 0 20px;
    background: rgba(var(--surface-0-rgb), var(--chrome-alpha));
    border-bottom: 1px solid var(--border-primary);
}
/* 현재 위치 = 고른 탭 이름 — 흰 글씨 · 굵게 (2026-09-21 사용자 지시 · SCREEN_DESIGN §2 상단바). 크기는 패널 제목과 같다 */
.topbar .crumb { color: var(--text-primary); font-size: var(--fs-md); font-weight: bold; }
/* crumb 은 게임 밖 화면 이름만 든다 — 게임 화면엔 비고 자리를 안 잡는다 [2026-10-21 사용자 지시 · SCREEN_DESIGN §2 · ADR-0686] */
.topbar .crumb { flex-shrink: 0; white-space: nowrap; }
.topbar .crumb:empty { display: none; }
/* 원정 세그먼트 — 상단바 왼쪽 끝 · **모든 탭에 선다** (ADR-0094 · ADR-0353 · ADR-0686). 비면(게임 밖) 자리를 안 잡는다 */
.tab-seg { margin-right: auto; min-width: 0; }
/* 자원 줄은 앞의 칸이 다 비어도(메뉴 — crumb · 세그먼트 둘 다 없다) 오른쪽 끝에 남는다 */
.topbar > .resources { margin-left: auto; }
/* 상단바가 그리드 열(1fr)을 밀어 넓히지 않게 — 안 그러면 부대 칸이 줄기 전에 한 장이 오른쪽으로 넘친다 (ADR-0517) */
.topbar { min-width: 0; }
/* 자리가 모자랄 때 줄어드는 것은 부대 칸의 스테이지 글자 하나다 — 오른쪽 자원 줄은 안 줄어 글자가 두 줄로 안 접힌다 */
.topbar > .resources { flex-shrink: 0; }
.tab-seg:empty { display: none; }
.tab-seg .segmented { flex-wrap: nowrap; }
/* 부대 칸 = 이름 + 그 부대가 있는 스테이지 (ADR-0517) — 상단바가 모자라면 **스테이지 글자만** 줄어 「…」로 끝난다.
   부대 이름(앞 글자)은 제 폭을 지킨다 · 라벨 칸이라 고정 px 이 아니다 (Stages · Report 칸은 2026-10-18 걷혔다 · ADR-0661) */
.tab-seg .btn.seg-party { display: inline-flex; min-width: 0; white-space: pre; }
.tab-seg .seg-where { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* 원정 세그먼트의 관전 칸은 원정 상태를 든다 — 없음 회색 · 원정이 있으면(도는 중 · 끝남) 파랑. 고른 칸은 테두리까지 그 색 (SCREEN_DESIGN §4 · ADR-0147).
   파랑은 **폴백**이다 — 원정이 있는 부대 칸은 렌더러가 그 스테이지의 챕터 죄종 색을 인라인으로 덮는다(`app.js:expNavBox` · ADR-0519).
   끝나도(져도) 빨강으로 안 바뀐다 (ADR-0522) */
.tab-seg .btn.seg-none { color: var(--text-muted); }
/* 원정이 없는 열린 부대 = 흰 글씨 「Party I - 대기 중」 — 안 눌려도 꺼진 버튼 흐림을 안 받는다. 흐린 회색은 자물쇠 칸(`seg-none`)만 [2026-10-27 사용자 지시 · ADR-0912] */
.tab-seg .btn.seg-idle { color: var(--text-primary); }
.tab-seg .btn.seg-idle:disabled { opacity: 1; }
.tab-seg .btn.seg-live, .tab-seg .btn.seg-over { color: var(--color-info); }
.tab-seg .btn.seg-live.on, .tab-seg .btn.seg-over.on { border-color: var(--color-info); }
/* 관전으로 가는 버튼 — 칸 모양은 그대로 · 이름 앞에 같은 색 ▶ 하나 [2026-10-21 사용자 지시 · SCREEN_DESIGN §4 · ADR-0689 — 0688 의 채운 모양을 걷었다].
   상단바 부대 칸 · 스테이지 목록 줄의 ▶ 부대 버튼(`app.js:partyGo`) */
.btn.party-go::before { content: '\25B6'; font-size: .75em; margin-right: 6px; align-self: center; }
.resources { display: flex; gap: 18px; font-size: var(--fs-sm); }
.resources span b { color: var(--text-primary); margin-left: 6px; }
.resources span { color: var(--text-muted); }
/* 원정 플레이 시간 — 골드와 같은 모양 · 숫자 폭을 고르게 둬 1초마다 바뀌어도 옆 버튼이 안 흔들린다 (SCREEN_DESIGN §2 · ADR-0356 · ADR-0514) */
.resources .exp-time b { font-variant-numeric: tabular-nums; }
/* 언어 토글 — 리소스 줄 끝에 붙는다 */
.lang-btn { margin-left: 4px; min-width: 46px; }
/* 우편함 — 골드 바로 오른쪽 편지봉투 · 우편이 있으면 오른쪽 위 개수 배지 (SCREEN_DESIGN §2 「상단바」 · ADR-0732) */
.mail-btn {
    position: relative; width: 30px; height: 30px; min-width: 0; padding: 4px; align-self: center;
    appearance: none; background: transparent; border: 0; box-shadow: none;
}
.mail-btn:focus-visible { outline: 1px solid var(--border-highlight); outline-offset: 2px; }
.mail-btn img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); opacity: .85; }
.mail-btn.has img, .mail-btn:hover img, .mail-btn:focus-visible img { opacity: 1; }
.mail-btn:hover img { filter: brightness(1.08); }
.mail-btn .mail-n {
    position: absolute; top: -4px; right: -6px; min-width: 16px; padding: 0 4px; border-radius: 8px;
    background: var(--color-error); color: var(--text-primary); font-size: var(--fs-xs); line-height: 16px; text-align: center;
}
/* 우편함 옆의 알림 종과 상단 앵커 판 (ADR-0969). 메인·관전은 다시 그리지 않는다.
   판의 겉모양은 게임 창을 따른다 (ADR-0988) — 껍데기 = 창(`.modal-box`)과 같은 바탕 · 테두리 · 여백 · 머리 = 창 머리(`.modal-head.plain` · 정사각 `.modal-x`) ·
   폴더 탭 = 대장간 작업 탭(`.fg-gap` · `.fg-fill`)이 윗변인 판 · 항목 = 우편 카드(왼쪽 굵은 띠 · 인벤토리 칸 바탕) · 빈 자리 = 흐린 종(우편함의 흐린 편지봉투) */
.notification-slot { position: relative; display: flex; align-items: center; }
.notification-btn img, .mail-btn img { image-rendering: auto; }
.notification-dot { position: absolute; top: 0; right: 0; width: 6px; height: 6px; border-radius: 50%; background: var(--color-error); }
.notification-panel {
    position: absolute; top: calc(100% + 12px); right: -8px; z-index: 49;
    width: 420px; max-width: 80vw; box-sizing: border-box;
    display: flex; flex-direction: column; padding: 12px 14px 14px;
    background: var(--bg-secondary); border: 1px solid var(--border-highlight);
    box-shadow: 0 12px 40px -8px #000; color: var(--text-primary);
}
.notification-panel[hidden] { display: none; }
.notification-head { margin-bottom: 10px; }
.notification-folder.fg-tab { display: inline-flex; align-items: center; justify-content: center; flex: 0 1 auto; min-width: 0; gap: 5px; padding-left: 14px; padding-right: 14px; font-size: var(--fs-sm); }
.notification-folder .notification-folder-label { min-width: 0; color: inherit; overflow: hidden; text-overflow: ellipsis; }
.notification-folder .notification-folder-count { flex: none; color: var(--text-primary); font-size: var(--fs-xs); }
.notification-folder .lock-ico { display: inline-flex; flex: none; }
.notification-folder .lock-ico svg { width: 1em; height: 1em; }
.notification-folder:focus-visible { outline: 1px solid var(--border-highlight); outline-offset: -3px; }
/* 본문 = 탭 아래 윗변 없는 판 · 높이는 카드 세 장(`notifications.js:SLOTS`) · 오른쪽 스크롤바는 보인다 (ADR-0984) */
.notification-list {
    --nt-h: 66px; --nt-gap: 8px;
    display: flex; flex-direction: column; gap: var(--nt-gap);
    height: calc(3 * var(--nt-h) + 2 * var(--nt-gap) + 18px); box-sizing: border-box; padding: 8px 4px 8px 8px;
    border: 1px solid var(--border-primary); border-top: 0;
    overflow-y: scroll; overflow-x: hidden; scrollbar-gutter: stable;
    scrollbar-width: auto; scrollbar-color: auto;
}
.notification-list::-webkit-scrollbar { display: block; width: 10px; }
.notification-list::-webkit-scrollbar-track { background: var(--surface-1); }
.notification-list::-webkit-scrollbar-thumb { background: var(--border-highlight); border: 2px solid var(--surface-1); border-radius: 5px; }
.notification-guide-toggle { flex: none; display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 2px 2px 0; border: 0; background: none; color: var(--text-secondary); font: inherit; font-size: var(--fs-sm); cursor: pointer; }
.notification-guide-toggle:hover { color: var(--text-primary); }
/* 카드 = 우편 카드(`.mail-card`)와 같은 바탕 · 테두리 · 왼쪽 굵은 띠 */
.notification-card {
    flex: none; display: flex; align-items: center; gap: 12px; min-height: var(--nt-h); box-sizing: border-box;
    padding: 8px 10px 8px 12px; background: var(--bg-tertiary);
    border: 1px solid var(--border-primary); border-left: 3px solid var(--color-warning);
}
.notification-card:not(.empty):hover { background: var(--surface-5); }
/* 빈 자리는 남은 높이를 나눠 갖는다 — 두 줄 카드가 서도 빈 자리 때문에 본문이 스크롤하지 않는다 */
.notification-card.empty { flex: 1 1 0; min-height: 24px; justify-content: center; padding: 0; background: transparent; border: 1px dashed var(--border-dark); }
.notification-card.empty img { width: 26px; height: 26px; object-fit: contain; opacity: .12; }
.notification-copy { min-width: 0; flex: 1; }
.notification-title { color: var(--text-primary); font-weight: bold; font-size: var(--fs-sm); line-height: 1.4; overflow-wrap: anywhere; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; }
.notification-detail { margin-top: 4px; color: var(--text-muted); font-size: var(--fs-xs); line-height: 1.4; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.notification-retry { align-items: flex-start; }
.notification-retry .notification-detail { white-space: normal; overflow: visible; text-overflow: clip; overflow-wrap: anywhere; }
.notification-actions { display: flex; flex: none; align-items: center; gap: 6px; }
.notification-go { flex-shrink: 0; }
.notification-bubble {
    position: absolute; top: calc(100% + 12px); right: -8px; z-index: 49; pointer-events: none;
    width: max-content; max-width: 320px; padding: 10px 14px; background: var(--bg-secondary);
    border: 1px solid var(--border-highlight); color: var(--text-primary); font-size: var(--fs-sm);
    box-shadow: 0 6px 18px rgba(var(--shadow-rgb), .5);
}
.notification-btn.ringing img { transform-origin: 50% 15%; animation: notification-ring .65s ease-out; }
.notification-target { animation: notification-focus 1.4s ease-out; }
@keyframes notification-ring { 0%, 100% { transform: rotate(0); } 20%, 60% { transform: rotate(15deg); } 40%, 80% { transform: rotate(-15deg); } }
@keyframes notification-focus { 0%, 50% { outline: 2px solid var(--border-highlight); outline-offset: 3px; } 100% { outline-color: transparent; } }
@media (prefers-reduced-motion: reduce) { .notification-btn.ringing img, .notification-target { animation: none; } }
/* 플래시 — 한 장 오른쪽 아래의 카드 [2026-10-21 사용자 지시 · ADR-0692 · SCREEN_DESIGN §2 「플래시」].
   한 장 오른쪽 가장자리 밖에서 튀어나와 서 있다가 다시 들어간다. **길이는 `app.js:TOAST_MS` 가 준다**(인라인 animation-duration) — 여기는 들고 나기의 **몫**만 든다.
   카드는 세로로 쌓인다 — 새 카드가 맨 아래(모서리)에 붙고 위의 카드는 밀려 오른다. 몇 장까지인지는 `app.js:TOAST_MAX`.
   자리는 한 장(#stage) 직속이라 메인 배율(zoom)을 안 타고 render() 가 안 지운다. z-index 는 창 레이어(40) 위 · 툴팁(50) 아래.
   자리의 오른쪽 끝이 한 장 오른쪽 끝이고 overflow 를 자른다 — 들고 나는 카드가 한 장 밖 바닥색 위로 안 삐져나온다. 위 · 왼쪽 여백은 그림자 몫.
   클릭은 통과한다(pointer-events 는 물려받는다) — 카드가 덮은 가방 칸 · 버튼이 그대로 눌린다 */
.toast-layer {
    position: absolute; right: 0; bottom: 0; z-index: 48; pointer-events: none;
    display: flex; flex-direction: column; align-items: flex-end; gap: 8px;
    padding: 24px 16px 16px 32px; overflow: hidden;
}
.toast {
    min-width: 240px; max-width: 380px; line-height: 1.4;   /* 짧은 문구도 같은 폭으로 서서 쌓인 카드의 왼쪽 끝이 들쭉날쭉하지 않다 */
    font-size: var(--fs-sm); color: var(--color-warning);
    padding: 10px 16px 10px 14px;
    border: 1px solid var(--warn-line); border-left: 3px solid var(--color-warning); background: var(--warn-bg);
    box-shadow: 0 8px 22px rgba(var(--shadow-rgb), .7);
    animation: toast-pop ease-out both;   /* 길이 없음 — JS 가 준다 */
}
/* 글 줄 안의 자물쇠 — 잠김 한 줄(「도서관 건설」)의 앞 · 플래시 · 빈 칸 사유 · 잠김 안내 줄이 같이 쓴다 (SCREEN_DESIGN §13-1 · ADR-0699).
   그림은 `lockIcon`(잠김 베일과 같은 것) · 크기는 글자 높이 */
.lock-inl { display: inline-flex; vertical-align: -0.125em; margin-right: .3em; }
.lock-inl svg { width: 1em; height: 1em; }
/* 잠금 표시는 어디서나 회색 [2026-10-27 사용자 지시 「모든 잠금 표시를 회색으로」 · SCREEN_DESIGN §13-1 · ADR-0925] —
   자물쇠(`lockIcon`)는 둘레 글자색(죄종 색 탭 · 빨간 막힘 줄 · 플래시)을 안 따른다 · 잠김 한 줄(`lockLine` → `.lock-line`)은 글자까지 회색.
   예외 = 전술 잠금 토글(`.rs-pin` — 유저가 거는 잠금 · 버튼 색) · 플래시의 글(카드 색 그대로 — 자물쇠만 회색) */
.rs-pin-ico { color: var(--text-muted); }
.rs-pin .rs-pin-ico { color: inherit; }
.lock-line { color: var(--text-muted); }
.toast .lock-line { color: inherit; }
@keyframes toast-pop {
    0%   { opacity: 0; transform: translateX(calc(100% + 16px)); }
    8%   { opacity: 1; transform: none; }
    90%  { opacity: 1; transform: none; animation-timing-function: ease-in; }
    100% { opacity: 0; transform: translateX(calc(100% + 16px)); }
}

.nav {
    grid-area: nav;
    background: rgba(var(--surface-0-rgb), var(--chrome-alpha));
    border-right: 1px solid var(--border-primary);
    padding: 12px 0;
    display: flex; flex-direction: column; gap: 2px;
}
/* 탭은 묶음 머리보다 한 단 안으로 들어가 선다 [2026-10-09 사용자 지시 · SCREEN_DESIGN §1] — 왼쪽 여백 31px = 머리 글씨(19px)보다 12px 안.
   「새 게임」은 묶음 밖이라 머리와 같은 선이다(아래 `.b-newgame`) */
.nav button {
    background: none; border: 0; border-left: 3px solid transparent;
    padding: 8px 16px 8px 31px; text-align: left; color: var(--text-secondary);
}
/* 묶음 머리 [2026-10-09 사용자 지시 · SCREEN_DESIGN §1 · ADR-0554] — 누를 수 없는 작은 회색 글씨 · 묶음 사이 간격은 이 윗여백이 든다.
   왼쪽 여백 19px = 탭 버튼의 왼쪽 띠(3px) + 16px — 「새 게임」과 같은 선 · 탭 이름은 이보다 안으로 든다 */
.nav .nav-grp {
    margin-top: 14px; padding: 0 16px 4px 19px;
    font-size: var(--fs-xs); color: var(--text-muted); letter-spacing: .06em;
    user-select: none; cursor: default;
}
.nav .nav-grp:first-child { margin-top: 0; }
.nav button:hover { background: var(--bg-tertiary); color: var(--text-primary); }
.nav button.on {
    background: var(--bg-tertiary); color: var(--text-primary);
    border-left-color: var(--text-accent);
}
/* 흐린 탭 [2026-09-28 사용자 지시 · SCREEN_DESIGN §1] — 이름과 오른쪽 끝 자물쇠가 **같은 색 · 같이 흐리다**(경고색 아님) */
.nav button.dim { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.nav button.dim .nav-lbl, .nav button.dim .nav-lock { opacity: .45; }
.nav .nav-lock { display: inline-flex; color: inherit; }
.nav .nav-lock svg { width: 1.1em; height: 1.1em; }
/* 할 일 점 [2026-10-16 · SCREEN_DESIGN §1 · ADR-0637] — 하면 꺼지는 일이 기다리는 탭 · 이름 오른쪽 끝(흐린 탭의 자물쇠 자리 — 둘은 같이 안 선다) ·
   건설 부지의 초록 점(`.cn-lot.ready::after`)과 같은 색 · 같은 크기 · 숫자 없음 */
.nav button.todo { position: relative; }
.nav button.todo::after {
    content: ''; position: absolute; top: 50%; right: 16px; width: 7px; height: 7px; margin-top: -3.5px; border-radius: 50%;
    background: var(--color-success);
}
.nav .tag {
    float: right; font-size: var(--fs-xs); color: var(--bg-primary);
    background: var(--color-warning); padding: 0 5px; border-radius: 2px;
}

.main { grid-area: main; overflow-y: auto; padding: 20px; }
/* 메인은 한 번 더 줄인다 (2026-09-10 · ADR-0090) — 칸(1270×752) 안에서 내용이 1411×836 으로 레이아웃되고 90% 로 선다.
   **모든 탭이 같은 비율**이고 줄어든 폭은 위 `#app` 첫 열(nav)이 갖는다. 배율은 세로가 정한다 — 752 ÷ 가장 긴 탭(캐릭터 834).
   `transform` 이 아니라 `zoom` — 칸 폭 안에서 레이아웃이 설계 크기로 돈다. 메인 안에는 마우스 좌표 코드가 없다(툴팁 = 한 장 직속 · 진형 드래그 = #modal).
   내비가 없는 화면(pregame — 시작 · 프롤로그)은 안 줄인다. 값과 대가는 src/ui/README.md 「화면 크기 정책」 */
#app:not(.pregame) > .main { zoom: .9; }
/* 탭 내용은 박스다 [2026-09-11 사용자 지시 · ADR-0097 · SCREEN_DESIGN §2 「박스」] — 탭 루트에 `.page` 가 붙으면 메인은 스크롤을 멈추고
   루트가 남는 세로를 다 먹는다. 박스 아랫변 = 탭 내비 「새 게임」 아랫변(한 장 788) — 내비 아래 여백 12 는 배율을 안 타므로 메인 아래 여백이 12 / .9 다.
   넘치는 내용은 박스 **안**이 받는다: 머리 아래 본문(`.box-body`) · 쌓인 판의 마지막(`.page-stack > .fill`) · 탭마다의 자리(리포트 상세 · 가방 칸 · 단계 목록).
   재접속 알림은 루트의 형제로 제 높이를 쓰고, 박스가 그만큼 준다(플래시는 한 장 오른쪽 아래에 떠서 박스를 안 민다 · ADR-0692) */
.main:has(> .page) { display: flex; flex-direction: column; overflow: hidden; padding-bottom: calc(12px / .9); }
.main > .page { flex: 1 1 0; min-height: 0; }
.panel.page, .page-stack { display: flex; flex-direction: column; }
.page-stack > * { flex: none; }
.page-stack > .fill { flex: 1 1 0; min-height: 0; overflow-y: auto; }
.box-body { flex: 1 1 0; min-height: 0; overflow-y: auto; }

/* ───────── 공통 조각 ───────── */

/* 패널은 살짝 비쳐서 배경 텍스처가 숨쉬되, 글자 대비는 유지한다 */
.panel {
    background: rgba(var(--surface-0-rgb), var(--panel-alpha));
    border: 1px solid var(--border-primary);
    padding: 10px 16px 11px;   /* 2026-09-01 세로 압축 — 가로 여백은 그대로 (읽기 폭은 안 건드린다) */
}

.panel + .panel { margin-top: 14px; }
/* ⚠ 위 규칙은 **세로로 쌓을 때**의 여백이다. 격자(.cols) 안에서는 둘째 칸부터 위로 14px 밀려
   **첫 칸(장비)만 높이 서는** 어긋남이 생긴다 — 격자의 간격은 `gap` 이 이미 든다 (2026-09-01 사용자 지시) */
.cols > .panel + .panel { margin-top: 0; }
/* 패널 제목 · 소제목은 **한 모양**이다 [2026-09-21 사용자 지시 · SCREEN_DESIGN §2 · ADR-0241] — 기준은 선술집 「의뢰」 제목.
   모양은 이 규칙 하나가 든다 — 태그(h2 · h3 · div)는 모양을 안 정한다. 둘이 다른 것은 자리 여백뿐이라
   패널 제목은 아래 줄이, 소제목은 `.sub-h`(캐릭터 탭 절)가 든다. 이름을 둘로 남긴 것은 나중에 한쪽만 바꿀 자리다 */
.panel > h2, .sub-h {
    font-size: var(--fs-md); font-weight: bold; color: var(--text-primary); letter-spacing: 0;
    border-bottom: 1px solid var(--border-primary); padding-bottom: 5px;
}
.panel > h2 { margin-bottom: 8px; display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
.panel > h2 small { text-align: right; }
.panel > h2 small { color: var(--text-muted); font-size: var(--fs-xs); }
/* 제목 줄 안의 부제 · 목업 표지 · 신원 칩(기본 옵션의 등급 · 죄종 · 직업 · ADR-0750)은 굵어지지 않는다 — 제목이 아니라 제목에 붙은 값이다 */
.panel > h2 small, .sub-h small, .panel > h2 .sin-chip, .panel > h2 .attr-ids { font-weight: normal; }
/* 기본 옵션 제목 오른쪽의 칩 셋 — 한 줄로 서고 접히지 않는다 (SCREEN_DESIGN §6 · ADR-0750) */
.panel > h2 .attr-ids { display: flex; gap: 4px; flex: none; white-space: nowrap; }

.cols { display: grid; gap: 14px; }
.cols.c2 { grid-template-columns: 1fr 1fr; }
/* minmax 로 최소만 보장하고 나머지는 흐르게 — 영어에서 라벨이 길어져도 안 깨진다 */
.cols.c-side { grid-template-columns: minmax(300px, 24%) 1fr; }

.muted { color: var(--text-muted); }
.dim { color: var(--text-secondary); }
.right { text-align: right; }
.center { text-align: center; }
.up { color: var(--color-success); }
.down { color: var(--color-error); }

.btn {
    background: var(--bg-tertiary); border: 1px solid var(--border-secondary);
    padding: 7px 14px; color: var(--text-secondary);
}
.btn:hover { border-color: var(--border-highlight); background: var(--surface-4); }
.btn.primary { background: var(--btn-primary-bg); border-color: var(--btn-primary-line); color: var(--btn-primary-fg); }
.btn.primary:hover { background: var(--btn-primary-bg-hover); border-color: var(--text-accent); }
.btn:disabled { opacity: .4; cursor: not-allowed; }
/* 안 지은 건물이 잠근 자리 — 흐리지만 **눌린다**(누르면 지을 건물을 말한다 · disabled 가 아니다) · 탭 바의 흐린 탭은 이름만 흐린다(`.nav-lbl` · 위 `.nav` 규칙) (SCREEN_DESIGN §1 · §13 · R137) */
.btn.dim { opacity: .45; }
.btn.sm { padding: 3px 8px; font-size: var(--fs-sm); }

/* 기본은 **무채색**이다 (2026-09-03 사용자 지시) — 영웅의 죄종 칩에서 색을 걷었기 때문(SCREEN_DESIGN §5).
   챕터 줄 · 리포트의 정예 죄종은 여전히 인라인으로 죄종 색을 덮는다 — 그쪽은 「어느 죄종의 것인가」라는 다른 축이다 */
.sin-chip {
    display: inline-block; font-size: var(--fs-xs); padding: 0 6px;
    border: 1px solid currentColor; border-radius: 2px; line-height: 16px;
    color: var(--text-secondary);
    white-space: nowrap;   /* 영어 죄종명이 접히면 칩 모양이 무너진다 */
}

/* 영웅 2층 구조 — 유니크/레어 배지 (아이템 희귀도와 같은 계단).
   **죄종 칩과 같은 규격이다** (2026-09-03 사용자 지적) — 이름 줄에 나란히 서는 같은 층의 정체성인데
   9px / 12px 로 갈려 있어 한쪽이 덜 중요해 보였다. 크기 · 줄높이 · 여백을 죄종 칩에 맞춘다 */
.tier-chip {
    display: inline-block; font-size: var(--fs-xs); padding: 0 6px; line-height: 16px;
    border: 1px solid currentColor; border-radius: 2px;
}
/* 직업 칩 — 후보 카드 · 도감 몬스터 카드 칩 줄의 셋째(죄종 오른쪽) · 그 직업 색(`class.csv:color`) · 같은 규격 (SCREEN_DESIGN §3 · §9 · ADR-0724)
   부류 칩 — 도감 몬스터 툴팁 칩 줄의 둘째(종족 오른쪽 · 죄종 칩 자리) · 무채색 · 같은 규격 (§9 · ADR-0922) · 도감 몬스터 카드 윗줄의 종족 · 부류 칩도 이것이다 (ADR-0929) */
.cls-chip, .base-chip {
    display: inline-block; font-size: var(--fs-xs); padding: 0 6px; line-height: 16px;
    border: 1px solid currentColor; border-radius: 2px;
    color: var(--text-secondary); white-space: nowrap;
}

/* 전투불능 — 방치형 계약의 언어("사망" 아님). 클래스 이름의 injury 는 옛 어휘가 남은 것이다 [09-06] */
.injury-chip {
    display: inline-block; font-size: var(--fs-xs); color: var(--color-error);
    border: 1px solid currentColor; padding: 0 5px; line-height: 15px; margin-top: 3px;
}
.party-slot.downed { opacity: .6; border-color: var(--downed-line); }
/* ~~.injury-box~~ (리포트의 전투불능 상자) 는 2026-09-10 삭제 — 기여 표의 영웅 줄이 **초상 회색**으로 든다 (ADR-0086) */

/* 고유 패시브 = 영웅 Implicit (유니크 전용) */
.passive-box {
    border: 1px solid var(--elite-line); background: var(--elite-bg); padding: 8px 10px; margin-bottom: 12px;
}
.passive-box .t { font-size: var(--fs-xs); color: var(--elite-fg); letter-spacing: 1px; margin-bottom: 3px; }
.passive-box .n { font-size: var(--fs-sm); color: var(--text-primary); }

/* 초상 바탕 음영 [2026-10-30 사용자 지시 · ADR-0957 · SCREEN_DESIGN §5] — 영웅 · 몬스터 초상 그림은 어디서나 뒤에 같은 음영 한 장을 깐다
   (막시무스 초상의 바탕을 본뜬 그림 · `scripts/build_face_backdrop.py`). 칸이 아니라 **그림에 붙인다** — 그림이 없거나 `onerror` 로 빠진 칸은 빈 칸 그대로다.
   초상 img 는 여러 렌더러가 따로 조립하지만 경로가 모두 `assets/art/faces/` 라 이 한 규칙이 빠짐없이 덮는다 */
img[src*="/art/faces/"] { background: url('../assets/art/faces/backdrop.webp') center / cover no-repeat; }

/* 몬스터 얼굴 — 128×128 정사각 PNG. 원형 마스크는 CSS가 하고 파일에는 굽지 않는다. 원형은 몬스터 전용 — 영웅은 .hero-face(네모) */
.face {
    position: relative;
    display: inline-flex; align-items: center; justify-content: center;
    width: 26px; height: 26px; flex: 0 0 auto;
    background: var(--bg-input); border: 1px solid var(--border-secondary);
    border-radius: 50%; overflow: hidden; vertical-align: middle;
}
/* 칸 안에는 그림 하나뿐이다 — **밑에 아무것도 깔지 않는다** (2026-09-06 사용자 지시).
   옛 판은 이니셜을 깔고 이미지를 위에 덮었는데, 몬스터 그림도 배경 투명 PNG 라 여백 사이로 글자가 비쳤다 */
.face img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; image-rendering: var(--face-render); }
/* 아트가 없는 몬스터 — **빈 원**. 죄종 색 배경·테두리만 JS가 인라인으로 준다 (글자 없음) */
.face.boss { border-color: var(--text-accent); box-shadow: 0 0 0 1px rgba(var(--accent-rgb),.25); }

/* 영웅 초상 — 네모 박스 (2026-08-27). 관전 유닛 카드의 .sprite 와 같은 그림이다: 영웅의 생김새는 어디서나 같다.
   원형(.face)은 몬스터 전용. 죄종 색은 카드 상단 테두리가 든다 — 초상은 색을 갖지 않는다.
   **아트가 없으면 빈 칸이다** (2026-09-03 사용자 지시 — 직업 글리프 폐지. 그림이 배경 투명 PNG 라 밑에 깔면 비친다).
   기본 크기 64px. 크기는 담는 카드가 정한다 — 시작 화면 후보 카드는 키우고(.ng-head, 2026-08-31) 선술집 명단은 줄이며(.tv-cands),
   영웅 띠·관전 유닛 카드는 카드 전체로 키운다(아래 「카드를 채우는 초상」) */
.hero-face {
    position: relative;
    display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto;
    width: 64px; height: 64px;
    background: var(--bg-input); border: 1px solid var(--border-secondary);
    overflow: hidden; vertical-align: middle;
}
/* 그림은 칸을 통째로 덮는다. 그 스타일에 영웅 그림이 없으면 `onerror` 로 img 가 빠지고 **빈 칸**이 남는다
   (2026-08-30 영웅 초상 연결 · 2026-09-03 밑에 깔던 글리프 폐지) */
.hero-face img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }

/* 카드를 채우는 초상 — 영웅 띠 카드(.hs-card .hero-face) (2026-08-27, SCREEN_DESIGN §5).
   정사각으로 카드 전체를 채운다. 아트가 없으면 빈 칸이다 (2026-09-03 글리프 폐지).
   (관전 유닛 카드는 같은 얼굴 그림을 쓰되 구성이 가로형이라 여기 안 낀다 — 전투 관전 절의 .unit .sprite) */
.hs-card .hero-face {
    display: flex; align-items: center; justify-content: center;
    width: 100%; height: auto; aspect-ratio: 1; border: 0;
    background: var(--bg-input); overflow: hidden;
}
/* 카드 위칸 — 초상 위에 얹는 반투명 띠. 왼쪽 = 상태 · 오른쪽 = 이름. 안 들어가면 두 줄로 접힌다 (고정 px 없음) */
/* ⚠ `z-index` 가 없어 **띠가 초상 밑에 깔려 안 보였다** (2026-09-03 발견 · 이름과 「하는 일」이 화면에서 통째로 사라져 있었다).
   `.hs-band` 는 DOM 에서 초상보다 **앞**인데 `.hero-face` 도 위치 지정 요소라 뒤에 오는 쪽이 이긴다.
   초상 여백을 걷기 전에는 그림 위쪽이 투명해 「가려도 티가 안 나던」 것이라 더 늦게 드러났다 (SCREEN_DESIGN §5) */
.hs-band {
    position: absolute; top: 0; left: 0; right: 0; z-index: 1;
    /* **한 줄 고정** [2026-09-09 사용자 지시] — wrap 이 켜져 있어 `On expedition` 이 이름을 아랫줄로 밀었다.
       줄바꿈 대신 **「하는 일」만 말줄임**된다 — **이름은 안 줄어든다**(`flex-shrink:0`). 이름은 카드를 고르는 키이고,
       상태는 색(주황=원정 중)이 이미 말하므로 글자가 잘려도 뜻이 안 사라진다. 이름이 카드보다 길면 `max-width:100%` 가 받는다 */
    display: flex; flex-wrap: nowrap; align-items: baseline; justify-content: space-between; gap: 1px 6px;
    padding: 4px 7px 5px;
    background: color-mix(in srgb, var(--bg-primary) 78%, transparent);
    border-bottom: 1px solid var(--border-dark);
}
/* 위칸의 이름 — 오른쪽 정렬(접혀도 오른쪽), 넘치면 생략표 */
.hs-name {
    margin-left: auto; min-width: 0; max-width: 100%; flex: 0 0 auto;   /* 이름은 절대 안 줄어든다 (2026-09-09) */
    font-size: var(--fs-sm); font-weight: normal; line-height: 1.3;
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}


.bar { height: 6px; background: var(--bg-input); border: 1px solid var(--border-dark); }
.bar > i { display: block; height: 100%; background: var(--color-info); }
.bar.xp > i { background: var(--xp-fill); }
.bar.hp > i { background: var(--hp-fill); width: 100%; transform-origin: left; }   /* 관전 HP 는 늘이고 줄인다(scaleX) — 폭을 바꾸면 눈금마다 배치를 다시 잰다 (DEV_PLAN §4 #86) */

/* ───────── 원정 ───────── */

/* 행 높이는 **못박는다** [2026-09-10 사용자 지시 · ADR-0080] — 접이식 「구성 보기」를 걷었다고 행이 짧아지면 안 된다.
   109 = 접이식이 있던 시절의 실측 높이(제목 줄 피치 117 − 아래 여백 8). 걷어낸 것이 그 안에서 차지하던 자리는
   요약 줄 20 + 격자 행 간격 12 + 위 여백 2 로 **38px** 였다.
   ⚠ 이 값이 없으면 행이 71px 로 줄어 **배경 아트가 그만큼 잘린다** — 행의 그림은 스테이지를 알아보는 단서다.
   `align-items: center` 라 남는 세로는 글 위아래로 고르게 퍼진다 */
/* **장소 한 줄 = 버튼 하나** [2026-09-29 사용자 지시 · SCREEN_DESIGN §4-1 · ADR-0436 — 같은 날의 칸 버튼 셋(ADR-0429)을 걷고 옛 행 모양으로].
   왼쪽 = 이름 + 잔글씨(레벨 범위 · 소요 · 원소) · 오른쪽 끝 = 잠긴 줄의 자물쇠 + 이유. 칸은 출정 창의 출발 칸 버튼(`.cp-*`)이 고른다 */
/* 줄은 **회색 테두리가 없다** [2026-10-25 사용자 지시 · ADR-0787] — 테두리 자리(1px)는 투명으로 남아 올린 줄 · 고른 줄에서만 밝은 테두리가 선다.
   면 밝기는 손대지 않는다(ADR-0786 의 흰 기운을 되돌렸다) · 왼쪽 죄종 색 띠는 그대로 */
.zone {
    display: grid; grid-template-columns: 1fr auto; gap: 12px; align-items: center;
    min-height: 109px;
    padding: 11px 12px; background: var(--bg-tertiary);
    border: 1px solid transparent; border-left: 3px solid var(--border-secondary);
    margin-bottom: 8px;
}
/* 69.3% = 잘라 낸 사본(2752×1360)에서 원본(×1536)의 60% 와 **같은 띠**가 보이는 값 — 행 그림은 안 바뀐다 (2026-09-11 · 아래 `.arena.has-bg`) */
.zone.has-bg { background-size: cover; background-position: center 69.3%; image-rendering: var(--bg-render); }
/* 칸 I 이 잠긴 장소는 줄째 흐리다 — II · III 의 잠김은 창의 출발 칸 버튼이 든다 (ADR-0436) */
.zone.locked { opacity: .45; }
.zone.boss { border-left-color: var(--text-accent); }
.zone .title { display: flex; align-items: center; gap: 8px; }
.zone .meta { font-size: var(--fs-sm); color: var(--text-muted); margin-top: 2px; }
/* 잠긴 줄의 오른쪽 끝 — 자물쇠 + 왜 잠겼나 한 줄(출발 칸 버튼의 잠긴 모양과 같은 자물쇠) */
.zone-lock { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-sm); color: var(--text-muted); }
.zone-lock .lock-ico { display: inline-flex; flex: 0 0 auto; }
.zone-lock .lock-ico svg { width: 1em; height: 1em; }
/* 부대가 도는 줄의 오른쪽 끝 — ▶ 부대 버튼(`.party-go`)이 부대 번호 순으로 나란히 (ADR-0688) */
.zone-go { display: flex; gap: 8px; }
/* 줄 클릭 = 그 장소의 출정 창 (2026-08-27 · SCREEN_DESIGN §4-1 · ADR-0436).
   커서는 실제로 눌리는 줄에만 준다. 잠긴 줄은 눌러도 플래시뿐이라 안 준다 */
.zone:not(.locked) { cursor: pointer; }
.zone:not(.locked):hover { border-color: var(--border-highlight); }
/* 고른 줄 — 테두리가 혼자 든다 · 창을 닫아도 남는다. ⚠ 옛 `margin-bottom: 0`(접이식이 행 아래 붙던 시절)은 안 되살린다 — 고르면 아래 줄이 당겨 붙었다 */
.zone.on { border-color: var(--border-highlight); background-color: var(--bg-card); }
/* ⚠ 「원정」 칩(`.zone-pick`)은 없다 [2026-09-15 사용자 지시 · ADR-0151] — 고른 줄은 테두리가 혼자 표시한다 */

/* ───────── 출정 창 (SCREEN_DESIGN §4-1 · ADR-0084 · ADR-0088) ─────────
   장소 줄을 누르면 **탭 위에 겹쳐 뜨는 창**이다 — 접이식 전진 패널(`.form-panel` · 2026-08-28~2026-09-10)을 걷었다.
   껍데기(어두운 판 · 가운데 · 정사각 X)는 셸의 창(.modal-layer/.modal-box)을 **그대로** 쓰고 여기서는 크기만 정한다.
   **폭을 못박는 이유**는 판 크기를 내용에 맡기면 상태가 크기를 흔들기 때문이다: 경고 줄의 글자가 있고 없고에 따라
   출정 칸 폭이 바뀌면 창이 통째로 넓어졌다 좁아졌다 한다(「크기는 상태에 흔들리지 않는다」 · 2026-08-28 사용자 지시).
   폭은 1180 → 1280 → 1520(2026-09-10 「탭 자체를 더 키워라」) → 1200 [2026-09-29 사용자 지시 「탭 좌우가 너무 넓어서 좀 줄이고 이야기를 4줄이 아니라 더 늘어나도 되도록」 · ADR-0438]
   → **1300** [같은 날 사용자 지시 「물약을 나중에 4개까지 나오게 할 거니까 미리 4칸 들어갔다고 가정하고 조금만 더 넓게」 · ADR-0441] — 칸이 다 열린 물약 넉 칸이 한 줄에 든다.
   줄어든 폭은 오른쪽 열(이야기 · 들고 가는 것)이 받는다 — 이야기 줄 수에 상한이 없어 창이 그만큼 길어진다(한 장을 넘으면 `.modal-box` 의 창 안 스크롤).
   판 여백은 창 공통(12/14)보다 넉넉하게 준다 — 칸이 넷이다.
   **높이는 칸이 아니라 간격 · 여백으로 키웠다** [2026-09-10 사용자 지시 · ADR-0088] — 칸을 키우면 가로가 같이 커진다.
   ⚠ **선택자가 `.modal-box.depart-box` 인 것이 기능이다** — `.depart-box` 한 단이면 뒤에 선언된 창 공통 `.modal-box` 와 명시도가 같아
     여백이 그쪽(12/14/14)에 덮여 안 먹었다(옛 16/20/20 도). 이 창에서만 한 단 올린다 — `.modal-box` 자체는 안 건드린다 */
/* **배율 .9** [2026-09-11 사용자 지시 · ADR-0099] — 창의 배율은 **창마다 정한다**(창은 한 장 직속이라 메인 배율을 안 물려받는다).
   출정 창은 띠 카드가 **캐릭터 탭 띠와 같은 크기**로 보이게 줄인다 — 메인과 같은 값이지만 묶지 않는다(메인이 바뀌어도 이 창은 제 값).
   폭 1300 · 칸 118 · 여백은 **설계 크기**이고 화면에는 90% 로 선다. 배율 아래서는 보이는 폭과 `offsetWidth` 가 갈린다 —
   진형 드래그 고스트가 그 차를 보정한다(`app.js:bindFormDrag`) */
/* **높이를 한 번 더 키운다** [2026-09-14 사용자 지시 — 「너무 답답해 보인다」] — 이번에도 칸이 아니라 간격으로:
   판 위아래 여백 22/26 → 36/40 · 머리와 속 사이 10 → 24(창 공통 `gap` 을 이 창에서만 덮는다) · 줄 사이 · 칸 이름 아래는 아래 규칙.
   **가로 여백 24 는 그대로다** — 늘리면 오른쪽 열(이야기 · 출정 방식)에 남는 폭이 없어 넘친다 */
/* 위 여백 36 → **24**(가로 여백과 같다) · 머리 아래 **판 전폭 선** [2026-09-21 사용자 지시 「Ch1-1 아래에도 선 쫙 · 위의 빈 공간을 좀 줄여」 · ADR-0288] —
   선은 패널 제목 밑줄(`.panel > h2`)과 같은 색이고 닫기 X 까지 머리 한 줄 전체를 받친다. 선 아래 → 칸 이름까지는 창의 `gap` 24 그대로 */
/* `--dw-gap` = **선 아래 → 칸 이름** 간격 하나 [2026-09-22 사용자 지시 「Party 와 중간선의 높이 차이를 Enemies 와 똑같이」 · ADR-0292] —
   머리 선 → 위 줄 이름(창 `gap`)과 가림막 → 아래 줄 이름(`.dw-r2` 윗 여백)이 같은 값을 읽는다. 둘이 갈라지면 아래 줄 이름만 떠 보인다 */
/* 아래 여백 40 → **28** [2026-09-22 사용자 지시 「표 아래 높이도 12px 감소」] — 그중 `--dw-gap` 만 판이 들고 나머지(4)는 출정 방식 선이 든다
   (선 끝 → 판 아랫변 = 선 위 여백 · ADR-0295 · `.fp-side`). 판 높이는 28 그대로다 */
.modal-box.depart-box { --dw-gap: 24px; width: min(1300px, 100%); padding: 24px 24px var(--dw-gap); gap: var(--dw-gap); zoom: .9; }
.modal-box.depart-box > .modal-head { padding-bottom: 14px; border-bottom: 1px solid var(--border-primary); }
/* 속은 **칸 넷이 격자 하나에 2×2** 다 [2026-09-10 사용자 지시 · ADR-0088 · 자리는 2026-09-21 ADR-0214]
     위 줄   = 적 구성 ↔ 이야기 — 어떤 곳인가 (**읽는 자리 둘**)
     아래 줄 = 편성 ↔ 출정 방식 — 누구를 보내나 ↔ 갈까 (**누르는 자리 둘**)
   열 폭은 **왼쪽 = 초상 넉 장 폭**(`auto` — 적 구성이 정하고 아래의 편성 초상 셋이 그 안에 든다) · **오른쪽 = 남는 폭**이다.
   이야기가 그 남는 폭을 받아 줄 수가 줄고(글이 열을 안 넓힌다 — `.dw-story`), 출정 방식은 제 폭을 든다(`.fp-side`).
   칸 넷이 **격자의 직접 자식**이라 두 줄의 열 경계가 한 세로줄에 맞는다(파티 전술이 이야기와 같은 자리에서 시작한다).
   세로 구분선은 **줄마다 하나** [2026-09-22 사용자 지시 · ADR-0292] — 위 줄은 이야기 칸 왼쪽(`.dw-c2`) · 아래 줄은 출정 방식 왼쪽(`.fp-side`).
   두 선 다 **가림막에 안 닿는다** [2026-09-22 사용자 지시 · ADR-0293] — 칸 이름 높이에서 시작한다.
   **선 위아래 여백이 같다** [2026-09-22 사용자 지시 「세로선 길이를 위의 여백에 맞춰서 아래를 늘려」 · ADR-0295] — 선 윗끝이 위 가로선(머리 선 · 가림막)에서
   `--dw-gap` 떨어지므로 아랫끝도 아래 가로선(가림막 · 판 아랫변)에서 `--dw-gap` 떨어진다.
   `align-items` 는 기본(stretch) — 칸이 줄 높이를 받아 선이 그 줄의 가장 긴 내용까지 서고, 칸 안 내용은 위 정렬 그대로다 */
.dw-body { display: grid; grid-template-columns: auto minmax(0, 1fr); }
/* 가림막 · 여백 — 칸마다 오른쪽 · 아래 여백을 두고, 오른쪽 열(`.dw-c2`)은 왼쪽에 세로선 · 아래 줄(`.dw-r2`)은 위에 가로선을 세운다 */
/* 줄 사이 28 + 28 → **48 + 48** [2026-09-14 사용자 지시 — 「답답해 보인다」 · 위 `.depart-box` 와 같은 날] — 가로선 위아래가 같은 폭이라 선이 두 줄 사이 가운데에 선다.
   가로선은 **칸 이름 밑줄과 함께 선다** [2026-09-21 사용자 지시 「위아래를 나눠야 할 것 같다」 · ADR-0286 — 같은 날 여백만 남겼던 것(ADR-0285)을 되돌렸다] —
   여백만으로는 위 줄(읽는 자리)과 아래 줄(누르는 자리)이 한 덩어리로 붙어 보였다.
   가림막 **아래**는 48 → `--dw-gap` [2026-09-22 사용자 지시 · ADR-0292] — 머리 선 아래와 같은 값이라 선이 아래 줄 쪽에 붙어 선다(머리 선이 위 줄에 붙듯이).
   가림막 **위**는 48 → **42** [2026-09-22 사용자 지시 「가운데선과 아래 내용물을 6px 위로」] — 선 아래 간격(`--dw-gap`)은 그대로라 아래 줄이 선과 함께 오른다.
   위 줄의 이 42 는 **margin `--dw-gap` + padding 나머지(18)** 로 가른다 [2026-09-22 사용자 지시 · ADR-0295] — padding 몫만큼 이야기 칸의 왼쪽 선이 내려가
   가림막 앞 `--dw-gap` 에서 멈춘다(선 윗끝이 머리 선에서 떨어진 거리와 같다). 전부 padding 이면 선이 가림막에 닿는다(ADR-0293) · 합이 42 라 가림막 자리는 그대로다 */
.dw-body > * { padding-right: 26px; padding-bottom: calc(42px - var(--dw-gap)); margin-bottom: var(--dw-gap); }
.dw-body > .dw-c2 { padding-right: 0; padding-left: 26px; border-left: 1px solid var(--border-secondary); }
.dw-body > .dw-r2 { margin-bottom: 0; padding-bottom: 0; padding-top: var(--dw-gap); border-top: 1px solid var(--border-secondary); }
/* 아래 줄 오른쪽 칸은 **왼쪽 선을 안 든다** — 그 줄의 선은 출정 방식 왼쪽에 선다(`.fp-side` · ADR-0292).
   윗 여백은 칸이 든다 — 그래서 출정 방식의 선이 여백 아래(칸 이름 높이)에서 시작해 가림막에 안 닿는다 (ADR-0293) */
.dw-body > .dw-prep { border-left: 0; }
/* 칸 하나 — 이름 + 내용. 지금 이 껍데기를 쓰는 것은 캐릭터 선택(띠) 하나다(나머지 셋은 제 상자가 있다) */
.dw-block { min-width: 0; }
/* ⚠ **띠 카드는 공통 규격 그대로다** [2026-09-10 사용자 지시 — 같은 날의 `max-width: 160px` 특례를 철회] —
   창이 커진 몫은 **적 구성 · 진형 칸**(`--fm-slot`)이 받는다. 띠는 캐릭터 탭과 같은 카드여야 같은 부품으로 읽힌다(§5) */
/* 창 머리 = **고른 스테이지의 신원**. 접이식이던 시절엔 바로 위 행이 말하던 것이라 패널에 머리가 없었는데,
   창은 목록에서 떨어져 뜨므로 여기가 그 자리를 이어받는다. 잔글씨 = 레벨(`stage.csv:dlvl`) · 소요 · 원소 (ADR-0437) */
.dw-title { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; min-width: 0; }
.dw-title small { font-size: var(--fs-sm); font-weight: 400; color: var(--text-muted); }
/* 진형 목업 (SCREEN_DESIGN §4-1) — 랭크 줄은 **항상 3줄**이고, 2랭크 템플릿의 셋째 줄은 빈 줄로 남는다.
   그 빈 줄의 높이를 `min-height` 가 잡는다 — 안 잡으면 템플릿을 바꿀 때 패널이 커졌다 작아져
   「패널 크기는 상태에 흔들리지 않는다」(2026-08-28)가 깨진다.
   라벨 칸에 고정 px 를 안 쓴다 — 영어(Front/Mid/Back)가 한국어보다 길다 */
/* 상자는 **내용에 딱 맞는다** [2026-09-09 사용자 지시 · ADR-0060] — 여백도 구분선도 제목 줄도 없다.
   ⚠ 옛 값(`margin-top`·`padding-top`·`border-top`)은 띠가 이 상자 **위**에 있던 시절 그것과 가르던 선이고,
     띠가 탭 최상단으로 올라가면서(ADR-0055) 위에 아무것도 없게 됐다. 그때 넣었던 `.form-panel > .fm-box:first-child`
     예외는 ADR-0059 로 상자가 `.fp-row` 안으로 들어가며 **선택자가 안 맞게 됐다** — 규칙째 걷는 쪽으로 닫는다.
   ~~`.fm-head`(「진형」 제목 줄)~~ 도 같이 삭제 — 아이콘 셋과 전열/후열 라벨이 이미 무엇인지 말한다 */
/* 상자는 **제 이름을 단다** [2026-09-10 사용자 지시 · ADR-0079 가 ADR-0060 을 대체].
   가림막은 상자가 아니라 **격자가 세운다**(`.dw-body > .dw-r2` · ADR-0088) — 칸 넷이 같은 규칙으로 갈린다 */
.fm-box {
    margin: 0;
    flex: 0 0 auto;
}
/* 왼쪽 = 템플릿 아이콘 · 오른쪽 = 보드. 덩어리는 **패널 왼쪽에 붙는다**
   [재개정 2026-09-09 사용자 지시 · ADR-0059 — 같은 날의 「가운데로」(ADR-0057)를 물렸다]:
   비어 있던 오른쪽 자리를 **출발 칸**이 받으므로 진형은 왼쪽에 서는 것이 맞다.
   ⚠ 옛 판은 아이콘을 **세로 가운데**에 뒀다(「위로 붙이면 아이콘 아래가 텅 빈다」) — 2026-09-10 에 걷었다:
     그 열이 이제 **이름 + 아이콘**을 들고, 이름은 옆 칸(출정 방식)의 이름과 **같은 줄**에 서야 한다.
     가운데 정렬이면 열 전체가 내려가 두 이름이 어긋난다 (ADR-0080) */
.fm-main { display: flex; align-items: flex-start; gap: 28px; }   /* 모양 버튼 열 ↔ 보드 — 버튼이 넓어지며 20 → 28 (2026-09-21 사용자 지시) */

/* 진형 모양 = **세로 버튼 셋 · 이름을 글로** [2026-09-21 사용자 지시 · ADR-0267 — 점 아이콘 가로 줄(2026-09-09)을 걷었다].
   이름은 표(`formation_template.csv`)가 든다 — 새 i18n 키가 없다. 폭은 **가장 긴 이름에 맞춰 같다**(열이 이름 폭으로 서고 버튼이 그 폭을 편다 —
   고정 px 이 아니라서 영어가 길어도 안 깨진다). 셋의 높이는 보드(칸 + 한 단 + 라벨) 안에 든다.
   셋 중 하나를 고르는 것이라 .toggle(초록 ON/OFF)이 아니라 .on(고른 것)을 쓴다 */
.fm-tpls { display: flex; flex-direction: column; gap: 6px; }
/* 버튼 폭은 이름보다 **한 단 넉넉하게**(`min-width` — em 이라 글꼴을 따른다 · 가장 긴 이름이 더 길면 그 폭) [2026-09-21 사용자 지시 「버튼 넓이를 좀 더 늘리고
   Formation 넓이를 맞춰서」] — 진형 칸 · 왼쪽 열은 내용 폭이라 버튼이 넓어진 만큼 저절로 는다(물약도 같은 열 폭을 받는다) */
.fm-tpl { min-width: 9.5em; text-align: left; white-space: nowrap; }
.fm-tpl.on { border-color: var(--border-highlight); background: var(--surface-6); color: var(--text-primary); }

/* 보드 — **높이가 고정**이라 템플릿을 바꿔도 「보내기」의 자리가 안 움직인다 (2026-08-28).
   랭크 최대가 둘(2·1 · 1·2)이므로 두 줄분으로 못박고, 한 줄짜리(3)는 그 안에서 **가운데**에 선다.
   줄 높이는 칸 한 변으로 고정 — 줄 수가 칸 크기를 바꾸지 않는다(칸은 언제나 얼굴 크기다).
   라벨은 칸 아래에 서므로 폭은 칸이 준다 — 영어(Front/Back)가 길어도 칸 폭 안이다 */
/* 보드 = **칸 한 줄** [2026-09-21 사용자 지시 · ADR-0234] — 세로로 쌓던 랭크 줄을 걷었다. 왼쪽 라벨 열도 걷었다 — 라벨은 칸마다 아래다(ADR-0269).
   높이가 `칸 + 단 + 라벨` 로 못박혀 템플릿을 바꿔도 패널이 안 흔들린다 */
.fm-board {
    display: flex; align-items: flex-start; gap: 10px;
    min-width: 0; height: var(--fm-board-h);
}
/* 자리 = **칸 + 그 칸의 랭크 라벨** [2026-09-21 사용자 지시 「Front 와 Back 글씨를 영웅의 아래에」 · ADR-0269] — 한 몸이라
   뒤 랭크가 한 단 내려가면 라벨도 같이 내려간다. 라벨은 칸 가운데 아래 · 빈 칸도 단다(놓기 전에 전열인지 후열인지 읽힌다) */
.fm-seat { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; gap: 4px; }
.fm-label { font-size: var(--fs-xs); line-height: 1.2; color: var(--text-secondary); white-space: nowrap; }
/* 칸은 **정원 최대(3칸) 폭의 축 위에서 가운데 정렬**된다 (2026-09-09 · ADR-0057) — 폭을 늘 3칸으로 잡아 두므로
   템플릿을 바꿔도 축이 안 흔들린다. 랭크는 **한 줄 안의 어긋남**이 말한다 [2026-09-21 · ADR-0234] —
   가로 차례는 렌더러가 관전과 같은 식(`x = (i + 0.5) / k`)으로 이미 정해 놓았다 */
.fm-line { display: flex; align-items: flex-start; justify-content: center; gap: 7px; width: var(--fm-axis); height: 100%; }
/* 뒤 랭크만 물러선다 — 관전(`.side-party .unit-slot[data-rank]`)과 같은 규칙 · 랭크가 하나뿐이면(일자) 아무도 안 내려간다.
   단은 자리(칸 + 라벨)가 받는다 — 라벨이 제 칸을 따라간다 (ADR-0269) */
.fm-line > .fm-seat[data-rank="1"] { margin-top: var(--fm-step); }
.fm-line > .fm-seat[data-rank="2"] { margin-top: calc(var(--fm-step) * 2); }

/* 칸은 정사각이고 높이를 줄에서 받는다 — 영웅 띠 카드와 같은 크기라
   빈 칸이 「여기에 영웅을 놓는다」로 크기만으로 읽힌다 */
.fm-cell {
    /* 칸 한 변은 **`--fm-slot` 자신**이다 [2026-09-21 · ADR-0234] — 줄 높이에서 뽑던 옛 식(`height: 100%` + `aspect-ratio`)은
       줄이 칸 높이였을 때의 것이라, 보드가 `칸 + 단` 높이가 된 지금은 칸이 그 단만큼 커져 축을 넘친다.
       flex 가 줄이지 못하게 0 0 auto 로 못박는다(안 그러면 칸이 납작해진다) */
    flex: 0 0 auto; width: var(--fm-slot); height: var(--fm-slot); position: relative; overflow: hidden;
    border: 1px dashed var(--border-secondary); background: var(--bg-secondary);
}
.fm-cell.filled {
    border: 1px solid var(--border-dark); border-top: 3px solid var(--border-secondary);
    background: var(--bg-tertiary);
    /* 드래그가 이 칸의 동사다 · touch-action 을 끊어야 포인터 이동이 스크롤로 안 샌다 */
    cursor: grab; touch-action: none;
}
.fm-cell.filled:hover { border-color: var(--border-highlight); }
.fm-cell.drag { opacity: .35; cursor: grabbing; }
.fm-cell .hero-face { width: 100%; height: 100%; border: 0; background: var(--bg-input); }
/* 칸 위의 글자는 **영웅 띠 카드의 조각 그대로**다 [2026-09-21 사용자 지시 · ADR-0280] — 위칸 `.hs-band`(하는 일 · 이름) ·
   오른쪽 아래 `.hs-lv` · 왼쪽 아래 `.hs-leader`. 이름 하나만 들던 보드 전용 띠(.fm-nm)는 걷었다 — 같은 크기의 카드가 두 벌 규칙을 갖지 않는다 */
/* 드래그 고스트 — 커서를 따라다니는 **감싸개**이고 안에 클론 하나가 든다 [2026-09-11]. 놓을 자리 판정(elementFromPoint)을 가리면 안 되므로 클릭을 안 받는다.
   위치 규칙은 감싸개에만 건다 — 클론에 달면 뒤에 선언된 `.hs-card { position: relative }` 가 이겨 띠에서 끈 고스트가 한 장 밖으로 떨어진다(`app.js:bindFormDrag`).
   툴팁(z-index 50)보다는 아래 */
.fm-ghost { position: fixed; z-index: 45; pointer-events: none; cursor: grabbing; opacity: .9; }

/* 같은 크기 버튼 둘 — 반복 원정 / 보내기 */
/* 칸 이름 여섯은 **소제목**이다 [2026-09-21 사용자 지시 「Enemies 아래에 선이 없다 · 다른 화면들과 비슷하게」 · ADR-0285] —
   모양은 `.panel > h2, .sub-h` 한 규칙이 든다(편성 탭 「진형 · 물약 · 파티 전술」과 같다 · ADR-0241 · ADR-0256). 여기는 자리만:
   왼쪽 위 · 밑줄은 그 묶음 폭만큼 · 밑줄 아래 내용까지 20(편성 탭 소제목과 같다) */
.depart-box .sub-h { margin: 0 0 20px; white-space: nowrap; }
/* 진형의 이름은 **왼쪽 열 맨 위**다 [2026-09-10 사용자 지시 · ADR-0080] — 상자 위에 얹으면 그 줄 높이가
   패널에 그대로 더해져 창이 세로로 커졌다. 이 열(템플릿 아이콘 셋)은 보드보다 한참 짧아 위가 비어 있으므로
   거기 얹으면 **세로 비용이 0** 이고 이름이 보드와 같은 줄에 선다 */
/* 모양 버튼 열은 **위아래 빈자리가 같게** 선다 [2026-10-09 사용자 지시 · ADR-0577 — 위 정렬을 걷었다] —
   「진형」 밑줄 ↔ 첫 버튼 = 끝 버튼 ↔ 「물약」 이름. 보드 높이가 고정이라 열을 보드 세로 가운데에 세우면 거의 맞고,
   밑줄 아래 여백(`--fm-head-gap`)과 물약까지의 여백(`--pt-left-gap`)의 차만큼 위에 더 얹어 둘을 맞춘다
   (가운데 정렬은 여백 상자째 가운데에 두므로 차의 절반씩 갈린다). 템플릿을 바꿔도 보드 높이가 같아 안 흔들린다.
   옛 위 정렬은 이 상자가 출정 창에서 「출정 방식」과 이름 줄을 맞추던 시절 것이다 */
.fm-side {
    display: flex; flex-direction: column; justify-content: flex-start;
    align-self: center; margin-top: calc(var(--pt-left-gap, 0px) - var(--fm-head-gap, 0px));
}
/* **가로 한 줄** — 넷이 나란히 선다 [2026-09-10 사용자 지시]. 세로로 쌓은 판을 걷었다:
   칸이 진형보다 높아져 패널을 통째로 늘렸는데, 정작 이 칸이 쓰라고 비어 있던 자리는 **가로**였다.
   칸 사이는 진형과 같은 7px — 두 덩어리가 같은 리듬으로 서야 마주 놓인 것으로 읽힌다 */
/* **자리는 늘 넷만큼 잡는다** [2026-09-11 · ADR-0098] — 보통 스테이지는 일반 셋 + 보스 하나지만 챕터보스 스테이지는 보스 칸 하나뿐이다.
   칸 수에 폭을 맡기면 오른쪽 열(= 세로 구분선의 자리 · ADR-0088)이 스테이지마다 줄었다 늘었다 해서 그 선에 붙은 「보내기」가 옮겨 다닌다 (104 ↔ 105 실측) */
.foe-list { display: flex; align-items: center; gap: 7px; min-width: calc(var(--fm-slot) * 4 + 7px * 3); }
/* 칸은 **진형 칸과 같은 크기·같은 정사각**이다 [2026-09-10 사용자 지시] — `--fm-slot` 을 그대로 읽으므로
   진형 칸이 커지면 이 칸도 같이 커진다(두 값이 갈라지면 「마주 놓는다」가 깨진다).
   생김새도 `.fm-cell.filled` 를 따른다: 얇은 테두리 + **윗변 3px** · 그림이 칸을 통째로 덮는다.
   ⚠ 원형(`.face`)이 아니다 — 몬스터를 정사각으로 그리는 자리는 관전 유닛 카드가 이미 있다(ADR-0022).
      도감 · 접이식 「구성 보기」의 원형은 그대로다 */
/* 윗변 = **일반 몬스터의 등급 색** — 영웅 · 장비의 일반과 **같은 밝은 회색**이다 [2026-09-14 사용자 지시].
   같은 「일반」이 짙은 회색(몬스터) · 흰색(영웅 · 장비)으로 갈려 있었다. 공용 토큰 `--border-secondary` 를 바꾸지 않고
   이 칸에만 준다(그 토큰은 다른 테두리도 쓴다). 값은 `data/hero_tier.csv:normal` · `ui/mock.js:RARITY.normal` 과 **같다 — 하나를 바꾸면 셋 다** */
.foe-cell {
    position: relative; overflow: hidden; flex: 0 0 auto;
    width: var(--fm-slot); height: var(--fm-slot);
    background: var(--bg-tertiary);
    border: 1px solid var(--border-dark); border-top: 3px solid #D8D8D8;
}
.foe-cell img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 보스는 **윗변 색**이 든다 — 등급을 윗변이 말하는 것은 관전 카드와 같은 문법이다 (ADR-0021) */
.foe-cell.boss { border-top-color: var(--text-accent); }
/* 무덤 명패 — 죽어 있는 챕터보스의 초상 자리 [2026-10-10 사용자 지시 · SCREEN_DESIGN §4-2 「무덤 명패」 · ADR-0590].
   **비석 그림 한 장**(.grave-stone)이다 [2026-10-13 사용자 지시 · ADR-0611] — 일곱 챕터보스가 같은 그림이고 앞면의 흰 비문도 그림이다(읽히는 글자가 아니다 · ADR-0614).
   명패(.grave-plaque)는 칸을 가득 채우는 틀이고, 그림은 칸 높이를 채우는 정사각 · 남은 초는 칸 오른쪽 아래 구석에 선다.
   관전 카드(.sprite.grave)와 출정 창 적 칸(.foe-cell.grave)이 같이 쓴다 */
.grave-plaque { position: absolute; inset: 0; }
.grave-stone {
    position: absolute; left: 50%; bottom: 0; height: 100%; aspect-ratio: 1; transform: translateX(-50%);
    background: url('../assets/art/grave/tombstone.webp') center / contain no-repeat;
}
/* 남은 초 — 비석 밖 **칸 오른쪽 아래 구석** [2026-10-13 사용자 지시 「초를 다른곳으로 빼볼까」 · ADR-0614].
   초상의 레벨(.hs-lv)과 같은 문법 · 같은 구석 — 판 없이 검은 테두리를 두른 작은 글자 */
.grave-left {
    position: absolute; right: 4px; bottom: 3px; z-index: 1;
    font-size: var(--fs-xs); line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-secondary); white-space: nowrap;
    text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000;
}
.foe-cell.grave { background: var(--bg-input); }
.foe-cell.grave .grave-stone { height: 80%; }   /* 위 이름 띠(.hs-band) 아래에서 선다 — 띠에는 그림 위 여백 · 뿔 끝만 걸린다 */
/* 초상 + 그 아래 스킬 칸 줄 = **한 몸** [2026-10-09 사용자 지시 · SCREEN_DESIGN §4-1 · ADR-0568] — 적 구성 · 편성 초상이 같이 쓴다.
   폭은 초상 한 변이라 적 넷 ↔ 영웅 셋이 위아래로 마주 서는 열이 그대로다 */
.dw-seat { flex: 0 0 auto; display: flex; flex-direction: column; gap: 5px; width: var(--fm-slot); }
/* 칸 줄 — 관전 카드의 쿨 칸 줄(`.cd-list`)과 같은 문법. 칸은 초상 한 변을 나눠 갖는 정사각이다(칸 수는 렌더러가 `active_slots` 로 세운다) */
.dw-sk { display: flex; gap: 4px; }
.dw-sk.ghost { visibility: hidden; }   /* 빈 편성 자리 — 높이만 잡는다 */
.dw-sk-cell {
    flex: 1 1 0; min-width: 0; aspect-ratio: 1; position: relative; overflow: hidden;
    display: flex; align-items: center; justify-content: center;
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
.dw-sk-cell img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
.dw-sk-cell.empty { background: transparent; border-style: dashed; border-color: var(--border-primary); }   /* `.cd-slot.empty` 와 같다 */
.dw-sk-cell.rolled { font-size: var(--fs-md); color: var(--text-secondary); }   /* 보스가 스폰 때 굴리는 칸 = 「?」 */
/* 이름은 **칸 안의 위 띠**가 든다 — 편성 초상의 위칸과 같은 조각(`.hs-band` · `.hs-name`)이고 칸 폭에서 말줄임된다 [2026-10-09 사용자 지시 · ADR-0568].
   칸 밖에 이름을 적던 판(2026-09-10 이전)은 Ch7-4 `Grand Gargoyle Thronekeeper`(27자)가
   한 줄로 뻗어 하한 1280 에서 **보내기 버튼을 화면 밖으로 밀고 가로 스크롤을 만들었다** (실측) — 띠는 칸 폭을 안 넘는다.
   칸 크기는 아래 `.foe-cell` 이 진형에서 받아 온다 */
/* 아래 줄 오른쪽 칸 = **들고 가는 것(전술 · 물약) → 출정 방식** [2026-09-21 사용자 지시 · ADR-0216 — 옛 「출정 방식 하나」는 ADR-0214].
   왼쪽 묶음은 읽는 자리(전술 효과 · 물약 칸)이고 출정 방식은 **칸 오른쪽 끝**에 붙는다 — 눈이 「무엇을 들고」 → 「보낸다」 순으로 흐른다.
   **위 정렬** — 칸 이름 셋이 아래 줄 편성 이름과 한 줄에 선다 (ADR-0079 · ADR-0080) */
.dw-prep { display: flex; align-items: flex-start; justify-content: space-between; gap: 26px; }
/* 왼쪽 묶음 — 전술(남는 폭) · 물약(제 폭). 둘 다 **읽기 전용**이라 커서도 안 바꾼다 */
.dw-load { display: flex; align-items: flex-start; gap: 26px; flex: 1 1 auto; min-width: 0; }
/* 전술 묶음은 **제 폭을 못박는다** — 효과 글 길이(리롤 · 언어)가 옆의 물약 칸 자리를 흔들면 안 된다.
   라벨이 드는 칸이라 고정 px 가 아니라 `clamp()` (§4-1 「크기는 상태에 흔들리지 않는다」).
   13em(상한 210) → **12em(상한 180)** [2026-09-29 · ADR-0438] — 창 폭 1200 에서 이 칸(전술 + 물약 + 출정 방식)이 받는 폭은 설계 606 이다.
   옛 폭(195 + 26 + 물약 넉 칸 172 + 26 + 327 = 746)이면 물약 칸이 출정 방식 밑으로 파고들었다(실측 — 2칸에서도 25px 겹쳤다).
   창 폭 1300 [ADR-0441] 에서 받는 폭은 706 이고 이 값 그대로 넉 칸 한 줄이 든다 — 180 + 26 + 172 + 26 + 287 = 691 */
.dw-tac { flex: 0 0 clamp(150px, 12em, 180px); min-width: 0; }
/* 효과 한 줄 — 효과 글 + 카운터. **조건을 못 채운 칸은 흐리다** — 칸 격자(편성 탭)의 켜짐/꺼짐을 진하기 하나로 줄인 것이다 */
.dw-tac-row { display: flex; align-items: baseline; gap: 8px; margin-bottom: 6px; opacity: .4; }
.dw-tac-row.on { opacity: 1; }
/* 물약 칸 — 아레나 칸(`.b-belt .p-slot` 34)과 편성 탭 칸(44) 사이. 창 배율(.9) 아래서 편성 탭 칸과 비슷하게 보인다 */
.dw-pot .p-slot { width: 40px; height: 40px; }
.dw-pot .p-slot.short { opacity: .4; border-style: dashed; }
/* 물약 칸은 **한 줄**이다 [2026-09-29 사용자 지시 · ADR-0441 — 같은 날의 「두 칸씩 줄」(ADR-0438)을 걷었다] — 창 폭을 칸이 다 열린 넉 칸(172)이 한 줄로 드는 값으로 잡았다.
   줄바꿈 규칙이 따로 없다 — 공용 `.p-belt` 의 가로 줄 그대로다 */
/* **출정 방식** — 이름 + 출발 칸 + 경고 + 버튼 둘. **폭은 못박는다** — 옛 자리에서는 열(적 구성 내용 폭)이 정했는데,
   제 폭이 없으면 경고 줄의 글자가 폭을 흔들어 버튼이 옆으로 옮겨 다닌다(「크기는 상태에 흔들리지 않는다」 · 2026-08-28).
   라벨이 드는 칸이라 고정 px 가 아니라 `clamp()` — 상한은 진형 옆에 남는 폭이다 */
/* **왼쪽에 세로 구분선** [2026-09-22 사용자 지시 「아래 선 빼 버리고 Departure 옆에」 · ADR-0292] — 들고 가는 것(읽는 자리)과 보내는 자리를 가른다.
   `align-self: stretch` 라 선이 **칸 이름 높이부터 격자 끝까지** 선다 — 가림막에는 안 닿는다(위 줄 선과 같은 문법 · ADR-0293).
   선 · 여백 몫(26 + 1)은 폭에 **더한다** — 빼면 버튼이 그만큼 좁아진다.
   아래 padding = 판 아래 여백 28 에서 `--dw-gap` 을 뺀 몫 [2026-09-22 사용자 지시 · ADR-0295] — 선이 보내기 아래로 그만큼 더 내려가 판 아랫변 앞 `--dw-gap` 에서 멈춘다.
   폭 20em(상한 300) → **17em(상한 260)** [2026-09-29 · ADR-0438] — 창 폭 1200 에서 전술 · 물약과 한 줄에 들게 줄였다(`.dw-tac` 위 주석의 셈) */
.fp-side {
    display: flex; flex-direction: column; align-items: stretch; gap: 10px;
    flex: 0 0 calc(clamp(240px, 17em, 260px) + 27px); align-self: stretch;
    padding-left: 26px; padding-bottom: calc(28px - var(--dw-gap)); border-left: 1px solid var(--border-secondary);
}
/* 이 칸의 이름은 아래 여백을 **flex `gap`(10) 만큼 덜** 준다 — 옆 칸 이름 아래(20)와 합이 같아야 내용의 윗선이 옆 칸과 맞는다 */
.fp-side .sub-h { margin-bottom: 10px; }
/* 출발 칸 줄 — 출정 방식 칸 맨 위 [2026-09-29 사용자 지시 · SCREEN_DESIGN §4-1 · ADR-0437 — 위험도 줄(ADR-0104)을 걷은 자리].
   윗줄 잔글씨 라벨 · 아랫줄 칸 버튼 셋. **자리는 늘 셋 · 같은 폭**(`repeat(3, minmax(0, 1fr))`) — 칸이 하나인 장소(챕터보스)도
   빈 자리 둘(`.cp-void`)이 폭을 잡아 버튼 폭이 장소마다 안 흔들린다. 라벨 칸이라 고정 px 이 아니다(영어 「Chapter Boss」가 한 칸 폭을 넘으면 두 줄로 접힌다) */
.cp-box { display: flex; flex-direction: column; gap: 4px; }
.cp-h { font-size: var(--fs-sm); color: var(--text-secondary); white-space: nowrap; }
.cp-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
/* ⚠ 선택자는 `.btn.sm.cp-btn` — 한 단(`.cp-btn`)이면 공용 `.btn.sm { padding }` · `.btn.sm.on`(클래스 둘 · 셋)에 져서 안 먹는다(`.go-tree` 와 같은 사정) */
.btn.sm.cp-btn { min-width: 0; display: inline-flex; align-items: center; justify-content: center; gap: 5px; padding: 5px 4px; line-height: 1.2; text-align: center; }
/* 고른 칸 — 강조색 테두리 + 밝은 글자(공용 `.btn.sm.on` 은 한 단 밝아질 뿐이라 안 보였다 — 대장간 작업 탭과 같은 처방 · 2026-09-21) */
.btn.sm.cp-btn.on { color: var(--text-primary); border-color: var(--text-accent); }
/* 잠긴 칸 — 흐리고 자물쇠. 눌러도 플래시뿐이라 커서를 안 준다 · 이유는 툴팁 한 줄(`tip-mini`) */
.cp-btn.locked { opacity: .45; cursor: default; }
.cp-btn.locked:hover { border-color: var(--border-secondary); background: var(--bg-tertiary); }
.cp-btn .lock-ico { display: inline-flex; flex: 0 0 auto; }
.cp-btn .lock-ico svg { width: 1em; height: 1em; }
/* 버튼 줄 — 자동 분해 창의 레벨 선(§6)이 쓴다(옛 위험도 줄의 모양 · 위험도는 2026-09-29 폐지 · ADR-0437).
   버튼과 숫자는 **한 무리로 가운데에 모인다** — 숫자가 칸 폭을 먹으면 버튼이 양끝으로 벌어져 한 조절기로 안 읽힌다 */
.lv-row { display: flex; align-items: center; justify-content: center; gap: 4px; }
.lv-btn { flex: 0 0 auto; min-width: 2.2em; text-align: center; }
.lv-val { flex: 0 0 auto; min-width: 3em; text-align: center; font-size: var(--fs-lg); color: var(--text-primary); font-variant-numeric: tabular-nums; }
/* 켠 값 — 강조색 */
.lv-val.up { color: var(--text-accent); }
/* 세로로 쌓이던 시절의 윗 여백을 걷는다 — 이제 제 칸 안에서 경고 줄 바로 밑이다 */
/* 버튼 둘은 **세로로 쌓는다** [2026-09-10 사용자 지시] — 가로로 나란하던 것을 세웠다.
   `stretch` 라 둘의 폭이 저절로 같아진다(옛 `min-width: 148px` 는 가로 배치에서 크기를 맞추던 값이라 하한으로만 남긴다) */
.form-actions { display: flex; flex-direction: column; align-items: stretch; gap: 8px; }
.form-actions .btn.lg { flex: 0 0 auto; min-width: 148px; text-align: center; }
/* 위 줄 오른쪽 = **이야기** [2026-09-21 사용자 지시 · ADR-0214 — 칸의 속은 ADR-0105] — 이 스테이지의 입장 텍스트. 읽는 자리라 클릭이 없다.
   **크기 격리는 가로만**(`contain: inline-size`) — 글이 열을 넓히지는 않고(폭은 왼쪽 열이 쓰고 남는 폭) **줄 높이는 글이 정한다**.
   ⚠ 세로까지 묶던 옛 값(`contain: size`)은 **아래 줄에 있던 시절** 것이다 — 같은 줄의 짝(출정 방식)이 줄 높이를 넉넉히 세워 줬다.
   위 줄의 짝은 초상 한 줄(적 구성)이라 그대로 두면 긴 글이 반 넘게 잘린다(영어가 더 길다) */
.dw-story { contain: inline-size; overflow: hidden; }
.dw-story-text { margin: 0; font-size: var(--fs-md); line-height: 1.7; color: var(--text-primary); word-break: keep-all; white-space: pre-line; }

.running {
    background: linear-gradient(var(--bg-tertiary), var(--bg-card));
    border: 1px solid var(--border-secondary);
    padding: 14px 16px; margin-bottom: 14px;
}
.running .head { display: flex; justify-content: space-between; margin-bottom: 10px; }

.party-slot {
    display: flex; align-items: center; gap: 10px;
    padding: 9px 10px; background: var(--bg-tertiary);
    border: 1px solid var(--border-dark); margin-bottom: 6px;
}
.party-slot.empty { justify-content: center; color: var(--text-muted); border-style: dashed; }
/* "Archer · Lv.8" 이 중간에서 접히면 가운뎃점만 앞줄에 남는다 — 통째로 넘긴다 */
.party-slot .lv { font-size: var(--fs-sm); color: var(--text-muted); white-space: nowrap; }

/* ───────── 로스터 ───────── */

/* (선술집 로스터 격자 .hero-grid/.hero-card 는 2026-08-26 공통 영웅 띠로 대체 — 삭제) */

/* ───────── 장비 ───────── */

.slot-row {
    /* 죄종 칩 열은 고정폭이면 영어 "Gluttony" 가 잘린다 — 내용에 맞춰 늘어나게 */
    display: grid; grid-template-columns: minmax(44px, auto) minmax(0, 1fr); gap: 9px; align-items: center;
    padding: 7px 9px; background: var(--bg-tertiary);
    border: 1px solid var(--border-dark); margin-bottom: 5px;
}
.slot-row.on { border-color: var(--border-highlight); }
.slot-row .slot-label { font-size: var(--fs-sm); color: var(--text-muted); }
.slot-row .item-name { font-size: var(--fs-sm); word-break: keep-all; }
.slot-row.vacant .item-name { color: var(--text-muted); }

.stat-table { width: 100%; font-size: var(--fs-sm); border-collapse: collapse; }
.stat-table td { padding: 3px 0; }
.stat-table td:last-child { text-align: right; color: var(--text-primary); }
.stat-table td:first-child { color: var(--text-secondary); }
.stat-table tr.sep td { border-top: 1px solid var(--border-dark); padding-top: 8px; }

/* 접사 죄종 태그 — 세트포인트가 아니다 (세트효과 보류, item_design §4). 수는 죄종 접사 수 */
.sin-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.sin-tag {
    font-size: var(--fs-xs); padding: 1px 7px; border: 1px solid currentColor;
    display: inline-flex; align-items: center; gap: 5px;
}
.sin-tag b { font-weight: normal; }

.inv-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 7px; }
.inv-item {
    background: var(--bg-tertiary); border: 1px solid var(--border-dark);
    padding: 8px 10px; cursor: pointer; position: relative;
}
.inv-item:hover { border-color: var(--border-highlight); background: var(--surface-3); }
.inv-item .n { font-size: var(--fs-sm); word-break: keep-all; }
.inv-item .s { font-size: var(--fs-xs); color: var(--text-muted); margin-top: 2px; }

/* 비교 툴팁 — 장비 게임의 핵심 UI */
/* ⚠ **`pointer-events: none` 이 기능이다** [2026-09-10 버그 수정] — 툴팁은 z-index 50 으로 **드래그 고스트(45)보다도 위**라,
   이게 없으면 진형 드래그의 놓을 자리 판정(`app.js:bindFormDrag` 의 `elementFromPoint`)이 **툴팁을 먼저 집는다**.
   증상이 자리마다 갈렸던 이유는 `moveTip` 이 커서 오른쪽 아래(+16,+16)에 띄우다가 **화면 아래에 닿으면 위로 접기** 때문이다 —
   접힌 순간에만 툴팁이 커서 지점을 덮어서 그 자리에서만 드롭이 죽었다. 기본은 그대로 두고 **Alt 로 붙든 영웅 툴팁만**
   아래 `.interactive` 로 포인터를 받는다 (ADR-0176) */
.tooltip {
    position: fixed; z-index: 50; display: none; pointer-events: none;
    background: var(--bg-secondary); border: 1px solid var(--border-secondary);
    padding: 0; box-shadow: 0 6px 24px rgba(var(--shadow-rgb),.75);
    max-width: 640px;
}
.tooltip.show { display: flex; }
.tooltip.interactive { pointer-events: auto; }
/* 손가락 툴팁의 버튼 줄 [2026-09-27 · ADR-0374] — 툴팁 **아래 바깥**에 매달린다(`absolute` 라 툴팁의 flex 줄에 안 끼고, 상자를 걷는 비교 툴팁에도 같다).
   아래 넘침 보정은 `tip.js:moveTip` 이 이 높이까지 잰다(간격 6 도 거기와 같다). 한 장 단위라 폰 가로(배율 약 0.5)에서도 손가락이 닿게 크게 둔다 */
.tip-touch { position: absolute; left: 0; top: calc(100% + 6px); display: flex; gap: 8px; }
.tip-touch .btn { min-height: 52px; min-width: 120px; padding: 6px 18px; font-size: var(--fs-lg); background: var(--bg-secondary); }
.tip-touch .btn.on { border-color: var(--border-highlight); background: var(--surface-6); }
/* Alt + 영웅 장비 hover의 기존 아이템 카드(ADR-0182) — 부모 영웅 툴팁과 별도라 붙였다 떼도 장비 칸이 움직이지 않는다. */
.equipment-item-tooltip { z-index: 51; pointer-events: none; }
.tip-card { width: 304px; padding: 11px 13px; font-size: var(--fs-sm); }
/* 한 줄 툴팁 — 폭이 글자만큼이다 (잠긴 스킬 칸 「Level n+」 · 2026-09-29 사용자 「가로 넓이 줄여」 · ADR-0428) */
.tip-card.tip-mini { width: max-content; padding: 6px 10px; }
.tip-card.tip-mini .tip-name { margin: 0; }
.tip-card + .tip-card { border-left: 1px solid var(--border-dark); background: var(--bg-input); }
/* 아이템 비교 두 장 (SCREEN_DESIGN §6 · ADR-0337 · ADR-0339) — 두 장이 **따로 선 상자**다: 툴팁 상자를 걷고 카드가 상자를 든다.
   순서는 DOM 그대로 `착용 중 | VS | 이 아이템` — 툴팁이 커서 왼쪽으로 접혀도 뒤집지 않는다(2026-10-21 · ADR-0690 — ~~접히면 row-reverse~~ ADR-0337).
   두 장은 **기본 상태부터** 선다 — 카드 · VS 를 묶음(`.tip-compare`)이 들고, 묶음은 상자가 없어(`contents`) 셋이 그대로 툴팁 줄의 항목이다 ·
   두 장은 늘 같은 키(긴 쪽 — 줄의 기본 정렬)다. Alt 동안엔 「이 아이템」 카드에 착용 델타가 서서 아랫변만 내려간다 (ADR-0658) */
.tip-compare { display: contents; }
.tooltip:has(> .tip-compare > .tip-vs) { background: none; border: 0; box-shadow: none; max-width: none; }
.tooltip:has(> .tip-compare > .tip-vs) > .tip-compare > .tip-card {
    background: var(--bg-secondary); border: 1px solid var(--border-secondary);
    box-shadow: 0 6px 24px rgba(var(--shadow-rgb),.75);
}
/* Alt 때 모양의 「이 아이템」 카드 사본 (ADR-0658 · 취지는 ADR-0450) — 안 보이고 툴팁 줄에도 안 낀다(`absolute` — 줄에 끼면 두 장이 이 키로 늘어 바닥이 빈다).
   `tip.js:moveTip` 이 아래 넘침 보정에 이 키까지 재서 Alt 로 델타가 서도 툴팁이 위로 안 뛴다 */
.tip-ghost { position: absolute; left: 0; top: 0; visibility: hidden; }
/* 손가락 버튼 줄은 「이 아이템」 카드 아래 — 비교 툴팁은 그 카드가 언제나 오른쪽 끝이다(왼쪽 끝은 착용품 카드 · ADR-0690) */
.tooltip:has(> .tip-compare > .tip-vs) > .tip-touch { left: auto; right: 0; }
/* VS — 틈은 좁고(`width`), 원정 관전과 같은 **글자만** 그 **위**에 떠 두 장의 가장자리에 겹친다(ADR-0339 · 상자 없음 ADR-0340).
   글자는 틈보다 넓지만 **카드 안 여백(13px)까지만** 걸친다 — 가장자리의 값 열을 가리지 않는다. 세로는 두 장의 가운데.
   그림자는 카드 바탕색 번짐이다 — 글자 밑을 지나는 두 카드의 테두리 선만 지운다(가장자리가 없어 네모로 안 읽힌다) */
.tip-vs { position: relative; width: 8px; }
.tip-vs span {
    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); z-index: 1;
    margin-left: 1px;   /* 끝 글자 뒤 자간(2px)의 절반 — 글자가 가운데에 선다 */
    font-size: var(--fs-xs); letter-spacing: 2px; line-height: 1; white-space: nowrap; color: var(--text-muted);
    text-shadow: 0 0 3px var(--bg-secondary), 0 0 3px var(--bg-secondary), 0 0 2px var(--bg-secondary);
}
.tip-card .tip-head { font-size: var(--fs-xs); color: var(--text-muted); margin-bottom: 5px; letter-spacing: 1px; }
/* 「착용 중」 칩 (SCREEN_DESIGN §6 · ADR-0659 · 모양 ADR-0662) — 죄종 칩(`.sin-chip`)과 같은 결: 글자색 1px 테두리 · 모서리 2px · 바탕 없음.
   글씨만 가장 밝게 굵게 — 흐린 맨글자 「이 아이템」과 갈린다. 테두리는 안쪽 그림자다: 머리글 줄은 flex 라 `border` 를 주면
   착용품 카드만 2px 높아져 두 장의 줄이 어긋난다 · 오른쪽 여백은 끝 글자 뒤 자간(1px)만큼 덜어 글자가 가운데에 선다 */
.tip-card .tip-head .tip-worn {
    padding: 0 5px 0 6px; border-radius: 2px; box-shadow: inset 0 0 0 1px currentColor;
    color: var(--text-primary); font-weight: 700;
}
.tip-card .tip-name { font-size: var(--fs-md); word-break: keep-all; margin-bottom: 3px; }
.tip-card .tip-sub { font-size: var(--fs-xs); color: var(--text-muted); margin-bottom: 8px; }
/* 아이템 카드 머리글 — 왼쪽 「이 아이템」 · 오른쪽 끝 Lv (SCREEN_DESIGN §6 · ADR-0473 · ADR-0474). 레벨은 두 장 비교에서 같은 모서리에 서서 대조된다 ·
   글씨는 머리글보다 한 치수(1px) 작다(사용자 지시) — 확대 배율의 `--fs-xs` 재정의도 따라가게 calc */
.tip-card .tip-head-row { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.tip-card .tip-meta { font-size: calc(var(--fs-xs) - 1px); letter-spacing: 0; white-space: nowrap; color: var(--text-secondary); }
.tip-card .tip-kind { margin-right: 8px; }   /* 종류  Lv.n — 둘 사이 (ADR-0526) */
.tip-card .tip-head-row + .tip-name { margin-bottom: 8px; }   /* 이름 아래 줄이 걷힌 자리 — 그 줄이 쥐던 간격을 이름이 든다 */
/* 스킬·마스터리 툴팁 — 이름과 그림을 한 줄의 머리로 묶고 효과 문장에 읽을 자리를 준다. */
.tip-card.skill { width: 348px; padding: 14px 16px 15px; border-top: 2px solid var(--border-highlight); }
.tip-card.skill .tip-name {
    display: flex; align-items: center; gap: 11px;
    margin: 0; padding-bottom: 11px; border-bottom: 1px solid var(--border-dark);
    font-size: 14px; font-weight: 700; line-height: 1.3;
}
.tip-card.skill .tip-sk-ico {
    position: relative; flex: none; width: 42px; height: 42px; margin: 0;
    padding: 3px; background: var(--bg-input); border: 1px solid var(--border-primary);
}
/* 이름 줄 [2026-10-03 사용자 지시 · ADR-0496] — 이름 **바로 뒤에** 능력치 칩(`.tip-name-attr`) · **맨 오른쪽 끝에** 필요 무기(`.tip-name-side` · `.need` — 무기가 필요한 스킬만).
   출처 · 태그 · 종류 칩은 이름 아래 제 줄(`.tip-chips`)에 남는다. 이름은 접히고 필요 무기는 남는 폭을 밀어 끝에 붙는다 ·
   이름 줄의 굵은 글자 · 크기를 칩이 물려받지 않게 되돌린다 */
.tip-card.skill .tip-chips { margin-top: 10px; gap: 5px; }
.tip-card.skill .tip-name-text { flex: 0 1 auto; min-width: 0; }
.tip-card.skill .tip-name-attr { flex: none; display: flex; gap: 4px; margin-left: -4px; font-weight: 400; }
.tip-card.skill .tip-name-side { flex: none; margin-left: auto; font-weight: 400; }
.tip-card.skill .tip-name .tip-chip { white-space: nowrap; }
.tip-card.skill .tip-chip.need { color: var(--text-secondary); border-color: var(--border-primary); }
.tip-card.skill .tip-chip.need.off { color: var(--danger-fg); border-color: var(--danger-fg); }
.tip-card.skill .tip-chip { background: none; border-color: var(--border-dark); color: var(--text-muted); }
.tip-card.skill .tip-chip.attr { color: var(--bronze-fg); border-color: var(--bronze-line); }
.tip-card.skill .tip-line { max-width: none; margin-top: 11px; line-height: 1.6; }
.tip-card.skill .tip-line + .tip-line { margin-top: 7px; }
.tip-card.mastery .tip-name { justify-content: space-between; }
.tip-card.mastery .tip-title { display: flex; align-items: center; gap: 11px; min-width: 0; }
.tip-card.mastery .tip-rank {
    flex: none; margin-left: auto; font-size: var(--fs-xs); font-weight: normal;
    color: var(--text-muted); white-space: nowrap;
}
.tip-card.mastery .tip-gate { color: var(--text-muted); }
/* **메인 옵션(밑수)** [개정 2026-09-10 사용자 지시 · ADR-0081] — ~~`.tip-implicit` 한 줄~~ 을 대체한다.
   본문(`--fs-sm`)보다 **한 단 큰 값**이 이름 오른쪽에 선다: 아이템을 고르는 첫 판단이 이 두세 줄이고,
   접사 목록(`--fs-xs`)과 크기로 층이 갈려야 「밑수 ↔ 굴린 옵션」이 눈에 먼저 들어온다.
   값은 **오른쪽 정렬** — 두 카드가 나란히 서는 비교 툴팁에서 같은 x 에 값이 모여야 대조가 된다 */
.tip-card .tip-base { margin-bottom: 8px; }
.tip-card .tip-base .r {
    display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
    padding: 1px 0;
}
.tip-card .tip-base .n { font-size: var(--fs-sm); color: var(--text-secondary); word-break: keep-all; }
/* 원소는 마법 무기 **개체**가 든 값이라 이름의 주석으로 붙는다 — 이름 옆 흐린 잔글씨 문법 */
.tip-card .tip-base .n i { font-style: normal; color: var(--text-muted); font-size: var(--fs-xs); margin-left: 5px; }
.tip-card .tip-base b { font-size: var(--fs-md); font-weight: normal; color: var(--color-info); white-space: nowrap; }
/* ~~`.tip-up`~~ (강화 줄) 삭제 2026-09-08 — 툴팁이 강화를 말하지 않는다 (SCREEN_DESIGN §6) */
/* 유닛 툴팁 — 영웅 · 몬스터 (SCREEN_DESIGN §2 「유닛 툴팁 규격」 · ADR-0114 · ADR-0171). 영웅 첫 열은 착용 장비, 몬스터 첫 열은
   캐릭터 탭의 `.attr-list` · `.cs-row` 를 그대로 쓴 기본 옵션이다. **Alt 를 누르는 동안만** 세부 옵션 두 열이 서고 카드가 넓어진다 —
   몬스터 첫 열은 기본 카드의 안쪽 폭을 하한으로 들고 세부 열 폭은 내용이 정한다(영어가 길다).
   영웅은 아래 `.equipment` 규칙으로 장비 200px · 세부 옵션 220px에 고정한다(ADR-0182). 비교 두 장(640)을 전제한 툴팁 상한도 이 카드에서는 푼다 */
.tip-card.unit.alt { width: auto; }
.tooltip:has(> .tip-card.unit.alt) { max-width: none; }
/* 자리는 격자가 정한다 [개정 2026-09-19 사용자 지시 · ADR-0126 · ADR-0171] — 세부 옵션 1 · 2 가 첫 열의 **바깥쪽**에 선다:
   카드 오른쪽에 선 툴팁은 [첫 장][1][2] · 왼쪽에 선 툴팁(`grow-left`)은 [1][2][첫 장]. 첫 장은 Alt 를 눌러도 제자리다(DOM 순서는 그대로).
   이름 · 소속 줄은 없다(ADR-0134) — 한 줄짜리 격자다.
   몬스터 세부 옵션 두 열은 **같은 폭** — `1fr 1fr` 이고 카드는 내용 폭으로 재므로 더 긴 열의 폭을 둘이 똑같이 갖는다.
   영웅은 아래 고정 격자가 이 값을 덮어 장비와 세부 옵션을 각각 정한 폭으로 만든다.
   열 사이 선은 **틈 한가운데의 가짜 요소**다 — 열의 테두리 · 여백으로 그으면 첫 열과 나머지 열의 안쪽 폭이 여백만큼 달라져 「같은 폭」이 깨진다.
   `stretch` — 선이 가장 긴 열 높이까지 내려간다 */
.tip-unit { display: grid; grid-template-columns: minmax(278px, 1fr); column-gap: 33px; align-items: stretch; }
.tip-unit-col { grid-row: 1; grid-column: 1; position: relative; }
.tip-card.unit.alt .tip-unit { grid-template-columns: minmax(278px, auto) 1fr 1fr; }
.tip-card.unit.alt .tip-unit-col.d1 { grid-column: 2; }
.tip-card.unit.alt .tip-unit-col.d2 { grid-column: 3; }
.tip-card.unit.alt.grow-left .tip-unit { grid-template-columns: 1fr 1fr minmax(278px, auto); }
.tip-card.unit.alt.grow-left .tip-unit-col.base { grid-column: 3; }
.tip-card.unit.alt.grow-left .tip-unit-col.d1 { grid-column: 1; }
.tip-card.unit.alt.grow-left .tip-unit-col.d2 { grid-column: 2; }
/* 선은 격자에서 **첫 열이 아닌** 열의 왼쪽 틈에 선다 — 오른쪽에 선 카드는 1 · 2 앞, 왼쪽에 선 카드는 2 · 첫 장 앞 */
.tip-card.unit.alt .tip-unit-col.d1::before,
.tip-card.unit.alt .tip-unit-col.d2::before,
.tip-card.unit.alt.grow-left .tip-unit-col.base::before {
    content: ''; position: absolute; left: -17px; top: 0; bottom: 0; border-left: 1px solid var(--border-dark);
}
.tip-card.unit.alt.grow-left .tip-unit-col.d1::before { content: none; }
/* 열 이름(장비 · 세부 옵션 1 · 2 · 기본 옵션) — 흰 글씨 · 한 단 크게 · 아래에 열 폭 전부를 긋는 선 [2026-09-21 사용자 지시 · ADR-0277].
   숨은 높이 기준(`.tip-equipment-probe`)도 같은 머리를 들어 기본 · Alt 높이가 같이 는다 */
.tip-col-h { font-size: var(--fs-sm); color: var(--text-primary); margin: 4px 0 6px; padding-bottom: 3px; border-bottom: 1px solid var(--border-secondary); }
/* 「기본 옵션」 머리 오른쪽 끝 칩 셋 [2026-10-24 사용자 지시 · ADR-0773] — 영웅 등급 · 죄종 · 직업 / 몬스터 종족 · 죄종 · 직업.
   후보 카드 칩 줄(`.ng-chips`)과 같은 칩 · 같은 여백 · 어두운 등급 색(몬스터 일반 · 보스)의 종족 칩은 막대처럼 밝힌다(`bar-lift`) */
.tip-col-h.with-chips { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.tip-chips { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }
.tip-chips > span { padding: 0 4px; }
.tip-card.unit.bar-lift .tip-chips .tier-chip { filter: brightness(1.8); }
/* 개정 2026-09-15 [사용자 지시 · ADR-0119 · ADR-0120 · SCREEN_DESIGN §2 「유닛 툴팁 규격」]
   ① 윗변 3px = 막대 색(`--unit-line` — 렌더러가 카드에 건다) — 관전 카드 · 띠 카드의 윗변(3px)과 같은 문법이다.
      툴팁 겉테두리(1px) 위에 겹쳐 앉힌다(margin -1) — 안쪽에 따로 서면 회색 선과 색 선이 두 줄로 읽힌다
   ② 줄 높이 1.4 — 툴팁은 메인 `zoom: .9` 밖이라 본문 1.6 을 물려받으면 캐릭터 탭보다 줄마다 2px 넘게 성겼다(23 대 20.5 실측)
   ③ Alt 열의 이름-값 간격 — 열 폭을 내용이 정해서 짧은 열(세부 옵션 2)은 이름과 값이 붙어 있었다
   ④ 몬스터의 대표값 3줄(`.tip-lead`)은 막대 아래 윗선 하나로 가른다 — Alt 와 무관하게 선다
   ⑤ 어두운 등급 색(몬스터 일반 · 보스 — `--enemy-line` · `--boss-line`)은 막대만 밝힌다 — 검은 막대 바탕에 묻혔다.
      색 값을 새로 만들지 않고 같은 토큰을 밝혀 윗변과 같은 색 계열로 남긴다 */
/* ⑥ `zoom: .85` — 카드 전체(글씨 · 막대 · 폭)를 한 단 줄인다 [2026-09-15 사용자 지시 「너무 크다」 · 값은 src/ui/README.md 크기 정책].
      창(`#tooltip`)이 아니라 **카드**에 건다 — 창의 `left/top` 은 `moveTip` 이 한 장 좌표로 넣는 값이다 */
.tip-card.unit { border-top: 3px solid var(--unit-line, var(--border-secondary)); margin-top: -1px; line-height: 1.4; zoom: .85; }
.tip-unit .cs-row { gap: 20px; }
.tip-lead { margin-top: 8px; padding-top: 7px; border-top: 1px solid var(--border-dark); }
.tip-card.unit.bar-lift .attr-bar > i { filter: brightness(1.8); }
/* 영웅 툴팁 첫 장 = 페이퍼돌 (ADR-0171 · ADR-0172 · ADR-0182).
   아래 보관 칸은 메인 zoom .9 → 화면 45.03px, 툴팁은 53px에 zoom .85 → 45.05px다(1600×800 브라우저 실측).
   같은 60px 페이퍼돌을 그대로 쓰면 화면 51px로 한 단계 컸다. 칸 간격도 보관과 같은 4px로 맞춘다.
   열은 **장비 200px · 세부 옵션 1/2 각 220px**다. 기본 상태는 220px 폭의 보이지 않는 세부 옵션 1을 겹쳐 놓아 그 높이를 첫 장부터 그대로 잡는다. */
/* `--tip-equip-gutter` = Alt 에서 장비 열과 **구분선** 사이 거리 — 열 틈 33 중 선이 다음 열 앞 17 에 서므로 33−17 이다.
   기본 상태에서도 장비 열 바깥에 같은 거리를 남겨야 「장비 구역의 보이는 폭」이 Alt 전후로 같다 */
.tip-card.unit.equipment { --tip-equip-col-w: 200px; --tip-detail-col-w: 220px; --tip-equip-gutter: 16px; }
/* 기본 상태의 카드 폭은 **내용이 정한다** [정정 2026-09-21] — 박아 둔 226px 는 「200 + 좌우 padding 13」이라는 산수였는데
   이 카드의 실제 좌우 padding 은 6px 다: 툴팁 카드가 `tip-card unit` 이라 **아레나 카드의 `.unit`**(style.css 아래쪽 · 같은 명시도 · 뒤에 선언)
   규칙까지 함께 먹는다(`padding: 5px 6px 6px`). 그래서 카드가 내용보다 11.6px 넓었고, 200px 트랙이 왼쪽에 붙어
   **오른변 쪽에 빈 11.6px** 이 남았다 — 툴팁이 카드 왼쪽에 서면(`grow-left`) 오른변을 못 박으므로 그 빈 자리만큼
   Alt 전후로 장비 열이 어긋났다(실측 9.9px). `max-content` 면 padding 이 무엇이든 카드가 트랙에 딱 맞는다 */
.tip-card.unit.equipment:not(.alt) { width: max-content; }
/* 기본 상태의 **바깥 여백** [2026-09-21 사용자 지적 「Alt 누르면 장비칸 넓이가 커진다」] — Alt 에서는 장비 열 바깥에
   구분선까지 16px 이 서는데 기본 상태에는 카드 padding(6) 뿐이라, Alt 를 누르는 순간 장비 구역이 그만큼 넓어 보였다.
   모자란 만큼을 **붙는 쪽 반대편에만** 둔다 — 못 박은 변(오른쪽에 서면 왼변 · 왼쪽에 서면 오른변)을 건드리면
   열이 다시 튄다. 카드 padding 이 아니라 `.tip-unit` 의 margin 으로 주는 이유도 같다(padding 은 `.unit` 충돌로
   값이 미덥지 않다 — DEV_PLAN 부채 #53). ⚠ 뺄셈의 6px 이 그 충돌에서 온 값이다 */
.tip-card.unit.equipment:not(.alt) .tip-unit { margin-right: calc(var(--tip-equip-gutter) - 6px); }
.tip-card.unit.equipment.grow-left:not(.alt) .tip-unit { margin-right: 0; margin-left: calc(var(--tip-equip-gutter) - 6px); }
.tip-card.unit.equipment .tip-unit { grid-template-columns: var(--tip-equip-col-w); }
.tip-card.unit.equipment.alt.grow-left .tip-unit { grid-template-columns: var(--tip-detail-col-w) var(--tip-detail-col-w) var(--tip-equip-col-w); }
.tip-card.unit.equipment.alt:not(.grow-left) .tip-unit { grid-template-columns: var(--tip-equip-col-w) var(--tip-detail-col-w) var(--tip-detail-col-w); }
/* 열 폭은 **장비 열 하나로 못박는다** [2026-09-21 · 사용자 지적 「Alt 누를 때랑 안 누를 때 자리가 바뀐다」].
   기본 상태의 높이 기준(`.tip-equipment-probe`)은 세부 옵션 1과 같은 220px 라서, 트랙을 `auto` 로 두면
   **보이지 않는 그 220px 이 트랙을 넓혀** 장비 면까지 220 이 됐다 — 페이퍼돌이 `justify-content: center` 라
   Alt 로 기준이 빠지는 순간 3×3 이 10px(화면 8.5px) 왼쪽으로 튀었다. 트랙을 200 으로 박으면 기준은
   제 폭(220)으로 **넘쳐 흐르며 높이만** 낸다 — 보이지 않으므로 넘친 자리는 화면에 없다 */
.tip-card.unit.equipment .tip-unit-col.base { display: grid; grid-template-columns: var(--tip-equip-col-w); }
.tip-card.unit.equipment .tip-equipment-face,
.tip-card.unit.equipment .tip-equipment-probe { grid-area: 1 / 1; }
.tip-card.unit.equipment .tip-equipment-face { display: flex; flex-direction: column; min-height: 0; }
.tip-card.unit.equipment .tip-equipment-face .tip-foot { margin-top: auto; }
.tip-card.unit.equipment .tip-equipment-probe { width: var(--tip-detail-col-w); visibility: hidden; pointer-events: none; }
/* 3×3 은 머리글 바로 밑이 아니라 **한 단 내려** 선다 [2026-09-21 사용자 지시 「살짝 아래로」] — 첫 장은 세부 옵션 1의
   높이를 쓰므로 칸 아래에 빈 자리가 길게 남았고, 칸이 위로 쏠려 카드가 머리만 찬 것처럼 읽혔다.
   ⚠ **기본 · Alt 가 같은 값**이라야 한다 — 이 여백은 둘 다 타는 `.tip-equipment-face` 안이라 Alt 전후 자리가 안 움직인다 */
.tip-card.unit .tip-equipment.paperdoll {
    grid-template-columns: repeat(3, 53px); gap: 4px; justify-content: center; margin-top: 28px;
}
.tip-card.unit .tip-equipment .pd-cell,
.tip-card.unit .tip-equipment .pd-gap { width: 53px; height: 53px; }
.tip-card.unit .tip-equipment .pd-cell { cursor: default; }
.tooltip.interactive .tip-card.unit .tip-equipment .pd-cell.tip-optionable { cursor: help; }
.tip-card.unit .tip-equipment .pd-cell.tip-equip-active { background: var(--surface-7); }
.tip-card.unit .tip-equipment .pd-icon { width: 42px; height: 42px; }
.tip-card.unit .tip-equipment .pd-cell.art .pd-art { inset: 6px; }
/* 편성 탭 영웅 카드 [2026-09-21 사용자 지시 · ADR-0287] — 첫 장 기본 옵션(막대 + 액티브 스킬 그림) · Alt 동안 **바깥쪽에** 장비 · 세부 옵션 1 · 2.
   기본 옵션 열은 **폭을 못박는다** — Alt 전후로 제자리여야 「사라지지 않고 옆에 붙는다」로 읽힌다(툴팁 창은 붙은 쪽 변을 못박는다 · ADR-0126).
   카드 폭은 내용이 정한다(`max-content`) — `.tip-card` 의 304 를 쓰면 기본 상태에서만 열이 넓어졌다가 Alt 에 줄어든다.
   장비 · 세부 옵션 열 폭은 다른 자리의 영웅 카드(`.equipment`)와 같은 200 · 220 이다 */
.tip-card.unit.stats-first { --tip-base-col-w: 278px; --tip-equip-col-w: 200px; --tip-detail-col-w: 220px; width: max-content; }
.tip-card.unit.stats-first .tip-unit { grid-template-columns: var(--tip-base-col-w); }
.tip-card.unit.stats-first.alt .tip-unit { grid-template-columns: var(--tip-base-col-w) var(--tip-equip-col-w) var(--tip-detail-col-w) var(--tip-detail-col-w); }
.tip-card.unit.stats-first.alt .tip-unit-col.gear { grid-column: 2; }
.tip-card.unit.stats-first.alt .tip-unit-col.d1 { grid-column: 3; }
.tip-card.unit.stats-first.alt .tip-unit-col.d2 { grid-column: 4; }
/* 카드 왼쪽에 선 툴팁 — [1][2][장비][기본 옵션] · 기본 옵션이 카드 쪽(못박은 오른변)에 남는다 */
.tip-card.unit.stats-first.alt.grow-left .tip-unit { grid-template-columns: var(--tip-detail-col-w) var(--tip-detail-col-w) var(--tip-equip-col-w) var(--tip-base-col-w); }
.tip-card.unit.stats-first.alt.grow-left .tip-unit-col.d1 { grid-column: 1; }
.tip-card.unit.stats-first.alt.grow-left .tip-unit-col.d2 { grid-column: 2; }
.tip-card.unit.stats-first.alt.grow-left .tip-unit-col.gear { grid-column: 3; }
.tip-card.unit.stats-first.alt.grow-left .tip-unit-col.base { grid-column: 4; }
/* 구분선 — 장비 열 앞에도 선다(나머지 열의 선은 위 유닛 카드 공통 규칙이 긋는다) */
.tip-card.unit.stats-first.alt .tip-unit-col.gear::before {
    content: ''; position: absolute; left: -17px; top: 0; bottom: 0; border-left: 1px solid var(--border-dark);
}
/* 원정 양 진영 카드 (ADR-0486 · tip.js UNIT_TIP_ALL) — 장비가 기본 옵션 아래에 늘 서고 Alt는 세부 옵션 1 · 2만: [기본+장비][1][2] */
.tip-card.unit.stats-first.gear-below.alt .tip-unit { grid-template-columns: var(--tip-base-col-w) var(--tip-detail-col-w) var(--tip-detail-col-w); }
.tip-card.unit.stats-first.gear-below.alt .tip-unit-col.d1 { grid-column: 2; }
.tip-card.unit.stats-first.gear-below.alt .tip-unit-col.d2 { grid-column: 3; }
.tip-card.unit.stats-first.gear-below.alt.grow-left .tip-unit { grid-template-columns: var(--tip-detail-col-w) var(--tip-detail-col-w) var(--tip-base-col-w); }
.tip-card.unit.stats-first.gear-below.alt.grow-left .tip-unit-col.d1 { grid-column: 1; }
.tip-card.unit.stats-first.gear-below.alt.grow-left .tip-unit-col.d2 { grid-column: 2; }
.tip-card.unit.stats-first.gear-below.alt.grow-left .tip-unit-col.base { grid-column: 3; }
.tip-gear-below { margin-top: 10px; padding-top: 8px; border-top: 1px solid var(--border-secondary); }
.tip-gear-below .tip-col-h { display: none; }   /* 「장비」 글씨는 빼고 줄만 [2026-09-27 사용자 지시] */
/* 줄 ~ 3×3 · 3×3 ~ 각주 선이 같은 8px — 공통 규칙의 28px(`.tip-card.unit .tip-equipment.paperdoll`)을 명시도로 누른다 */
.tip-card.unit .tip-gear-below .tip-equipment.paperdoll { margin-top: 0; }
/* 세부 옵션 줄은 한 줄 — 값은 온전히 · 이름이 모자라면 `…` 로 자른다 [2026-09-28 사용자 지시] */
.tip-card.unit.gear-below .cs-row { gap: 12px; }
.tip-card.unit.gear-below .cs-n { flex: 1 1 auto; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* 액티브 스킬 그림 셋 — 막대 아래 윗선 하나로 가른다(걷은 대표값 줄 `.tip-lead` 와 같은 선 · 같은 자리).
   칸은 캐릭터 탭 스킬 칸(`.sk-card`)과 같은 문법 — 찬 칸은 그림 하나 · 빈 칸은 파선 + 흐림 */
.tip-skills { display: flex; gap: 6px; margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--border-dark); }
/* `.tip-skills` 안으로 좁힌다 — 아이템 카드의 스킬 칸(아래 `.tip-card > .tip-skill`)도 같은 클래스라, 좁히지 않으면 그 칸이 48px 상자에 갇혀 이름 · 문장이 넘쳤다 (2026-09-23) */
.tip-skills .tip-skill { width: 48px; height: 48px; padding: 3px; background: var(--bg-input); border: 1px solid var(--border-dark); position: relative; }   /* `Lv.n` 의 기준 칸 (ADR-0701) */
.tip-skills .tip-skill img { display: block; width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
.tip-skills .tip-skill.vacant { border-style: dashed; opacity: .55; }
.tip-skills .tip-skill.locked { display: flex; align-items: center; justify-content: center; }
/* 영웅 hover — 장비를 왼쪽에, 액티브 스킬 셋을 오른쪽에 세워 3×3 장비의 각 줄과 맞춘다. */
.tip-gear-below.with-skills { display: grid; grid-template-columns: max-content 53px; column-gap: 20px; justify-content: center; align-items: start; }
.tip-gear-below.with-skills .tip-skills { flex-direction: column; gap: 4px; margin: 0; padding: 0; border: 0; }
.tip-gear-below.with-skills .tip-skill { width: 53px; height: 53px; }
/* 스킬 툴팁 — 이름 앞 아이콘 (고정 설명 문단은 2026-09-15 에 뗐다 · ADR-0118) */
/* 그림이 들어오면서 인라인 블록이 된다 (2026-09-03 · SCREEN_DESIGN §2) — 이름 줄의 baseline 을 흔들지 않게 가운데 정렬 */
.tip-sk-ico { margin-right: 7px; display: inline-block; width: 22px; height: 22px; vertical-align: middle; }
.tip-sk-ico img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 마스크로 칠하는 노드 그림(죄종 마스터리) — 칸 · 툴팁 공통. 색은 렌더러가 인라인으로 준다 (SCREEN_DESIGN §7 · ADR-0378) */
.sk-icon-mask { display: block; -webkit-mask-size: contain; mask-size: contain; -webkit-mask-position: center; mask-position: center; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; }
.tip-sk-ico .sk-icon-mask { width: 83%; height: 83%; margin: 8.5%; }
/* 칸 안 그림 크기 — 실루엣(파일의 88%)이 칸의 약 66% 를 차지한다 (0.75 × 0.88) [2026-10-09 사용자 지시 「마스터리 안의 아이콘 크기를 조금씩만 줄여줘」].
   전직 판 가지 칸 그림(`.adv-node-art`)도 같은 크기다 (ADR-0555) */
.sk-icon-art.sk-icon-mask { inset: 12.5%; width: auto; height: auto; }
/* ~~아이템 카드의 스킬 칸(`.tip-card > .tip-skill`)~~ — 2026-09-29 걷었다(R179 · ADR-0421): 무기가 스킬을 안 담는다 */
.tip-card ul { list-style: none; }
.tip-card li { color: var(--info-fg); }
/* 물약 카드 (SCREEN_DESIGN §2 「물약 툴팁 규격」 · ADR-0315) — 따로 규칙이 없다: 창 뱃지 툴팁의 클래스(`.tip-effect-*` · `.tip-sk-ico`)를 그대로 탄다 */
/* 옵션 출처 태그 (SCREEN_DESIGN §6 · ADR-0100) — 접사 줄 **앞**에 선다. 셋이다: 베이스 옵션 · 죄종 이름 · 랜덤.
   베이스 · 랜덤은 줄마다 반복되므로 **값보다 약하게** 둔다: 읽히되 접사 이름·수치를 밀어내지 않는 밝기다.
   **죄종 칸만 색을 받는다** — 글자색은 렌더러가 `SINS` 색을 인라인으로 넣고 테두리가 그 색을 따른다 (2026-09-11 R78) */
.tip-src {
    font-style: normal; font-size: var(--fs-2xs); color: var(--text-muted);
    border: 1px solid var(--border-dark); padding: 0 4px; margin-right: 6px;
    vertical-align: middle;
}
.tip-src.sin { border-color: currentColor; }
/* 「(미적용)」 — 전투가 아직 안 읽는 옵션 줄 끝 (SCREEN_DESIGN §6 · ADR-0213). 값보다 한 단 흐리게 — 줄을 지우지 않고 상태만 알린다 */
.tip-inert { font-style: normal; font-size: var(--fs-2xs); color: var(--text-muted); white-space: nowrap; }
/* Shift 범위 — 옵션 줄 끝 `(최소~최대)` · 값보다 흐리게 (SCREEN_DESIGN §6 · ADR-0617) */
.tip-range { font-style: normal; color: var(--text-muted); white-space: nowrap; }
/* 착용 델타 — 옵션 아래 · 힌트 위 「{영웅} 착용 시」 (SCREEN_DESIGN §6 · ADR-0618). 줄 = 이름 | 지금 → 낀 뒤 | 화살표 —
   글씨는 옵션 줄과 같은 단이고 화살표 칸은 폭을 박아 줄마다 값이 같은 x 에서 끝난다 */
.tip-card .tip-delta { margin-top: 8px; padding-top: 6px; border-top: 1px solid var(--border-dark); }
.tip-card .tip-delta-h { font-size: var(--fs-xs); color: var(--text-muted); margin-bottom: 2px; }
.tip-card .tip-delta .r { display: flex; align-items: baseline; gap: 6px; font-size: var(--fs-xs); padding: 1px 0; }
.tip-card .tip-delta .n { flex: 1 1 auto; color: var(--text-secondary); word-break: keep-all; }
.tip-card .tip-delta .v { white-space: nowrap; color: var(--text-primary); }
.tip-card .tip-delta b { flex: none; width: 1em; text-align: center; font-weight: normal; }
.tip-card .tip-delta b.up { color: var(--color-success); }
.tip-card .tip-delta b.down { color: var(--color-error); }
.tip-card .tip-delta .r.none { color: var(--text-muted); }
/* 하단 태그 줄 — 죄종 태그 + 힌트(반지 칸 · 착용 중 없음). 둘 다 없으면 렌더러가 줄째 안 낸다(구분선만 남으면 안 된다).
   간격은 `gap` 이 든다 — 옛 판은 태그마다 인라인 `margin-right` 였고 힌트는 그 규칙 밖이었다 (2026-09-08) */
.tip-card .tip-sins {
    margin-top: 8px; padding-top: 7px; border-top: 1px solid var(--border-dark);
    display: flex; flex-wrap: wrap; align-items: center; gap: 5px;
}
.tip-card .tip-empty { color: var(--text-muted); }

/* ───────── 리포트 ───────── */

.report-head {
    display: flex; align-items: baseline; gap: 14px; padding-bottom: 12px;
    border-bottom: 1px solid var(--border-dark); margin-bottom: 12px;
}
.report-head .verdict { font-size: var(--fs-xl); }
.report-head .verdict.clear { color: var(--color-success); }

/* 획득 줄 — 다섯 칸의 **자리가 고정**이다 (ADR-0086). 내용 폭에 맡기면 「없음」↔「3명」 같은 값 글자에 옆 칸이 밀린다.
   몫은 그 칸이 흔히 드는 글자 길이를 따른다(빗나감 `12 / 261 (5%)` 가 길다). ~~도감 카드 칸~~ 은 2026-09-21 삭제(카드 걷음 · SCREEN_DESIGN §4-3).
   하한이 `max-content` 라 몫을 넘는 값은 잘리지 않고 칸을 민다 — 값은 항상 찍는다 */
.gain-row {
    display: grid; column-gap: 12px; margin-bottom: 14px; font-size: var(--fs-sm); white-space: nowrap;
    grid-template-columns:
        minmax(max-content, .8fr) minmax(max-content, 1fr) minmax(max-content, .8fr)
        minmax(max-content, .9fr) minmax(max-content, 1.4fr);
}
.gain-row div span { color: var(--text-muted); margin-right: 7px; }

/* 런 목록 — 왼쪽 열. 한 줄 = 한 런이고 클릭이 오른쪽 상세를 바꾼다 (ADR-0063)
   **두 열의 높이는 박스가 정한다** (ADR-0097) — 목록은 `contain: size` 라 격자 행 높이에 안 들어가고, 받은 높이를 채운 뒤
   넘치는 줄은 안에서 스크롤한다. 줄은 [balance.csv:report_keep] 까지 쌓이므로 목록이 높이를 정하면 런이 쌓일수록 화면이 늘어난다 */
.rep-runs { display: flex; flex-direction: column; }
/* 부대 탭 — 목록 위 · 고른 부대의 런만 선다 (SCREEN_DESIGN §4-3 · ADR-0622) */
.rep-runs .rep-party { margin-bottom: 8px; }
.rep-empty { padding: 6px 2px; font-size: var(--fs-sm); }
.rep-list {
    display: flex; flex-direction: column; gap: 4px;
    flex: 1 1 0; min-height: 0; contain: size;
    overflow-y: auto;
}
/* 리포트는 박스다 (ADR-0097) — 두 열이 박스 세로를 다 쓰고, 상세는 넘치면 상세 안에서 스크롤한다 */
.cols.c-side.page { grid-template-rows: minmax(0, 1fr); }
.c-side.page > .rep-detail { overflow-y: auto; }
.rep-run {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 9px; align-items: center;
    padding: 7px 9px; background: var(--bg-tertiary);
    border: 1px solid var(--border-dark); cursor: pointer;
}
.rep-run:hover { border-color: var(--border-highlight); }
.rep-run.on { background: var(--bg-input); border-color: var(--border-highlight); }
/* 판정은 점 하나로만 — 줄이 좁아 글자를 더 못 넣는다. 색 어휘는 상세의 판정 글자와 같다 */
.rep-run .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--text-muted); }
.rep-run .dot.clear { background: var(--color-success); }
.rep-run .dot.retreat { background: var(--color-warning); }
.rep-run .dot.lose { background: var(--color-error); }
.rep-run .n { font-size: var(--fs-sm); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rep-run .s { font-size: var(--fs-xs); }
.rep-run .r { text-align: right; white-space: nowrap; }
.rep-run .g { font-size: var(--fs-sm); color: var(--color-warning); }

/* 절 구분선 — **덩어리가 끝나는 자리**에 긋는다(획득 줄 · 장비 격자 · 기여 표).
   표 안의 줄 구분(`--border-dark`)보다 한 단계 진해야 「줄 사이」와 「절 사이」가 갈린다 */
.rep-detail .rep-cut { padding-bottom: 13px; border-bottom: 1px solid var(--border-secondary); }

/* 상세 — 절 머리가 여럿이라 첫 줄만 붙여 놓는다 */
.rep-detail > h2 { margin-top: 18px; }
.rep-detail > h2:first-of-type { margin-top: 0; }
.rep-note { font-size: var(--fs-xs); margin-bottom: 8px; }
.rep-contrib { margin-bottom: 4px; }
/* 상세는 **어느 런을 골라도 같은 크기**다 (ADR-0086) — 있을 때만 그리는 줄을 두지 않는다.
   `.void` 는 **자리만 잡고 안 그린다**: 기여 집계가 없는 옛 리포트의 표 */
.rep-detail .void { visibility: hidden; }
/* 머리 줄 오른쪽 — 버린 수. 따로 줄을 세우면 버린 런만 상세가 한 줄 길어진다 (리포트는 보기 전용이라 버튼이 없다 · ADR-0186) */
.rep-h-tail { display: flex; align-items: center; gap: 10px; }
.rep-detail > h2 .rep-h-tail small.down { color: var(--color-error); }
/* 장비 격자 — **한 줄 높이로 못박힌다**. 「없음」도 그 높이 안에 서고, 한 줄을 넘치는 런만 칸 안에서 스크롤한다 */
.rep-drops { --rep-cell: 44px; }
.rep-drops > .inv-cells.wide {
    grid-template-columns: repeat(auto-fill, var(--rep-cell));
    height: var(--rep-cell); overflow-y: auto;
}
.rep-drops > .rep-note { height: var(--rep-cell); display: flex; align-items: center; margin: 0; }
/* 도감 카드 — **줄은 늘 선다**(없으면 「없음」) · 한 줄에서 끊고 전체는 호버(`title`)가 든다 */

/* 기여 표 — 견주는 값이라 칸으로 세운다 (ADR-0069 · ADR-0070).
   「가한」·「받은」은 **같은 폭 · 같은 모양**이고, 막대는 각자 **자기 칸의 최대**를 기준으로 그 칸 배경에 깔린다 */
.rep-ct { font-size: var(--fs-sm); margin-bottom: 4px; }
.rep-ct .ct-row {
    display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(130px, 1.8fr) minmax(130px, 1.8fr) minmax(56px, .6fr) minmax(0, 1.5fr);
    gap: 10px; align-items: center; border-bottom: 1px solid var(--border-dark);
}
.rep-ct .ct-row.head { font-size: var(--fs-xs); color: var(--text-muted); letter-spacing: 1px; padding-bottom: 5px; }
.rep-ct .ct-row.head span { padding: 0 7px; text-align: right; }
.rep-ct .ct-row.head span:first-child { padding-left: 0; text-align: left; }
/* 이름 칸 — 초상 + 오른쪽에 이름. 초상 크기는 담는 칸이 정한다(§5).
   **영웅에게 일어난 일도 여기 붙는다** (ADR-0086) — 이름 아래 레벨업 · 쓰러졌으면 초상이 회색.
   줄 높이는 초상(52)이 정하고 이름 두 줄은 그 안에 들어가서, 표시가 붙어도 줄이 안 자란다 */
.rep-ct .n { display: flex; align-items: center; gap: 11px; min-width: 0; padding: 4px 0; }
.rep-ct .n b { font-weight: normal; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rep-ct .n .hero-face { width: 52px; height: 52px; }
/* 이름 아래는 **한 줄씩 쌓는다** — 레벨업(.up · 초록 · 오른 영웅만) 위 · 받은 경험치(.xp) 아래 (ADR-0653).
   줄 간격을 좁혀 세 줄(이름 + 둘)이 초상 높이 안에 든다 — 줄이 안 자란다(ADR-0086) */
.rep-ct .nm { display: flex; flex-direction: column; min-width: 0; line-height: 1.35; }
.rep-ct .nm > em { font-style: normal; font-size: var(--fs-xs); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rep-ct .nm > em.xp { color: var(--text-muted); }
/* 전투불능 — 관전의 쓰러진 카드(`.unit.dead`)와 같은 문법. 카드가 아니라 초상 하나라 같은 값이면 빈 칸으로 읽혀 한 단 덜 흐리다.
   ⚠ 클래스를 `.down` 으로 두면 전역 `.down`(붉은 글자)이 **이름까지 붉게** 칠한다 — 표시는 초상 회색 하나다 */
.rep-ct .n.dead .hero-face { filter: grayscale(1); opacity: .45; }
/* 빈자리 — 파티 정원까지 **줄만 잡는다**. 초상 칸이 줄 높이를 정하므로 칸은 두되 안 그린다 */
.rep-ct .ct-row.pad .hero-face { visibility: hidden; }
/* 값 칸 — 막대가 칸을 채우는 배경, 수치는 그 위에 선다 */
.rep-ct .d { position: relative; display: flex; align-items: center; justify-content: flex-end; gap: 8px; padding: 5px 7px; align-self: stretch; }
.rep-ct .d > i { position: absolute; left: 0; top: 4px; bottom: 4px; background: var(--color-info); opacity: .3; }
.rep-ct .d.taken > i { background: var(--color-error); opacity: .26; }   /* 두 칸을 색으로 가른다 — 형태가 같아서 */
.rep-ct .d > b { position: relative; font-weight: normal; }
.rep-ct .d > em { position: relative; font-style: normal; font-size: var(--fs-xs); color: var(--text-muted); min-width: 34px; text-align: right; }
.rep-ct .v { color: var(--text-secondary); white-space: nowrap; text-align: right; padding: 5px 7px; }
/* 합계 — 줄이 아니라 기준선이라 테두리를 지우고 이름만 흐리게 */
.rep-ct .ct-row.total { border-bottom: none; }
/* 쓰러짐 칸 — `시각 ← 몬스터 몫%` · 왼쪽 정렬 · 줄 높이는 초상이 정해 두 줄까지 든다 (SCREEN_DESIGN §4-3 · ADR-0623) */
.rep-ct .f { font-size: var(--fs-xs); color: var(--text-secondary); padding: 5px 7px; line-height: 1.35; }
.rep-ct .ct-row.head span:nth-child(5) { text-align: left; }
/* 남은 적 줄 — 기여 표 아래 · 모든 런이 자리를 잡는다 (ADR-0623) */
.rep-foes { display: flex; align-items: baseline; gap: 10px; padding: 10px 0 2px; font-size: var(--fs-sm); }
.rep-foes > span { flex: none; font-size: var(--fs-xs); color: var(--text-muted); }
.rep-foes > b { font-weight: normal; color: var(--text-secondary); }
.rep-ct .ct-row.total .n > b { color: var(--text-muted); }
/* 가방을 떠난 드롭 — **있었다는 사실만** 남긴다. 분해했으면 정의가 없어 빈 칸이고, 착용 중이면 그림째 흐리다 */
.inv-cell.gone { opacity: .38; cursor: default; }
.inv-cell.gone:hover { background: var(--bg-tertiary); }


.verdict-upgrade { color: var(--color-success); }
.verdict-sidegrade { color: var(--color-warning); }
.verdict-junk { color: var(--text-muted); }

/* ───────── 전투 관전 ─────────
   상하 대치: 적(위) / 파티(아래)
   진영 안에서는 유닛이 가로로 나란히. 유닛 카드는 위칸(이름) + 가로형 본문 */

/* 헤드는 **한 줄** [재개정 2026-09-04 사용자 지시] — 라운드 수치·시계를 걷은 자리로 컨트롤 줄이 통째로 올라왔다.
     화면 전환 · 스테이지 이름 · 라운드 트랙 ─── (밀어내기) ─── 배속 · 일시정지 · 건너뛰기 │ 배치 · 로그 · 누적
   「라운드 n / 총 · 종류 · 경과 시계」는 삭제됐다 — 몇 라운드인지는 트랙의 `.now` 가, 종류는 칸 색이,
   경과 시각은 로그 줄 머리의 타임스탬프가 이미 든다.
   ⚠ **한 줄에 넣으려고 컨트롤 문구를 줄였다** — 하한 폭 1280 의 메인 칸은 1006 인데 옛 문구(`1배속` · `건너뛰고 리포트만`)
     로는 1148 이라 안 들어간다. 배속은 `×1`(ko·en 동일) · 건너뛰기는 `건너뛰기 / Skip` 으로 줄이고
     줄 간격(12 → 10)과 버튼 간격(5 → 4)을 한 단씩 좁혀 맞췄다. 남는 넘침은 스테이지 이름이 말줄임으로 받는다.
   `flex-wrap` 은 두지 않는다 — 접히면 2줄로 돌아가 이 개정의 목적(가방이 잘리던 것)이 사라진다 */
.battle-head {
    display: flex; flex-direction: column; align-items: stretch;
    padding-bottom: 9px; margin-bottom: 10px;
    border-bottom: 1px solid var(--border-dark);
}
.bh-top { display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: nowrap; }
.bh-title { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* 컨트롤 — 줄 오른쪽 끝. 재생(배속·일시정지·건너뛰기)과 판 고르기(배치·로그·누적)를 `.ctrl-div` 가 가른다 */
.battle-ctrl { flex: 0 0 auto; margin-left: auto; display: flex; gap: 4px; flex-wrap: nowrap; }
/* 한 줄에 여덟 개가 서야 해서 좌우 패딩을 한 단 좁힌다 (다른 화면의 `.btn.sm` 은 그대로) */
.battle-ctrl .btn.sm { padding: 3px 6px; }
/* 지속 버프 — 아레나 왼쪽 위에 신단 · 전술 · 도감 흰색 그림 세 칸.
   빈 출처도 같은 자리를 지키고 그림만 흐리다. 설명은 공통 툴팁이 카드 위에 띄운다. */
.arena > .run-buff-icons { position: absolute; left: 12px; top: 10px; z-index: 2; display: flex; gap: 4px; }
.run-buff-icon {
    display: inline-flex; align-items: center; justify-content: center;
    width: 34px; height: 34px; flex: 0 0 34px;
    background: rgba(var(--veil-rgb), .85); border: 1px solid var(--border-secondary);
    cursor: help;
}
.run-buff-icon img { width: 28px; height: 28px; object-fit: contain; pointer-events: none; }
.run-buff-icon.empty img { opacity: .3; }
.run-buff-icon:hover, .run-buff-icon:focus-visible { border-color: var(--border-highlight); }
.run-buff-icon:focus-visible { outline: 1px solid var(--text-primary); outline-offset: 2px; }
.run-buff-tip .tip-effect-summary { white-space: normal; word-break: keep-all; }
.run-buff-line + .run-buff-line { margin-top: 4px; }
/* 도감의 모든 효과도 hover 한 번에 읽도록 긴 목록은 위에서 아래 순서로 두 열에 나눈다. */
.run-buff-tip.many { width: 600px; }
.run-buff-tip.many .tip-effect-summary {
    display: grid; grid-auto-flow: column; grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: repeat(var(--buff-rows), auto); gap: 4px 18px;
}
.run-buff-tip.many .run-buff-line { margin-top: 0; }
/* 물약 칸 [2026-09-15 · R104 · ADR-0148] — 칸 하나에 물약 하나. **관전 아레나 왼쪽 아래 구석**과 **대장간 물약 머리 줄**이 같은 칸을 쓴다.
   찬 칸 = 실선 + 그 물약 그림 · 빈 칸 = 점선(스킬 빈 칸 `.cd-slot.empty` 와 같은 문법).
   바탕 한 변 28(대장간 재고 칸) · **아레나 칸은 44 · 그 안의 그림은 34**(칸을 따라 안 늘어 `D2 Min` 회색 선에 안 닿는다) [2026-10-27 사용자 지시 · ADR-0918 — 옛 34 는 ADR-0276 · 40 은 ADR-0916 · 48 은 ADR-0917] — 아래 `.b-belt .p-slot`.
   ⚠ 나눔 배치에서 칸 줄(오른쪽 끝 200)이 왼쪽 카드의 창 뱃지 줄 밑으로 들어간다(카드 왼쪽 끝 108 · 개편 전 카드 147) — 뱃지 첫 칩과 세로로 겹칠 수 있다 */
.p-belt { display: inline-flex; flex-direction: row; gap: 4px; }
.p-slot {
    flex: 0 0 auto; width: 28px; height: 28px;
    display: inline-flex; align-items: center; justify-content: center;
    background: transparent; border: 1px dashed var(--border-primary);
    transition: background .2s, border-color .2s;
}
.p-slot.full { border-style: solid; border-color: var(--border-secondary); background: var(--bg-input); }
.p-slot img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 그림이 없는 칸의 병 실루엣 [2026-09-17 사용자 지시] — 칸 넷이 같은 한 장이라 **티어를 안 가린다**(「여기에 물약이 들어간다」).
   그래서 찬 칸 · 빈 칸을 **진하기**가 가른다 — 테두리(실선 · 점선)만으로는 28px 에서 덜 읽힌다.
   빈 칸은 미장착 착용 칸(`.pd-cell.art .pd-art img`)과 같은 .3 · 찬 칸은 「들어 있다」가 보이게 한 단 진하다 */
.p-slot img.p-bg { opacity: .3; }
.p-slot.full img.p-bg { opacity: .8; }
/* 마신 순간 — 그 칸이 한 번 번쩍인다(회복 색). 재생기가 520ms 뒤 걷는다 */
.p-slot.fire { border-style: solid; border-color: var(--color-success); background: var(--bg-tertiary); }
/* 아레나 구석 — 흐름 밖(`.arena > *` 의 relative 를 덮는다) · 결과 띠(z 3)보다 아래. 배경 그림 위에서 빈 칸이 사라지지 않게 칸 바닥을 깐다 */
.arena > .b-belt { position: absolute; left: 12px; bottom: 10px; z-index: 2; }
.b-belt .p-slot { width: 44px; height: 44px; background: rgba(var(--veil-rgb), .6); }
.b-belt .p-slot img { width: 34px; height: 34px; }
.b-belt .p-slot.full { background: rgba(var(--veil-rgb), .85); }
/* 안 열린 칸 [2026-10-22 · R315 · ADR-0716] — 다 지은 칸 수까지 서고 칸 안에 닫힌 자물쇠(`lockIcon` · **회색** — 사용자 지시 「잠금표시 색깔을 회색으로」). 물약이 못 드는 자리라 실선 · 옅게 */
.p-slot.locked { border-style: solid; border-color: var(--border-primary); color: var(--text-muted); opacity: .7; }
.p-slot.locked .rs-pin-ico { width: 50%; height: 50%; }
/* 라운드를 물약 없이 시작한 칸 [2026-10-22 사용자 지시 · ADR-0716] — 빨간 반투명. 그 라운드 안에서 마셔서 빈 칸(`.full` 이 빠진 칸)은 위 빈 칸 그대로다 */
.b-belt .p-slot.none { background: color-mix(in srgb, var(--color-error) 35%, transparent); border-color: color-mix(in srgb, var(--color-error) 65%, transparent); }
.ctrl-div { align-self: stretch; width: 1px; margin: 0 4px; background: var(--border-primary); }
.btn.sm.on { border-color: var(--border-highlight); background: var(--surface-6); }

/* ── 배치 둘 [2026-09-03 사용자 지시] — 컨트롤의 버튼 하나가 오간다 (SCREEN_DESIGN §4-2)
   기본(클래스 없음) = **넓게**: 아레나 판 전폭(ADR-0095) · 로그/누적은 창
   `.split`          = **나눔**: 좌 아레나(열을 뺀 폭 · 넓게와 같은 높이 · 같은 카드 · ADR-0097) / 우 로그 열 (ADR-0093)
   ⚠ 두 배치가 **같은 뼈대**를 쓴다 — 판(.pane) DOM 은 하나뿐이고 JS 가 집만 옮긴다(쌓인 로그를 안 버리려고) */
.battle-body.split {
    display: grid; grid-template-columns: minmax(0, 1fr) minmax(300px, 25%); grid-template-rows: minmax(0, 1fr); gap: 14px; align-items: stretch;
}
/* 나눔 배치 — 폭은 격자 칸이 정하고 높이는 **넓게와 같은 남는 세로**다(비를 안 지킨다 · ADR-0097 — 비 2.33 이면 가방이 박스 끝에 못 닿는다).
   카드 · 진형 간격은 넓게와 같다 (ADR-0093) */
/* 우측 딜미터 열 — 높이 예산은 아레나와 같다. 판은 그 안에서만 스크롤한다
   ⚠ `display:flex` 는 브라우저 기본 `[hidden]{display:none}` 을 **이긴다** — 아래 한 줄이 없으면 넓게 배치에서도 빈 열이 자리를 먹는다
      (.modal-layer 와 같은 함정이다) */
/* 높이는 격자의 `align-items: stretch` 가 준다 — 아레나와 **정확히** 같은 높이가 된다.
   옛 `max-height: clamp(280px,38vh,360px)` 은 아레나보다 짧게 끊겨 아랫변이 어긋났다 */
.battle-side { display: flex; flex-direction: column; min-height: 0; }
.battle-side[hidden] { display: none; }

/* 관전 화면 한 장 [2026-09-11 사용자 지시 · ADR-0095 · ADR-0097] — 전투 판 + 가방(`.bt-page` — 박스 `.page`)이 박스 세로를 채운다.
   **두 배치가 같은 뼈대다** — 전투 판 → `.battle-body` → 아레나가 **남는 세로**를 넘겨받고 가방은 제 높이로 맨 아래(박스 끝)에 선다.
   나눔 배치는 그 세로를 아레나와 로그 열이 나눠 갖는다(위 `.battle-body.split` 격자). 박스 아랫변과 아래 여백은 셸 절 */
/* 전투 판과 보관 사이 = **캐릭터 탭의 단 사이와 같은 14** [2026-09-14 사용자 지시] — 전투 판 아랫변이 캐릭터 탭 네 칸의 아랫변과 같은 높이에 선다.
   ⚠ 보관이 두 칸(`.bag-row` — 패널이 아닌 격자)이 된 09-11 부터 `.panel + .panel` 마진이 안 붙어 **전투 판이 보관에 달라붙어 있었다**
      (1600×800 실측 — 전투 판 아랫변 596.3 · 캐릭터 탭 네 칸 583.7). 간격은 `gap` 이 들고, 한 칸(재료 탭 · `.panel.bag`)에 붙던 마진은 걷는다 — 안 걷으면 28 */
.bt-page { display: flex; flex-direction: column; gap: 14px; }
.arena-page { gap: 18px; }
/* 콜로세움 · 결투장 — 탭 둘 · 뼈대 하나 [2026-10-18 사용자 지시 · ADR-0670] — 박스 안이 두 열: 왼쪽 레일(상대의 출처 · 결과가 움직이는 것) | 오른쪽 판.
   판은 카드 셋이 가운데 모여 좌우가 비었다 — 레일이 그 빈 폭을 쓴다. 레일 폭은 clamp(이름 칸이 들어 고정 px 이 아니다 · src/ui/README.md 크기 정책) */
.arena-page { min-height: 0; }
.arena-page > h2 { margin-bottom: 0; }
/*   머리 그림 — 탭 이름 앞 · 글씨 높이보다 조금 크게(밑줄 선을 안 민다 — 음수 여백) */
/*   `.panel > h2` 는 양 끝으로 민다(제목 · 오른쪽 small) — 여기는 그림과 이름이 붙어 서야 해 왼쪽으로 모은다(같은 특이도를 이긴다) */
.panel > h2.arena-h { align-items: center; justify-content: flex-start; gap: 8px; }
.arena-h .arena-h-ico { width: 34px; height: 34px; margin: -8px 0 -6px; }
.arena-h > .heading-label { display: inline-flex; align-items: center; gap: 8px; }
.arena-wrap { flex: 1 1 0; min-height: 0; display: grid; grid-template-columns: clamp(250px, 22%, 330px) minmax(0, 1fr); gap: 22px; }
.arena-main { display: flex; flex-direction: column; gap: 12px; min-width: 0; min-height: 0; }
.arena-rail { display: flex; flex-direction: column; gap: 10px; min-width: 0; min-height: 0; padding-right: 22px; border-right: 1px solid var(--border-dark); }
/*   판 머리 한 줄 — Party 고르개 · 출전 인원 · [편성 수정] · 오른쪽 끝 상대의 출처(AI 는 AI 라고 적는다) */
.arena-selection { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; }
.arena-selection .sub-h { margin: 0; }
.arena-selection .segmented { margin: 0; }
.arena-from { margin-left: auto; color: var(--text-secondary); font-size: var(--fs-sm); }
.ar-ico { display: block; width: 100%; height: 100%; object-fit: contain; pointer-events: none; }

/* 콜로세움 레일 — 사다리 · 등급마다 한 줄 · 맨 위 = 가장 높은 등급(올라가는 모양). 줄 사이 세로는 레일이 나눠 준다 */
.cs-progress { font-size: var(--fs-md, 15px); font-weight: 700; color: var(--text-primary); letter-spacing: .02em; }
.cs-ladder { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; gap: 6px; position: relative; }
/*   등급을 잇는 세로 기둥 — 휘장 가운데를 지난다(「위로 오른다」가 그림으로 읽힌다) */
.cs-ladder::before { content: ''; position: absolute; left: 34px; top: 20px; bottom: 20px; width: 2px; background: var(--border-primary); }
.cs-tier { flex: 1 1 0; min-height: 0; display: flex; align-items: center; gap: 10px; padding: 4px 8px 4px 6px; border: 1px solid var(--border-dark); background: var(--surface-1); position: relative; }
.cs-tier.current { border-color: var(--border-highlight); background: var(--surface-4); }
.cs-tier.earned { border-color: var(--bronze-line); }
.cs-emblem { flex: none; width: 60px; height: 60px; position: relative; z-index: 1; }
/*   아직 못 얻은 휘장 = 흐린 회색 · 지금 오르는 등급은 반쯤 · 얻은 휘장은 제 색 */
.cs-emblem .ar-ico { filter: grayscale(1) brightness(.45); opacity: .75; }
.cs-tier.current .cs-emblem .ar-ico { filter: grayscale(.55) brightness(.8); opacity: 1; }
.cs-tier.earned .cs-emblem .ar-ico { filter: drop-shadow(0 0 6px rgba(var(--tint-rgb), .12)); opacity: 1; }
.cs-tier-body { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.cs-tier-name { display: flex; align-items: baseline; gap: 8px; font-weight: 700; color: var(--text-muted); white-space: nowrap; }
.cs-tier.current .cs-tier-name, .cs-tier.earned .cs-tier-name { color: var(--text-primary); }
.cs-tier-name small { font-size: var(--fs-xs); font-weight: 400; color: var(--text-muted); }
.cs-floors { display: flex; gap: 4px; flex-wrap: wrap; }
/*   층 칸 — 깬 층 채움 · 다음 층 강조 테두리(숨쉬기) · 안 열린 층 흐림 · 승급전 = 검투사 투구 위에 층 번호 · 고른 층 = 굵은 흰 테두리 */
.cs-floor { position: relative; width: 36px; height: 30px; padding: 0; display: inline-flex; align-items: center; justify-content: center; overflow: hidden;
    border: 1px solid var(--border-primary); background: var(--bg-input); color: var(--text-muted); font-size: var(--fs-sm); cursor: pointer; }
.cs-floor b { position: relative; z-index: 1; font-weight: 700; text-shadow: 0 1px 2px rgba(var(--shadow-rgb), .9); }
.cs-floor.clear { background: var(--warn-bg); border-color: var(--bronze-line); color: var(--bronze-fg); }
.cs-floor.next { border-color: var(--color-progress); color: var(--text-primary); animation: cs-next 1.6s ease-in-out infinite; }
.cs-floor.locked { opacity: .45; cursor: default; }
/*   승급전 — 투구 그림이 칸을 채우고 층 번호는 오른쪽 아래 작은 글씨(이 칸이 다르다는 것이 번호보다 먼저 읽힌다) */
.cs-floor.gate { width: 44px; border-color: var(--elite-line); }
.cs-floor.gate .ar-ico { position: absolute; left: 2px; top: 1px; width: calc(100% - 4px); height: calc(100% - 2px); opacity: .9; }
.cs-floor.gate b { position: absolute; right: 2px; bottom: 0; font-size: 10px; line-height: 1.1; }
.cs-floor.gate.locked .ar-ico { filter: grayscale(1); }
.cs-floor.on { outline: 3px solid var(--text-primary); outline-offset: 1px; z-index: 2; }
.cs-floor:not(:disabled):hover { border-color: var(--border-highlight); }
@keyframes cs-next { 0%, 100% { box-shadow: 0 0 0 0 rgba(255, 140, 0, 0); } 50% { box-shadow: 0 0 8px 1px rgba(255, 140, 0, .45); } }
@media (prefers-reduced-motion: reduce) { .cs-floor.next { animation: none; } }

/* 결투장 레일 — 리그 카드 + 상대 후보 셋 + [새 상대] · [친선전] */
.ar-league { display: flex; gap: 12px; align-items: center; padding: 10px; border: 1px solid var(--border-secondary); background: var(--surface-4); }
.ar-league-ico { flex: none; width: 84px; height: 84px; }
.ar-league-info { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.ar-league-name { font-weight: 700; color: var(--text-secondary); }
.ar-rating { display: flex; align-items: baseline; gap: 6px; }
.ar-rating b { font-size: 30px; line-height: 1; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.ar-rating small { font-size: var(--fs-xs); color: var(--text-muted); }
.ar-bar { height: 6px; background: var(--surface-7); border: 1px solid var(--border-dark); }
.ar-bar > i { display: block; height: 100%; background: var(--color-progress); }
.ar-next, .ar-record { font-size: var(--fs-xs); }
.ar-cands-h { margin: 6px 0 0; }
.ar-cands { display: flex; flex-direction: column; gap: 6px; }
.ar-cand { display: flex; align-items: center; gap: 10px; padding: 6px 10px 6px 6px; border: 1px solid var(--border-primary); background: var(--surface-1); color: var(--text-secondary); text-align: left; cursor: pointer; }
.ar-cand .ar-ico { flex: none; width: 44px; height: 44px; }
.ar-cand:hover { border-color: var(--border-highlight); }
.ar-cand.on { border-color: var(--text-primary); background: var(--surface-5); }
.ar-cand-r { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; }
.ar-cand-r b { font-size: 18px; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.ar-cand-r small { font-size: var(--fs-xs); color: var(--text-muted); }
.ar-cand-stake { display: flex; flex-direction: column; align-items: flex-end; font-size: var(--fs-sm); font-variant-numeric: tabular-nums; }
.ar-cand-stake em { font-style: normal; }
.ar-cand-stake .up { color: var(--color-success); }
.ar-cand-stake .down { color: var(--color-error); }
.ar-cand.ghost .ar-cand-r b { font-size: var(--fs-md, 15px); }
.ar-rail-btns { display: flex; gap: 8px; }
/*   리그 표 — 레일 아래 · 등급마다 한 줄(휘장 · 이름 · 문턱) · 맨 위 = 가장 높은 리그 · 내 리그 강조 · 아래 리그는 흐림 없이, 위 리그는 흐린 휘장 */
.ar-leagues { margin-top: auto; display: flex; flex-direction: column; gap: 2px; border-top: 1px solid var(--border-dark); padding-top: 8px; }
.ar-lg { display: flex; align-items: center; gap: 8px; padding: 2px 6px; font-size: var(--fs-xs); color: var(--text-muted); }
.ar-lg .ar-ico { flex: none; width: 24px; height: 24px; }
.ar-lg.above .ar-ico { filter: grayscale(1) brightness(.5); }
.ar-lg span { flex: 1 1 0; }
.ar-lg em { font-style: normal; font-variant-numeric: tabular-nums; }
.ar-lg.on { color: var(--text-primary); background: var(--surface-5); outline: 1px solid var(--border-secondary); }

/* 친선전 창 — 글상자 둘이 나란히 · 한 칸 = 제목 / 글상자 / 버튼 (옛 온라인 갈래의 줄 · ADR-0656 → ADR-0670) · 사유 줄은 그 아래 */
.ar-code-modal { width: min(920px, 92%); }
.arena-code { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 6px 24px; align-items: start; }
.arena-code-box { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; min-width: 0; }
.arena-code-box .sub-h { margin: 0; white-space: nowrap; flex-basis: 100%; }
.arena-code-text { flex: 1 1 100%; min-width: 0; height: 110px; resize: none; background: var(--bg-input); color: var(--text-primary); border: 1px solid var(--border-secondary);
    font-size: var(--fs-xs); font-family: var(--font-main); padding: 4px 6px; word-break: break-all; overflow: auto; user-select: text; caret-color: auto; }
.arena-code-btns { display: flex; gap: 8px; }
.arena-bad { flex-basis: 100%; color: var(--color-error); font-size: var(--fs-sm); margin: 0; padding: 0; list-style: none; }
/* 두 팀 = 관전 판 그대로 [2026-10-12 사용자 지시 · ADR-0606] — `.arena` · `.side-*` · `.divider` · `.unit-slot` 규칙을 그대로 입는다
   (위 상대 · VS · 아래 우리 팀 · 후열은 VS 반대쪽으로 `--form-step`). 판은 남는 세로를 받는다(`.arena` 의 flex · 바닥 높이) */
/* 빈자리 · 상대 없음 = 관전 카드와 같은 크기의 점선 카드 — 띠 · 본문 높이는 카드 규칙이 그대로 잡는다 */
/*   진영 색(`.unit.enemy` 윗변)을 안 입는다 — 아직 아무도 없는 자리다. 띠는 높이만 잡는다 */
.arena-prep .unit.vacant { background: transparent; border: 1px dashed var(--border-secondary); border-top-width: 3px; }
.arena-prep .unit.vacant > .unit-top { visibility: hidden; }
.arena-prep .unit.vacant .unit-body { justify-content: center; text-align: center; }
.arena-actions { display: flex; gap: 12px; align-items: center; margin-top: auto; }
/* 결투 관전 = 원정 관전과 같은 높이 [2026-10-24 사용자 지시 · ADR-0766] — 전투 판은 `.bt-page > .battle-panel` 의 flex 가 나머지를 받고,
   아래 칸이 원정 보관 줄 자리를 든다. 칸 안의 보관 줄(`itemsPanel`)은 **높이만 빌린다** — 안 보이고 안 눌린다(포커스도 안 간다).
   그 위를 **두 팀 누적 데미지 판**(`.tdm` — 재생기 `renderTeams`)이 덮는다 (ADR-0769) */
.arena-floor { flex: none; position: relative; }
.arena-floor > .bag-row { visibility: hidden; pointer-events: none; }
/*   두 판은 보관 줄의 두 칸처럼 나란히 · 간격도 같은 14 · 판은 패널 모양 그대로 */
.tdm { position: absolute; inset: 0; display: flex; gap: 14px; }
.tdm-team { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 6px; }
.tdm > .panel + .panel { margin-top: 0; }   /* `.panel + .panel` 의 세로 마진을 걷는다 — 나란히 선 판이다 */
/*   머리 줄과 유닛 줄이 같은 열을 쓴다 — 초상 · 이름 | 가한 피해 | 받은 피해 (머리는 팀 이름이 앞 두 열을 덮는다) */
.tdm-head, .tdm-row { display: grid; grid-template-columns: 44px minmax(0, 1fr) minmax(0, 1.25fr) minmax(0, 1.25fr); column-gap: 10px; align-items: center; }
/*   머리 아래 선 = 패널 제목(`.panel > h2`)의 선 · 팀 이름도 제목 글씨 [2026-10-24 사용자 지시 · ADR-0771] — 합계 수는 없고 열 이름만 막대 열 위에 선다 */
.tdm-head { border-bottom: 1px solid var(--border-primary); padding-bottom: 5px; }
.tdm-name { grid-column: 1 / 3; font-size: var(--fs-md); font-weight: bold; color: var(--text-primary); }
.tdm-col { font-size: var(--fs-sm); color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/*   소환으로 줄이 늘면 판 안에서 스크롤한다 — 판 높이는 보관 줄 높이로 박혀 있다 */
.tdm-rows { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; gap: 4px; overflow-y: auto; }
.tdm-row .dmg-face { width: 44px; height: 44px; }
.tdm-n { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tdm-v { display: flex; align-items: center; gap: 8px; min-width: 0; }
.tdm-v .bar.dmg { flex: 1 1 0; min-width: 0; margin-top: 0; }
.tdm-v > b { flex: none; min-width: 4.5em; text-align: right; font-variant-numeric: tabular-nums; }
.tdm-row.fallen { opacity: .45; }   /* `.down` 은 수치 감소(빨강)의 전역 이름이라 안 쓴다 */
/*   보기 버튼 [요약] · [스킬별] — 오른쪽 판 머리 끝 (ADR-0772). 흐름 밖에 띄운다 — 머리 줄의 높이 · 열 격자를 안 건드려 두 판의 줄이 같은 높이에 선다 */
.tdm-head { position: relative; }
.tdm-view { position: absolute; right: 0; bottom: 4px; flex-wrap: nowrap; }
/*   스킬별 보기 — 유닛이 가로로 한 명씩(사이 세로선) · 유닛 머리 아래에 스킬마다 한 줄. 줄이 넘치면 그 열 안에서 스크롤한다 */
.tdm-cols { flex: 1 1 0; min-height: 0; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); column-gap: 12px; }
.tdm-hero { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 5px; }
.tdm-hero + .tdm-hero { border-left: 1px solid var(--border-dark); padding-left: 12px; }
.tdm-hero.fallen { opacity: .45; }
.tdm-hh { display: flex; gap: 8px; align-items: center; min-width: 0; }
.tdm-hh .dmg-face { flex: none; width: 36px; height: 36px; }
.tdm-hn { min-width: 0; display: flex; flex-direction: column; }
.tdm-ht { font-size: var(--fs-xs); color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tdm-ht b { color: var(--text-primary); font-weight: 600; font-variant-numeric: tabular-nums; }
.tdm-sks { flex: 1 1 0; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }
.tdm-sk { display: flex; align-items: center; gap: 6px; font-size: var(--fs-sm); line-height: 1.35; }
.tdm-skn { flex: 1 1 0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-secondary); }
.tdm-sk > b { flex: none; font-weight: 600; font-variant-numeric: tabular-nums; }
/* 우리 팀 아래 물약 · 전술 [2026-10-03 사용자 지시 · ADR-0497] — 카드 줄 바로 아래에 **늘 선다**.
   두 열이다 — 왼쪽 물약 · 오른쪽 파티 전술. 한 줄로 쌓으면 전술 7칸에서 결투 버튼이 한 장(1600×800) 밖으로 밀렸다(실측).
   진형 글씨 칸은 걷었다 — 카드 자리가 진형을 말한다 (ADR-0602).
   Party 버튼을 누르면 물약 → 전술 순으로 내려온다. 움직임은 누른 직후 한 번(`.unfold` 를 JS 가 첫 그리기에만 단다 — `.sort-fold.anim` 과 같은 수법) */
.arena-load { display: grid; grid-template-columns: minmax(0, auto) minmax(0, 1fr); gap: 12px 28px; margin-top: 16px; align-items: start; }
.arena-load > .dw-pot { grid-column: 1; }
.arena-load > .dw-tac { grid-column: 2; flex: none; }
.arena-load .sub-h { margin: 0 0 6px; }
.arena-load .dw-tac-row { margin-bottom: 3px; }
.arena-load.unfold > * { animation: arena-load-item .26s ease-out both; }
.arena-load.unfold > :nth-child(2) { animation-delay: .1s; }
@keyframes arena-load-item {
    from { opacity: 0; transform: translateY(-12px); }
    to   { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) { .arena-load.unfold > * { animation: none; } }
.bt-page > .panel + .panel { margin-top: 0; }
.bt-page > .battle-panel { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; }
.battle-panel > .battle-body { flex: 1 1 0; min-height: 0; }
.battle-panel > .battle-body:not(.split) { display: flex; flex-direction: column; }
/* 가방은 칸 · 그림이 한 단 크다 — **관전과 캐릭터 탭이 같은 크기**다(`.bag` = `itemsPanel` 의 패널 · ADR-0097).
   **보관은 두 칸이다** [2026-09-11 사용자 확정] — 왼쪽 창고 · 오른쪽 인벤토리가 나란히 서고 **둘 다 3줄**이다.
   열 수는 `auto-fill` 이 아니라 **칸 수 ÷ 3**(`--cols` — `stash_cap` · `inventory_cap` · app.js itemsPanel)이다 — 줄 수를 박고 폭은 열 수대로 나눈다.
   두 칸의 열 합이 24 면(12 · 12 · 9 · 15 …) 판 안 1337 에서 **한 변 약 51.5** 로 09-11 이전(52)과 같다 */
/* 두 칸은 **윗변 · 칸 줄 · 아랫변이 맞는다** [2026-09-14 사용자 지시] — 도구 줄에 버튼([분해] · [자동 분해])이 서는 것은 인벤토리 쪽뿐이라
   창고 쪽 도구 줄이 글자 높이만큼 낮고, `align-items: start` 였던 창고 패널이 약 3px 짧았다. 두 패널을 행 높이로 늘리고 **모자란 높이는 도구 줄이 받는다** —
   칸 격자는 두 칸이 같은 높이라 아래에 붙어 칸 줄까지 맞는다. 버튼 높이를 px 로 박지 않는다(글꼴이 바뀌면 다시 어긋난다) */
/* 두 칸의 폭은 **열 수(`--cols` = 상한 ÷ 3 · app.js itemsPanel)대로** 나눈다 — 바탕 30 = 패널 좌우 여백 · 테두리 34 − 칸 간격 4 라
   남는 폭이 열 수에 비례해 붙으면 (칸 + 간격)이 두 칸에서 같다 → 창고 · 인벤토리 칸 크기가 같다. 12 · 12 면 옛 1fr 1fr 과 같은 폭이다 */
.bag-row { display: flex; gap: 14px; align-items: stretch; }
.bag-row > .bag { display: flex; flex-direction: column; flex: var(--cols, 12) 1 30px; min-width: 0; }
/* 모자란 높이는 **도구 줄 아래 빈자리**가 받는다(격자가 아랫변에 붙는다) — ~~도구 줄이 늘어난다~~ 는 두 칸의 줄 수가 다를 때(인벤토리 4줄 시안 2026-10-13)
   늘어난 도구 줄 가운데로 창고 이름이 내려앉았다. 이름 줄은 제 높이로 윗변에 붙는다 */
.bag-row > .bag > .items-tools { flex: 0 0 auto; }
.bag-row > .bag > .items-tools + * { margin-top: auto; }
/* ⚠ 격자 안의 둘째 패널에도 `.panel + .panel` 의 세로 마진이 붙는다 — 열이 나란한데 **위 마진이 행 높이에 더해져**
   관전(flex 부모)은 227, 캐릭터 탭(grid 부모)은 눌려 218.9 로 **두 화면 크기가 갈렸다**(ADR-0097 「두 탭이 같은 크기」 위반 · 09-11 실측).
   `.cols` 가 이미 같은 예외를 갖고 있다 — 새 컨테이너에도 같은 줄이 필요하다 */
.bag-row > .panel + .panel { margin-top: 0; }
.bag .inv-cells.wide { grid-template-columns: repeat(var(--cols, 12), minmax(0, 1fr)); }
.bag .inv-icon { width: 40px; height: 40px; }
/* 칸 이름 — 「창고」 / 「인벤토리」. 도구 줄 맨 왼쪽에 서고 나머지(부대 버튼 · [분해] · [정렬])가 그 오른쪽이다.
   글씨는 **패널 제목(`.panel > h2`)과 같다** [2026-09-21 사용자 지시 「Equipment 처럼」 · SCREEN_DESIGN §6] — 크기 · 굵기 · 색만.
   밑줄은 안 긋는다 — 제목 줄이 아니라 버튼과 한 줄에 선 이름이라, 선이 버튼 밑까지 안 가고 이름 밑에서 끊긴다 */
.items-name { font-size: var(--fs-md); font-weight: bold; color: var(--text-primary); margin-right: 2px; white-space: nowrap; }
/* 인벤토리 재료 탭 [2026-09-27 · SCREEN_DESIGN §6 · ADR-0379] — **장비 격자(`.bag .inv-cells.wide`)를 그대로 쓴다** — 칸 크기 · 칸 수가 같아
   탭을 바꿔도 인벤토리 · 창고 크기가 안 변한다(사용자 지시). 줄 머리 글자는 없다 — 줄이 곧 종류다.
   0 개인 칸은 흐리게 — 빠지지 않고 자리를 지킨다 */
.mat-cell { cursor: default; }
.mat-cell .inv-icon svg { width: 70%; height: 70%; fill: currentColor; }
.mat-cell.zero .inv-icon { opacity: .35; }
.mat-cell.zero .inv-lv { color: var(--text-muted); }
/* 재료 탭 칸 자리 [2026-10-27 · ADR-0857 · 2026-10-30 ADR-0982] — 한 행에 줄 묶음이 나란히 · 묶음 안 열 = 단계(`app.js:materialGrid` 가 `--r` · `--c` 를 박는다) · 남는 빈 칸은 자동 배치로 그 뒤 구멍을 메운다 */
.mat-grid > .mat-cell { grid-row: var(--r, auto); grid-column: var(--c, auto); }
/* 재료의 단계 숫자 [2026-10-30 · ADR-0983 — 노란 마름모 점(ADR-0857)을 대체] — 칸 왼쪽 위 `I` ~ `V` · 표시 글꼴 · 청동 금색 ·
   `+n` · `Lv.n` 배지와 같은 검은 테두리로 그림 위에서도 읽힌다 · 비용 칸(`.cn-mat`)도 같다 */
.mat-tier {
    position: absolute; top: 2px; left: 3px; z-index: 1; font: 700 10px/1 var(--font-display);
    color: var(--bronze-fg); pointer-events: none;
    text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000;
}
/* 창고 스킬북 탭 [2026-10-14 · SCREEN_DESIGN §6 · ADR-0616] — 재료 탭과 같은 장비 격자 · 칸은 리포트 책 칸(`.book-cell`)의 그림 · 조회만 */
.stash-books .inv-cell { cursor: default; }

.arena {
    /* 적(위) / 파티(아래) 상하 대치 — 가로형 카드가 진영마다 한 줄로 나란히 (2026-08-27 좌우 대치를 시도했다가 사용자 지시로 상하 복귀) */
    display: flex; flex-direction: column; justify-content: center;
    /* 메인 칸 전폭 · **높이 420 고정** (2026-09-03 사용자 지시 · SCREEN_DESIGN §4-2) — 로그가 창으로 빠지며 우측 열이 쓰던 자리를 받는다.
       ⚠ **화면비 고정(`aspect-ratio: 2/1`)은 같은 날 넣었다가 걷었다** — 폭이 688 → 1002 로 +46% 늘면 비를 지킨 높이도 345 → 500 이 되어
       세로가 같이 부푼다. 「지금 화면비 그대로」가 노린 건 박스의 비가 아니라 **지금 보이는 높이**였다.
       420 = 내용(카드 두 줄 + 구분선 345) 위아래로 배경이 약 37px 씩 더 보이는 값이고, 헤드까지 더해도 세로 예산 700 안에서 아래 가방의 도구 줄이 남는다.
       늘어난 **가로** 자리는 카드가 아니라 배경이 받는다 — 카드 크기는 「몬스터·영웅·보스 전부 같은 고정값」이라 안 커진다.
       `min-height` 는 바닥이다 — 카드 줄이 자라면(창 뱃지) 잘리는 대신 상자가 따라 커져야 한다.
       **높이는 화면비 2.33 : 1 이 정한다** [개정 2026-09-03 사용자 지시] — 나눔 배치가 실제로 서는 비(689 × 296)를 넓게에도 그대로 옮겼다.
       ⚠ 폭을 따라 높이도 커진다: 1280 창 1001 × 430 · 1600 창 1340 × 575. 09-03 오전에 같은 이유로 `aspect-ratio` 를 걷었던 적이 있다 —
         그때 문제는 비 자체가 아니라 「높이가 같이 커지는 것」이었고, 이번엔 그걸 알고 택했다.
       옛 `clamp(280px, 38vh, 360px)` 의 뷰포트 비례는 안 되살렸다 — 폭이 전폭으로 정해진 마당에 세로만 창 높이를 따라가면 아레나가 창마다 흔들린다 */
    padding: 14px 12px; min-height: 350px;
    /* **판 전폭 · 남는 세로** [2026-09-11 사용자 지시 · ADR-0095 가 ADR-0091(폭 1184 · 가운데)을 대체] — 넓게 배치는 **비를 안 지킨다**.
       높이는 세로 flex 인 `.battle-body` 가 넘겨 주는 나머지다(아래 「관전 화면 한 장」) — 헤드나 가방이 자라면 아레나가 받는다.
       나눔 배치도 같은 높이를 받고 폭만 로그 열을 뺀 나머지다(ADR-0097). 위 주석의 420 · 2.33 은 이 줄 이전 이야기다 (src/ui/README.md 크기 정책) */
    flex: 1 1 0;
    background: radial-gradient(ellipse at center, var(--surface-0) 0%, var(--bg-input) 100%);
    border: 1px solid var(--border-dark);
    position: relative;
}
/* 스테이지 배경 = **아래 워터마크 띠를 잘라 낸 사본** (`backgrounds/<스타일>/` — 계승 도트는 2752×1360, 신규 아트는 1376×615). 없는 스테이지는 위 그라디언트로 폴백
   [2026-09-11 사용자 지시] 원본(2752×1536)은 오른쪽 아래에 생성기 ✦ 가 박혀 있다. 넓게 보기(비 약 2.66)는 `cover` 가 아래를 12% 잘라
   우연히 가렸고, 나눔 보기(약 1.97)는 3% 만 잘려 드러났다 — CSS 로 가리지 않고 그림에서 뺐다 (src/assets/art/README.md 「backgrounds/」) */
.arena.has-bg {
    background-size: cover;
    background-position: center 95.2%;      /* = 원본의 62% 와 같은 띠 — 넓게 보기 구도는 그대로다. 나눔 보기는 사본의 세로가 다 보인다 */
    image-rendering: var(--bg-render);      /* 도트는 보간하면 뭉개지고 일러스트는 안 하면 선이 끊긴다 — 스타일이 정한다 */
    border-color: var(--border-secondary);
}
/* 가장자리를 어둡게 눌러 유닛 카드가 배경에서 떠 보이게 한다 */
.arena.has-bg::after {
    content: ''; position: absolute; inset: 0; pointer-events: none;
    background: radial-gradient(ellipse at center, transparent 42%, rgba(var(--veil-rgb),.72) 100%);
}
.arena > * { position: relative; z-index: 1; }

/* 진영 = 가로 한 줄 (수가 많으면 줄바꿈) — 카드를 VS 쪽으로 붙인다 */
.side { display: flex; flex-direction: row; flex-wrap: wrap; justify-content: center; gap: 8px; }
.side-enemy { align-items: flex-end; }
.side-party { align-items: flex-start; }

/* 진형이 카드를 **살짝** 위아래로 민다 — **양 진영 다** (⚠ 목업 · 2026-09-09 사용자 지시 · SCREEN_DESIGN §4-1·§4-2).
   전열은 제자리, 후열은 VS 반대쪽으로 — 「누가 앞에 섰나」를 자리가 든다. 랭크가 어디서 오는지만 진영마다 다르다
   (파티 = 편성 진형 · 적 = `monster.csv:role`). 전투 계산은 어느 쪽도 진형을 모른다.
   ⚠ **랭크 2 규칙은 지금 안 선다** — `formation.csv` 도 `monster_role.csv` 도 랭크가 **0·1 뿐**이라 깊이는 언제나 1 이나 2 다.
     세 번째 랭크가 발행되면 그날 바로 서라고 남겨 둔 줄이고, 규칙이 깊이를 안 보므로 값도 안 고친다.
   ⚠ **방향이 진영마다 뒤집힌다** — 「전열 = VS 쪽」은 하나인데 파티는 아래 진영이고 적은 위 진영이라, 같은 랭크 0 이
     파티에선 **위로**, 적에선 **아래로** 간다. 이 뒤집힘이 없으면 적의 전열이 뒤로 물러선 그림이 된다.
   ⚠ **`top` 이지 `margin`/`transform` 이 아니다** — 칸은 이미 `position: relative` 라 흐름을 안 건드리고(줄 높이가 그대로다),
     `transform` 과 달리 새 컨테이닝 블록도 안 만든다(카드 안 팝업 · 툴팁이 쓰던 기준이 그대로 남는다).
   ⚠ **전열은 안 밀린다 — 물러서는 것은 후열뿐이다** [개정 2026-09-10 사용자 지적 · ADR-0083].
     그래서 **전열 ↔ VS 거리가 양 진영 언제나 같다**(1280 창 47.5px = 여백 38 + VS 상자 반 9.5).
     ⚠ 옛 규칙은 「랭크 묶음을 그 진영의 무게중심 기준으로 대칭으로」였고, 그게 **깊이가 다르면 어긋나는 원인**이었다 —
       깊이 2 는 전열이 `step/2` 만큼 당겨지는데 깊이 1(한 랭크에 다 몰림)은 아무도 안 밀려서, 실측 **54.5 vs 40.5px** 로 갈렸다
       (`monster_role.csv` 는 전열/후열 둘뿐이라 두 진영의 깊이가 다른 조합이 흔하다).
     ⚠ **깊이 선택자가 사라졌다** — 랭크 하나가 자기 자리를 혼자 정하므로 `[data-depth]` 를 안 본다(규칙 8 → 4).
       `battle.js` 는 여전히 `data-depth` 를 찍지만 **읽는 CSS 는 없다** — 진형 깊이를 눈으로 볼 수 있게 남긴 표시다.
   ⚠ **상한이 있다 — 창 뱃지 줄이 아레나를 넘는 지점** (1280×700 실측 · 2026-09-10 재측):
     후열이 혼자 물러서므로 봉투는 `여백 + step` 이 정한다 — **`여백 + step ≤ 59.5`**(= 아레나 반높이 214 − VS 상자 반 9.5 − 카드 116 − 뱃지 줄 29).
     지금 값 38 + 21 = 59 → 여유 **0.5px**. step 을 올리려면 여백을 같은 만큼 내려야 하고, 그러면 간격이 그 두 배로 좁아진다. */
/* 40 → 28 → **21px** (2026-09-10 사용자 지시·지적) — 두 번 깎였다. 한 번은 간격을 벌리는 값으로,
   한 번은 **전열을 한 선에 세우는 값**으로. 후자가 더 먹는다: 옛 규칙에서 후열은 `step/2` 만 물러섰는데 이제 `step` 을 통째로 물러서므로
   같은 봉투에 들어가는 step 이 절반이 된다. 21 은 그 제약 아래에서 **간격 95px 을 지키는 최대값**이다
   (`여백 38 + step 21 = 59 ≤ 59.5`). ⚠ 신설 당시 값은 18 이었다 — 아직 그보다 크다. */
.side { --form-step: 21px; }
/* 전열(랭크 0)은 규칙이 없다 = `top: 0`. 후열만 **VS 반대쪽으로** 물러선다 — 방향은 진영이 뒤집는다 */
.side-party .unit-slot[data-rank="1"] { top: var(--form-step); }                    /* 아래 진영 → 아래로 */
.side-party .unit-slot[data-rank="2"] { top: calc(var(--form-step) * 2); }
.side-enemy .unit-slot[data-rank="1"] { top: calc(var(--form-step) * -1); }         /* 위 진영 → 위로 */
.side-enemy .unit-slot[data-rank="2"] { top: calc(var(--form-step) * -2); }

/* VS 선 — **두 진영 사이의 간격을 이 여백이 정한다** (2026-09-08 사용자 지시 · SCREEN_DESIGN §4-2).
   아레나가 내용을 세로 가운데 정렬하므로 이 한 값이 **VS 선을 축으로 위아래를 대칭으로** 민다.
   12 → 40 → 45 → **38px** (2026-09-10 사용자 지시·지적): 전열이 안 밀리게 되며(ADR-0083) 이 여백이 **곧 전열의 자리**가 됐다 —
   전열 ↔ VS 거리 = `38 + 9.5` = **47.5px**, 두 진영 전열 사이 = 그 두 배 **95px**. 옛 값 45 는 전열이 `step/2` 당겨지는 걸 전제한 값이라
   같이 내렸다(간격은 그대로 95 — 당겨지는 몫이 없어진 만큼 여백에서 뺐다).
   ⚠ **아레나 높이가 상한을 정한다** — 높이는 화면비가 정한 고정값(1280 창 430px)이라 가운데가 먹는 만큼 위아래 여백이 준다.
     창 뱃지 줄(`.buff-row` 26 + 3px)이 **흐름 밖**으로 그 여백에 얹혀서, 봉투 식은 위 `.side` 주석의 **`여백 + step ≤ 59.5`** 하나다.
     여기서 더 벌리려면 **아레나 높이**를 손대야 하고 세로 예산 700 · 아래 가방 자리에 걸린다 */
.divider {
    display: flex; align-items: center; gap: 12px;
    margin: 38px 0; font-size: var(--fs-xs); letter-spacing: 2px;
}
.divider::before, .divider::after {
    content: ''; flex: 1; height: 1px;
    background: linear-gradient(90deg, transparent, var(--border-secondary), transparent);
}

/* 유닛 카드 — 위칸 + 가로형 본문 (2026-08-27 개편 · 참고: Lootun 카드, SCREEN_DESIGN §4-2):
   위칸은 영웅 띠(.hs-band)와 같은 배치 — 왼쪽 태그 / 오른쪽 이름. 본문은 왼쪽 초상(§5 얼굴 규격) · 오른쪽에 HP 바 / 행동 게이지 / 스킬 쿨 3줄.
   **크기는 몬스터·영웅·보스가 전부 같은 고정값** (2026-08-27 사용자 지시) — 진영마다 카드 수가 달라도, 정예 특성 줄이 붙어도,
   보스여도 같은 박스다. 본문 높이를 초상 칸에 못박고(.unit-body height) 넘치는 내용은 자른다 — 그래야 위아래 두 진영이 같은 격자로 읽힌다.
   폭 고정 200px 은 화면 폭 정책(라벨 칸 고정 px 금지)의 **의도된 예외**다: 한 진영 최대 3장(party_size_max=3 · wave_monster_max=3)이라
   하한 폭 1280 의 아레나(약 660px)에 3×200 + 여백이 들어간다. 긴 이름은 위칸에서 말줄임된다 */
/* 칸 = 카드 + 그 아래 창 뱃지 줄 (2026-08-31 사용자 지시). 폭 고정은 카드에서 이 칸으로 올라왔다 —
   .side 의 flex item 은 이제 카드가 아니라 칸이다. 카드는 창이 걸리든 말든 **옛 크기 그대로**다 */
/* 폭 200 → **226** (2026-09-03 사용자 지시) — 초상이 카드 높이를 통째로 쓰게 키우면(76 → 101) 정사각이라 가로도 같이 커진다.
   오른쪽 수치 열의 폭(약 104)을 그대로 지키려고 칸을 그만큼만 늘렸다 — 「살짝」의 실제 값이 26px 다 */
/* 칸 = 카드 뿐이다 (2026-09-03 사용자 지시) — 뱃지 줄은 아래에서 **흐름 밖**(absolute)으로 나갔다.
   줄이 흐름에 있으면 창이 없을 때도 26px 를 잡아, 카드가 그 띠 위에 **떠 보였다**(적 진영은 아래 정렬이라 VS 에서 더 밀려났다) */
.unit-slot { flex: 0 0 226px; width: 226px; position: relative; display: flex; flex-direction: column; }

.unit {
    /* 이름 띠 + 본문 (2026-09-03 사용자 지시로 위칸 재도입 — SCREEN_DESIGN §4-2) */
    display: flex; flex-direction: column;
    width: 100%; padding: 5px 6px 6px;
    background: var(--bg-tertiary);
    /* 윗변 3px = 등급 색의 집 (2026-09-03 띠 아랫변으로 옮겼다가 같은 날 복귀 · 사용자 지시) —
       영웅 띠 카드·후보 카드와 같은 문법이다. 색 자리가 카드마다 다르면 같은 뜻으로 안 읽힌다 */
    border: 1px solid var(--border-dark); border-top: 3px solid var(--border-secondary);
    position: relative; text-align: left;   /* overflow 는 주지 않는다 — 피해 팝업이 카드 밖으로 떠오른다 */
    transition: opacity .3s;
}
/* 이름 + 신원 = **오른쪽 열의 첫 줄 하나** (2026-09-03 사용자 지시 · SCREEN_DESIGN §4-2) — 위칸(띠)은 완전히 폐기됐다.
   왼쪽에 무채색 신원(`Lv.n · 직업` / 정예·보스 라벨) · **이름은 오른쪽 끝**(옛 위칸의 「왼쪽 태그 / 오른쪽 이름」 배치).
   일반 몬스터는 이름뿐이라 이름만 오른쪽에 선다. 넘치면 **이름이** 말줄임된다(신원은 고정 조각) */
/* 이름 줄은 **HP 바 바로 위**다 (재개정 2026-09-04 사용자 지시 — 전날의 「초상 윗변」(margin-bottom: auto) 을 물렸다).
   열이 바닥 정렬(flex-end)이라 이름·HP·게이지·스킬이 한 묶음으로 초상 아랫변에 붙고, 남는 세로는 전부 이름 위에 쌓인다 —
   이름을 윗변에 떼어 두면 수치 묶음과 붕 떠서 두 덩어리로 읽혔다 (SCREEN_DESIGN §4-2) */
/* 신원·이름 = **두 줄** (개정 2026-09-07 사용자 지시 — 09-03 「한 줄」 폐기 · SCREEN_DESIGN §4-2) —
   한 줄 합침은 좁은 열(~104px)에서 신원(고정 조각)이 줄을 먼저 먹어 이름이 짜부라졌다.
   윗줄(신원)은 빈 채도 자리를 잡는다(min-height) — 일반 몬스터와 영웅의 이름·HP 가 같은 높이에 선다 */
/* 두 줄 다 **오른쪽 정렬** (재개정 2026-09-07 사용자 지시 — 같은 날 아침의 「둘 다 왼쪽 정렬」을 물렸다).
   카드의 `text-align: left` 를 이 블록에서만 덮는다 — **양 진영 같다**(몬스터의 이름·정예 라벨도 같은 변에 선다) */
.unit-id { width: 100%; min-width: 0; display: flex; flex-direction: column; line-height: 1.2; text-align: right; }
.unit-ident {
    max-width: 100%; min-height: 1.2em;
    font-size: var(--fs-xs); color: var(--text-muted);
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* 이름은 신원보다 **한 단 큰 글씨** (2026-09-07 사용자 지시 — `--fs-sm` → `--fs-md`) —
   두 줄이 같은 크기면 어느 쪽이 이름인지 색(무채색/본문색)으로만 갈렸다. 카드 높이는 안 변한다(열이 바닥 정렬 · 남는 세로는 이름 위) */
.unit-name {
    min-width: 0;
    font-size: var(--fs-md); color: var(--text-primary);
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* 관전 카드 개편판 [2026-09-21 사용자 지시 · ADR-0262] — **개편 규칙은 전부 `.unit.v2` 아래에만 둔다**(되돌림 스위치 `battle.js:CARD_V2` —
   끄면 위 규칙 그대로의 개편 전 카드다 · 개편판으로 고정 ADR-0566).
   **맨 위 띠** = 신원(ADR-0262 · ADR-0270) · **이름 줄**(HP 바 바로 위) = 왼쪽 죄종 칩 · 오른쪽 이름(ADR-0274).
   카드 안쪽 여백을 음수 여백으로 먹어 좌우 끝까지 · 등급 색 윗변 바로 아래. 신원이 빈 일반 몬스터 · 죄종이 없는 몬스터도
   띠는 같은 높이다(`height` 고정 — 칩이 있는 띠와 없는 띠가 0.3px 어긋났다) — 카드 높이가 카드마다 같아야 격자로 읽힌다. 초상 크기는 그대로라 카드가 띠만큼 길어진다 */
.unit.v2 > .unit-top {
    display: flex; align-items: center; gap: 6px; height: 24px;
    margin: -5px -6px 5px; padding: 2px 7px;
    background: rgba(var(--tint-rgb), .06); border-bottom: 1px solid var(--border-dark);
}
.unit.v2 > .unit-top .unit-ident { flex: 0 1 auto; min-width: 0; font-size: var(--fs-xs); color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* 띠 오른쪽 라벨 — 신단 카드의 「신단 획득」 [ADR-0275 의 자리] · 몬스터 등급은 이름 줄 칩으로 내려갔다(ADR-0759). 무채색 보조 글씨 */
.unit.v2 > .unit-top .unit-grade { flex: none; margin-left: auto; font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; }
/* 정예 특성 칩 = **띠 오른쪽 · 오른쪽 맞춤 · 가로 한 줄** [2026-10-24 사용자 「초상화 말고 카드 오른쪽위에 오른쪽정렬로 넣어줘 일단」 · ADR-0775 — ADR-0774 의 초상 아래를 대체].
   띠가 모자라면 **왼쪽 신원이 먼저 줄어든다** — 칩 줄은 줄지 않고(`flex-shrink: 0`) 띠 폭까지만(`max-width: 100%`) · 그래도 넘치면 왼쪽부터 잘린다(카드 밖으로 안 나간다).
   칩 모양은 죄종 칩(`.sin-chip` — 글자색 1px 테두리 · 모서리 2px)에 카드 바탕 · 색은 항목이 든다(없으면 본문 색 · 무채색 테두리) · 글씨는 신원보다 1px 작다(`.tip-meta` 와 같은 값) */
.unit.v2 > .unit-top .unit-traits {
    flex: 0 0 auto; max-width: 100%; min-width: 0; margin-left: auto;
    display: flex; justify-content: flex-end; gap: 3px; overflow: hidden; pointer-events: none;
}
.unit.v2 > .unit-top .unit-traits .trait-chip {
    flex: none; font-size: calc(var(--fs-xs) - 1px); line-height: 15px; padding: 0 5px; white-space: nowrap;
    color: var(--text-primary); border: 1px solid currentColor; border-radius: 2px; background: var(--bg-tertiary);
}
.unit.v2 > .unit-top .unit-traits .trait-chip:not([style]) { border-color: var(--border-secondary); }
/* 이름 줄 = 왼쪽 칩(왼쪽 정렬) · 오른쪽 이름 [2026-09-21 사용자 지시 · ADR-0274] — HP 바와 조금 띄운다(열 틈 2 + 3).
   칩은 영웅 = 죄종 · 몬스터 = 등급 [2026-10-24 · ADR-0759] — 등급 칩 색은 라운드 트랙 · 로그의 정예 · 보스 칸과 같다 */
.unit.v2 .unit-id { flex-direction: row; align-items: center; gap: 6px; margin-bottom: 3px; }
.unit.v2 .unit-id .sin-chip { flex: none; }
.unit.v2 .unit-id .grade-chip.elite { color: var(--elite-fg); }
.unit.v2 .unit-id .grade-chip.boss { color: var(--text-accent); border-color: var(--boss-line); }
.unit.v2 .unit-id .unit-name { flex: 0 1 auto; margin-left: auto; }
/* 개편판 크기 [2026-09-21 사용자 지시 · ADR-0265 · ADR-0270] — 카드가 넓고(226 → 260 · 폭은 칸이 정한다) 스킬 칸 · HP 바 · HP 수치가 크다.
   **스킬 칸은 40 × 40 정사각 고정** · **카드 폭은 스킬 칸 오른쪽 끝에 맞춘다**(ADR-0274) — 252 = 테두리 2 + 안쪽 여백 12 + 초상 101 + 틈 7 + 칸 셋 130(40 × 3 + 틈 5 × 2).
   오른쪽 열 폭이 곧 130 이라 HP 바 · 스킬 칸 줄이 같은 오른쪽 끝에 선다. 칸 크기나 초상을 바꾸면 이 값도 같이 고친다 */
.unit-slot.v2 { flex-basis: 252px; width: 252px; }
.unit.v2 .hp-row .bar.hp { height: 23px; }
.unit.v2 .hp-text { font-size: calc(var(--fs-xs) + 1px); }
.unit.v2 .cd-slot { flex: 0 0 40px; width: 40px; height: 40px; }
/* 본문 — 왼쪽 초상, 오른쪽 수치 열. 높이는 초상 칸에 못박는다 = 모든 카드가 같은 높이 */
/* 높이 101 = 옛 띠(20) + 옛 간격(4) + 옛 본문(76). 위칸이 사라져도 **카드 크기는 그대로 둔다** —
   「몬스터·영웅·보스가 전부 같은 고정값」이 크기의 근거지, 위칸의 유무가 아니다 (2026-09-03) */
.unit-body { display: flex; flex-direction: row; align-items: center; gap: 7px; min-width: 0; height: 101px; overflow: hidden; }
/* 윗변 색 = **등급** (2026-09-03 사용자 지시 · SCREEN_DESIGN §5) — 죄종은 색을 갖지 않는다.
   순서가 규칙이다: 진영 기본 → 영웅 등급. 정예·보스는 아래의 **전체 테두리** 규칙(.unit.elite / .unit.boss)이 덮는다 */
.unit.enemy { border-top-color: var(--enemy-line); }
/* 영웅 등급 — 색은 `data/hero_tier.csv:color_hex` 를 렌더러가 `--tier-line` 으로 건다(아이템 희귀도의 같은 계단이라 화면에서 같은 뜻으로 읽힌다).
   ⚠ 옛 `.unit.tier-rare` · `.unit.tier-unique` 는 걷었다 (2026-09-15) — 등급마다 여기 줄을 박아 둬서, 줄이 없던 `normal` · `magic` 이
   진영색(`--ally-line` 파랑)으로 떨어졌다. 진영색은 이제 변수가 없을 때의 폴백일 뿐이다 */
.unit.party { border-top-color: var(--tier-line, var(--ally-line)); }
/* 등급 = **테두리 색** [개정 2026-09-03 사용자 지시] — 죄종 칩·정예 태그가 카드에서 걷혔으므로 「정예인가」를 이제 테두리 혼자 든다.
   그래서 옛 갈색(#6a4a2a)을 걷고 눈에 띄는 노랑으로 올린다. 배경 색조는 그대로 — 색이 둘 다 바뀌면 정예가 다른 카드로 보인다 */
.unit.elite { border-color: var(--color-warning); background: var(--elite-bg-unit); }
.unit.dead { opacity: .26; filter: grayscale(1); }
/* 무덤 명패가 선 쓰러진 챕터보스 — 카드는 흐려지지 않고 명패가 「죽어 있다」를 든다 · 오른쪽 정보 칸만 한 단 가라앉는다 (ADR-0590) */
.unit.dead.grave { opacity: 1; filter: none; }
.unit.dead.grave .unit-info { opacity: .45; }
.unit .sprite.grave { background: var(--bg-input); }
/* 장착 대상 — 영웅 카드를 누르면 아래 보관 칸이 그 영웅을 향한다 (2026-09-15 사용자 지시 · SCREEN_DESIGN §4-2 · ADR-0137).
   표시는 영웅 띠의 고른 카드(.hs-card.on)와 같은 **파란 겉 테두리**다 — 테두리 색은 등급이 들고 있어 아웃라인이 그 바깥에 선다.
   굵기 3px = 모든 고른 표시와 같다 (2026-10-27 사용자 「약간만 더 두껍게」 → 「모두 3px로」 · §2 「고른 표시」 · ADR-0926) */
.unit.click { cursor: pointer; }
.unit.on { outline: 3px solid var(--color-info); outline-offset: 1px; }
/* 고른 쓰러진 영웅 — 카드에 건 흐림은 아웃라인까지 26% 회색으로 묻는다. 흐림을 안쪽으로 내려 테두리는 제 세기로 서고
   안쪽은 `.unit.dead` 와 같은 값 · 같은 한 박자 늦은 흐려짐이다 (SCREEN_DESIGN §4-2 · ADR-0697) */
.unit.dead.on { opacity: 1; filter: none; }
.unit.dead.on > * { opacity: .26; filter: grayscale(1); transition: opacity .45s .3s, filter .45s .3s; }
/* ⚠ **`.unit.buffed` 의 테두리·발광은 걷었다** (2026-09-03 사용자 지시) — 창이 켜지면 카드 전체에 파란 안쪽 선 +
   바깥 글로우를 두르던 자리다. 카드 테두리는 이미 **등급**을 말하고 있어(일반/정예/보스) 거기에 창까지 얹으면
   같은 변이 두 가지를 말한다. 「무언가 걸려 있다」도 아래 뱃지 줄이 이미 든다 — 줄이 곧 개수이자 종류다.
   ⚠ 클래스 자체는 `battle.js` 가 계속 단다(`refreshUnit`) — 다른 표시를 붙일 자리로 남긴다 */
/* 창 뱃지 줄 — 카드 전체가 「무언가 걸려 있다」를, 이 줄이 「무엇이 걸려 있나」를 든다 (SCREEN_DESIGN §4-2, 2026-08-31).
   자리는 **카드 밖 · 카드 바로 아래** (2026-08-31 사용자 지시) — 카드 안에 두면 그만큼 박스가 커진다.
   ⚠ 창이 없어도 **높이를 그대로 둔다** — 개수를 따라 흔들리면 칸 높이가 변해 카드가 위아래로 뛴다 */
/* 칩 16 → **24px** (2026-09-03 사용자 지시) — 칩이 이모지에서 **그림**으로 바뀌면서
   16px 은 무슨 스킬인지 못 읽는 크기가 됐다(스킬 쿨 칸은 32px 다).
   ⚠ **줄은 흐름 밖이다** (2026-09-03 사용자 지시) — 옛 판은 칸의 둘째 행이라 창이 없어도 26px 를 잡았고,
   그래서 카드가 빈 띠 위에 떠 보였다. `absolute` 라 **칸 높이 = 카드 높이**이고 창 개수가 카드를 못 흔든다
   (「높이를 그대로 둔다」가 지키려던 것 — 카드가 위아래로 안 뛰는 것 — 을 자리를 안 잡는 쪽으로 지킨다).
   자리는 **양 진영 다 화면 기준 카드 밑**이다 [2026-09-15 사용자 지시 · ADR-0128] — 흐름 밖이라 어느 쪽에 두든 카드 자리는 안 움직인다.
   적의 줄은 VS 쪽 여백에 얹힌다(옛 판은 위 진영만 카드 위 · 오른쪽 정렬이었다) */
.buff-row {
    position: absolute; left: 0; right: 0; top: 100%; margin-top: 3px;
    display: flex; flex-direction: row; align-items: center; gap: 3px; height: 26px; overflow: hidden;
}
.buff-chip {
    flex: 0 0 auto; width: 24px; height: 24px;
    display: inline-flex; align-items: center; justify-content: center;
    font-size: var(--fs-xs); line-height: 1; background: var(--bg-input); border: 1px solid;
}
/* 칩도 그림을 든다 (2026-09-03 · SCREEN_DESIGN §2) — 칸을 여백 없이 꽉 채운다 */
.buff-chip img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 이로운 창 = 초록 · 해로운 창 = 빨강. 가르는 것은 창의 값 부호다 (재생기 refreshBuffs) */
.buff-chip.good { border-color: var(--color-success); color: var(--color-success); }
.buff-chip.bad { border-color: var(--color-error); color: var(--color-error); }
/* 창 뱃지 툴팁 — 첫 줄은 이름 + 남은 초, 둘째 줄은 지금 적용 중인 실효값뿐이다. */
.tip-effect-head { display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.tip-effect-head .tip-name { margin-bottom: 0; }
.tip-effect-duration { color: var(--color-info); font-size: var(--fs-xs); font-weight: normal; white-space: nowrap; }
.tip-effect-summary {
    margin-top: 7px; padding-top: 6px; border-top: 1px solid var(--border-dark);
    color: var(--text-primary); white-space: nowrap;
}
/* 물약 카드 · 첫 클리어 상자 카드 [2026-10-30 사용자 지시] — 같은 모양(이름 / 선 아래 효과)에 같은 폭 · 물약 304 와 상자 글자만큼(약 140)의 중간 ·
   상자 줄은 영웅 이름이 길면 낱말 단위로 접힌다 (SCREEN_DESIGN §2 「물약 툴팁 규격」 · §6 「첫 클리어 상자」) */
.tip-card.potion, .tip-card.box-tip { width: 220px; }
.tip-card.box-tip .tip-effect-summary { white-space: normal; word-break: keep-all; }
/* 능력치 설명 카드 [2026-10-10 · ADR-0581] — 같은 모양(이름 / 선 아래 효과 — 여럿이면 한 줄에 하나) · 폭은 글자만큼이고 긴 효과 줄은 낱말 단위로 접힌다 */
.tip-card.stat-tip { width: max-content; max-width: 24em; }
.tip-card.stat-tip .tip-effect-summary { white-space: normal; word-break: keep-all; line-height: 1.5; }
/* 경직 툴팁도 칩과 같은 멈춤 표시 — 글자가 아니라 막대 둘이라 언어·글꼴을 안 탄다. */
.tip-effect-stagger { display: inline-block; position: relative; width: 100%; height: 100%; }
.tip-effect-stagger::before,
.tip-effect-stagger::after {
    content: ''; position: absolute; top: 4px; bottom: 4px; width: 4px;
    background: var(--color-error); opacity: .65;
}
.tip-effect-stagger::before { left: 5px; }
.tip-effect-stagger::after { right: 5px; }
/* 물리 경직 (R110 · SCREEN_DESIGN §4-2 · ADR-0154) — 해로운 창보다 **옅은 빨강**이고 칩 안은 그림이 아니라 **멈춤 표시**(세로 막대 둘)다.
   0.5초씩 켜졌다 꺼지므로 진한 빨강이면 줄이 번쩍인다. 막대는 글자가 아니라 테두리라 언어 · 글꼴을 안 탄다 */
.buff-chip.stagger {
    border-color: color-mix(in srgb, var(--color-error) 55%, transparent);
    color: color-mix(in srgb, var(--color-error) 70%, transparent);
}
.buff-chip.stagger::before {
    content: ''; width: 8px; height: 10px;
    border-left: 3px solid currentColor; border-right: 3px solid currentColor;
}
/* 상태이상 초상 빛깔 [2026-10-28 사용자 지시 · ADR-0936 · SCREEN_DESIGN §4-2] — 결빙 · 화상 · 중독은 **인물이 물든다**.
   초상 그림(`--face` — 재생기가 그 카드의 초상 주소를 건다)을 가림막으로 인물 모양에만 색을 겹친다 — 카드 바탕 · 테두리 · 초상 칸 바탕은 안 바뀐다
   (윗변 · 테두리는 등급, 바탕은 정예 · 보스 몫이다). 흑백은 안 쓴다 — 쓰러진 카드 표시다.
   고정이 아니라 원색 ↔ 그 색 깜빡임이고, 여럿이면 원색을 사이에 두고 번갈아(`data-n` = 색 수 · 색은 `--c0` ~ `--c2` 에 결빙 › 화상 › 중독 순).
   한 번(원색 → 색 → 원색) = `--ail-beat` · 한 바퀴 = 색 수 × 한 번 · 가장 진할 때 = `--ail-peak`. 상태 표시라 관전 배속을 안 탄다 */
:root { --ail-freeze: #4f8cc8; --ail-burn: #d4582a; --ail-poison: #7d9e2c; --ail-beat: 1.6s; --ail-peak: .30; }
.unit .sprite .ail-tint {
    position: absolute; inset: 0; pointer-events: none; opacity: 0;
    mix-blend-mode: color; background-color: var(--c0);
    -webkit-mask: var(--face) center / contain no-repeat; mask: var(--face) center / contain no-repeat;
    animation: ail-pulse1 var(--ail-beat) ease-in-out infinite;
}
.unit .sprite .ail-tint[data-n="2"] { animation-name: ail-pulse2; animation-duration: calc(var(--ail-beat) * 2); }
.unit .sprite .ail-tint[data-n="3"] { animation-name: ail-pulse3; animation-duration: calc(var(--ail-beat) * 3); }
@keyframes ail-pulse1 { 0%, 100% { opacity: 0; } 50% { opacity: var(--ail-peak); } }
@keyframes ail-pulse2 {
    0% { opacity: 0; background-color: var(--c0); } 25% { opacity: var(--ail-peak); background-color: var(--c0); } 49.99% { opacity: 0; background-color: var(--c0); }
    50% { opacity: 0; background-color: var(--c1); } 75% { opacity: var(--ail-peak); background-color: var(--c1); } 100% { opacity: 0; background-color: var(--c1); }
}
@keyframes ail-pulse3 {
    0% { opacity: 0; background-color: var(--c0); } 16.667% { opacity: var(--ail-peak); background-color: var(--c0); } 33.32% { opacity: 0; background-color: var(--c0); }
    33.333% { opacity: 0; background-color: var(--c1); } 50% { opacity: var(--ail-peak); background-color: var(--c1); } 66.65% { opacity: 0; background-color: var(--c1); }
    66.667% { opacity: 0; background-color: var(--c2); } 83.333% { opacity: var(--ail-peak); background-color: var(--c2); } 100% { opacity: 0; background-color: var(--c2); }
}
/* 스턴 별 — 초상 윗부분의 검은 일자 선(`i`) + 그 선을 따라 도는 녹슨 쇠 별 셋(`b` · fx/ui/stun_star.webp). 옆에서 본 궤도다 —
   앞쪽 반 바퀴(아래로 1.5px)는 크게 선 앞, 뒤쪽 반 바퀴는 작게 선 뒤. 별은 제자리에서 정면 → 옆면으로 뒤집힌다(`rotateY`).
   궤도 · 회전은 연출이라 관전 배속(`--fx-k`)을 탄다. 색은 안 바꾼다 — 경직은 칩만이고 별은 스턴에만 선다 */
.unit .sprite .stun-mark { position: absolute; left: 50%; top: 0; width: 66px; height: 24px; margin-left: -33px; z-index: 2; pointer-events: none; }
.stun-mark > i { position: absolute; left: 5px; right: 5px; top: 7px; height: 2px; background: #000; border-radius: 1px; z-index: 2; }
.stun-mark > b {
    position: absolute; left: 50%; top: 8px; width: 14px; height: 14px; margin: -7px 0 0 -7px;
    animation: stun-orbit calc(1.1s * var(--fx-k, 1)) linear infinite;
}
.stun-mark > b:nth-of-type(2) { animation-delay: calc(-.3667s * var(--fx-k, 1)); }
.stun-mark > b:nth-of-type(3) { animation-delay: calc(-.7333s * var(--fx-k, 1)); }
.stun-mark img { display: block; width: 100%; height: 100%; object-fit: contain; animation: stun-spin calc(.55s * var(--fx-k, 1)) linear infinite; }
@keyframes stun-orbit {
    0%    { transform: translate(25px, 0) scale(.81);         z-index: 3; }
    12.5% { transform: translate(17.7px, 1.1px) scale(.94);   z-index: 3; }
    25%   { transform: translate(0, 1.5px) scale(1);          z-index: 3; }
    37.5% { transform: translate(-17.7px, 1.1px) scale(.94);  z-index: 3; }
    50%   { transform: translate(-25px, 0) scale(.81);        z-index: 1; }
    62.5% { transform: translate(-17.7px, -1.1px) scale(.68); z-index: 1; }
    75%   { transform: translate(0, -1.5px) scale(.62);       z-index: 1; }
    87.5% { transform: translate(17.7px, -1.1px) scale(.68);  z-index: 1; }
    100%  { transform: translate(25px, 0) scale(.81);         z-index: 3; }
}
@keyframes stun-spin { to { transform: rotateY(360deg); } }
@media (prefers-reduced-motion: reduce) {
    .unit .sprite .ail-tint { animation: none; opacity: calc(var(--ail-peak) * .7); }
    .stun-mark > b, .stun-mark img { animation: none; }
    .stun-mark > b:nth-of-type(1) { transform: translate(-18px, 0) scale(.9); }
    .stun-mark > b:nth-of-type(3) { transform: translate(18px, 0) scale(.9); }
}
/* 오른쪽 정보 열 — 위에서부터 (정예 특성) / HP / 행동 게이지 / 스킬 쿨 */
/* 오른쪽 정보 열 — HP / 행동 게이지 / 스킬 쿨.
   **아래로 붙인다** (2026-09-03 사용자 지시) — 옛 판은 가운데 정렬이라 스킬 칸의 아랫변이 초상 아랫변보다 위에 떠서
   두 열의 바닥이 어긋났다. `align-self: stretch` 로 열이 본문 높이를 통째로 쓰고 `flex-end` 로 내용을 바닥에 붙이면,
   **스킬 칸 아랫변 = 초상 아랫변**이 된다 (본문 높이를 초상이 정하므로) */
.unit-info { flex: 1 1 0; min-width: 0; align-self: stretch; display: flex; flex-direction: column; justify-content: flex-end; gap: 2px; }
/* 위칸(.unit-band · .unit-name)은 2026-09-03 사용자 지시로 폐기 — 이름·죄종 칩·정예/보스 태그가 카드에서 사라졌다 (SCREEN_DESIGN §4-2) */

/* 초상 — 정사각 한 칸. 그림 규격은 공통 조각 .hero-face 와 같다(네모 박스). 보스는 한 단 크다 */
.unit .sprite {
    position: relative;
    /* 76 → **101** (2026-09-03 사용자 지시) — 카드 높이(본문 101)를 통째로 쓴다. 정사각이라 가로도 101 이 되고, 그만큼 칸을 226 으로 넓혔다 */
    flex: 0 0 auto; width: 101px; height: 101px; align-self: center;
    display: flex; align-items: center; justify-content: center;
    background: var(--bg-input); border: 1px solid var(--border-secondary); overflow: hidden;
}
/* 파리 떼 (스웜 · R380 · ADR-0944) — 창 동안 초상 아래쪽에 파리 마리마다 작은 HP 막대 한 줄 · 초상 칸 안에 겹쳐 카드 배치를 안 민다 · 쓰러진 파리는 흐린 빈 칸 */
.unit .sprite .fly-row { position: absolute; left: 4px; right: 4px; bottom: 4px; z-index: 2; display: flex; gap: 3px; pointer-events: none; }
.unit .sprite .fly-row > i { flex: 1 1 0; height: 7px; position: relative; overflow: hidden; background: var(--bg-input); border: 1px solid var(--border-dark); }
.unit .sprite .fly-row > i > b { position: absolute; inset: 0; background: var(--hp-fill); transform-origin: left; }
.unit .sprite .fly-row > i.gone { opacity: .35; }
/* 보스도 같은 크기다 — 카드 크기를 진영·등급 무관 고정으로 못박았다 (2026-08-27). 보스 표시는 태그와 테두리가 든다 */
/* 얼굴 이미지가 있는 유닛 — **없으면 양쪽 다 빈 칸**이다 (영웅 2026-09-03 · 몬스터 2026-09-06 사용자 지시) */
.sprite.has-face { background: radial-gradient(circle at 50% 38%, var(--surface-6) 0%, var(--bg-input) 100%); }
.sprite.has-face img {
    position: absolute; inset: 0;      /* 칸을 통째로 쓴다 — 밑에 깔린 것이 없다 (.face 와 같은 규칙) */
    width: 100%; height: 100%; object-fit: contain;
    image-rendering: var(--face-render);
    /* drop-shadow 는 걷었다 — 그림 상자가 음영 바탕으로 불투명해져 인물이 아니라 상자에 그림자가 진다 (ADR-0957) */
}
/* 아트 없는 몬스터의 폴백 = **이니셜 한 글자**뿐 [2026-09-03 사용자 지시]. 옛 죄종 색 원판 규칙은 폐기했다 —
   원형도 색도 몬스터만 달라서 「카드 형태를 똑같이」와 「죄종 안 보이게」 둘 다에 걸렸다. 칸은 영웅과 같은 빈 네모다 */

.unit .bar { width: 100%; }
/* HP 바 — 수치는 바 가운데 (2026-08-27). 바를 글자 높이만큼 키운다 */
.hp-row { position: relative; width: 100%; }
/* 15 → 18 → **20** (2026-09-04 사용자 지시 — 한 단 더) — 본문 101 예산 안이다(이름 16 + 20 + 8 + 32 + 여백 ≈ 94) */
.hp-row .bar.hp { height: 20px; }
.hp-text {
    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
    font-size: var(--fs-xs); line-height: 1; color: var(--text-primary); text-shadow: 0 1px 2px #000;
    white-space: nowrap; pointer-events: none;
}
/* ───────── 행동 게이지 / 쿨 게이지 ─────────
   숫자로 "12s" 라고 적어두면 언제 터지는지 읽히지 않는다. 채워지는 칸으로 바꾸면
   행동 주기(battle_design §2)와 실시간 쿨(§6)이 눈으로 보인다. */

/* 행동 게이지 — 다 차면 그 유닛이 행동한다 */
.act-row {
    /* 5 → 8 (2026-09-03 사용자 지시) — 「차오르면 행동한다」의 인과가 5px 로는 안 읽혔다 */
    width: 100%; height: 8px; margin-top: 1px;
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
.act-fill {
    display: block; height: 100%; width: 100%;
    background: var(--color-warning);        /* 기본 노랑 — 파견 창(채굴 타격)이 쓴다 */
    transform: scaleX(0); transform-origin: left;   /* 차오름은 늘임이다 — 폭을 바꾸면 눈금마다 배치를 다시 잰다 (DEV_PLAN §4 #86) */
    transition: transform .1s linear;        /* 틱 간격과 맞춘다 */
}
/* 관전 카드는 **무기 종류** 색이다 [2026-10-02 사용자 지시 · ADR-0476] — 물리 무기 주황 · 마법 무기(평타 없음 — 칸을 쌓아 스킬에 쓴다 · R198 · R200) 파랑.
   양 진영 같다(옛 적 갈색 `--enemy-fill` 폐지) · 누적 판 막대(`.bar.dmg > i.k-phys/k-magic`)와 같은 두 색 */
.act-fill.k-phys { background: var(--dt-physical); }
.act-fill.k-magic { background: var(--color-info); }
/* 마법 무기는 **칸으로 갈린다** [2026-10-02 사용자 확정 · R200 · ADR-0483] — 같은 자리 같은 높이를 칸 수(`cast_charge_max`)로 나눈다.
   찬 칸 = 가득 · 지금 차는 칸 = 경과 ÷ 주기 · 나머지 = 빈 칸. 틀은 칸마다 따로 그린다(한 줄의 틀을 걷는다) */
.act-row.segs { display: flex; gap: 2px; background: none; border: none; }
.act-seg { flex: 1 1 0; min-width: 0; height: 100%; background: var(--bg-input); border: 1px solid var(--border-dark); }
/* 막바지(85%~) 발광(.act-row.full)은 **삭제했다** (2026-09-04 사용자 지시) — 인과는 특수효과가 아니라
   게이지가 실제로 100% 까지 차는 것으로 읽는다. 행동 틱의 100% 표시와 스냅 리셋은 재생기(battle.js refreshUnit)가 든다 */

/* 스킬 쿨 3칸 — 슬롯 순서 = 동률 시 우선순위. **왼쪽부터** 1·2·3번 (2026-08-27 세로 3줄 → 가로 3칸).
   세로로 쌓으면 오른쪽 열의 가로 105px 중 아이콘이 13px 만 쓴다. 눕히면 같은 자리에서 아이콘이 13 → 32px 가 되고
   세로 예산은 43 → 35 로 오히려 준다. 아이콘이 안 읽히던 건 공간이 없어서가 아니라 배치가 세로였기 때문이다.
   이름도 % 도 찍지 않는다 — 이름·표기 쿨은 칸의 title 툴팁이 든다 (값을 지운 게 아니라 옮겼다).
   게이지·아이콘 전부 목업이다 — 스킬 미작성이라 타임라인에 스킬 이벤트가 없다 (DEV_PLAN 부채 #13) */
.cd-list { width: 100%; display: flex; flex-direction: row; gap: 5px; margin-top: 3px; }
.cd-slot {
    flex: 1 1 0; min-width: 0; height: 32px; position: relative; overflow: hidden;
    display: flex; align-items: center; justify-content: center;
    font-size: 19px; line-height: 1; color: var(--text-primary);
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
/* 칸이 드는 것은 그림이다 (2026-09-03 · SCREEN_DESIGN §2) — 이모지가 들던 자리를 그대로 채운다.
   `.cd-g` 는 발동 연출(`cd-fire`)이 튀게 하는 상자라 그림도 그 안에 든다 */
.cd-slot .cd-g { display: block; width: 100%; height: 100%; }
.cd-slot .cd-g img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 제 그림이 없는 스킬 = 검은 칸 (2026-09-18 사용자 지시 · ADR-0162) — 스킬 그림을 그리는 칸 전부가 같은 한 줄을 쓴다 (`skillImg` 셋) */
.sk-noart { display: block; width: 100%; height: 100%; background: #000; border-radius: inherit; }
/* 쿨 마스크 — 남은 쿨만큼 위에서 덮는다. 다 걷히면 아이콘이 전부 드러난다 = 준비 완료 */
.cd-slot .cd-mask {
    position: absolute; left: 0; right: 0; top: 0; height: 100%;
    background: rgba(var(--veil-rgb),.78);
    transform-origin: top; transition: transform .1s linear;   /* 걷힘은 줄임(scaleY)이다 — 높이를 바꾸면 눈금마다 배치를 다시 잰다 (DEV_PLAN §4 #86) */
}
/* 빈 칸 — 액티브가 셋을 못 채운 영웅의 남은 자리. 칸 수는 언제나 active_slots 다 (SCREEN_DESIGN §4-2 개정 2026-08-31).
   칸이 사라지면 카드마다 줄 길이가 달라져 위아래 두 진영이 같은 격자로 안 읽힌다 */
/* ⚠ 테두리색을 `--border-dark`(#18182a) 에서 올렸다 (2026-09-03) — 카드 배경(#1a1a2a)과 값이 거의 같아
   **빈 칸이 아예 안 보였다.** 몬스터는 칸 셋이 전부 비어 있어(액티브 데이터 없음) 그 줄이 통째로 사라져 보이고,
   그러면 「스킬 줄이 없는 카드」로 읽힌다 — 빈 칸은 「없다」가 아니라 「아직 안 찼다」여야 한다 (SCREEN_DESIGN §4-2) */
.cd-slot.empty { background: transparent; border-style: dashed; border-color: var(--border-primary); }
/* 다 찬 스킬의 파란 강조(`ready` 테두리)는 **삭제했다** (2026-09-03 사용자 지시) — 찰 때마다 칸이 번쩍여
   소란스러웠다. 마스크가 다 걷힌 것 자체가 「준비」다 — 상태 표시가 이미 게이지 안에 있다 */
/* 정신 집중 [2026-10-22 · R318 · ADR-0723 — ADR-0720 의 카드 떨림을 대체] — 쓰는 그 칸이 표시를 든다: 덮개를 걷어 그림이 다 드러나고
   테두리를 따라 불빛 한 줄기가 돌며(`::before` 의 원뿔 그라데이션이 돌고 `::after` 가 안쪽을 칸 바탕으로 덮어 테두리 띠만 남긴다) 그림이 고동친다.
   늘 켜진다(흔들림 설정과 상관없다) · battle.js `refreshUnit` 이 쓰는 칸에만 건다 · 발동 튐(`fire` — 아래)이 뒤에 서서 튀는 순간엔 그쪽이 이긴다 */
.cd-slot.chan { border-color: var(--color-warning); }
.cd-slot.chan::before {
    content: ''; position: absolute; left: 50%; top: 50%; width: 150%; aspect-ratio: 1; translate: -50% -50%;
    background: conic-gradient(transparent 0 55%, var(--color-warning) 85%, var(--text-primary) 96%, transparent 100%);
    animation: cd-chan-spin calc(900ms * var(--fx-k, 1)) linear infinite;
}
.cd-slot.chan::after { content: ''; position: absolute; inset: 3px; background: var(--bg-input); }
.cd-slot.chan .cd-g { position: relative; z-index: 1; animation: cd-chan-pulse calc(600ms * var(--fx-k, 1)) ease-in-out infinite alternate; }
.cd-slot.chan .sk-lv { z-index: 1; }
.cd-slot.chan .cd-mask { opacity: 0; }
@keyframes cd-chan-spin { to { rotate: 1turn; } }
@keyframes cd-chan-pulse { from { transform: scale(1); filter: brightness(1); } to { transform: scale(1.08); filter: brightness(1.35); } }
@media (prefers-reduced-motion: reduce) {
    .cd-slot.chan::before { animation: none; background: var(--color-warning); }
    .cd-slot.chan .cd-g { animation: none; }
}
/* 발동 — 그 칸이 한 번 튄다. 튀는 건 글리프만 (칸을 키우면 .unit-body 의 고정 높이에 잘린다) */
.cd-slot.fire { border-color: var(--color-warning); background: var(--fire-bg); }
.cd-slot.fire .cd-g { animation: cd-fire .5s ease-out; }
@keyframes cd-fire {
    0% { transform: scale(1); }
    20% { transform: scale(1.45); }
    100% { transform: scale(1); }
}

/* 보스는 **지금 그대로 빨강** (2026-09-03 사용자 확인). 정예(노랑)보다 뒤에 와야 보스가 이긴다 — 순서가 규칙이다 */
.unit.boss { border-color: var(--boss-line); background: var(--boss-bg); }

/* 라운드 진행 트랙 — 구조가 고정이라 한눈에 읽힌다 */
/* 트랙이 헤드 첫 줄에 **가로로** 들어왔다 (2026-09-03) — 옛 세로 쌓기용 `margin-top: 6px` 는 걷었다 */
.round-track { display: flex; flex: 0 0 auto; gap: 2px; }
/* 칸 18 → 16 · 간격 3 → 2 [2026-09-04] — 헤드가 한 줄이 되며 가로를 26px 돌려받아야 했다 (한 자리 숫자라 안 넘친다) */
.round-track .rt {
    width: 16px; line-height: 16px; text-align: center; font-size: var(--fs-2xs);
    border: 1px solid var(--border-dark); background: var(--bg-input); color: var(--text-muted);
}
.round-track .rt.elite { border-color: var(--elite-line-soft); color: var(--elite-fg); }
.round-track .rt.boss { border-color: var(--boss-line); color: var(--text-accent); }
.round-track .rt.done { opacity: .35; }
.round-track .rt.now { background: var(--bg-tertiary); color: var(--text-primary); border-color: var(--border-highlight); }

/* 데미지 숫자 — 생성 후 0.9초 뒤 DOM에서 제거 */
/* 스킬 툴팁 문장 (2026-09-08 · SCREEN_DESIGN §4-2) — 수치표 대신 한 문장. 숫자만 강조색으로 뽑는다 */
.tip-line {
    margin-top: 6px; font-size: var(--fs-sm); line-height: 1.55; color: var(--text-primary);
    max-width: 30em;
}
.tip-hl { color: var(--color-warning); font-weight: 700; }
/* 계산식 [2026-09-10 · SCREEN_DESIGN §2 「스킬 설명창 규격」 · ADR-0089] — Alt 를 누르는 동안 숫자 뒤에 괄호로 선다.
   **숫자만 강조색, 식은 흐린 색** — 식은 풀이지 값이 아니라 문장을 밀어내지 않게 한 단 물러선다.
   값이 없는 자리(도감)는 식이 숫자 자리를 **대신**하므로 이 클래스를 안 쓴다(식 속 숫자가 `.tip-hl` 을 그대로 탄다) */
.tip-fx { color: var(--text-muted); }
/* Alt 각주 — 툴팁 바닥 한 줄(「Alt 세부 옵션」 · 「Alt 비교」 …). Alt 를 누르는 동안에도 걷지 않는다 (ADR-0456) */
.tip-foot {
    margin-top: 8px; padding-top: 5px; border-top: 1px solid var(--border-dark);
    font-size: var(--fs-xs); color: var(--text-muted);
}
/* 출처 · 태그 칩 — 이름 줄 아래 한 줄. 넘치면 접어 내린다(영어가 길다) */
.tip-chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 5px; }
.tip-chip {
    font-style: normal; font-size: var(--fs-xs); line-height: 1.5;
    padding: 0 6px; border-radius: 3px;
    background: rgba(var(--tint-rgb),.06); border: 1px solid var(--border-primary); color: var(--text-secondary);
}
.tip-chip.src { color: var(--info-fg-soft); border-color: var(--info-line); background: rgba(var(--info-line-rgb),.18); }
/* 능력치 칩 — 스킬을 미는 능력치의 약어 (ADR-0118). 태그 칩과 섞여 읽히지 않게 금색 계열을 든다.
   청동 선 · 바탕 없음 · 각진 모서리 · 굵은 글자 [2026-09-24 사용자 지시 「AI색」 · 시험 적용] — 같은 색 글자 + 선 + 비치는 바탕 + 둥근 모서리 조합을 걷었다 */
.tip-chip.attr { color: var(--bronze-fg); border-color: var(--bronze-line); background: none; border-radius: 0; font-weight: 700; }

.pop-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
.pop {
    /* 초상 오른쪽 위(얼굴 옆 검은 여백)에서 떠오른다 (2026-10-02 · ADR-0470) — 오른쪽 끝 = 패딩 6 + 초상 101 - 4 · 위 = 패딩 5 + 4.
       개편판(.v2)은 초상이 맨 위 띠(24 + 틈 5) 아래라 그만큼 내린다 */
    /* 동시에 뜬 팝업은 줄(`--pop-row` — battle.js `popup` 이 잡는다)마다 18px 씩 아래로 쌓인다 (ADR-0471) */
    position: absolute; top: 9px; left: 103px; margin-top: calc(var(--pop-row, 0) * 18px); font-size: var(--fs-sm);
    animation: pop-up-r .9s ease-out forwards; white-space: nowrap;
    text-shadow: 0 1px 2px #000;
}
/* 피해 숫자는 크다 [2026-09-28 사용자 지시 · ADR-0407 → 2026-10-18 한 단 더 · ADR-0657] — 13 → 15 → 18. 글자 팝업(빗나감 · 반격 · 전투 불능 · 회복)은 그대로.
   색은 **피해 종류 색** — 로그의 피해 숫자와 같은 토큰(`--dt-*`) [2026-09-28 사용자 지시 · ADR-0408]. 종류가 없는 피해(반사 · 자폭)는 무채색 기본이다.
   때린 쪽 · 맞은 쪽을 색으로 가르지 않는다(옛 `--dmg-out` 연분홍 / `--dmg-in` 빨강 폐지 — 카드 자리가 든다) · 치명도 같은 색이고 크기만 크다(옛 치명 노랑 폐지) */
.unit.v2 .pop:not(.lvup) { top: 33px; }
.pop.dmg { color: var(--text-primary); font-size: var(--fs-lg); }
/* 피해 숫자는 스킬 · 평타 · 치명 모두 같은 크기다 (2026-10-02 사용자 지시 · ADR-0471 — 치명의 큰 글씨 폐지) */
.pop.dmg.dt-physical { color: var(--dt-physical); }
.pop.dmg.dt-fire { color: var(--dt-fire); }
.pop.dmg.dt-cold { color: var(--dt-cold); }
.pop.dmg.dt-lightning { color: var(--dt-lightning); }
.pop.dmg.dt-poison { color: var(--dt-poison); }
.pop.dead-tag { color: var(--text-muted); font-size: var(--fs-xs); }
.pop.counter { color: var(--color-warning); font-size: var(--fs-xs); }            /* 반격 — 반격한 카드의 글자 (ADR-0158) */
.pop.heal { color: var(--heal-fg); }                                          /* 회복 — 피해와 같은 자리, 부호와 색만 반대 */
.pop.pay { color: var(--text-muted); font-size: var(--fs-xs); }              /* HP 소모 — 스킬을 쓰며 낸 HP(차지) · 피해 숫자와 갈리게 작고 흐리다 (ADR-0781) */
/* 레벨업 — 금색 · 다른 글자 팝업보다 크고 한 박자 길다(1.6s = battle.js `LVUP_MS`) (2026-09-29 · ADR-0435) · 아래 적중 변화 줄은 없다 (2026-10-22 · ADR-0718).
   피해 숫자(초상 오른쪽 위 모서리)와 자리를 갈라 왼쪽 초상(101px 칸 — 패딩 6 + 50.5) 위에서 떠오른다 (ADR-0470) */
.pop.lvup {
    top: 18%; left: 57px; font-size: var(--fs-md); font-weight: 700; color: var(--color-warning); text-align: center;
    animation-name: pop-up; animation-duration: 1.6s;
}
/* 본 적 없는 레벨업 — 관전 카드 신원의 `Lv.n` 이 반짝인다 · **그 영웅 카드를 누를 때까지** (2026-09-29 · SCREEN_DESIGN §4-2 · ADR-0440 · ADR-0463) */
.unit-lv.lv-new { color: var(--color-warning); font-weight: 700; cursor: pointer; animation: lv-blink 1.1s ease-in-out infinite; }
@keyframes lv-blink {
    0%, 100% { opacity: 1; text-shadow: 0 0 6px var(--color-warning); }
    50% { opacity: .35; text-shadow: none; }
}
/* ⚠ 피해 팝업의 스킬 아이콘(`.pop-ico` · ADR-0039)은 걷었다 (2026-09-28 · ADR-0409) — 「스킬이 나갔다」는 아래 「관전 연출」의 스킬 이펙트가 든다 */
/* 스킬 이름 팝업(`.pop.skill-tag`)은 걷었다 (2026-10-02 · ADR-0470) */
@keyframes pop-up-r {
    0% { transform: translate(-100%, 6px); opacity: 0; }       /* 글자의 오른쪽 끝을 초상 오른쪽 끝에 붙인다 */
    18% { transform: translate(-100%, -2px); opacity: 1; }
    100% { transform: translate(-100%, -30px); opacity: 0; }
}
@keyframes pop-up {
    0% { transform: translate(-50%, 6px); opacity: 0; }
    18% { transform: translate(-50%, -2px); opacity: 1; }
    100% { transform: translate(-50%, -30px); opacity: 0; }
}

/* 관전 연출 = **스킬 이펙트** [2026-09-28 사용자 지시 · SCREEN_DESIGN §4-2 「연출」 · ADR-0409] — 스킬에만 · 늘 켜져 있다. **어느 카드에 붙이나는 `fx.js`, 모양 · 길이는 여기.**
   길이는 전부 `--fx-k` 를 곱한다 — 배속이 오르면 짧아진다(fx.js 가 칸 `.unit-slot` 에 건다 · ×1 1 / ×2 .75 / ×4 .55).
   모양은 아래 코드 모양이다 · 그림 한 장(`.fx-stamp` — 이 절 끝)은 꺼져 있다(나중에 전직 스킬에만 · ADR-0412) · 피격 반응은 설정 탭에서 켜고 끈다(기본 켜짐 · 2026-09-30) */

/* 쓰러진 카드는 **한 박자 뒤에** 흐려진다 — 곧바로 흐려지면(.unit.dead) 마지막 타격의 스킬 이펙트가 회색으로 옅게 탄다. 배속을 따르지 않는 고정 박자다 */
.unit.dead { transition: opacity .45s .3s, filter .45s .3s; }

/* ── 피격 반응 — 카드 · 초상 · 칸이 움직인다. 그림 없음 · 아레나 전체는 안 흔든다(소란) · fx.js 가 켜져 있을 때만 클래스를 건다 ── */
.unit.fx-shake { animation: fx-shake calc(220ms * var(--fx-k, 1)) ease-out; }
.unit.fx-shake-crit { animation: fx-shake-crit calc(320ms * var(--fx-k, 1)) ease-out; }
.unit.fx-dodge { animation: fx-dodge calc(260ms * var(--fx-k, 1)) ease-out; }
.unit.fx-down { animation: fx-down calc(380ms * var(--fx-k, 1)) ease-out; }
.sprite.fx-flash { animation: fx-flash calc(200ms * var(--fx-k, 1)) ease-out; }
.sprite.fx-flash-crit { animation: fx-flash-crit calc(340ms * var(--fx-k, 1)) linear; }
/* 쓰러짐 — 초상을 덮는 붉은 막(곱하기 섞기라 그림의 선이 그대로 비친다). 조각 층에 서서 초상 크기(`--sw` · `--sh`)를 받는다 */
.fx-layer > .fx-bleed {
    width: var(--sw, 101px); height: var(--sh, 101px); margin: calc(var(--sh, 101px) / -2) 0 0 calc(var(--sw, 101px) / -2);
    background: rgb(var(--fx-bleed-rgb)); mix-blend-mode: multiply;
    animation: fx-bleed calc(520ms * var(--fx-k, 1)) ease-out both;
}
/* 때린 카드 — 상대 진영 쪽으로. 파티는 아래 진영이라 위로, 적은 아래로 (진형이 칸을 `top` 으로 미는 것과 안 부딪히게 칸의 transform 을 쓴다) */
.side-party .unit-slot.fx-lunge { animation: fx-lunge-up calc(240ms * var(--fx-k, 1)) ease-out; }
.side-enemy .unit-slot.fx-lunge { animation: fx-lunge-down calc(240ms * var(--fx-k, 1)) ease-out; }
/* 흔들림 폭 — `--shake` · 치명 `--shake-crit`. 기본(영웅 카드 · 파견 관전 창) 4px · 치명 7px ·
   **몬스터 카드는 설정 탭의 「몬스터 흔들림」 단계**를 fx.js 가 `data-shake` 로 단다 (2026-09-29 · SCREEN_DESIGN §2-2 · ADR-0454) */
.unit.enemy[data-shake="0"] { --shake: 0px; --shake-crit: 0px; }
.unit.enemy[data-shake="1"] { --shake: 2px; --shake-crit: 4px; }
.unit.enemy[data-shake="2"] { --shake: 4px; --shake-crit: 7px; }
.unit.enemy[data-shake="3"] { --shake: 8px; --shake-crit: 12px; }
@keyframes fx-shake { 0%, 100% { transform: none; } 20% { transform: translateX(calc(var(--shake, 4px) * -1)); } 45% { transform: translateX(var(--shake, 4px)); } 70% { transform: translateX(calc(var(--shake, 4px) * -.5)); } }
@keyframes fx-shake-crit { 0%, 100% { transform: none; } 15% { transform: translateX(calc(var(--shake-crit, 7px) * -1)); } 35% { transform: translateX(var(--shake-crit, 7px)); } 55% { transform: translateX(calc(var(--shake-crit, 7px) * -.714)); } 75% { transform: translateX(calc(var(--shake-crit, 7px) * .429)); } }
@keyframes fx-dodge { 0%, 100% { transform: none; } 35% { transform: translateX(calc(12px * var(--fx-sx, 1))); } }
@keyframes fx-down { 0%, 100% { transform: none; } 30% { transform: translateY(6px); } }
@keyframes fx-flash { 0% { filter: brightness(2.4); } 100% { filter: none; } }
@keyframes fx-flash-crit { 0% { filter: brightness(2.8); } 30% { filter: none; } 50% { filter: brightness(2.2); } 100% { filter: none; } }
@keyframes fx-bleed { 0% { opacity: .95; } 45% { opacity: .8; } 100% { opacity: 0; } }
@keyframes fx-lunge-up { 0%, 100% { transform: none; } 35% { transform: translateY(-9px); } }
@keyframes fx-lunge-down { 0%, 100% { transform: none; } 35% { transform: translateY(9px); } }

/* ── 조각 층 — 카드 안 **팝업 층 앞**이라 피해 숫자가 늘 위에 선다. 조각은 초상 한가운데(`--cx` · `--cy` — fx.js 가 잰다)에서 시작한다 ── */
.fx-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
.fx-layer > * { position: absolute; left: var(--cx, 56px); top: var(--cy, 56px); pointer-events: none; }

/* ── 스킬 이펙트 — 타격은 피해 종류가 모양을 정한다 · 색은 `--fx-*`(피해 종류 색을 채도를 낮춘 값) ──
   「조금 더 강력하게」 [2026-10-04 사용자 지시 · ADR-0506] — 모든 타격에 섬광 원판(`.fx-flare <종류>`) · 조각 수 · 크기 · 거리 · 굵기를 한 단 올렸다. 번짐 빛은 여전히 없다 */
/* 물리 — 굵은 베기 궤적 + 뒤따르는 가는 줄(`.echo` — 조금 비켜 늦게). 왼쪽에서 오른쪽으로 그어지고 왼쪽부터 사라진다.
   평타(`.fx-b-slash` — 은빛 한 줄)와 키프레임 `fx-slash` 를 같이 쓴다 — 키프레임을 고치면 평타도 바뀐다 */
.fx-slash {
    width: 150px; height: 9px; margin: -4.5px 0 0 -75px; border-radius: 4px;
    background: linear-gradient(90deg, transparent, var(--fx-physical) 25%, var(--fx-physical-core) 60%, transparent);
    transform: rotate(var(--r));
    animation: fx-slash calc(300ms * var(--fx-k, 1)) ease-out calc(var(--dl, 0ms) * var(--fx-k, 1)) both;
}
.fx-slash.echo { width: 128px; height: 3px; margin: -1.5px 0 0 -64px; transform: rotate(var(--r)) translateY(11px); }
@keyframes fx-slash { 0% { clip-path: inset(0 100% 0 0); opacity: 1; } 45% { clip-path: inset(0 0 0 0); opacity: 1; } 100% { clip-path: inset(0 0 0 60%); opacity: 0; } }
/* 화염 — 불똥 */
.fx-ember {
    width: var(--sz); height: var(--sz); margin: calc(var(--sz) / -2) 0 0 calc(var(--sz) / -2); border-radius: 50%;
    background: radial-gradient(circle, var(--fx-fire-core) 0 30%, var(--fx-fire) 65%);
