.fx-flare {
    width: var(--fs, 84px); height: var(--fs, 84px); margin: calc(var(--fs, 84px) / -2) 0 0 calc(var(--fs, 84px) / -2); border-radius: 50%;
    animation: fx-flare calc(300ms * var(--fx-k, 1)) ease-out both;
}
.fx-flare.fire { --fs: 92px; background: radial-gradient(circle, var(--fx-fire-core) 0 32%, var(--fx-fire) 58% 68%, transparent 69%); }
.fx-flare.poison { --fs: 90px; background: radial-gradient(circle at 45% 40%, var(--fx-poison-core) 0 22%, var(--fx-poison) 45% 66%, transparent 67%); }
.fx-flare.physical { --fs: 58px; background: radial-gradient(circle, var(--fx-physical-core) 0 30%, var(--fx-physical) 54% 64%, transparent 65%); }
.fx-flare.cold { --fs: 74px; background: radial-gradient(circle, var(--fx-cold-core) 0 34%, var(--fx-cold) 58% 66%, transparent 67%); }
.fx-flare.lightning { --fs: 68px; background: radial-gradient(circle, var(--fx-lightning-core) 0 36%, var(--fx-lightning) 58% 66%, transparent 67%); }
.fx-flare.blast { --fs: 80px; background: radial-gradient(circle, var(--fx-physical-core) 0 28%, var(--fx-ring) 52% 64%, transparent 65%); }
