.fx-bolt polyline.core { stroke: var(--fx-lightning-core); stroke-width: 2.2; }
@keyframes fx-flicker { 0% { opacity: 0; } 8% { opacity: 1; } 25% { opacity: .25; } 40% { opacity: 1; } 70% { opacity: .6; } 100% { opacity: 0; } }
/* 독 — 방울이 튀어 올랐다 떨어진다 */
.fx-drop {
    width: var(--sz); height: calc(var(--sz) * 1.25); margin: calc(var(--sz) / -2) 0 0 calc(var(--sz) / -2);
