@keyframes fx-drop {
    0% { transform: translate(0, 0) scale(.6); opacity: 1; animation-timing-function: ease-out; }
    40% { transform: translate(calc(var(--dx) * .6), var(--dy)) scale(1); opacity: 1; animation-timing-function: ease-in; }
    100% { transform: translate(var(--dx), calc(var(--dy) + 56px)) scale(.85); opacity: 0; }
