    animation: fx-ring calc(380ms * var(--fx-k, 1)) ease-out both;
}
@keyframes fx-ring { 0% { transform: scale(.3); opacity: 1; } 100% { transform: scale(1.35); opacity: 0; } }
/* ── 조각 [2026-10-04 사용자 지시 「모든 스킬이 스킬별로 생김새가 달라야」 · SCREEN_DESIGN §4-2 · ADR-0511] — 스킬마다 다른 생김새를 짜는 조각.
   어느 스킬이 어느 조각을 쓰나는 skill_looks.js · 조각마다 다른 값은 fx.js:PIECES. 공통 변수 — 색 `--c`(바탕) · `--cc`(밝은 속) · 길이 `--t` · 늦춤 `--dl`.
   길이 · 늦춤은 배속(`--fx-k`)을 곱한다 · 치명(`.crit`)은 굵기 `--tk` 1.4 · 늦춘 동안은 안 보인다(첫 키프레임이 투명하거나 잘려 있다) ── */
.fp { --tk: 1; }
.fp.crit { --tk: 1.4; }
.fp { animation-duration: calc(var(--t) * var(--fx-k, 1)); animation-delay: calc(var(--dl) * var(--fx-k, 1)); animation-fill-mode: both; }
/* 곧은 줄 — 결을 따라 그어지고 그어진 쪽부터 사라진다 · 가운데가 굵고 양 끝이 가늘다 */
.fp-streak {
    width: var(--len); height: calc(var(--w) * var(--tk)); margin: calc(var(--w) * var(--tk) / -2) 0 0 calc(var(--len) / -2); border-radius: 50%;
    background: linear-gradient(90deg, transparent, var(--c) 22%, var(--cc) 62%, transparent);
    transform: rotate(var(--a)) translate(var(--sh, 0px), var(--off, 0px));
    animation-name: fp-sweep; animation-timing-function: ease-out;
}
/* 흰 심 + 둘레 띠(백호참 · ADR-0509) — 굵기 방향으로 밝은 속과 반투명 띠 · 길이 방향 양 끝은 가늘게 사라진다 · 세 컷에 그어지고 두 컷에 꺼진다 */
.fp-streak.halo {
    border-radius: 0;
    background: linear-gradient(to bottom, transparent, color-mix(in srgb, var(--c) 32%, transparent) 20%, color-mix(in srgb, var(--c) 60%, transparent) 38%,
        var(--cc) 45% 55%, color-mix(in srgb, var(--c) 60%, transparent) 62%, color-mix(in srgb, var(--c) 32%, transparent) 80%, transparent);
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 14%, #000 86%, transparent);
