    animation-name: fp-chop;
}
@keyframes fp-sweep { 0% { clip-path: inset(0 100% 0 0); opacity: 1; } 40% { clip-path: inset(0 0 0 0); opacity: 1; } 100% { clip-path: inset(0 0 0 65%); opacity: 0; } }
@keyframes fp-chop {
    0% { clip-path: inset(0 100% 0 0); opacity: 1; animation-timing-function: steps(3, end); }
    24% { clip-path: inset(0 0 0 0); opacity: 1; animation-timing-function: steps(1, end); }
    66% { clip-path: inset(0 0 0 0); opacity: 1; animation-timing-function: steps(2, end); }
    100% { clip-path: inset(0 0 0 0); opacity: 0; }
}
/* 휜 칼날 — 납작한 타원의 윗변(양 끝이 가늘다) · 꼭짓점이 축 */
.fp-arc {
    width: var(--s); height: var(--h); margin: -12px 0 0 calc(var(--s) / -2); border-radius: 50%;
    border-top: calc(var(--w) * var(--tk)) solid var(--cc);
    transform-origin: 50% 0; transform: rotate(var(--a));
    animation-name: fp-sweep; animation-timing-function: ease-out;
}
/* 섬광 원판 — 가장자리를 끊은 원판(번짐 빛이 아니다) */
.fp-flare {
    width: var(--s); height: var(--s); margin: calc(var(--s) / -2) 0 0 calc(var(--s) / -2); border-radius: 50%;
    background: radial-gradient(circle, var(--cc) 0 30%, var(--c) 54% 64%, transparent 65%);
    animation-name: fp-flare; animation-timing-function: ease-out;
}
@keyframes fp-flare { 0% { transform: scale(.35); opacity: 0; } 8% { opacity: .95; } 100% { transform: scale(1.25); opacity: 0; } }
/* 고리 — 퍼지거나 조여든다(`--r0` → `--r1`) · `--fy` 가 1 보다 작으면 땅에 누운 고리 · `--oy` 만큼 아래 */
.fp-ring {
    width: var(--s); height: var(--s); margin: calc(var(--s) / -2 + var(--oy, 0px)) 0 0 calc(var(--s) / -2); border-radius: 50%;
    border: calc(var(--w) * var(--tk)) solid var(--c);
    animation-name: fp-ring; animation-timing-function: ease-out;
}
@keyframes fp-ring {
    0% { transform: scale(var(--r0), calc(var(--r0) * var(--fy))); opacity: 0; }
    8% { opacity: 1; }
    100% { transform: scale(var(--r1), calc(var(--r1) * var(--fy))); opacity: 0; }
}
/* 알갱이 — (x0, y0) 에서 (x1, y1) 로 난다(튐 · 오름 · 비). 모양 — 둥근 알 · shard 마름모 · drop 방울 · dash 짧은 줄(나는 쪽으로 눕는다) */
.fp-dot {
    width: var(--sz); height: var(--sz); margin: calc(var(--sz) / -2) 0 0 calc(var(--sz) / -2); border-radius: 50%;
    background: radial-gradient(circle, var(--cc) 0 32%, var(--c) 62%);
    animation-name: fp-fly; animation-timing-function: cubic-bezier(.2, .7, .4, 1);
