.fp-dot.shard { border-radius: 0; height: calc(var(--sz) * 2.4); margin-top: calc(var(--sz) * -1.2); clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); background: linear-gradient(var(--cc), var(--c)); }
.fp-dot.drop { height: calc(var(--sz) * 1.25); border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%; }
.fp-dot.dash { width: calc(var(--sz) * 4); height: 3px; margin: -1.5px 0 0 calc(var(--sz) * -2); background: linear-gradient(90deg, transparent, var(--c) 40%, var(--cc)); }
@keyframes fp-fly {
    0% { transform: translate(var(--x0), var(--y0)) rotate(var(--a)) scale(.6); opacity: 0; }
    10% { opacity: 1; }
    75% { opacity: .9; }
    100% { transform: translate(var(--x1), var(--y1)) rotate(var(--a)) scale(1); opacity: 0; }
}
/* 번개 · 갈라짐 — 꺾인 갈래(그림 틀 -60 -70 · 120 × 140 의 원점이 초상 한가운데) · 바탕 획 + 밝은 속 획 */
.fp-bolt, .fp-crack { width: 120px; height: 140px; margin: -70px 0 0 -60px; }
.fp-bolt svg, .fp-crack svg { display: block; width: 120px; height: 140px; overflow: visible; }
.fp-bolt polyline, .fp-crack polyline { fill: none; stroke: var(--c); stroke-width: calc(5.6px * var(--tk)); stroke-linejoin: miter; stroke-linecap: round; }
.fp-bolt polyline.core, .fp-crack polyline.core { stroke: var(--cc); stroke-width: calc(2.2px * var(--tk)); }
.fp-bolt { animation-name: fx-flicker; animation-timing-function: linear; }
.fp-crack { animation-name: fp-crack; animation-timing-function: ease-out; }
@keyframes fp-crack { 0% { clip-path: inset(0 0 100% 0); opacity: 1; } 30% { clip-path: inset(0 0 0 0); opacity: 1; } 100% { clip-path: inset(0 0 0 0); opacity: 0; } }
/* 빛기둥 — 위에서 내리꽂혀(아랫변이 한가운데 30px 아래 · 높이 `--ph`) 가늘어지며 사라진다 */
.fp-pillar {
    width: var(--w); height: var(--ph); margin: calc(30px - var(--ph)) 0 0 calc(var(--w) / -2); border-radius: 40% 40% 50% 50% / 8% 8% 24% 24%;
