    animation-name: fp-pillar; animation-timing-function: ease-out;
}
@keyframes fp-pillar { 0% { transform: scaleY(0); opacity: 0; } 12% { opacity: 1; } 35% { transform: scaleY(1); opacity: 1; } 100% { transform: scaleY(1) scaleX(.4); opacity: 0; } }
/* 땅 가시 — 초상 아랫변(한가운데에서 46px 아래)에서 솟는다 · `--sx` 가로 자리 */
.fp-spike {
    width: var(--sw); height: var(--sh); margin: calc(46px - var(--sh)) 0 0 calc(var(--sw) / -2);
    clip-path: polygon(50% 0, 100% 100%, 0 100%); background: linear-gradient(var(--cc), var(--c));
    transform-origin: 50% 100%;
    animation-name: fp-spike; animation-timing-function: ease-out;
}
@keyframes fp-spike {
    0% { transform: translateX(var(--sx)) scaleY(0); opacity: 0; }
    10% { opacity: 1; }
    35% { transform: translateX(var(--sx)) scaleY(1.08); }
    45% { transform: translateX(var(--sx)) scaleY(1); opacity: 1; }
    100% { transform: translateX(var(--sx)) scaleY(1); opacity: 0; }
}
/* 문양 — 점선 고리 + 안쪽 실선 고리가 돌며 조여든다 */
.fp-sigil {
    width: var(--s); height: var(--s); margin: calc(var(--s) / -2) 0 0 calc(var(--s) / -2); border-radius: 50%;
    border: calc(2px * var(--tk)) dashed var(--cc);
    animation-name: fp-sigil; animation-timing-function: ease-out;
}
.fp-sigil::after { content: ''; position: absolute; inset: 16%; border-radius: 50%; border: 1.5px solid var(--c); }
@keyframes fp-sigil { 0% { transform: scale(1.35) rotate(0deg); opacity: 0; } 20% { opacity: 1; } 70% { transform: scale(1) rotate(100deg); opacity: 1; } 100% { transform: scale(.92) rotate(140deg); opacity: 0; } }
/* 꺾쇠 — 위로 오르는 ^ · `--sx` 가로 자리 */
.fp-chev {
    width: 16px; height: 16px; margin: -8px 0 0 -8px;
    border-top: calc(3px * var(--tk)) solid var(--cc); border-left: calc(3px * var(--tk)) solid var(--cc);
    animation-name: fp-chev; animation-timing-function: ease-out;
}
@keyframes fp-chev { 0% { transform: translate(var(--sx), 34px) rotate(45deg); opacity: 0; } 20% { opacity: 1; } 100% { transform: translate(var(--sx), -40px) rotate(45deg); opacity: 0; } }
/* 회전 칼날 — 고리의 위(밝은 속) · 아래(바탕) 칼날이 한 바퀴 반 돌며 커진다 */
.fp-spin {
    width: var(--s); height: var(--s); margin: calc(var(--s) / -2) 0 0 calc(var(--s) / -2); border-radius: 50%;
