.fp-x::after { transform: rotate(-45deg); }
@keyframes fp-x {
    0% { transform: translate(var(--ox), var(--oy)) scale(1.7); opacity: 0; }
    15% { transform: translate(var(--ox), var(--oy)) scale(1); opacity: 1; }
    65% { opacity: 1; }
    100% { transform: translate(var(--ox), var(--oy)) scale(.9); opacity: 0; }
