@keyframes fx-rise { 0% { transform: translate(var(--dx), var(--y0)); opacity: 0; } 25% { opacity: 1; } 100% { transform: translate(var(--dx), var(--y1)); opacity: 0; } }
/* 창 · 방벽 — 카드 전체. 조각 층의 기본 자리(초상 한가운데)를 덮어 카드를 채운다 */
.fx-layer > .fx-card { left: 0; top: 0; width: 100%; height: 100%; overflow: hidden; }
.fx-card::before { content: ''; position: absolute; left: 0; right: 0; top: 0; }
