    animation: fx-shell calc(540ms * var(--fx-k, 1)) ease-out both;
}
@keyframes fx-shell { 0% { transform: scale(.95); opacity: 0; } 30% { opacity: 1; } 100% { transform: scale(1.04); opacity: 0; } }
/* 불러낸 무리 — 떠오르며 선다 */
.unit-slot.fx-appear { animation: fx-appear calc(380ms * var(--fx-k, 1)) ease-out backwards; }
@keyframes fx-appear { 0% { transform: translateY(12px); opacity: 0; } 100% { transform: none; opacity: 1; } }
/* 라운드 사이 — 마지막 적이 쓰러지면 적 카드가 사라지고 숨 동안 빈 줄이 선다 (ADR-0948). 사라지는 0.45초는 숨 길이(pace.js:ROUND_GAP_MS 0.95초 =
   사라짐 0.45 + 빈 줄 0.5)와 짝이다 — 하나만 바꾸면 빈 줄 길이가 바뀐다. 새 라운드 적의 다가옴은 fx.js:fxArrive(웹 애니메이션)다 */
.side-enemy.round-clear > .unit-slot { opacity: 0; transition: opacity calc(450ms * var(--fx-k, 1)) cubic-bezier(.4, 0, .6, 1); }

/* ── 기본 공격 이펙트 [2026-10-03 · SCREEN_DESIGN §4-2 「연출」 · ADR-0501 · 모양 ADR-0505] — 기본 공격 · 반격.
   **무기와 상관없이 대각선 베기 한 줄** — 스킬 물리 베기(`.fx-slash`)와 같은 크기 · 같은 그어짐(키프레임 `fx-slash` 를 같이 쓴다)이고 **색만 무채색**(`--fx-basic*`)이다.
   치명(`.crit`)은 한 단 굵다(`--th` — 굵기 배수 · 평타 1.5 · 치명 2.25 · ADR-0504) ── */
.fx-b { --th: 1.5; }
.fx-b.crit { --th: 2.25; }
.fx-b-slash {
    width: 132px; height: calc(4px * var(--th)); margin: calc(-2px * var(--th)) 0 0 -66px; border-radius: 3px;
    background: linear-gradient(90deg, transparent, var(--fx-basic) 25%, var(--fx-basic-core) 60%, transparent);
    transform: rotate(var(--r));
    animation: fx-slash calc(280ms * var(--fx-k, 1)) ease-out both;
}
/* 공격자 포커스 (개발용 비교 · 임시 — battle.js:syncFocus · 세움 길이는 pace.js · SCREEN_DESIGN §10-2)
   올라감 — 행동한 카드가 상대 진영 쪽으로 나간 채 선다(`.fx-advance` · 들어갈 때 전환 = pace.js:RISE_MS · 늦게 그린 만큼 줄인 값을 battle.js:syncFocus 가 `--rise-ms` 로 건다) · 풀리면 아래 기본 전환으로 내려온다.
   Focus `Off` 는 battle.js:syncOffRise 가 같은 `.fx-advance` 를 행동 앞에서 미리 건다(`.off-rise` 는 그 표지일 뿐 — 모양이 없다).
   `Dim` — 재생을 세운 동안 그 행동에 안 낀 카드를 어둡게 */
.arena .unit-slot { transition: filter 90ms ease-out, transform calc(240ms * var(--fx-k, 1)) ease-in-out; }
.arena .unit-slot.fx-advance { transition: filter 90ms ease-out, transform var(--rise-ms, calc(200ms * var(--fx-k, 1))) ease-out; }
.side-party .unit-slot.fx-advance { transform: translateY(-14px); }
.side-enemy .unit-slot.fx-advance { transform: translateY(14px); }
.arena.focus-dim .unit-slot:not(.focus-in) { filter: brightness(.45) saturate(.5); }

/* 기본 직업 스킬의 투명 이미지 — 초상 둘레 안 · 전직 스킬은 크게 카드 밖까지(ADR-0550) · 배속과 정리는 기존 조각과 같다(ADR-0515 · ADR-0520).
   이미지는 그림의 색을 그대로 쓰고, CSS는 등장·이동·사라짐만 정한다.
   `--oy` 는 그림을 위아래로 옮긴다(SKILL_ART `ay`) · `--dl` 은 이어 서는 그림의 늦춤이다 — 둘 다 없으면 0 (ADR-0541) */
.fx-skill-stamp {
    width: var(--sz); height: var(--sz); margin: calc(var(--sz) / -2 + var(--oy, 0px)) 0 0 calc(var(--sz) / -2);
    object-fit: contain; image-rendering: auto;
    animation: fx-skill-slash calc(var(--t) * var(--fx-k, 1)) ease-out both;
    animation-delay: calc(var(--dl, 0ms) * var(--fx-k, 1));
    /* 다단의 흔들림 — 타마다 각도 · 자리(`SKILL_ART` 의 `jitter` · 러시 · ADR-0780) · 움직임의 transform 과 따로 얹힌다 · 없으면 0 */
    rotate: var(--rot, 0deg); translate: var(--jx, 0px) var(--jy, 0px);
}
.fx-skill-stamp.crit { filter: brightness(1.12); }
/* 스킬 이펙트 투명도 — 스킬이 그린 조각에만(fx.js:asSkill 이 `.fx-sk` · `--fx-skill-a` 를 단다 · §2-2 · ADR-0562).
   조각의 애니메이션이 opacity 를 움직이므로 같은 속성을 덮지 않고 필터로 곱한다 · 치명 그림은 밝기와 함께 */
.fx-layer > .fx-sk { filter: opacity(var(--fx-skill-a, 1)); }
.fx-layer > .fx-sk.fx-skill-stamp.crit { filter: brightness(1.12) opacity(var(--fx-skill-a, 1)); }
.fx-skill-cross { animation-name: fx-skill-cross; }
/* 단일 다단의 칼날 하나 — 그림을 `--mask` 띠(칼날을 따라가는 흐린 가림)로 갈라 그 칼날만 · `--mx` · `--my` 쪽에서 그어 들어온다(더블스윙 「\」 → 「/」 · ADR-0778) */
.fx-skill-swing { animation-name: fx-skill-swing; -webkit-mask-image: var(--mask, none); mask-image: var(--mask, none); }
.fx-skill-ground { animation-name: fx-skill-ground; }
.fx-skill-land { animation-name: fx-skill-land; }
.fx-skill-inward { animation-name: fx-skill-inward; }
.fx-skill-wave { animation-name: fx-skill-wave; }
.fx-skill-orders { animation-name: fx-skill-orders; }
.fx-skill-shell { animation-name: fx-skill-shell; }
.fx-skill-burst { animation-name: fx-skill-burst; }
.fx-skill-thrust { animation-name: fx-skill-thrust; }
.fx-skill-pillar { animation-name: fx-skill-pillar; }
.fx-skill-strike { animation-name: fx-skill-strike; }
.fx-skill-rain { animation-name: fx-skill-rain; }
.fx-skill-orbit { animation-name: fx-skill-orbit; }
.fx-skill-sweep { animation-name: fx-skill-sweep; }
.fx-skill-heal { animation-name: fx-skill-heal; }
.fx-skill-sink { animation-name: fx-skill-sink; }
/* 마법사 라이트닝 · 아이스 블라스트 — 초상 바깥 위에서 떨어진다(ADR-0541).
   번개는 위에서 아래로 그어지고 한 번 깜빡인다 · 얼음은 초상 한 칸 위에서 점점 빨라지며 떨어지고 · 깨짐은 맞은 자리에서 터진다 */
.fx-skill-bolt { animation-name: fx-skill-bolt; animation-timing-function: linear; }
.fx-skill-fall { animation-name: fx-skill-fall; animation-timing-function: cubic-bezier(.32, 0, .67, 0); }
.fx-skill-shatter { animation-name: fx-skill-shatter; transform-origin: 50% 89%; }
/* 전직 휠윈드 · 재장전 — 칼날 바퀴 · 화살 고리가 한 바퀴 가까이 돈다(ADR-0550) */
.fx-skill-spin { animation-name: fx-skill-spin; animation-timing-function: linear; }
@keyframes fx-skill-spin {
    0% { transform: rotate(0deg) scale(.85); opacity: 0; }
    12% { opacity: 1; }
    15% { transform: rotate(48deg) scale(1); }
    78% { opacity: 1; }
    100% { transform: rotate(320deg) scale(1.04); opacity: 0; }
}
/* 전사 버프 —칸 전체를 초상에 맞추고 가장자리의 그림을 그 자리에서 움직인다. */
.fx-skill-edge-burst { animation-name: fx-skill-edge-burst; transform-origin: 50% 100%; }
.fx-skill-edge-wave { animation-name: fx-skill-edge-wave; }
.fx-skill-edge-orders { animation-name: fx-skill-edge-orders; }
.fx-skill-edge-shell { animation-name: fx-skill-edge-shell; transform-origin: 50% 100%; }
@keyframes fx-skill-edge-burst {
    0% { transform: translateY(4px) scale(1, .88); opacity: 0; }
    22% { transform: translateY(0) scale(1); opacity: 1; }
    65% { transform: scale(1.02); opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
@keyframes fx-skill-edge-wave {
    0% { transform: scale(.96); opacity: 0; }
    25% { transform: scale(1); opacity: 1; }
    70% { transform: scale(1.025); opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
@keyframes fx-skill-edge-orders {
    0% { transform: translateY(3px); opacity: 0; }
    25% { transform: translateY(1px); opacity: 1; }
    70% { transform: translateY(-1px); opacity: 1; }
    100% { transform: translateY(-3px); opacity: 0; }
}
@keyframes fx-skill-edge-shell {
    0% { transform: translateY(4px) scale(1, .96); opacity: 0; }
    25% { transform: translateY(0) scale(1); opacity: 1; }
    70% { transform: scale(1.01); opacity: 1; }
    100% { transform: scale(1); opacity: 0; }
}
@keyframes fx-skill-slash {
    0% { clip-path: inset(0 100% 100% 0); opacity: 0; transform: scale(.92); }
    25% { clip-path: inset(0); opacity: 1; transform: scale(1); }
    65% { opacity: 1; }
    100% { clip-path: inset(0); opacity: 0; transform: scale(1.04); }
}
@keyframes fx-skill-cross {
    0% { transform: scale(.65); opacity: 0; }
    20% { transform: scale(1); opacity: 1; }
    65% { opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
@keyframes fx-skill-swing {
    0% { transform: translate(var(--mx, 0px), var(--my, 0px)) scale(.92); opacity: 0; }
    22% { transform: translate(0, 0) scale(1); opacity: 1; }
    65% { opacity: 1; }
    100% { transform: scale(1.03); opacity: 0; }
}
@keyframes fx-skill-ground {
    0% { transform: scale(.55, .35); opacity: 0; }
    25% { transform: scale(1); opacity: 1; }
    65% { transform: scale(1.02); opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
@keyframes fx-skill-land {
    0% { transform: translateY(-7px) scale(.72); opacity: 0; }
    25% { transform: translateY(2px) scale(1); opacity: 1; }
    65% { transform: translateY(0) scale(1.02); opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
@keyframes fx-skill-inward {
    0% { transform: scale(1.08); opacity: 0; }
    25% { opacity: 1; }
    75% { transform: scale(.75); opacity: 1; }
    100% { transform: scale(.6); opacity: 0; }
}
@keyframes fx-skill-wave {
    0% { transform: scale(.6); opacity: 0; }
    25% { opacity: 1; }
    70% { transform: scale(1); opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
@keyframes fx-skill-orders {
    0% { transform: translateY(8px) scale(.82); opacity: 0; }
    25% { opacity: 1; }
    70% { transform: translateY(-2px) scale(1); opacity: 1; }
    100% { transform: translateY(-5px); opacity: 0; }
}
@keyframes fx-skill-shell {
    0% { transform: scale(.82); opacity: 0; }
    25% { transform: scale(1.03); opacity: 1; }
    70% { transform: scale(1); opacity: 1; }
    100% { transform: scale(1.02); opacity: 0; }
}
@keyframes fx-skill-burst {
    0% { transform: scale(.45); opacity: 0; }
    22% { transform: scale(1); opacity: 1; }
    65% { transform: scale(1.02); opacity: 1; }
    100% { transform: scale(1.04); opacity: 0; }
}
/* `--ct` · `--cb` = 위아래를 잘라 한 띠만 보인다(래피드 샷 한 발 · ADR-0778) — 없으면 0 이라 다른 스킬은 그림 전체 */
@keyframes fx-skill-thrust {
    0% { clip-path: inset(var(--ct, 0) 100% var(--cb, 0) 0); transform: translateX(-6px); opacity: 0; }
    25% { clip-path: inset(var(--ct, 0) 0 var(--cb, 0) 0); transform: translateX(0); opacity: 1; }
    65% { opacity: 1; }
    100% { clip-path: inset(var(--ct, 0) 0 var(--cb, 0) 0); transform: translateX(3px); opacity: 0; }
}
@keyframes fx-skill-pillar {
    0% { clip-path: inset(100% 0 0); transform: scale(.86, .7); opacity: 0; }
    25% { clip-path: inset(0); transform: scale(1); opacity: 1; }
    65% { opacity: 1; }
    100% { clip-path: inset(0); transform: scale(1.02); opacity: 0; }
}
@keyframes fx-skill-rain {
    0% { transform: translate(-4px, -6px) scale(.85); opacity: 0; }
    25% { transform: translate(0, 0) scale(1); opacity: 1; }
    65% { opacity: 1; }
    100% { transform: translate(3px, 4px); opacity: 0; }
}
@keyframes fx-skill-strike {
    0% { clip-path: inset(0 0 100%); transform: translateY(-4px) scale(.9); opacity: 0; }
    25% { clip-path: inset(0); transform: translateY(0) scale(1); opacity: 1; }
    65% { opacity: 1; }
    100% { clip-path: inset(0); transform: scale(1.02); opacity: 0; }
}
@keyframes fx-skill-orbit {
    0% { transform: rotate(-12deg) scale(.78); opacity: 0; }
    25% { opacity: 1; }
    70% { transform: rotate(4deg) scale(1); opacity: 1; }
    100% { transform: rotate(10deg) scale(.95); opacity: 0; }
}
@keyframes fx-skill-sweep {
    0% { clip-path: inset(0 100% 0 0); transform: scale(.85); opacity: 0; }
    30% { clip-path: inset(0); transform: scale(1); opacity: 1; }
    70% { opacity: 1; }
    100% { clip-path: inset(0); transform: translateY(-3px); opacity: 0; }
}
@keyframes fx-skill-heal {
    0% { transform: translateY(6px) scale(.82); opacity: 0; }
    25% { opacity: 1; }
    70% { transform: translateY(-2px) scale(1); opacity: 1; }
    100% { transform: translateY(-5px); opacity: 0; }
}
@keyframes fx-skill-sink {
    0% { transform: translateY(-5px) scale(.85); opacity: 0; }
    25% { opacity: 1; }
    70% { transform: translateY(1px) scale(1); opacity: 1; }
    100% { transform: translateY(4px); opacity: 0; }
}
@keyframes fx-skill-bolt {
    0% { clip-path: inset(0 0 100%); opacity: 1; }
    20% { clip-path: inset(0); opacity: 1; }
    28% { opacity: .45; }
    36% { opacity: 1; }
    65% { clip-path: inset(0); opacity: 1; }
    100% { clip-path: inset(0); opacity: 0; }
}
@keyframes fx-skill-fall {
    0% { transform: translateY(calc(var(--sh, 101px) * -1)); opacity: 0; }
    15% { opacity: 1; }
    100% { transform: translateY(0); opacity: 1; }
}
@keyframes fx-skill-shatter {
    0% { transform: scale(.8); opacity: 0; }
    14% { transform: scale(1); opacity: 1; }
    60% { opacity: 1; }
    100% { transform: translateY(2px) scale(1.03); opacity: 0; }
}

/* ── 종류 공통 그림 — `fx.js:ART_ON`이 꺼져 있다. 직업 스킬 이미지는 위의 별도 규칙을 쓴다.
   크기 보통 83 · 치명 101(초상 101 안 — 수치 열을 안 덮는다). 움직임은 종류가 정한다(fx.js `MOTION`) — 터짐(타격 · 자폭) · 떠오름(회복 · 강화) · 내려앉음(약화) · 부풂(방벽) ── */
.fx-stamp {
    width: 83px; height: 83px; margin: -41.5px 0 0 -41.5px; object-fit: contain;
    animation: fx-stamp calc(440ms * var(--fx-k, 1)) ease-out both;
}
.fx-stamp.crit { width: 101px; height: 101px; margin: -50.5px 0 0 -50.5px; }
.fx-stamp.fx-m-rise { animation-name: fx-stamp-rise; animation-duration: calc(620ms * var(--fx-k, 1)); }
.fx-stamp.fx-m-sink { animation-name: fx-stamp-sink; animation-duration: calc(620ms * var(--fx-k, 1)); }
.fx-stamp.fx-m-pulse { animation-name: fx-stamp-pulse; animation-duration: calc(540ms * var(--fx-k, 1)); }
@keyframes fx-stamp {
    0% { transform: rotate(var(--r)) scale(.5); opacity: 0; }
    15% { opacity: 1; }
    60% { transform: rotate(var(--r)) scale(1.02); opacity: 1; }
    100% { transform: rotate(var(--r)) scale(1.1); opacity: 0; }
}
@keyframes fx-stamp-rise { 0% { transform: translateY(16px) scale(.8); opacity: 0; } 25% { opacity: 1; } 100% { transform: translateY(-20px) scale(1); opacity: 0; } }
@keyframes fx-stamp-sink { 0% { transform: translateY(-18px); opacity: 0; } 30% { opacity: 1; } 100% { transform: translateY(14px) scale(.9); opacity: 0; } }
@keyframes fx-stamp-pulse { 0% { transform: scale(.7); opacity: 0; } 30% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(1.12); opacity: 0; } }

/* 판(로그 · 누적) — **나눔 배치의 우측 열에만** 선다 (SCREEN_DESIGN §4-2 · ADR-0130). 넓게 배치에는 판이 없다 */
.battle-side .pane {
    flex: 1 1 0; min-height: 0; overflow-y: auto;
    background: var(--bg-input); border: 1px solid var(--border-dark); padding: 8px 11px;
}
.battle-side .pane[hidden] { display: none; }
/* 누적 데미지 — **영웅만** 선다 (SCREEN_DESIGN §4-2 · ADR-0149). 머리 줄(합계 · 파티 합 안 % · 막대는 파티 안 최대 기준) 아래에
   기본 공격 · 스킬 · 반사가 한 줄씩 — 영웅 셋 × 다섯 줄도 열 높이 안에 든다(측정은 ADR) */
/* 영웅 한 덩어리 = 왼쪽 초상 + 오른쪽 열 [2026-09-21 사용자 지시 · ADR-0211]. 덩어리 높이는 둘 중 긴 쪽이다.
   초상 한 변 = **네 줄(기본 공격 + 스킬 셋) 열의 높이** [2026-09-21 사용자 지시 · ADR-0258] — 머리 줄 약 21 + 막대 15 + 목록 여백 4 + 줄 18 × 4 ≈ 111.
   스킬 칸을 다 채운 영웅까지 덩어리가 초상 높이로 같다 · 다섯 줄(반사)이면 열이 약 129 로 초상보다 길다. 초상은 공통 조각 `.hero-face` 를 크기만 바꿔 쓴다 */
/* 덩어리 사이는 넓게 띈다 [2026-09-21 사용자 지시 · ADR-0252] — 줄 간격과 비슷하면 윗 영웅의 마지막 줄과 아랫 영웅의 머리 줄이 붙어 읽힌다 */
.dmg-row { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 22px; }
.dmg-row:last-child { margin-bottom: 0; }
/* 초상 윗변 = 영웅 등급 색 [2026-09-21 사용자 지시] — 아레나 카드 윗변(.unit.party)과 같은 굵기 · 같은 변수 · 같은 폴백 */
.dmg-face { width: 112px; height: 112px; border-top: 3px solid var(--tier-line, var(--ally-line)); }
.dmg-body { flex: 1 1 0; min-width: 0; }
.dmg-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: var(--fs-sm); }
.dmg-n { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-secondary); }
.dmg-v { white-space: nowrap; color: var(--text-primary); }
/* 막대 = 피해 종류 조각 셋을 왼쪽부터 쌓는다 [2026-09-21 사용자 지시 · ADR-0252] — 물리 주황(로그의 물리 숫자와 같은 토큰) · 마법(원소 전부) 파랑 · 기타(반사 · 자폭) 회색.
   조각 폭은 렌더러가 인라인으로 건다(값 / 파티 안 최대) — 합이 곧 막대 길이다 */
.bar.dmg { display: flex; height: 12px; margin-top: 3px; }
.dmg-row .bar.dmg > i, .tdm .bar.dmg > i { flex: none; }
.dmg-row .bar.dmg > i.k-phys, .tdm .bar.dmg > i.k-phys { background: var(--dt-physical); }
.dmg-row .bar.dmg > i.k-magic, .tdm .bar.dmg > i.k-magic { background: var(--color-info); }
.dmg-row .bar.dmg > i.k-etc, .tdm .bar.dmg > i.k-etc { background: var(--text-muted); }
.dmg-sks { margin-top: 4px; }
.dmg-sk { display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); line-height: 1.5; color: var(--text-muted); }
.dmg-ico { flex: none; width: 18px; height: 18px; display: inline-flex; }
.dmg-ico img { width: 100%; height: 100%; object-fit: contain; }
.dmg-skn { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dmg-skv { white-space: nowrap; color: var(--text-secondary); }
/* 로그 한 줄 = 네 칸 격자 [2026-09-21 사용자 지시 · SCREEN_DESIGN §4-2 · ADR-0189] — 주체 이름 · 스킬 그림 · 대상 이름 · 값.
   칸 폭은 **로그 판(`.battle-log-wrap`)의 격자**가 정하고 목록 · 줄(`li.lg-row`)이 `subgrid` 로 차례로 물려받는다 — 그래서 모든 줄이 세로로 선다.
   이름 · 대상 = 같은 폭(1fr : 1fr) · 넘치면 `…` · 그림 = 누적 판 아이콘과 같은 18(칸 폭은 머리 줄 「스킬」 라벨과 넓은 쪽 · ADR-0198) · 값 = 보이는 줄 중 가장 긴 값(최소 4em) — 값은 잘리면 뜻이 없다.
   로그 탭이 숨긴 줄은 트랙 계산에서 빠진다. 라운드 시작 · 종료(`li.lg-wide`)만 격자 밖 전폭이다 */
/* 줄 높이는 하나(`--lg-row-h`)이고 목록 높이는 그 **정수배**다 [2026-09-21 사용자 지시 「아래 로그 글씨가 안 짤리도록」 · ADR-0208] —
   맨 아래로 따라갈 때 스크롤 끝이 줄 경계에 떨어져 맨 윗줄이 반쯤 걸리지 않는다(남는 몇 px 은 목록 아래로 빠진다 · `align-self: start`).
   ⚠ 줄 높이를 명시하지 않으면 목록이 넘칠 때 `overflow: hidden` 인 전폭 줄(라운드 · 종료)이 높이 0 으로 접혔다 —
      넘치는 격자에서 자동 행은 최소 크기로 서고, overflow 가 걸린 칸의 최소 크기는 0 이다(2026-09-21 실측 1.78px).
   `round()` 를 모르는 브라우저는 앞 줄의 `100%` 로 선다(정수배만 빠진다) */
.battle-log {
    list-style: none; font-size: var(--fs-sm);
    grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-content: start; grid-auto-rows: var(--lg-row-h);
    min-height: 0; overflow-y: auto; align-self: start;
    height: 100%; height: round(down, 100%, var(--lg-row-h));
}
.battle-log li { height: var(--lg-row-h); padding: 1px 0; color: var(--text-secondary); }
.battle-log li.lg-row { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center; }
.battle-log li.lg-wide { grid-column: 1 / -1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: calc(var(--lg-row-h) - 2px); }
.lg-n, .lg-d { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lg-ico { width: 18px; height: 18px; display: inline-flex; }
.lg-ico img { width: 100%; height: 100%; object-fit: contain; }
.lg-v { text-align: right; white-space: nowrap; }
.battle-log li b { font-weight: normal; color: var(--text-primary); }
/* 로그 판 = 격자 하나 [2026-09-21 사용자 지시 · ADR-0201] — 네 칸 트랙은 **판이 정하고** 머리 줄(`.lg-head`)과 스크롤 목록(`.battle-log`)이
   `subgrid` 로 물려받는다(목록의 줄이 다시 물려받는다). 그래서 머리 줄은 목록 **밖**인데도 칸이 줄과 맞는다.
   ⚠ 머리 줄을 목록 안 첫 줄로 두고 sticky 로 붙였을 때는, 새 줄이 와서 목록이 맨 아래로 튀는 프레임마다 지나가는 줄의 글자가
      머리 줄 위로 비쳤다(1920×1080 헤드리스 픽셀 실측 — 재생 중 네 컷 중 두 컷 · 멈추면 0). 목록 밖이면 줄이 머리 줄 자리에 닿을 수 없다.
   판은 스크롤하지 않는다 — 목록이 남는 세로(`minmax(0, 1fr)`)를 받아 스크롤한다. `[hidden]` 은 `.battle-side .pane[hidden]` 이 이긴다 */
.battle-side .battle-log-wrap {
    --lg-row-h: 23px;   /* 로그 한 줄 높이 — 그림 18 + 위아래 여백 · 13px 글 한 줄이 들어간다 (ADR-0208) */
    display: grid; grid-template-columns: minmax(0, 1fr) max-content minmax(0, 1fr) minmax(4em, max-content);
    grid-template-rows: auto auto minmax(0, 1fr); column-gap: 6px; overflow: hidden;
}
/* 칸 머리 줄 [ADR-0196 · ADR-0198 · ADR-0201] — 이름 · 스킬 · 대상 · 데미지. 주체(`data-side`)가 없어 탭 거르기 · 줄 수 세기와 무관하다 */
.battle-log-wrap > .lg-head {
    grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center;
    padding-bottom: 3px; margin-bottom: 2px; border-bottom: 1px solid var(--border-dark);
    font-size: var(--fs-xs); color: var(--text-muted);
}
.lg-head b { font-weight: normal; color: var(--text-muted); }
/* 「스킬」 — 그림 칸 **왼쪽 끝에서 시작한다**(줄의 그림도 칸 왼쪽에 서서 시작점이 맞는다). 그림 칸 폭은 그림(18)과 이 라벨 중 넓은 쪽이다(`max-content`) —
   18 에 넘치게 두면 「대상」 까지 3px 뿐이라 「스킬 대상」이 한 말로 읽혔다(2026-09-21 헤드리스 실측). 라벨 뒤 여백이 그 틈을 벌린다 (ADR-0198) */
.lg-head .lg-ico { width: auto; padding-right: .5em; align-items: center; white-space: nowrap; }
/* 지금 라운드 줄 [2026-09-21 사용자 지시 · ADR-0204] — 머리 줄 바로 아래 고정(목록 밖). 글은 라운드 시작 줄 그대로 · 첫 라운드 전엔 비어 안 선다.
   세 행을 **못박는다** — 빈 라운드 칸이 빠질 때 자동 배치가 목록을 둘째(auto) 행으로 당기면 목록이 남는 세로를 못 받아 스크롤이 죽는다 */
.battle-log-wrap > .lg-head { grid-row: 1; }
.battle-log-wrap > .lg-round {
    grid-row: 2; grid-column: 1 / -1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    padding: 2px 0 3px; margin-bottom: 6px; border-bottom: 1px solid var(--border-dark);   /* 아래 6 — 목록 첫 줄과 띄운다 (ADR-0208) */
    font-size: var(--fs-sm); color: var(--text-secondary);
}
.battle-log-wrap > .lg-round:empty { display: none; }
.lg-round b { font-weight: normal; color: var(--text-primary); }
/* 라운드 종류 칩 [2026-09-21 사용자 지시 「괄호로 넣지 말고 리더나 해고처럼 박스를 만들어 글씨의 왼쪽에」 · ADR-0205] — 고정 줄 · 목록의 라운드 줄 둘 다.
   모양은 리더 뱃지(`.hs-leader`)와 같은 작은 테두리 박스 · 색은 헤드의 라운드 트랙과 같다(정예 · 보스 — 같은 뜻을 같은 색으로) */
.lg-kind {
    display: inline-block; margin-right: 6px; padding: 1px 5px; line-height: 1.2;
    font-size: var(--fs-xs); border: 1px solid var(--border-dark); color: var(--text-secondary);
}
.lg-kind.elite { border-color: var(--elite-line-soft); color: var(--elite-fg); }
.lg-kind.boss { border-color: var(--boss-line); color: var(--text-accent); }
.battle-log-wrap > .battle-log { grid-row: 3; }
.battle-log li b.dt-physical { color: var(--dt-physical); }
.battle-log li b.dt-lightning { color: var(--dt-lightning); }
.battle-log li b.dt-cold { color: var(--dt-cold); }
.battle-log li b.dt-poison { color: var(--dt-poison); }
.battle-log li b.dt-fire { color: var(--dt-fire); }
.battle-log li b.heal-t { color: var(--heal-fg); }
/* 로그 탭 — 전체 · 우리 · 적 (SCREEN_DESIGN §4-2 · ADR-0131). 줄은 다 쌓여 있고 목록의 `data-f` 가 주체가 다른 줄을 숨긴다 */
.log-filter { flex: none; margin-bottom: 6px; }
.log-filter[hidden] { display: none; }
/* 누적 탭 — 가한 피해 · 받은 피해 (ADR-0252). 로그 탭과 같은 자리 · 같은 모양 */
.dmg-filter { flex: none; margin-bottom: 6px; }
.dmg-filter[hidden] { display: none; }
.battle-log[data-f="party"] li[data-side="enemy"],
.battle-log[data-f="enemy"] li[data-side="party"] { display: none; }
/* 로그 방식 — 문장 [2026-09-30 사용자 지시 · SCREEN_DESIGN §4-2 · ADR-0459] — 줄은 격자 칸 넷과 문장(`.lg-say`)을 다 들고 문서 뿌리의
   `data-log-style`(battle.js `setLogStyle`)이 하나만 보인다. 문장은 **접힌다** — 끝의 숫자가 잘리지 않게. 그래서 줄 높이 하나 · 목록 높이 정수배(ADR-0208)를
   격자 줄에만 두고 여기서 푼다. 머리 줄(이름 · 스킬 · 대상 · 데미지)은 문장에 가리킬 칸이 없어 숨는다. 이름 · 값은 `<b>` 라 밝고 나머지 글은 줄 색이다 */
.battle-log li .lg-say { display: none; }
:root[data-log-style="text"] .battle-log-wrap > .lg-head { display: none; }
:root[data-log-style="text"] .battle-log { grid-auto-rows: auto; height: 100%; }
:root[data-log-style="text"] .battle-log li.lg-row { display: block; height: auto; padding: 2px 0; line-height: 1.45; word-break: keep-all; overflow-wrap: anywhere; }
:root[data-log-style="text"] .battle-log li.lg-row > :not(.lg-say) { display: none; }
:root[data-log-style="text"] .battle-log li .lg-say { display: inline; }
.lg-say .lg-ico { vertical-align: -4px; margin: 0 2px; }

/* ───────── 서브 바 / 세그먼트 ───────── */

.sub-bar {
    display: flex; align-items: center; justify-content: space-between;
    gap: 16px; margin-bottom: 14px;
}
.segmented { display: flex; gap: 4px; flex-wrap: wrap; }
/* 자물쇠 챕터 — 어느 건물로도 안 열리는 장(원정 챕터 세그먼트 · SCREEN_DESIGN §4-1 · ADR-0531). 꺼진 버튼(`.btn:disabled` 흐림)이라
   올려도 밝아지지 않는다 · 자물쇠는 글자 높이(`.cp-btn .lock-ico` 와 같은 1em) — `.rs-pin-ico` 의 block 을 줄 안으로 접는다 */
.btn.seg-lock { display: inline-flex; align-items: center; gap: 5px; }
.btn.seg-lock:hover { border-color: var(--border-secondary); background: var(--bg-tertiary); }
.btn.seg-lock .lock-ico { display: inline-flex; flex: 0 0 auto; }
.btn.seg-lock .lock-ico svg { width: 1em; height: 1em; }
/* 부서진 글자 챕터 — 이번 버전이 안 여는 장(`chapterGate` 가 null · 원정 챕터 세그먼트 · SCREEN_DESIGN §4-1 · ADR-0739). 자물쇠 없이 꺼진 버튼이고,
   흐림은 여느 꺼진 버튼(.4)보다 옅다 — 부서진 모양이 읽혀야 한다. 글자 전체에 `#fx-crumble`(index.html)이 걸리고,
   렌더러가 한 자씩 감싼 `<i>` 의 **끝 넷이 차례로 기울며 내려앉아 흐려지고** 끝 셋은 더 큰 조각 필터를 받는다 — 앞(장 번호)은 읽힌다 */
.fx-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.btn.seg-crumble:disabled { opacity: .7; }
.btn.seg-crumble:hover { border-color: var(--border-secondary); background: var(--bg-tertiary); }
.seg-crumble .crumble { display: inline-block; filter: url(#fx-crumble); }
.seg-crumble .crumble > i { display: inline-block; font-style: normal; white-space: pre; }
.seg-crumble .crumble > i:nth-last-child(1) { transform: translate(3px, 5px) rotate(32deg); opacity: .3; filter: url(#fx-crumble-1); }
.seg-crumble .crumble > i:nth-last-child(2) { transform: translate(1.5px, 3px) rotate(-16deg); opacity: .5; filter: url(#fx-crumble-2); }
.seg-crumble .crumble > i:nth-last-child(3) { transform: translate(.5px, 1.6px) rotate(9deg); opacity: .7; filter: url(#fx-crumble-3); }
.seg-crumble .crumble > i:nth-last-child(4) { transform: translateY(.7px) rotate(-5deg); opacity: .85; }
.seg-crumble .crumble > i:nth-last-child(5) { transform: rotate(2deg); }
/* 난이도 탭 — 원정 목록 패널 윗변에 붙은 폴더 탭(SCREEN_DESIGN §4-1 · ADR-0596 이 ADR-0586 의 세그먼트 줄을 대체).
   **패널의 윗선은 이 줄이 긋는다** — 틈(`.dt-gap` · 첫 틈은 패널 가로 여백만큼) · 남은 자리(`.dt-fill`) · 안 고른 탭의 아랫변이 한 선을 잇고,
   고른 탭은 아랫변이 비어 그 자리에서만 선이 끊긴다 → 탭 안과 패널 안이 이어진다. 패널(`.diff-panel`)은 테두리가 없다(ADR-0785).
   흐림은 탭의 글자(안쪽 span)에만 건다 — 탭째 흐리면 아랫변(= 패널 윗선)까지 흐려져 선이 끊겨 보인다.
   고른 탭 윗변의 강조색은 출발 칸 버튼의 고른 칸(`.cp-btn.on`)과 같은 「고른 것」 표시다 — 단마다 색을 주지 않는다(ADR-0586).
   조건 글자는 잠긴 장소 줄 이유와 같은 `.zone-lock` 이고 탭 바로 옆에 선다.
   **대장간 작업 탭(`.fg-tabs` · `.fg-tab`)도 같은 폴더 탭이다** [2026-10-30 사용자 「폴더에서 선택하듯이」 · §8-2 · ADR-0963] — 틈 `.fg-gap` · 남은 자리 `.fg-fill` · 패널 `.fg-panel`(윗변이 없다).
   `D2 Min` 은 둘이 갈린다 — 난이도는 단계 화살표 · 대장간은 편성 고르개와 같은 돌 폴더 탭(아래 겉모양 비교 절) */
.diff-tabs, .fg-tabs { display: flex; align-items: flex-end; }
.diff-tabs .dt-gap, .fg-tabs .fg-gap { flex: 0 0 4px; align-self: stretch; border-bottom: 1px solid var(--border-primary); }
.diff-tabs .dt-gap:first-child, .fg-tabs .fg-gap:first-child { flex-basis: 16px; }
.fg-tabs .fg-fill { flex: 1 1 auto; }
.panel.fg-panel { border-top: none; }
.diff-tabs .dt-fill { flex: 1 1 auto; align-self: stretch; display: flex; align-items: center; padding-left: 10px; border-bottom: 1px solid var(--border-primary); }
/* [Report] — 남은 자리의 오른쪽 끝 · 오른쪽 여백은 첫 틈(패널 가로 여백)과 같다 (SCREEN_DESIGN §4-1 · ADR-0661) */
.diff-tabs .dt-report { margin-left: auto; margin-right: 16px; }
.diff-tab, .fg-tab {
    background: var(--bg-tertiary); border: 1px solid var(--border-dark); border-bottom-color: var(--border-primary);
    padding: 7px 22px 6px; font-weight: 700; color: var(--text-muted);
}
.fg-tab { white-space: nowrap; }
.fg-tab:disabled { opacity: .4; cursor: not-allowed; }
.diff-tab > span { display: inline-flex; align-items: center; gap: 5px; }
.diff-tab .lock-ico { display: inline-flex; flex: 0 0 auto; }
.diff-tab .lock-ico svg { width: 1em; height: 1em; }
.diff-tab:not(.on):not(:disabled):hover, .fg-tab:not(.on):not(:disabled):hover { color: var(--text-primary); border-color: var(--border-secondary); border-bottom-color: var(--border-primary); }
.diff-tab.on, .fg-tab.on {
    background: rgba(var(--surface-0-rgb), var(--panel-alpha)); border-color: var(--border-primary);
    border-top: 2px solid var(--text-accent); border-bottom-color: transparent;
    padding-top: 9px; color: var(--text-primary); cursor: default;
}
.diff-tab.locked { cursor: default; }
.diff-tab.locked > span { opacity: .45; }
/* 패널은 테두리가 없다 — 선은 위 탭 줄 밑선 하나다(장소 줄 띠가 칸이다 · ADR-0785) */
.panel.diff-panel { border: none; }
/* 단 이름 조각 — 부대 칸 · 리포트 머리의 스테이지 앞(노말은 안 선다). 색을 안 얹는다 — 색 자리는 챕터 죄종 색이 쓴다(ADR-0586) */
.diff-tag { font-weight: 700; }
/* 도감 챕터 버튼 — 상단바 탭 세그먼트와 같은 크기 (SCREEN_DESIGN §9 · 2026-09-21 사용자 지시).
   둘 다 `.btn.sm` 인데 메인만 `zoom: .9` 를 타서 한 단 작았다 — 이 줄만 배율을 되돌린다 */
.cx-ch-seg { zoom: calc(1 / .9); }

/* ───────── 스킬 ───────── */

/* 왼쪽 한 칸(포인트 · 액티브) + 판 셋이 **나란히** (2026-08-28 사용자 지시).
   옛 배치는 판 셋을 세로로 쌓아 한 화면(세로 예산 700)에 한 판 반밖에 안 들어왔다 — 스크롤 없이 셋을 다 보려면 옆으로 세운다.
   **폭에 상한을 준다** (2026-08-28 사용자 지시 — 칸 2/3 축소) — 1fr 로 두면 판이 화면 폭을 다 먹어 칸이 함께 커진다.
   고정 px 이 아니라 minmax 의 위쪽을 잡는 것이라 좁은 화면에서는 그대로 줄어든다 (ui/README 폭 정책).
   **판은 아래로 꽉 찬다** (2026-09-01 사용자 지시 — 옛 `align-items: start` 폐기): 판 셋의 아랫변이 왼쪽 칸과 나란히 맞는다.
   칸이 같이 부풀지는 않는다 — `.sk-cell` 높이가 62px 로 고정이고 `.sk-row` 가 안 늘어나므로, 남는 자리는 판 안 아래쪽 여백이 된다 */
.cols.c-skill {
    /* **열 넷을 비율이 나눈다** [개정 2026-09-09 사용자 지시] — 옛 판은 열 넷이 전부 고정 상한이라
       1920 짜리 화면에서도 창이 1190 에서 멈췄고, 좁은 하한(1280)에 맞춰 깎아 둔 판 셋(200px)이
       **넓은 화면에서도 계속 눌려 있었다.** 왼쪽 칸 1.9 : 판 셋 각 1. ⚠ 열 넷을 고정 px 로 되돌리면 이 성질이 사라진다 */
    /* 전체 폭은 **1600×800 한 장 기준 고정값**이다 (ADR-0087) — 옛 1508(= 한 장이 허락하는 최대)에서
       **1244 로 줄였다** [2026-09-27 사용자 지시 「탭 넓이를 좀 줄여」]. 판 = 칸 셋 + 칸 사이 둘 + 좌우 여백(칸 사이와 같은 14) ≈ 256 ·
       왼쪽 칸 440(옛 ≈570) = 1.72fr. 1244 = 440 + 256×3 + 사이 12×3 */
    width: 1244px;
    grid-template-columns: minmax(340px, 1.72fr) repeat(3, minmax(0, 1fr));
    gap: 12px;
}
/* 판 좌우 여백 = 칸 사이 간격 [2026-09-27 사용자 지시] — 옛 판은 칸을 줄 가운데 두어 좌우가 칸 사이의 2.5 배(≈36px) 비었다.
   칸 셋이 줄을 꽉 채우게 폭을 (줄 − 사이 둘) ÷ 3 으로 주고, 판 안쪽 좌우 패딩을 사이와 같게 둔다.
   **칸은 옛 크기의 90%다** [2026-09-30 사용자 지시] — 판 폭(≈256)은 두고 칸 사이 · 좌우 여백 · 줄 사이를 14 → 19 로 넓혀
   칸이 66 → 59 가 된다(판 안쪽 254 = 59.3×3 + 19×4). 칸 안 그림은 칸의 % 라 같이 준다(`.sk-icon-art`).
   스킬 창만이다 — 도감 마스터리 판(`.codex-mastery-grid`)은 그대로 */
.c-skill .sk-box { padding-left: 19px; padding-right: 19px; }
.c-skill .sk-grid, .c-skill .sk-row { gap: 19px; }
.c-skill .sk-cell { flex: 0 0 calc((100% - 38px) / 3); }
/* 왼쪽 칸(포인트 · 액티브)도 판 셋과 아랫변을 맞춘다 — 판이 더 높을 때 액티브 패널이 남는 높이를 받는다 [2026-09-27] */
.c-skill > div:first-child { display: flex; flex-direction: column; }
.c-skill > div:first-child > .panel:last-child { flex: 1; }
/* 판 머리는 **제목 한 줄**이고 글씨는 **아래 선 위 · 아이콘 아랫단에 맞춘다** [2026-09-27 사용자 지시 — 부제 삭제].
   높이(최소 높이)는 판 셋이 같다(첫 줄이 나란해야 한다) — 한 줄 머리(≈32)보다 넉넉한 60 으로 **위쪽 공간을 둔다** [2026-09-27 사용자 지시].
   제목 모양(굵기 · 줄 높이)은 아래 `.sk-title` 규칙 */
.c-skill .sk-box-head { align-items: flex-end; align-content: flex-end; min-height: 60px; padding-bottom: 6px; margin-bottom: 10px; }
.c-skill .sk-box-head .sk-head-icon { align-self: flex-end; }
/* 제목은 왼쪽 패널 제목(「포인트」 · `.panel > h2`)과 **같은 모양** — 굵게 · 기본 줄 높이 [2026-09-27 사용자 지시 「볼드 · 약간 위로 · 스킬포인트처럼」].
   기본 줄 높이의 글자 아래 여백만큼 글씨가 선에서 뜬다(아이콘은 선 위 그대로) */
.c-skill .sk-box-head .sk-title { font-weight: bold; color: var(--text-primary); }
/* 창 높이는 왼쪽 칸이 정한다 — 액티브 줄 위아래 안쪽 여백 6 → 4 [2026-09-27 「높이를 약간 줄여」] */
.c-skill .act-slot { padding-top: 4px; padding-bottom: 4px; }

/* 판 하나 */
.sk-box {
    display: flex; flex-direction: column;
    background: var(--bg-card); border: 1px solid var(--border-primary);
    padding: 10px 11px 11px;
}
.sk-box.mastery-colored {
    border-color: var(--mastery-color);
    box-shadow: inset 0 3px 0 var(--mastery-color);
}
.sk-box.mastery-colored .sk-tag { color: var(--mastery-color); }
.sk-box.mastery-colored .sk-cell.icon-only { border-color: var(--mastery-color); }
.sk-box.locked { opacity: .5; }

/* 좌상단 라벨 — 어떤 트리인지 */
/* 판 셋의 첫 줄이 같은 높이에서 시작하게 머리 높이를 맞춘다 — 안 맞추면 「나란히」가 깨진다 */
.sk-box-head {
    display: flex; align-items: baseline; align-content: flex-start; gap: 8px; flex-wrap: wrap;
    /* 42 → 88 → **62px** [정정 2026-09-09] — 88 은 판을 200px 로 깎아 뒀을 때 영어 「Advancement Tree」가
       두 줄로 접혀 §7 「판 머리 높이를 맞춰 첫 줄 정렬」이 깨진 것을 **덮으려던 값**이다. 같은 날 창이
       화면을 따라 넓어지면서(위 `.cols.c-skill`) 판이 228~303px 가 되어 **제목이 어디서도 안 접힌다** —
       실측 결과 머리는 ko/en · 1280/1920 전부 **59px 로 저절로 같다**. 88 은 26px 를 헛으로 먹으며
       세로 예산 700 에서 창을 스크롤시키고 있었다. 지금 값은 그 자연 높이에 얹은 **바닥**일 뿐이다.
       ⚠ 정렬을 지키는 것은 이 숫자가 아니라 **판이 제목을 한 줄에 담을 만큼 넓다**는 사실이다 —
          더 긴 판 이름이 생기면 여기서 다시 갈린다(실측 항목: `.sk-grid` 의 top 셋이 같은가) */
    min-height: 62px; padding-bottom: 7px; margin-bottom: 14px;
    border-bottom: 1px solid var(--border-dark);
}
.sk-tag {
    font-size: var(--fs-xs); color: var(--text-accent);
    border: 1px solid currentColor; padding: 0 6px; line-height: 16px;
}
.sk-title { font-size: var(--fs-md); }
/* 판 머리 아이콘 — 죄종 판은 죄종 · 직업 판은 직업. 회색 실루엣 PNG 를 마스크로 써서 판 색으로 칠한다 (SCREEN_DESIGN §7 · ADR-0368 · ADR-0375).
   머리는 baseline 정렬이라 아이콘만 가운데로 세운다 · 오른쪽 여백을 줄여 제목에 붙인다.
   ⚠ 그림 경로(`mask-image`)는 렌더러가 **인라인 스타일**로 준다 — CSS 변수에 담은 상대 url 은 이 파일(`ui/`) 기준으로 풀려 못 찾는다 */
.sk-head-icon {
    width: 26px; height: 26px; flex: none; align-self: center; margin-right: -3px;
    background: var(--mastery-color, var(--text-accent));
    -webkit-mask-position: center; mask-position: center;
    -webkit-mask-size: contain; mask-size: contain;
    -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat;
}
.sk-sub { font-size: var(--fs-xs); }

/* 칸 폭은 판 폭이 정한다(고정 px 없음) · 높이는 고정이다 — 늘어나면 칸이 세로로 부툁다 (2026-08-28 사용자 지시) */
/* 마스터리 판 — **줄 하나가 한 단계**다. 위가 먼저 열리고 아래로 갈수록 늦게 열린다 (SCREEN_DESIGN §7) */
.sk-grid { display: flex; flex-direction: column; gap: 14px; }
/* 세 칸의 너비를 기존의 75%로 줄이고 줄 가운데에 둔다. */
.sk-row { display: flex; flex-direction: row; justify-content: center; gap: 14px; }

/* 영어 노드명이 길다("All Resistances") — 긴 이름은 두 줄에서 접힌다.
   ⚠ **칸은 정사각형이다** [개정 2026-09-09 사용자 지시] — ~~높이 62px 고정~~(2026-08-28)을 물렸다.
   폭은 판 폭이 정하므로 높이도 그것을 따라간다(`aspect-ratio: 1`). */
.sk-cell {
    flex: 0 0 calc(25% - 3px); min-width: 0; aspect-ratio: 1 / 1;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
    padding: 3px 3px; text-align: center;
    background: var(--bg-tertiary); border: 1px solid var(--border-primary);
    cursor: pointer;
}
.sk-cell:hover { background: var(--surface-3); border-color: var(--border-highlight); }
.sk-cell.taken { background: var(--surface-1); }
.sk-cell.full { box-shadow: inset 0 0 0 1px rgba(var(--tint-rgb),.10); }
.sk-cell.locked { opacity: .6; cursor: not-allowed; }
/* 미작성 칸 — 가지 3 × 깊이 5 프레임이 보이도록 점선으로 남긴다 (비어 있음을 보여주는 것도 정보다) */
.sk-cell.empty {
    background: rgba(var(--tint-rgb), .015);
    border: 1px dashed var(--border-primary);
    cursor: default;
}
.sk-cell.empty:hover { background: rgba(var(--tint-rgb), .015); border-color: var(--border-primary); }
/* 잠긴 박스 안의 빈 칸은 한 번만 흐리게 — 이중으로 흐려지면 프레임이 사라진다 */
.sk-box.locked .sk-cell.empty { opacity: 1; }

.sk-n {
    font-size: var(--fs-2xs); line-height: 1.2; word-break: keep-all;
    overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
}
:root[lang="en"] .sk-n, html[lang="en"] .sk-n { letter-spacing: -.1px; }   /* 크기는 ko 와 같다 (2026-09-03 토큰 통일) */
.sk-r { font-size: var(--fs-2xs); color: var(--text-muted); }
.sk-cell.taken .sk-r { color: var(--text-secondary); }

/* 값 줄 — 현재 총합 + 랭크를 한 줄에. 잠긴 칸은 그 자리에 필요 레벨만 찍는다 (단계 번호는 화면에 쓰지 않는다) */
.sk-meta { display: flex; align-items: baseline; justify-content: center; gap: 5px; line-height: 1.2; }
/* 현재 총합 — 랭크 0 이어도 찍는다(빈 칸은 「안 재고 있다」로 읽힌다) */
.sk-v { font-size: var(--fs-2xs); color: var(--color-info); }
.sk-meta .lv { font-size: var(--fs-2xs); color: var(--color-warning); }
/* 못 찍는 칸은 손가락 커서를 주지 않는다 — 눌러도 되는 곳만 눌러 보인다 */
.sk-cell.dim { cursor: default; }
.sk-cell.dim:hover { background: var(--bg-tertiary); border-color: var(--border-primary); }
.sk-cell.taken.dim:hover { background: var(--surface-1); }
.sk-cell.can:hover { background: var(--surface-5); border-color: var(--border-highlight); }
/* 마스터리는 모두 봉인 문장을 쓰고, 잠금 레벨과 랭크는 바깥 모서리에 둔다. */
.sk-cell.icon-only { position: relative; padding: 0; border-color: var(--bronze-line); }
.sk-icon-art {
    position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; pointer-events: none;
}
.sk-icon-lock {
    position: absolute; left: 2px; top: 2px;
    padding: 0 2px; background: var(--bg-card); color: var(--color-warning);
    font-size: var(--fs-2xs); line-height: 1.2; white-space: nowrap; pointer-events: none;
}
.sk-icon-rank {
    position: absolute; right: 2px; bottom: 2px;
    padding: 0 2px; background: var(--bg-card); color: var(--text-secondary);
    font-size: var(--fs-2xs); line-height: 1.2; white-space: nowrap; pointer-events: none;
}
.sk-cell.icon-only.can:hover .sk-icon-art { filter: brightness(1.15); }
/* 낀 장비가 안 켠 칸 — 그림만 흐리다 (2026-10-30 복원 · ADR-0972) */
.sk-cell.icon-only.off .sk-icon-art { opacity: .4; }
/* 포인트 패널의 초기화 버튼은 제목 줄 오른쪽에 선다 [2026-09-27] — 제목의 굵기를 물려받지 않는다 */
.c-skill .panel > h2 .btn { font-weight: normal; }

/* 액티브 슬롯 3개 + 실효 쿨 병기 (battle_design §5·§6) */
.cycle-line {
    font-size: var(--fs-sm); padding-bottom: 6px; margin-bottom: 6px;
    border-bottom: 1px solid var(--border-dark);
}
.cycle-line b { font-weight: normal; color: var(--color-info); }
.cycle-line .muted { display: block; font-size: var(--fs-xs); }
/* 스킬 창에서는 공격 주기가 액티브 제목 줄 오른쪽에 선다 — 줄로 설 때의 밑줄 · 여백을 끈다 [2026-09-27] */
.panel > h2 .cycle-line { padding: 0; margin: 0; border: 0; font-size: var(--fs-xs); font-weight: normal; color: var(--text-secondary); }

/* 줄 셋은 **같은 높이**다 [2026-09-09 사용자 지시] — 전직 줄은 스킬이 없어 두 줄을 못 채우는데,
   그 줄만 낮으면 「덜 중요한 자리」로 읽힌다. 셋은 대등한 출처 칸이라 크기가 같아야 한다.
   `grid-auto-rows: 1fr` 이 **가장 큰 줄에 나머지를 맞춘다** — 높이를 px 로 못박지 않으므로
   문장이 한 줄이든 두 줄이든(en) 셋이 함께 따라간다 */
.slot-list { display: grid; grid-auto-rows: 1fr; row-gap: 4px; }
/* ⚠ 출처 열은 **고정 폭**이다 — README 「라벨 칸에 고정 px 금지」의 의도된 예외다 [2026-09-08 사용자 지시].
   줄마다 `.act-slot` 이 **자기 격자**라 `max-content` 는 줄마다 다르게 잡혔고, 그래서 en 에서
   「Hero」 줄과 「Weapon」 줄의 **아이콘 칸이 서로 다른 x 에 떨어졌다**(ko 는 둘 다 두 글자라 안 드러났다).
   폭은 en 최장 라벨 「Advance」(12px 에서 ≈47px)에 여유를 더한 값이고, 라벨은 칸 안에서 가운데 정렬된다.
   ⚠ 이 값을 줄이려면 `.no` 가 안 넘치는지 실측해야 한다(`white-space: nowrap` 이라 조용히 아이콘을 밀고 나간다) */
/* 줄이 여러 줄이므로 **위 정렬**이 기본이고(설명이 길어져도 이름 줄이 안 내려간다), 출처·아이콘 두 열만
   자기 축을 가운데로 되돌린다 — 그 둘은 줄 전체를 대표하는 표지라 글 흐름이 아니라 **줄의 중심**에 선다.
   아이콘 열은 `.ico` 실제 폭과 **같은 수**여야 한다 — 어긋나면 그림이 이름 쪽으로 밀린다 */
.act-slot {
    display: grid; grid-template-columns: 56px 44px 1fr; gap: 9px; align-items: start;
    padding: 6px 9px; background: var(--bg-tertiary); border: 1px solid var(--border-dark);
}
/* 빈 줄도 **같은 첫 열**을 쓴다 — 여기만 `max-content` 면 빈 줄의 사유가 다른 x 에서 시작한다 */
.act-slot.empty { grid-template-columns: 56px 1fr; border-style: dashed; opacity: .55; align-items: center; }
/* 출처는 **줄 가운데**에 선다 [2026-09-08 사용자 지시] — 여러 줄이 된 줄에서 위에 붙이면 아래가 비어 보인다.
   글씨는 9px(`--fs-2xs`) → **12px**(`--fs-xs`) [4차 지시] — 아이콘이 44px 로 커지면서 9px 라벨이 줄 왼쪽에서 사라졌다 */
.act-slot .no {
    font-size: var(--fs-xs); color: var(--text-secondary); text-align: center; white-space: nowrap;
    align-self: center;
}
/* 고유 칸 — 새 색 토큰을 만들지 않고 기존 강조색을 쓴다 (SCREEN_DESIGN §7 · skill_design §9-0).
   ⚠ 캐릭터 탭 카드(`.sk-card`)는 2026-09-08 로 **칸 이름 자체가 없다** — 이 규칙은 스킬 트리 창 목록 전용이다 */
.act-slot.innate .no { color: var(--text-accent); }
/* 그림이 들어오면서 칸을 정사각으로 잡는다 (2026-09-03 · SCREEN_DESIGN §2) — 이모지 때는 글씨 크기가 칸을 정했다.
   28 → **44px** [2026-09-08 4차 지시] — 줄이 세 줄이 되어 28px 그림이 줄 높이에 비해 점처럼 보였다.
   **정사각 칸으로 세운다** — 테두리·배경을 줘야 `ㅁ` 로 읽힌다(페이퍼돌 빈 칸·`.sk-card` 와 같은 문법) */
.act-slot .ico {
    display: flex; align-items: center; justify-content: center; align-self: center;
    position: relative; width: 44px; height: 44px; padding: 3px;
    font-size: var(--fs-lg); text-align: center;
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
.act-slot .ico img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
.act-slot .nm { font-size: var(--fs-sm); word-break: keep-all; line-height: 1.3; min-width: 0; }
/* 이름과 쿨은 **한 줄**에 선다 (2026-09-08 3차) — 설명이 아랫줄을 가져갔으므로 쿨이 더는 줄을 못 쓴다 */
.act-slot .nm .t { margin-right: 6px; }
/* 표기 쿨 — 값 하나뿐이다 (2026-09-08 2차 병기 폐기로 `.cd b` 규칙도 함께 사라졌다) */
.act-slot .cd { font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; }
/* 본문 한 줄 — **툴팁 문장과 같은 것**이다 [2026-09-08 · `tip.js:skillLineHtml`].
   툴팁의 `.tip-line` 을 그대로 쓰지 않고 별도 클래스를 두는 이유는 **크기만 다르기 때문**이다 —
   툴팁은 떠 있는 카드라 넉넉하고, 여기는 판 안이라 한 단 작다. 강조색(`.tip-hl`)은 전역이라 그대로 걸린다 */
/* 줄 높이는 툴팁(1.55)보다 **짜다** — 판 안이라 세로 예산 700 을 셋이 나눠 쓴다.
   ⚠ ~~`.ds`(회색 고정 설명 줄)~~ 은 2026-09-08 사용자 지시로 **삭제**됐다 — 문장이 같은 말을 더 정확히 한다 */
.act-slot .ln {
    display: block; margin-top: 2px;
    font-size: var(--fs-xs); line-height: 1.4; color: var(--text-primary); word-break: keep-all;
}

/* ───────── 선술집 ───────── */

.cand-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(256px, 1fr)); gap: 12px; }
.cand-card {
    background: var(--bg-tertiary); border: 1px solid var(--border-dark);
    border-top: 3px solid var(--border-secondary); padding: 12px;
}
.cand-head { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.cand-head b { font-weight: normal; font-size: var(--fs-lg); }
.cand-trait {
    font-size: var(--fs-sm); color: var(--text-secondary);
    margin: 7px 0 9px; padding-bottom: 8px; border-bottom: 1px solid var(--border-dark);
}
.cand-cost {
    display: flex; align-items: baseline; gap: 7px; font-size: var(--fs-sm);
    margin: 10px 0 9px; padding-top: 9px; border-top: 1px solid var(--border-dark);
}
.cand-cost b { font-weight: normal; color: var(--color-warning); font-size: var(--fs-md); }

.reroll {
    display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
    margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--border-dark);
}

/* ───────── 도감 ───────── */

/* 스테이지 = 한 줄, 몬스터는 오른쪽으로 쭉 나열.
   한 챕터가 한 화면이고 **그 화면을 맨 아래까지 채운다** (2026-09-21 사용자 지시) — 행이 본문 높이를 똑같이 나눠 갖는다.
   행 하한은 내용 높이(flex 기본 min-height)라 넘치면 종전처럼 본문이 스크롤된다 */
/* 카드 칸 격자 (ADR-0255) — 모든 행의 카드 폭이 같고 마지막 행(챕터보스 + `???`)의 두 자리도 위 행과 세로줄이 맞는다.
   카드 사이 간격 = 상자 안 여백 × 2 + 상자 테두리 × 2 + 두 자리 사이 틈. 열 수 `--cx-cols` 는 app.js 가 챕터마다 준다.
   **스테이지 상자는 지금 없다** [2026-09-21 사용자 지시 · 시험 중] — 여백 · 테두리가 0 이라 간격 = 틈이다.
   상자를 되살리면 `--cx-pad: 6px; --cx-bd: 1px` 과 `.mon-strip` 의 배경 한 줄이다 */
/* 세그먼트 줄 — 패널 박스 바로 위 (ADR-0273). 메인 배율을 되돌려 상단바 탭 세그먼트 · 챕터 버튼과 같은 크기다 */
/* 대장간 작업 탭은 자리만 같다 — 모양은 폴더 탭(`.fg-tabs` · 위 난이도 탭 묶음 · ADR-0963) */
.cx-tabs { flex: none; flex-wrap: nowrap; margin-bottom: 6px; zoom: calc(1 / .9); }
/* 고른 칸이 안 보였다 [2026-09-21 사용자 지시] — 공용 `.btn.sm.on` 은 테두리 · 배경이 한 단 밝아질 뿐이다.
   고른 칸 = 왼쪽 메뉴의 고른 칸과 같은 강조색 테두리 + 흰 글씨. 굵기는 안 바꾼다(폭이 흔들린다).
   안 고른 칸은 공용 글자색 그대로다 — 흐리게 하면 못 누르는 칸처럼 보였다(사용자 지시) */
.cx-tabs .btn.on { color: var(--text-primary); border-color: var(--text-accent); }
.cx-mon {
    display: flex; flex-direction: column; gap: 12px;
    --cx-pad: 0px; --cx-bd: 0px; --cx-split: 8px;
    --cx-gap: calc(2 * var(--cx-pad) + 2 * var(--cx-bd) + var(--cx-split));
}
.cx-mon .codex-stage { flex: 1 1 0; display: flex; flex-direction: column; }
.cs-pair { flex: 1 1 0; display: flex; gap: var(--cx-split); }
.cs-pair > .codex-stage { min-width: 0; }
/* 챕터보스 상자 — 격자 `--k` 칸 폭(ADR-0257 — 보스 카드 하나가 두 칸). 100% 는 행 폭이라 위 행의 카드 폭과 같은 식이 나온다.
   카드 상한 폭(`.mon-card` max-width)은 여기서 푼다 — 두 칸 카드가 상한에 걸리면 격자가 어긋난다 */
.cs-pair > .codex-stage:first-child .mon-card { max-width: none; }
.cs-pair > .codex-stage:first-child {
    flex: 0 0 auto;
    width: calc(var(--k) * (100% - (var(--cx-cols) - 1) * var(--cx-gap) - 2 * var(--cx-pad) - 2 * var(--cx-bd)) / var(--cx-cols)
        + (var(--k) - 1) * var(--cx-gap) + 2 * var(--cx-pad) + 2 * var(--cx-bd));
}
.mon-card.unknown .mon-name { color: var(--text-muted); }
/* 이름 줄 — 그 스테이지 카드 줄 위 · 아래에 가로선 하나 (ADR-0254 · 상자는 지금 없다 · 선은 도감 툴팁 머리글 아랫선과 같은 색) */
.cs-head {
    display: flex; align-items: baseline; justify-content: space-between; gap: 14px;
    flex-wrap: wrap; margin-bottom: 6px; padding: 0 2px 4px;
    border-bottom: 1px solid var(--border-dark);
}
.cs-title { font-size: var(--fs-md); }   /* sm → md (2026-09-21 사용자 지시 — 행이 바닥까지 커진 만큼 스테이지 이름도 한 단계) */
.cs-title .muted { margin-right: 4px; }

/* 가로 나열 — 몬스터가 늘어나면 이 줄만 가로 스크롤된다. 행이 늘어난 세로는 이 줄(= 카드)이 먹는다 */
.mon-strip {
    flex: 1 1 auto; display: flex; gap: var(--cx-gap); overflow-x: auto;
    padding: var(--cx-pad); border: var(--cx-bd) solid var(--border-dark);
}

/* 가로형 카드 — 초상 왼쪽 / 정보 오른쪽. **카드 높이는 초상이 정한다** (2026-08-30, SCREEN_DESIGN §9).
   초상이 커진 만큼 본문도 넓어야 해서 min-width 를 올렸다 — 하한 폭 1280 에서 4장 + 여백이 들어간다 */
.mon-card {
    flex: 1 1 0; min-width: 190px; max-width: 360px;
    display: flex; align-items: stretch; gap: 9px; padding: 5px 8px;
    background: var(--bg-card); border: 1px solid var(--border-dark);
    border-left: 2px solid var(--border-secondary);
}
.mon-card.boss { border-left-color: var(--text-accent); }
.mon-card.maxed { border-color: var(--done-line); border-left-color: var(--color-success); background: var(--done-bg); }
/* 도감의 초상 — 이 화면에서 가장 큰 칸. 원형 마스크는 몬스터 공통 규칙이라 그대로 두고 지름만 키운다.
   **지름은 카드 높이다** — 행이 화면을 채우며 늘어난 세로를 그대로 받아 원이 커진다(폭은 aspect-ratio 가 따라온다).
   72px 는 하한이다: 행이 내용 높이로 줄어드는 자리에서도 종전 크기 밑으로는 안 내려간다 */
.mon-card .face { width: auto; height: auto; min-height: 72px; align-self: stretch; aspect-ratio: 1 / 1; font-size: var(--fs-lg); }
.mon-card .face img { width: 100%; height: 100%; object-fit: cover; }

.mon-body { position: relative; flex: 1; min-width: 0; display: flex; flex-direction: column; justify-content: center; gap: 4px; }
/* 윗줄 칸 = 빈 칸 — 진행 줄이 걷혀 비었던 칸이라(ADR-0588) 높이는 그 빈 칸 그대로고 이름 · 핍은 안 움직인다 (ADR-0615 · ADR-0932) */
.mon-top { height: calc(var(--fs-xs) * 1.2); flex: none; }
/* 분류 셋 `종족 · 부류 · 직업` 칩 = 본문 위끝 오른쪽 — 본문은 카드 높이 안에서 가운데로 서서 윗줄 칸에 두면 카드마다 높이가 달라진다 (ADR-0922 · ADR-0929 · ADR-0932)
   칩은 툴팁 칩 줄과 같은 칩(`.base-chip` 무채색 · `.cls-chip` 직업 색 인라인) · 본문 폭에서 가로만 자른다 */
.mon-kinds {
    position: absolute; top: 3px; left: 0; right: 0;   /* 본문 위끝에서 3px 아래 (2026-10-27 사용자 「아주 살짝만 아래로」) */
    display: flex; justify-content: flex-end; gap: 4px;
    font-size: var(--fs-xs); white-space: nowrap; overflow-x: clip;
}
.mon-kinds > span { flex: none; padding: 0 4px; }
/* 이름이 윗줄을 통째로 쓴다 — 카드 수(장수) 칸은 2026-09-21 걷혔다(사용자 지시 · ADR-0200). 넘치면 말줄임 */
.mon-name {
    min-width: 0;
    font-size: calc(var(--fs-sm) + 1px); line-height: 1.3; word-break: keep-all;   /* 한 단 크게 (2026-09-21 사용자 지시) */
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.mon-name .b-tag { color: var(--text-accent); font-size: var(--fs-xs); margin-left: 4px; }
/* 이름 · 핍 두 줄(왼쪽 · 남는 폭 · 이름은 말줄임) + 오른쪽 끝 스킬 아이콘(두 줄 높이에 걸친다 · 안 줄어든다)
   — 정해진 칸의 그림만 가로로 · 카드엔 보상 글자가 없다 (ADR-0668 · 0666) */
/* 아이콘 한 변 32 → 38 · 이름은 아이콘 윗변 · 핍은 아랫변에 붙는다 — 본문 높이 = 아이콘이라 아이콘 없는 `???` 칸도 핍 높이가 같다 (ADR-0709) */
.mon-card { --mon-sk: 38px; }
/* 본문 위 여백 6 — 가운데 정렬이 늘어난 높이의 반만큼 이름을 끌어올리는 것을 덜어 핍이 실제로 내려선다 (ADR-0709 · 막대는 ADR-0931 이 걷음) */
.mon-card .mon-body { padding-top: 6px; }
.mon-main { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: 8px; row-gap: 4px; align-items: center; min-height: var(--mon-sk); }
.mon-main .mon-name, .mon-main .pips { grid-column: 1; }
.mon-main .mon-name { align-self: start; }
.mon-main .pips { align-self: end; }
.mon-main .mon-sk { grid-column: 2; grid-row: 1 / span 2; }
.mon-sk { display: flex; gap: 4px; flex: none; }
.mon-sk .sk-ico {
    width: var(--mon-sk); height: var(--mon-sk); position: relative; overflow: hidden;
    display: grid; place-items: center; background: var(--bg-input); border: 1px solid var(--border-dark);
}
.mon-sk .sk-ico img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 레벨 핍 — 도감 레벨(카드 누적 문턱)을 한눈에 · 카드 맨 아래 진행 막대는 없다 (ADR-0931) */
/* 칸 = 그 레벨 구간의 경험치가 차는 막대 — 이름 칸 폭을 같은 폭으로 나눠 채운다 · 높이 7 은 그대로 (2026-09-21 사용자 지시 18×7 · 2026-10-27 ADR-0931) */
.pips { display: flex; gap: 3px; }
.pips .pip {
    flex: 1 1 0; min-width: 0; height: 7px; background: var(--bg-input);
    /* 안 켜진 핍도 보여야 한다 — 「몇 번 더 올릴 수 있나」가 도감의 목표치다. --border-dark 는 카드 배경에 묻혔다 (2026-08-30) */
    border: 1px solid var(--border-secondary);
}
/* 채움 = 그 몬스터의 죄종 색(`--sin` — 핍 줄에 렌더러가 건다) · 다 차고 먹는 칸은 테두리도 그 색 (ADR-0932) */
.pips .pip > i { display: block; height: 100%; background: var(--sin, var(--color-warning)); }
.pips .pip.on { border-color: var(--sin, var(--color-warning)); }
/* 도서관이 안 연 단계 — 경험치는 쌓여 회색으로 찬다 (§9 · ADR-0762 · ADR-0925 · ADR-0931) · 작은 툴팁 끝에 「도서관 n랭크」 */
.pips .pip.locked > i { background: var(--text-muted); }

/* 도감 몬스터 툴팁 — 두 장: 왼쪽 선술집 후보 카드 · 오른쪽 스토리(머리글 + 이야기) · 보너스 효과(머리글 + 단계) (SCREEN_DESIGN §9 · ADR-0206 · ADR-0209 · ADR-0233 · ADR-0239 · ADR-0244).
   폭은 고정이고 이야기는 원고가 이야기 칸(최대 여섯 줄) 안에 든다(ADR-0244).
   **칸은 선으로 가른다** (ADR-0209) — 머리글 아랫선 둘 · 단계 줄마다 가로선 · 레벨 | 보정 세로선(이야기 아래엔 선이 없다 · ADR-0245). 색은 화면 전반의 구분선 토큰 */
/* 오른쪽 장은 세로 흐름이다 — 이야기 칸이 남는 세로를 다 가지고(`flex: 1`) **보너스 효과 묶음(머리글 + 단계)이 바닥에 붙는다** (ADR-0238 · ADR-0239).
   안쪽 여백은 왼쪽 장(`.ng-card` — 윗변 3 + 여백 14 · 바닥 테두리 1 + 여백 13)과 같은 자리에 선다 — 두 장의 윗선 · 바닥선이 나란하다.
   **두 장 모두 보이는 폭 280** (ADR-0239) — 카드가 배율 .9 를 들므로 설계 폭은 280 / .9 다.
   **윗변 3px = 왼쪽 장과 같은 등급 색** (ADR-0244) — 색은 렌더러가 왼쪽 장에서 옮겨 건다 · 윗변 3 + 여백 14 가 왼쪽 장과 같다 */
.tip-card.cx-tip { width: calc(280px / .9); display: flex; flex-direction: column; padding: 14px 16px 14px; border-top: 3px solid var(--border-secondary); }
/* 이야기 칸 — 글자 14px(툴팁 본문 13 보다 크다 · 사용자 지시) · 칸은 보너스 효과 머리글 위까지 늘어난다 · **아랫선은 없다** — 경계는 머리글 줄이 든다(ADR-0245) */
.cx-tip-story {
    flex: 1 0 auto; padding: 8px 0 10px;
    font-size: 14px; line-height: 1.55; word-break: keep-all; color: var(--text-secondary);
}
/* 머리글 둘 — 「스토리」(맨 위) · 「보너스 효과」. 한 모양이고 **아랫선**이 아래 칸을 연다 (ADR-0239 · ADR-0244).
   글자는 이야기와 같은 14px · 굵게 · 흰색(사용자 지시 · ADR-0245) — 이야기 글(밝은 회색 · 보통 굵기)과 굵기 · 색으로 갈린다.
   맨 위 머리글은 윗여백이 없다 — 카드 여백이 그 자리다(왼쪽 장의 칩 줄과 같은 높이에 선다) */
.cx-tip-h { font-size: 14px; font-weight: bold; color: var(--text-primary); padding: 8px 0 6px; border-bottom: 1px solid var(--border-dark); }
.cx-tip-h:first-child { padding-top: 0; }
/* 문단 하나 = 셀의 줄바꿈 하나 — 문단이 있으면 한 덩어리로 안 보이게 문단 사이만 띄운다 */
.cx-tip-story p { margin: 0; }
.cx-tip-story p + p { margin-top: 7px; }
/* 단계 한 줄 = Lv · 그 단계의 보정 — **처치 문턱은 안 적는다**(ADR-0209). 줄마다 윗선이 표의 행을 가른다 · 닿은 단계만 켜진다(레벨 핍과 같은 색).
   첫 줄은 윗선이 없다 — 「보너스 효과」 머리글의 아랫선이 그 자리다(겹선 방지).
   레벨 | 보정 세로선은 보정 칸의 왼쪽 선이다 — 위아래 여백을 줄이 아니라 **칸**이 가져야 선이 줄 높이를 꽉 채워 다음 줄 선과 이어진다 */
.cx-step {
    display: grid; grid-template-columns: 3.2em 1fr; column-gap: 10px;
    border-top: 1px solid var(--border-dark);
    font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap;
}
.cx-step:first-child { border-top: 0; }
.cx-step > span { padding: 5px 0; }
.cx-step-b { text-align: right; border-left: 1px solid var(--border-dark); }
/* 도서관이 안 연 단계 — 효과 글 대신 한 줄: 자물쇠 + 「도서관 n랭크」 · 자물쇠(`currentColor`)와 글자 모두 흐린 글자색 (ADR-0922 · ADR-0699 · ADR-0762) */
.cx-step-need { color: var(--text-muted); }
/* 왼쪽 장 = 선술집 후보 카드 그대로 (ADR-0233) — `.ng-card` 규격을 탄다. 초상도 영웅과 같은 네모다(ADR-0237).
   **배율은 선술집 카드와 같다** (ADR-0237) — 메인 배율(`#app:not(.pregame) > .main { zoom: .9 }`). 툴팁은 `#stage` 바로 아래라 메인 배율 밖이어서 카드가 스스로 든다 —
   안 들면 같은 규격이 약 11% 크게 섰다(실측 343 대 309.6). 오른쪽 장도 같은 배율이다(두 장의 글자 크기가 같아야 한 툴팁으로 읽힌다).
   어두운 등급 색(일반 · 보스)은 막대 · 등급 칩만 밝힌다 — 유닛 툴팁의 `bar-lift` 와 같다(칩은 검은 바탕에 글자가 묻혔다 · 윗변은 관전 카드 색 그대로) */
/* **선술집 카드보다 한 단 작다** (ADR-0238) — 초상 · 이름 글자 · 폭을 줄인다(배율 · 막대 줄 · 칩 · 직업 줄은 그대로).
   스킬 그림은 선술집 카드 칸 그대로다 — 줄였던 32 는 보이는 28.8px 로 목록 카드 아이콘보다 작았다 · 40 부터는 영어 칩 줄이 두 줄인 몬스터의 열이 초상보다 길어진다 (ADR-0987).
   초상 한 변 = 오른쪽 열 높이(칩 · 이름 · 직업 · 역할 · 스킬 그림 — 한국어 실측) — 스킬 그림 아랫변이 초상 아랫변에 서야 한다(ADR-0156) */
.ng-card.cx-cand { width: calc(280px / .9); zoom: .9; }   /* 보이는 폭 280 (ADR-0239) */
.cx-cand .ng-head .hero-face { width: 112px; height: 112px; }
.cx-cand .ng-name > b { font-size: var(--fs-md); }
.tip-card.cx-tip { zoom: .9; }
.cx-cand.bar-lift .attr-bar > i,
.cx-cand.bar-lift .ng-chips .tier-chip { filter: brightness(1.8); }
/* 두 장의 합이 툴팁 창의 폭 상한을 넘는다 — 유닛 툴팁 Alt 판과 같이 이 툴팁에서만 푼다 */
.tooltip:has(> .cx-cand) { max-width: none; }
.cx-step.on { color: var(--color-success); }
/* 도감 스킬 툴팁의 둘째 장 — 획득처 · 레벨이 오르면 (SCREEN_DESIGN §9-1 · ADR-0680 — ~~단계~~ ADR-0650). 위 오른쪽 장의 규격(`.cx-tip` — 머리글 · 바닥에 붙는 묶음)을 타고
   **배율만 푼다** — 왼쪽 장이 선술집 카드(배율 .9)가 아니라 스킬 카드(배율 없음)라 두 장의 글자가 같아야 한 툴팁으로 읽힌다.
   윗변은 스킬 카드와 같은 색 · 두께 · 왼쪽 선이 두 장을 가른다 */
.tip-card.cx-sk-tip { zoom: 1; width: 280px; padding: 14px 16px 15px; border-top: 2px solid var(--border-highlight); border-left: 1px solid var(--border-dark); }
.tooltip:has(> .cx-sk-tip) { max-width: none; }
/* 획득처 칸 — 남는 세로를 다 가져 「레벨이 오르면」 묶음을 바닥에 붙인다(몬스터 툴팁의 이야기 칸 자리) · 작은 원형 초상 + 아래 장-장소 */
.cx-src-box { flex: 1 0 auto; padding: 8px 0 10px; }
.cx-src { display: flex; flex-wrap: wrap; gap: 6px; }
.cx-src-cell { width: 38px; display: flex; flex-direction: column; align-items: center; gap: 2px; }
.cx-src-cell .face { width: 36px; height: 36px; }
.cx-src-at { font-size: var(--fs-xs); line-height: 1.1; }
/* 셋째 칸 굴림 보스 — 한 단 작다(같은 직업 보스가 전부 서서 고정 칸보다 많다 · 주인공은 고정 칸) */
.cx-src.roll { gap: 4px 3px; }
.cx-src.roll .cx-src-cell { width: 30px; }
.cx-src.roll .cx-src-cell .face { width: 26px; height: 26px; }
/* 「보스 · 무작위 칸」 — 고정 칸 몬스터 아래 작은 머리(머리글이 아니다 — 선 없음) */
.cx-src-h { font-size: var(--fs-xs); margin: 9px 0 5px; }
.cx-src-h:first-child { margin-top: 0; }
/* 획득처의 상단 — 건물 그림 · 몬스터 초상과 같은 크기 · 네모(원형은 몬스터의 표시다 · ADR-0680) */
.cx-src-cell .face.bld { border-radius: 4px; }
/* 레벨이 오르면 — 한 줄: 왼쪽 칸 이름 · 오른쪽 레벨마다 오르는 양(닿은 단계와 같은 색 — 좋아지는 쪽이다) */
.cx-lvup { display: flex; justify-content: space-between; gap: 10px; padding: 5px 0; font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; }
.cx-lvup > b { color: var(--color-success); }

/* ───────── 도감 — 자산 세그먼트 (SCREEN_DESIGN §9-1 · 2026-09-06 · 도감으로 흡수 2026-09-08) ─────────
   옛 「이미지 도감」 탭. 자산을 묶음별로 펼치는 조회 화면이고, 마스터리를 포함한 도감의 조회 세그먼트 넷이 됐다 —
   **클래스 이름은 `.ix-*` 그대로**다(화면의 속이 안 바뀌었다). 칸 폭은 고정 px 이 아니라 auto-fill + minmax 다 —
   이름과 파일명이 들어가는 칸이라 영어에서 길어진다 (폭 정책은 src/ui/README.md).
   마스크는 게임에서 쓰는 것 그대로 — 영웅·아이템·스킬은 네모(`box`), 몬스터는 원형(`round` — 09-08 이 화면에서는 안 쓰지만 §9 카드가 쓴다) */
.ix-style { display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); }
.ix-body { display: flex; flex-direction: column; gap: 10px; }
.ix-group {
    padding: 7px 10px 9px; background: var(--bg-tertiary);
    border: 1px solid var(--border-dark);
}
.ix-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 7px; }
.ix-title { font-size: var(--fs-sm); }
.ix-dir { font-size: var(--fs-xs); }
.ix-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(108px, 1fr)); gap: 8px; }
.ix-tile {
    display: flex; flex-direction: column; align-items: center; gap: 3px;
    padding: 6px 4px; background: var(--bg-card); border: 1px solid var(--border-dark);
}
/* 그림 칸 — 게임에서 가장 큰 자리(도감 초상 72px)보다 크게 잡는다. 아트를 확인하러 오는 화면이라
   여기서까지 작으면 이 탭이 있을 이유가 없다. 그림이 없으면 이 빈 네모가 그대로 남는다 */
.ix-art {
    width: 92px; height: 92px; flex: 0 0 auto;
    display: flex; align-items: center; justify-content: center; overflow: hidden;
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
.ix-art.round { border-radius: 50%; }
/* 전직 스킬 — 그림 칸 바탕만 전직 색이다 (SCREEN_DESIGN §2 「스킬 그림」 · ADR-0301) */
.ix-art.adv { background: var(--adv-skill-bg); }
.ix-art img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 원형 마스크는 가장자리를 잘라낸다 — 몬스터 카드(.face img)와 같은 cover 라야 도감에서 보이는 그대로다 */
.ix-art.round img { object-fit: cover; }
.ix-name { font-size: var(--fs-xs); line-height: 1.25; text-align: center; word-break: keep-all; }
.ix-file { font-size: var(--fs-xs); line-height: 1.2; text-align: center; word-break: break-all; }

/* 조밀 격자 — 스킬 세그먼트 전용 (ADR-0075 · 2026-09-10).
   묶음이 다섯이라(직업) 92px 그림으로는 하한 1280x700 에서 둘 반만 보이고 나머지는 스크롤 아래였다.
   그림을 줄여 **다섯 묶음이 한 화면에 다 선다** — 캐릭터 · 아이템은 자산 확인이 우선이라 그대로 92px 이다.
   칸 폭(minmax)은 가장 큰 묶음(8칸)이 하한 폭에서 한 줄에 서도록 잡았다 — 접히면 세로 예산이 깨진다 */
/* 그림 칸은 **1600×800 한 장 기준 고정값**이다 (ADR-0087) */
.ix-body.dense { gap: 5px; --ix-art: 48px; }
.ix-body.dense .ix-group { padding: 3px 8px 4px; }
.ix-body.dense .ix-head { margin-bottom: 3px; gap: 8px; }
.ix-body.dense .ix-title { font-size: var(--fs-xs); }
.ix-body.dense .ix-grid { grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); gap: 5px; }
.ix-body.dense .ix-tile { padding: 3px; gap: 1px; }
.ix-body.dense .ix-art { width: var(--ix-art); height: var(--ix-art); }
.ix-body.dense .ix-name { line-height: 1.15; }
.ix-body.dense .ix-file { line-height: 1.1; }
/* 도감 — 스킬의 이펙트 탭 [2026-10-05 · SCREEN_DESIGN §9-1 · ADR-0513] — 관전 카드(.unit · 폭은 관전 칸과 같다)를 그대로 깔고 오른쪽 칸만 스킬 그림(위) · 이름(아래)이다.
   전직 스킬의 조각은 카드 밖까지 나가므로 카드 사이 틈을 넉넉히 둔다 · 이름이 길면(영어) 두 줄까지 접고 넘치면 말줄임 */
.cx-fx-grid { display: grid; grid-template-columns: repeat(auto-fill, 226px); gap: 18px 22px; padding: 6px 4px 8px; }
.cx-fx-card .unit { cursor: pointer; }
.cx-fx-info { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 6px; font-size: var(--fs-sm); }
.cx-fx-info img { width: 32px; height: 32px; flex: none; }
.cx-fx-info span { max-width: 100%; overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-height: 1.25; overflow-wrap: break-word; }
.cx-fx-play { padding: 0 8px; font-size: var(--fs-xs); line-height: 18px; }
/* 전직 스킬 — 직업 하나가 한 줄 · 그 직업의 전직 박스가 나란히 (SCREEN_DESIGN §9-1 · ADR-0336).
   칸 폭은 줄 안에서 같고(개수는 데이터가 정한다) 높이는 grid 가 줄에서 가장 긴 박스에 맞춘다 */
.ix-row { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 5px; }
/* 일반 스킬 — 직업 카드 하나에 칸 없이 같은 간격 (SCREEN_DESIGN §9-1 · ADR-0479). 열 폭은 조밀 격자 칸 폭으로 고정 · 왼쪽부터 붙인다.
   티어 머리는 시작 그림 위에만 글자가 있고 나머지는 빈 줄로 높이를 맞춘다 · 2 · 3티어 시작은 열 틈 한가운데 세로선 */
.ix-flat { display: grid; grid-template-columns: repeat(auto-fill, 112px); column-gap: 5px; row-gap: 4px; }
.ix-cell { min-width: 0; position: relative; display: flex; flex-direction: column; gap: 1px; }
.ix-cell.tier-start::before { content: ''; position: absolute; left: -3px; top: 0; bottom: 0; border-left: 1px solid var(--border-dark); }
.ix-tier-head { font-size: var(--fs-xs); line-height: 1.2; min-height: 1.2em; }
.ix-flat .ix-tile { background: none; border: 0; }

/* 마스터리 도감 — 인게임 판을 그대로 세워 한 줄에 세 판씩 비교한다. */
.codex-mastery-grid {
    display: grid; grid-template-columns: repeat(3, minmax(0, 350px));
    gap: 14px; align-content: start; justify-content: center;
    padding: 2px 1px 8px;
}
.codex-mastery-grid .sk-box { min-width: 0; }
/* 도감 전직 판 — 가지 칸은 보려고 연 화면이라 흐리지 않는다(스킬 창은 배운 열만 또렷하다) · 누를 수 없다 (ADR-0557) */
.codex-mastery-grid .adv-node { opacity: 1; cursor: default; }

/* ───────── 페이퍼돌 (부위 8종 · 위치 9개, 반지 ×2) ───────── */

.paperdoll {
    display: grid; grid-template-columns: repeat(3, 60px);
    gap: 8px; justify-content: center; margin-top: 4px;
}
.pd-gap { width: 60px; height: 60px; }

.pd-cell {
    width: 60px; height: 60px;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
    background: var(--bg-input); border: 2px solid var(--border-dark);
    position: relative; cursor: pointer;
}
.pd-cell:hover { background: var(--surface-2); }
.pd-cell.filled { background: var(--bg-tertiary); }

.pd-icon { font-size: 22px; line-height: 1; filter: grayscale(1) brightness(.55); }
.pd-cell.filled .pd-icon { filter: none; }
/* 칸에는 글자가 없다 [2026-09-15 사용자 지시 · ADR-0122] — 부위 이름 줄을 걷었다. 찬 칸 그림은 빈 칸 실루엣(`.pd-art` 의 inset)과
   같은 크기로 선다. `.inv-icon` 과 함께 쓰는 34px 규칙(아래 「아이템 그림」)을 페이퍼돌에서만 덮는다 */
.pd-cell .pd-icon { width: 44px; height: 44px; }

/* 미장착 칸 = 부위 실루엣 [2026-09-03] — 「여기에 무엇이 들어가는가」를 그림이 말한다.
   ⚠ CSS `background: url()` 이 아니라 **`<img>`** 다 (스킬 아이콘과 같은 문법 · 규칙은 `mock.js:slotArt`).
   커스텀 프로퍼티에 담은 상대 url 은 **이 파일 기준**(`/ui/assets/…`)으로 풀려 404 가 난다 —
   실제로 그렇게 짰다가 칸이 통째로 비었다. img 의 src 는 문서 기준이라 그 함정이 없다.
   **이모지를 밑에 깔지 않는다** — 투명 PNG 사이로 비친다(직업 글리프 폐지와 같은 이유).
   2026-09-17 로 부위 7종이 다 찼다 — 빈 칸이 이모지로 떨어지는 일은 이제 없다 */
/* 실루엣은 칸 **가운데**에 선다 [2026-09-15 · ADR-0122] — 부위 이름 줄이 서던 아래 14px 을 걷었다.
   inset 이 찬 칸 그림(`.pd-cell .pd-icon` 44px)과 크기를 맞춘다 — 한쪽만 바꾸면 빈 칸과 찬 칸의 그림 크기가 갈린다 */
.pd-cell.art .pd-art { position: absolute; inset: 6px; pointer-events: none; }
.pd-cell.art .pd-art img {
    width: 100%; height: 100%; object-fit: contain;
    opacity: .3; image-rendering: var(--face-render);
}

/* 아이템 그림 — 이모지가 들던 칸 넷 (2026-09-03 · SCREEN_DESIGN §2 · 규칙은 `mock.js:itemArt`).
   ⚠ 칸에 **크기를 준다**: 이모지는 글씨라 font-size 가 칸을 정했지만 img 는 부모가 정해야 한다.
   그림이 없는 부위(투구·목걸이)는 같은 칸에 이모지로 떨어지므로 font-size 도 그대로 남는다 */
.pd-icon, .inv-icon {
    display: flex; align-items: center; justify-content: center;
    width: 34px; height: 34px;
}
.pd-icon img, .inv-icon img, .fg-ic img {
    width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render);
}
.fg-kind .fg-ic { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; font-size: 20px; }   /* 제작 종류 줄 — 부위 고르개 그림(`.seg-slot`)과 같은 한 변 · 그림이 없으면 부위 이모지 (ADR-0263) */

/* ───────── 인벤토리 격자 ───────── */

.inv-cells { display: grid; gap: 4px; }

.inv-cell {
    aspect-ratio: 1 / 1;
    display: flex; align-items: center; justify-content: center;
    background: var(--bg-input);
    border: 1px solid var(--border-dark);
    box-shadow: inset 1px 1px 0 0 rgba(var(--shadow-rgb), .5);
}
.inv-cell.filled {
    background: var(--bg-tertiary); border-width: 2px; cursor: pointer;
    box-shadow: none;
}
.inv-cell.filled:hover { background: var(--surface-5); }
.inv-icon { font-size: 20px; line-height: 1; }
/* 첫 클리어 상자 — 등급 테두리 없이 중립 테두리 · 그림만 (SCREEN_DESIGN §6 · ADR-0731) */
.inv-cell.box { border-color: var(--border-highlight); }
/* 상자의 부위 표식 — 왼쪽 위 모서리 · 빈 칸 실루엣을 어두운 바탕에 (ADR-0742). 기준은 `.inv-cell` — 보관 칸과 우편 카드의 첨부 칸(ADR-0748)이 같이 쓴다 */
.inv-icon img.box-kind {
    position: absolute; left: 2px; top: 2px; width: 42%; height: 42%;
    padding: 1px; box-sizing: border-box; background: rgba(0, 0, 0, .6); border-radius: 3px; pointer-events: none;
}

/* 유니크는 은은하게 빛난다 */
.inv-cell.shine { animation: shine 2.4s ease-in-out infinite; }
@keyframes shine {
    0%, 100% { box-shadow: none; }
    50% { box-shadow: 0 0 9px rgba(var(--rarity-unique-rgb), .55); }
}

/* 도움말 본문의 글자 규격 (접이식 「구성 보기」는 2026-09-10 삭제 · ADR-0080) */
.note-body {
    font-size: var(--fs-xs); color: var(--text-muted); line-height: 1.7;
    margin-top: 7px; padding-left: 2px;
}


/* ───────── 캐릭터 탭 (2026-08-23) ─────────
   세로 3단: 영웅 띠 / 4칸 / 아이템. 단 사이 간격은 .panel + .panel 이 아니라 스택이 준다 */

/* 세 단이 박스 높이를 통째로 나눠 갖는다 [2026-09-09 사용자 지시 · 박스 2026-09-11 ADR-0097] — **가방이 박스 끝에 서고**
   남는 세로는 가운데 네 칸(`.cols.c-char`)이 먹는다 (SCREEN_DESIGN §6).
   **가방 높이는 절대 줄지 않는다** [2026-09-27 사용자 지시 · ADR-0384] — 원정 화면의 창고 · 인벤토리와 같은 제 높이(`auto`)다.
   ~~셋째 행 `minmax(0, auto)` — 모자라면 네 칸이 하한을 지키고 가방이 줄어 가방 안에서 스크롤~~ 은 폐기: 세부 옵션 줄이 늘 때마다 가방이 깎였다.
   이제 모자라는 쪽은 **네 칸**이다 — 둘째 행이 `minmax(0, 1fr)` 이고 넘치는 목록은 칸 안에서 휠로 내린다(`.cs-scroll`) */
.char-stack { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 14px; }
.char-stack > .bag, .char-stack > .bag-row > .bag { display: flex; flex-direction: column; min-height: 0; }
/* 칸 격자는 **줄기만 하고 자라지 않는다** (flex-grow 0 · 2026-09-14) — 늘어난 창고 패널의 남는 높이는 도구 줄이 받아야 두 칸의 칸 줄이 맞는다(`.bag-row`).
   가방 행이 `minmax(0, auto)` 라 이 격자가 자랄 자리는 원래 그 경우뿐이었다 */
.char-stack > .bag > .inv-cells, .char-stack > .bag-row > .bag > .inv-cells { flex: 0 1 auto; min-height: 0; overflow-y: auto; }

/* ① 영웅 띠 — 원정 편성·캐릭터·스킬·선술집 공통 상단 (2026-08-26 · 2026-08-27 개편 · 2026-08-27 원정 편성 추가). 초상이 카드 전체를 채우는 정사각이고,
   글자는 초상 위에 얹는 위칸 하나다: 왼쪽 = 지금 하는 일(색 태그) · 오른쪽 = 이름 (SCREEN_DESIGN §5).
   로스터 상한(7)까지 한 줄에 편다 — 개수를 CSS에 박지 않는다(roster_cap 은 데이터다). flex 로 나눠 갖되 상한폭을 둬서
   영웅이 적을 때 카드가 판넬을 다 먹지 않게 한다 */
.hs-panel { padding: 10px 12px; }
/* 편성 패널 안에 들어갈 때 — 패널 안 패널이 되지 않게 껍데기를 벗는다 */
.hs-panel.flat { padding: 0; background: none; border: 0; }
.hero-strip { display: flex; flex-wrap: wrap; gap: var(--hs-gap); }
/* 순서 옮기기의 삽입선 (캐릭터 탭 띠 · ADR-0571) — 끄는 카드가 들어갈 틈 한가운데의 세로 막대. 자리 · 높이는 렌더러가 카드에서 재어 단다.
   고스트(`.fm-ghost`)와 같은 층(`#stage` 직속)에 **그 위로** 선다 — 고스트가 틈을 덮어도 선은 보인다.
   포인터를 안 받는다 — 놓을 곳 판정(elementFromPoint)을 가리면 안 된다 */
.hs-insert {
    position: fixed; width: 3px; transform: translateX(-50%); z-index: 46; pointer-events: none;
    background: var(--color-drop); border-radius: 2px; box-shadow: 0 0 6px var(--color-drop);
}
.hs-card {
    flex: 1 1 0; min-width: 96px; max-width: var(--hs-card-max);   /* 2026-08-27 축소 — 화면 대비 너무 컸다 (관전 유닛 카드 상한과는 별개다) */
    background: var(--bg-tertiary); border: 1px solid var(--border-dark);
    border-top: 3px solid var(--border-secondary);
    cursor: pointer; position: relative; overflow: hidden;
}
.hs-card:hover { border-color: var(--border-highlight); }
/* 보기 전용 띠(자원 탭 · ADR-0369) — 누를 것이 아니라 손가락 커서 · hover 테두리를 안 든다 (툴팁은 뜬다) */
.hero-strip.view-only .hs-card { cursor: default; }
.hero-strip.view-only .hs-card:hover { border-color: var(--border-dark); }
/* 편성 띠 — 파티에 넣을 수 있는 건 **대기**뿐이다. 출정 아웃은 거절(플래시)이므로 커서로도 미리 말한다.
   다른 탭에서는 아웃된 영웅도 눌러서 들여다볼 수 있으므로 이 띠에서만 건다 */
.hero-strip.party-mode .hs-card.downed { cursor: not-allowed; }
/* 클릭한 영웅 — **파란 겉 테두리**가 여기로 옮겨 왔다 (2026-09-08 사용자 지시 · SCREEN_DESIGN §5) */
.hs-card.on { border-color: var(--border-highlight); background: var(--surface-4); outline: 3px solid var(--color-info); outline-offset: 1px; }
/* 전투 파티 = **반투명** [개정 2026-09-09 사용자 지시 · SCREEN_DESIGN §5 · ADR-0056] —
   파란 겉 테두리(테두리 색 + 3px 아웃라인 + 번짐)를 통째로 걷고 **흐림 하나**가 그 뜻을 든다.
   띠가 탭 최상단으로 올라간 뒤(ADR-0055) 파티 영웅은 **아래 진형 보드에도 같이 서 있다** —
   그래서 위 카드의 흐림이 「이 영웅은 아래(전투)에 내려가 있다」로 읽힌다. 자리를 옮긴 표시지 못 쓰는 표시가 아니다.
   ⚠ 테두리를 안 쓰므로 `.on`(다른 띠의 「보고 있는 영웅」)과 표시가 겹칠 일이 없다 — 편성 띠는 `.on` 을 안 건다
   ⚠ **전진 패널이 열려 있을 때만 흐려진다** [2026-09-09 사용자 지시 · ADR-0058] — 「내려가 있다」는 **내려갈 곳이 있을 때만** 참이다.
     지역을 닫으면(`.deployed` 가 빠진다) 파티 영웅도 선명하게 돌아온다
   ⚠ **이 주석이 한 줄 일찍 닫혀 있었다** [2026-09-11 수정] — ADR-0058 문단이 주석 닫는 기호 뒤에 붙어 선택자로 읽히는 바람에
     바로 아래 `opacity: .5` 규칙이 통째로 버려졌다(09-09 cd72dcc 부터). hover 의 .72 만 살아 흐림이 올려놓을 때만 보였다.
     주석 안에 닫는 기호를 글자로 적지 않는다 — 적으면 같은 사고가 난다 */
.hero-strip.party-mode.deployed .hs-card.party { opacity: .5; }
.hero-strip.party-mode.deployed .hs-card.party:hover { opacity: .72; }
.hs-card.unique { border-bottom-color: var(--elite-line); }
.hs-card.downed { opacity: .62; }
.hs-card.empty {
    display: flex; align-items: center; justify-content: center; aspect-ratio: 1; cursor: default;
    border-style: dashed; border-top-width: 1px; background: transparent;
    color: var(--text-muted); font-size: var(--fs-lg);
}
.hs-card.empty:hover { border-color: var(--border-dark); }
/* 초상(카드 전체) · 위칸 · 이름의 규칙은 공통 조각에 있다 (.hs-card .hero-face / .hs-band / .hs-name) */
/* 리더 — 편성 화면에서 파티 첫 슬롯에만. 초상 아래쪽에 얹는다 (2026-08-27, 옛 파티 행의 리더 표시) */
/* 해고 — **고른 카드의 왼쪽 아래**에만 뜬다 [2026-09-09 사용자 지시 · SCREEN_DESIGN §5 · 자리는 2026-09-21 ADR-0278].
   띠 카드의 리더 뱃지(`.hs-leader`)도 왼쪽 아래지만 **편성 띠에만** 서고 해고는 캐릭터 탭 띠에만 서서 한 카드에서 안 만난다.
   초상 위에 얹히니 제 배경을 갖는다 —
   그림이 밝으면 글자가 안 읽힌다(원정 행의 옛 「원정」 칩이 배경 위에서 쓰던 것과 같은 이유) */
.hs-dismiss {
    position: absolute; left: 0; bottom: 0; z-index: 2;
    /* 한 단 키웠다 [2026-09-09 사용자 지시] — 9px 은 카드 구석에서 눌러야 할 것으로 안 읽혔다.
       상한은 카드 폭(.hs-card 하한 96px)이다: 영어 `Dismiss` 가 들어가야 하므로 여기서 더 키우지 않는다 */
    padding: 4px 9px; font-size: var(--fs-xs); line-height: 1.3;
    background: rgba(var(--danger-veil-rgb), .88); border: 1px solid var(--danger-line); color: var(--danger-fg);
}
.hs-dismiss:hover { background: var(--danger-bg-hover); border-color: var(--color-error); }
/* 레벨 — 초상 **오른쪽 아래** [2026-09-21 사용자 지시 「오른쪽 아래로 통일」 · ADR-0278 — 왼쪽 아래(ADR-0202)와 구석을 맞바꿨다].
   판 없이 검은 테두리를 두른 글자(아이템 칸 .inv-lv 와 **같은 문법 · 같은 구석**). 카드가 아이템 칸의 두 배쯤이라 글씨는 한 단 크다(--fs-xs).
   왼쪽 아래는 해고 버튼 · 리더 뱃지 자리라 어느 카드에서도 가리는 것이 없다 */
.hs-lv {
    position: absolute; right: 4px; bottom: 3px; z-index: 1;
    font-size: var(--fs-xs); line-height: 1; color: var(--text-secondary); white-space: nowrap;
    text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000;
    pointer-events: none;
}

.hs-leader {
    position: absolute; left: 0; bottom: 0;
    font-size: var(--fs-xs); line-height: 1.2; padding: 2px 6px;
    background: color-mix(in srgb, var(--bg-primary) 78%, transparent);
    border-top: 1px solid var(--border-dark); border-right: 1px solid var(--border-dark);
    color: var(--text-accent);
}
/* 리더는 **어디서나 왼쪽 아래**다 — 띠 카드 · 진형 보드 칸 · 출정 창 초상 [2026-09-21 ADR-0278].
   띠 카드만 오른쪽으로 뒤집던 규칙(ADR-0202)은 레벨이 오른쪽 아래로 가며 걷었다 */
/* 파티 없음 / 출발 불가 경고 — 띠 아래 (옛 파티 패널이 들던 자리) */
/* 경고 줄 — 글자가 없어도 **자리는 잡는다**. 안 그러면 편성 패널이 파티 상태에 따라 커졌다 작아진다 (2026-08-28) */
/* 세로 쌓기 시절의 윗 여백을 걷는다 (2026-09-09 · ADR-0059) — 이제 오른쪽 칸(.fp-side)의 첫 줄이라 gap 이 간격을 준다.
   ⚠ **줄은 여전히 항상 잡는다**(min-height) — 글자가 있고 없고에 따라 버튼이 위아래로 뛰면 안 된다 */
.exp-warn { font-size: var(--fs-xs); min-height: 1.35em; line-height: 1.35; }
/* 지금 하는 일 — 출정 아웃(빨강) / 전투 파티(파랑) / 대기(회색) */
.hs-doing {
    font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; line-height: 1.3;
    flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis;   /* 줄어드는 쪽은 여기뿐 (2026-09-09) */
}
.hs-doing.exp { color: var(--color-warning); }      /* 원정 중 — 주황 (2026-09-08) */
.hs-doing.down { color: var(--color-error); }       /* 남겨 둔 색 — 지금 쓰는 자리는 없다 */

/* ② 네 칸 — 장비 / 기본 옵션(+현재 스킬) / 세부 옵션 1 / 세부 옵션 2. **같은 폭 · 같은 높이** (2026-08-27).
   폭은 1fr × 4 (최소 창 1280 에서 칸당 약 245px — 페이퍼돌 3×60 이 들어간다), 높이는 **띠 · 가방이 남긴 세로**다 (위 `.char-stack` · ADR-0384) */
.cols.c-char { grid-template-columns: repeat(4, minmax(0, 1fr)); align-items: stretch; min-height: 0; }
/* ~~높이 하한 400~~ 폐기 [2026-09-27 사용자 지시 · ADR-0384] — 하한이 가방 몫을 먹었다. 세부 옵션은 칸 안에서 휠로 내린다(`.cs-scroll`).
   ⚠ **기본 옵션 칸은 스크롤하지 않는다** — 그 칸 내용(능력치 · 액티브 스킬 · 마스터리 버튼)이 네 칸 몫보다 길어지면 넘친다. 늘릴 땐 세로를 다시 잰다 */
.cols.c-char > .panel { display: flex; flex-direction: column; min-height: 0; }

/* 소제목 — 패널 안 둘째 묶음의 제목(캐릭터 탭 접사 죄종 · 현재 스킬 · 선술집 의뢰). h2 를 또 쓰면 칸이 나뉜 것처럼 보인다.
   **모양은 패널 제목과 같은 규칙이 든다**(`.panel > h2, .sub-h` · ADR-0241) — 여기는 자리만: 윗선 없이 위 내용과 여백으로 뗀다 */
.sub-h { margin: 14px 0 8px; }
/* 장비 칸의 「접사 죄종」은 옆 칸 「액티브 스킬」과 **같은 높이**에 선다 [2026-09-21 사용자 지시 「조금만 아래로」 · SCREEN_DESIGN §6].
   위 내용(페이퍼돌 ↔ 경험치 + 능력치 7줄)이 약 6px 짧아 그만큼 여백을 더 준다 — 두 칸 위 내용이 바뀌면 다시 잰다.
   20 → 18 은 옆 칸 블록 위 여백이 3 → 1 로 줄어서다 [2026-09-21 사용자 지시 「액티브 스킬을 약간만 높이고」] */
.sub-h.sins-h { margin-top: 18px; }

/* ②-2 레벨 · 경험치 — 기본 옵션 칸 맨 위, 능력치 막대 위 (2026-09-15 · SCREEN_DESIGN §6 · ADR-0129).
   막대는 **칸 폭 전부 · 능력치 막대(.attr-bar 7px)보다 얇다** — 시작 x 와 두께가 달라야 여덟째 능력치로 안 읽힌다.
   능력치 막대와는 **선 없이 간격**으로만 가른다 — 이 칸의 선은 액티브 스킬 소제목 윗선 하나다 */
.ch-xp { margin-bottom: 10px; }
.ch-xp-line { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin-bottom: 4px; }
.ch-lv { font-size: var(--fs-sm); font-weight: 700; color: var(--text-primary); white-space: nowrap; }
.ch-xp-n { font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; }
.ch-xp .bar { height: 5px; }

/* ②-2 기본 능력치 막대 — 범위는 [balance.csv:hero_attr_min ~ hero_attr_max] */
/* **격자는 줄이 아니라 목록이 든다** (2026-09-01 사용자 지시) — 줄마다 자기 격자를 가지면 라벨 열이
   줄마다 따로 계산돼 **막대 시작점이 들쭉날쭉해진다**(「힘」과 「매력」의 글자 폭이 다르므로).
   목록이 열을 잡고 줄은 `display: contents` 로 사라져야 일곱 줄이 **같은 x 에서** 시작한다.
   열 폭은 여전히 내용이 정한다(고정 px 없음 — ko/en 어느 쪽에서도 안 깨진다) */
.attr-list {
    display: grid; grid-template-columns: minmax(0, auto) minmax(38px, 1fr) 24px;
    gap: 3px 7px; align-items: center;
}
.attr-row { display: contents; }
/* 이름은 왼쪽 · **약어는 막대에 붙는다** (2026-09-01 사용자 지시) — 라벨 칸을 일곱 줄이 공유하므로,
   약어를 이름 뒤에 그냥 붙이면 이름 길이를 따라 x 가 흔들리고 막대와의 사이에 들쭉날쭉한 틈이 생긴다
   (영어에서 특히 — `Luck` 과 `Intelligence` 의 차이). 칸을 꽉 쓰고 양끝으로 밀면 약어 열이 **막대 왼쪽 변에 정렬**된다 */
.attr-n {
    font-size: var(--fs-sm); color: var(--text-secondary); white-space: nowrap;
    display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
}
.attr-bar { height: 7px; background: var(--bg-input); border: 1px solid var(--border-dark); }
.attr-bar > i { display: block; height: 100%; }
.attr-v { font-size: var(--fs-sm); text-align: right; }

/* 능력치 약어 배지 — 언어 중립(STR/AGI…)이라 한/영 어느 쪽에서도 폭이 같다.
   **기본 옵션 막대 줄(`.attr-n`) 전용** — 세부 옵션 행에는 안 붙는다 (2026-09-08 사용자 지시, SCREEN_DESIGN §6) */
.cs-a {
    font-style: normal; font-size: var(--fs-2xs); color: var(--text-muted);
    border: 1px solid var(--border-dark); padding: 0 3px; margin-left: 4px;
    vertical-align: 1px; letter-spacing: 0; flex: 0 0 auto;
}

/* ②-3·4 세부 옵션 1·2 — **목록은 칸 높이를 정하지 않는다** [2026-09-27 사용자 지시 · ADR-0384].
   flex-basis 0 — 목록이 높이 산정에서 빠져 네 칸 높이(= 가방이 남긴 세로)에 맞춰 서고, 넘치면 **칸 안에서 휠로 내린다**.
   ~~flex-basis auto — 가장 긴 칸이 네 칸의 높이를 정한다~~ 는 폐기: 줄이 늘 때마다 가방이 깎였다.
   두 칸은 **16 · 17 줄**이다 [ADR-0381] (SCREEN_DESIGN §6) */
.cs-scroll { flex: 1 1 0; min-height: 0; overflow-y: auto; padding-right: 4px; }
/* 캐릭터 탭 세부 옵션만 줄 간격을 좁힌다 [2026-09-22 · ADR-0291] — 본문 줄 높이(1.6)로는 18줄(지금은 세부 옵션 2)이 네 칸 높이를 밀어 올려 가방이 한 줄 넘게 줄었다.
   유닛 툴팁의 같은 줄(`.tip-unit .cs-row`)은 옵션 줄이 값이 있을 때만 서서 그대로 둔다 */
.cols.c-char .cs-row { line-height: 1.3; }
.cs-row { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; padding: 1px 0; }
.cs-n { font-size: var(--fs-sm); color: var(--text-secondary); }
.cs-v { font-size: var(--fs-sm); color: var(--text-primary); white-space: nowrap; }
/* 값이 없는 축 = 다음 장비가 들어올 자리. 지우지 않고 흐리게 남긴다 */
.cs-row.off .cs-n, .cs-row.off .cs-v { color: var(--text-muted); }
/* 머리 4줄 = 대표값(물리 · 마법 데미지 · 행동 주기 · 최대 HP — 넷은 2026-09-22 ADR-0294) — **값 굵기뿐** (2026-09-01 · 개정 2026-09-08 · 선은 2026-09-15 · 아래 간격은 2026-09-27 걷음 · ADR-0389).
   카테고리 제목을 두지 않기로 한 08-26 결정을 지키면서 「이것이 대표값」만 말한다.
   ⚠ ~~font-size: var(--fs-md)~~ 는 2026-09-08 폐기 [사용자 지시] — 크기까지 키우면 선·굵기와 같은 말을 세 번 하고,
   세부 옵션 1·2 의 행 눈금이 어긋나며, 늘 꺼져 있는 쪽 공격력 줄이 시트에서 제일 큰 글씨가 된다 (SCREEN_DESIGN §6) */
.cs-row.lead .cs-v { font-weight: 700; }
/* 살짝 띄우는 줄 [2026-09-27 · 2026-09-28 사용자 지시 · ADR-0396] — 세부 옵션 두 칸의 묶음 경계마다(`tip.js:sheetPages`).
   ~~묶음마다 간격~~(ADR-0381)은 ADR-0389 가 걷었다 */
.cs-row.gap { margin-top: 6px; }
/* 보관 칸 미리보기 — 끼면 바뀌는 줄의 값 색 (SCREEN_DESIGN §6 · ADR-0619): 좋아짐 · 나빠짐 · 조각마다 갈림 */
.cs-row.up .cs-v { color: var(--color-success); }
.cs-row.down .cs-v { color: var(--color-error); }
.cs-row.mixed .cs-v { color: var(--color-warning); }

/* 버튼은 **칸 바닥에 못 박는다** (2026-09-08) — 스킬 블록이 위로 올라간 뒤 남는 세로를 이 auto 가 먹는다 */
/* 버튼 높이 30 [2026-09-21 사용자 지시 「Open Mastery 버튼 조금만 키워」 24 → 26 · 2026-10-30 「약간만 더 크게」 26 → 30] — 위아래 여백만 늘린다(글씨 크기는 `.btn.sm` 그대로).
   바닥에 못 박혀 있어 **위로** 자란다 — 칸 높이는 안 바뀐다(버튼 위 남는 간격이 받는다).
   ⚠ 여백은 `.btn.sm.go-tree` 로 건다 — `.go-tree` 하나로는 `.btn.sm { padding }`(클래스 둘)에 져서 안 먹었다 */
.go-tree { width: 100%; margin-top: auto; }
.btn.sm.go-tree { padding-top: 6px; padding-bottom: 6px; }
/* 선택한 영웅에게 남은 마스터리 포인트가 있으면 열기 버튼이 깜빡인다. */
.go-tree.has-points { color: var(--color-warning); border-color: var(--color-warning); animation: lv-blink 1.1s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .go-tree.has-points { animation: none; } }
/* 해고 창의 속 — 한 줄 + (막히지 않았으면) 위험 색 버튼. 규칙 설명이 아니라 상태와 확인이다 (SCREEN_DESIGN §6) */
/* 자동 분해 창 [2026-09-21 · **2026-10-22 개편 ADR-0717** · SCREEN_DESIGN §6] — 위에서부터 프리셋 줄 · 레벨 줄 · 격자 · 미리보기 · 최근 분해.
   라벨 폭은 글자가 정한다(영어가 길다 · 고정 px 금지). 레벨 줄은 버튼 줄 `.lv-row`(옛 위험도 줄의 모양)를 그대로 쓰되 값이 문장이라 폭을 넉넉히 잡는다 */
.asv-box { display: flex; flex-direction: column; gap: 12px; font-size: var(--fs-sm); }
/* 이 창의 머리 이름 = **패널 제목(.panel > h2)과 같은 크기** [2026-09-21 사용자 지시] — 기본 h2(1.5em)가 속 줄보다 두 단 넘게 컸다.
   다른 창의 머리는 안 건드린다(이 창만 지시받았다) */
.modal-box.auto-modal .modal-head h2 { font-size: var(--fs-md); }
.asv-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.auto-k { color: var(--text-secondary); white-space: nowrap; min-width: 4em; }
.lv-val.auto-val { font-size: var(--fs-sm); min-width: 9em; }
.asv-at { color: var(--text-muted); font-size: var(--fs-xs); }
.segmented .btn.asv-empty { opacity: .45; }   /* 빈 프리셋 칸 — 고를 수는 있다(저장할 자리) */
/* 격자 — 줄 머리 열 + 부위 열(부위 수만큼 · 글자가 폭을 정한다). 칸 = 모드 글자 버튼 · 모드마다 색 */
.asv-grid { display: grid; grid-template-columns: max-content repeat(var(--asv-cols), minmax(max-content, 1fr)); gap: 4px; align-items: center; }
.asv-head { white-space: nowrap; }
.asv-k { color: var(--text-muted); font-size: var(--fs-xs); white-space: nowrap; }
.asv-th { display: flex; align-items: center; justify-content: center; gap: 2px; }
.asv-th-btn { padding: 0 6px; min-width: 0; }
.asv-th-val { min-width: 3.2em; text-align: center; font-variant-numeric: tabular-nums; }
.asv-none, .asv-cell.none { color: var(--text-muted); text-align: center; opacity: .5; }
/* 칸 모드 색 — 보존 = 흐린 글자 · 베이스 = 정보색 · 분해 = 위험 빨강 (출정 창 작은 칸 `.asv-dot` 과 같은 색) */
.asv-cell.keep { color: var(--text-muted); }
.asv-cell.base { color: var(--info-fg); border-color: var(--info-line); }
.asv-cell.salvage { color: var(--color-error); border-color: var(--color-error); }
.asv-sec { display: flex; flex-direction: column; gap: 6px; }
.asv-sub { color: var(--text-secondary); }
.asv-strip { grid-template-columns: repeat(auto-fill, 44px); }
.asv-more { align-self: center; color: var(--text-muted); }
.auto-act { display: flex; gap: 8px; align-items: center; justify-content: center; min-height: 2em; }
.auto-confirm { color: var(--color-warning); }
/* 출정 창 「들고 가는 것」의 자동 분해 칸 (§4-1 · ADR-0717) — 격자를 작은 칸 색으로 · 칸 하나 = 정사각 점(그림이라 px) · 없는 칸은 빈자리 */
.dw-col { display: flex; flex-direction: column; gap: 14px; flex: 0 0 auto; min-width: 0; }   /* 물약 칸 + 그 아래 자동 분해 칸 (§4-1) */
/* 자동 분해 칸은 **폭을 안 늘린다** — 폭은 위 물약 칸이 정하고 이 칸은 그 안에서 줄을 바꾼다(늘리면 출정 방식 칸 밑으로 파고든다) */
.dw-col > .dw-salv { width: 0; min-width: 100%; }
.asv-read { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.asv-mini { display: grid; grid-template-columns: repeat(var(--asv-cols), 8px); grid-auto-rows: 8px; gap: 2px; }
.asv-dot { border-radius: 1px; background: var(--bg-input); border: 1px solid var(--border-secondary); }
.asv-dot.base { background: var(--info-line); border-color: var(--info-fg); }
.asv-dot.salvage { background: var(--color-error); border-color: var(--color-error); }
.asv-dot.none { visibility: hidden; }
.asv-mini-lv { color: var(--text-muted); font-size: var(--fs-xs); margin-top: 4px; }
/* `⚙` 판의 설정 탭 [2026-09-28 · SCREEN_DESIGN §2-2 · ADR-0413 · ADR-0414] — 자동 분해 창과 같은 틀: 라벨 열 + [Off] [On] 열 ·
   라벨 폭은 글자가 정한다(영어가 길다 · 고정 px 금지). 판 · 탭의 모양은 devpalette.js 가 든다 */
.set-box { display: grid; grid-template-columns: max-content auto; gap: 14px 18px; align-items: center; font-size: var(--fs-sm); }
.set-row { display: contents; }
.set-k { color: var(--text-secondary); white-space: nowrap; }
/* 닉네임 칸 — 판에서 하나뿐인 글 입력 (§2-2 · ADR-0633). 게임 화면 기본기(①②)가 죽인 선택 · 캐럿을 이 칸만 살린다 */
.set-nick {
    justify-self: start; width: 13em; padding: 4px 8px;   /* em — 한글 한 자가 ch 보다 넓다 */
    font: inherit; color: var(--text-primary);
    background: var(--surface-1); border: 1px solid var(--border-highlight);
    -webkit-user-select: text; user-select: text; caret-color: auto;
}
.set-nick:focus { border-color: var(--text-accent); }
/* 고른 버튼 — 빨강 테두리 · 짙은 붉은 바탕 · 흰 굵은 글씨 (2026-10-09 사용자 지시 · §2-2). 공용 `.btn.sm.on` 은 바탕이 한 단 바뀔 뿐이라 On · Off 가 안 갈렸다.
   안 고른 버튼은 공용 그대로 — 흐리지 않는다(흐린 것은 못 누르는 버튼 `:disabled` 이다) */
.set-box .btn.on { background: var(--btn-primary-bg); border-color: var(--text-accent); color: var(--text-primary); font-weight: 700; }
.set-box .btn.on:hover { background: var(--btn-primary-bg-hover); }
.dismiss-box { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; font-size: var(--fs-sm); }
/* 답하는 버튼 줄 — 막힘이면 [확인] 하나, 확인이면 [확인] [취소] 둘 (2026-09-09 사용자 지시 · SCREEN_DESIGN §6).
   ⚠ **줄은 상태와 상관없이 늘 있다** — 막힘 상태에 버튼이 없던 옛 판은 창을 X 로만 닫을 수 있었다.
   **가로 가운데** (2026-09-09 사용자 지시) — 상자가 `align-items: flex-start` 라 줄이 왼쪽에 붙어 있었다.
   `align-self` 가 상자의 그 정렬을 이 줄에서만 덮고, `justify-content` 가 버튼 하나·둘 어느 쪽이든 가운데에 세운다 */
.dismiss-actions { display: flex; flex-direction: row; gap: 8px; align-self: center; justify-content: center; }

/* ②-2 액티브 스킬 — 기본 옵션 칸 아래쪽, 액티브 3 을 정사각 카드로 (2026-08-27 · 이름은 2026-09-08 개명).
   ⚠ 칸 폭을 그냥 3등분하면(`1fr`) 카드가 패널 폭을 따라 커진다 — 글자 줄이 있던 시절엔 그 줄들이 크기를
   붙들었지만, 그림 하나만 남은 뒤로는 붙드는 것이 없어 67px 짜리 판때기가 됐다 (2026-09-08 사용자 지적).
   그래서 **상한을 캡으로 묶는다** — 고정 px 이 아니라 폭 비례라 좁은 화면에서는 퍼센트가, 넓으면 캡이 든다.
   ⚠ **퍼센트 항은 캡보다 커야 캡이 산다** — 처음 넣은 `clamp(34px, 18%, 44px)` 은 1280 에서 18% = 39px 이라
   44px 캡이 **한 번도 안 걸렸고** 카드가 39px 로 떨어졌다. 지금의 `30%`(1280 에서 ≈65px)는 캡 52 위에 있다.
   **캡 60 → 52** [2026-09-21 사용자 지시 「스킬 아이콘 크기를 약간 줄여서 맞추는 걸로」] — 네 칸 높이를 이 칸이 정해서
   가방 셋째 줄이 3px 잘리고 [마스터리 열기]가 출처 글자에 붙어 있었다. 줄인 8px 중 3 은 가방이, 5 는 버튼 위 간격이 받는다 */
/* 블록은 **막대 바로 밑**에 붙고(선 하나로 가른다), 남는 세로는 아래 버튼의 `margin-top: auto` 가 먹는다
   [2026-09-08 사용자 지시 「위치 좀 옮겨봐」] — 종전엔 이 줄이 `margin-top: auto` 라 블록 전체가 칸 바닥으로
   밀려 막대와의 사이에 빈 띠가 크게 남아 있었다(칸 높이 하한 430px 이 그 띠를 더 벌렸다)
   **선은 하나 — 소제목(`.sub-h`)의 밑줄이다** [2026-09-15 사용자 지시 · 2026-09-21 윗선 → 밑줄] — 블록 윗선은 걷었다(두 줄로 겹쳐 서 있었다) */
/* 위 여백 3 → 1 [2026-09-21 사용자 지시 「액티브 스킬 위치를 약간만 높이고」] — 옆 칸 「접사 죄종」도 같이 2 올린다(`.sub-h.sins-h`) */
.sk-cards-wrap {
    display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0;
    margin-top: 1px;
}
/* 소제목 오른쪽 끝 [우선순위] (2026-10-28 · SCREEN_DESIGN §6 · ADR-0937) — 소제목 줄 높이를 안 늘린다: 버튼 위아래 여백을 걷고 글자는 한 단 아래 ·
   ⚠ `.btn.sm.sk-order-btn` 로 건다 — 한 단이면 `.btn.sm { padding }`(클래스 둘)에 진다(`.go-tree` 와 같은 사정) */
.sub-h.sk-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.btn.sm.sk-order-btn { padding: 0 8px; font-size: var(--fs-xs); font-weight: normal; line-height: 1.4; }
/* 스킬 우선순위 창 — 줄 = 순번 · 그림 · 이름 · 줄 전체가 잡는 곳이다(끌어 옮기기 · ADR-0937) */
.sk-order-list { display: flex; flex-direction: column; gap: 6px; min-width: 260px; }
.sk-order-row {
    display: flex; align-items: center; gap: 10px; padding: 6px 10px; cursor: grab; user-select: none; touch-action: none;
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
.sk-order-row:hover { border-color: var(--border-highlight); }
.sk-order-row.drag { opacity: .35; }
.sk-order-no { flex: none; min-width: 1.2em; text-align: center; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.sk-order-ico { position: relative; flex: none; width: 38px; height: 38px; }   /* 그림 오른쪽 아래 `Lv.n`(`.sk-lv`)의 기준 칸 (ADR-0701) */
.sk-order-ico img { display: block; width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
.sk-order-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* 삽입선 — 영웅 띠의 `.hs-insert` 를 가로로 눕힌 것(같은 색 · 같은 층) */
.sk-order-insert {
    position: fixed; height: 3px; transform: translateY(-50%); z-index: 46; pointer-events: none;
    background: var(--color-drop); border-radius: 2px; box-shadow: 0 0 6px var(--color-drop);
}
.sk-cards { display: grid; grid-template-columns: repeat(3, clamp(44px, 30%, 52px)); gap: 8px; }
/* 칸 + 칸 아래 출처 글자 [2026-09-15 사용자 지시 · ADR-0121] — 격자 열은 이 묶음이 받는다.
   글자는 칸 **밖**이라 빈 칸의 흐림(`.sk-card.vacant`)을 안 탄다 — 빈 칸 아래에도 자리 이름은 같은 세기로 선다 */
.sk-slot { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
/* 칸은 **정확히 정사각**이다 — 격자 칸일 때는 한 행이 늘려 맞춰 줬지만 묶음 안에서는 그림(`height: 100%`)이 칸을 몇 px 밀어
   찬 칸만 커지고 글자 줄이 칸마다 어긋났다(빈 칸 아래 「전직」이 3px 위에 섰다). `min-height: 0` 이 `aspect-ratio` 를 이기게 한다 */
.sk-slot > .sk-card { min-height: 0; }
.sk-src { font-size: var(--fs-xs); line-height: 1.2; color: var(--text-muted); text-align: center; white-space: nowrap; }
.sk-card {
    aspect-ratio: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
    padding: 3px; text-align: center; position: relative;   /* 그림 오른쪽 아래 `Lv.n`(`.sk-lv`)의 기준 칸 (ADR-0701) */
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
/* 찬 칸은 **그림 하나뿐**이라 (2026-09-08 · SCREEN_DESIGN §6) 그림이 칸을 꽉 쓴다.
   칸이 `aspect-ratio: 1` 이므로 `min-height: 0` 으로 카드가 먼저 줄게 둔다 */
.sk-card .ico { line-height: 1; width: 100%; height: 100%; min-height: 0; }
.sk-card .ico img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 빈 칸 — **글자가 없다.** 칸이 아이콘 크기(≤44px)라 `Not advanced` 가 안 들어간다(9px + 여백 0 에서도 잘렸다).
   사유는 `title` 이 들고, **찍는** 자리는 스킬 트리 창 목록(`.act-slot.empty`)이다 (SCREEN_DESIGN §6 · §7).
   빈 것을 말하는 것은 파선 테두리다 — 페이퍼돌 빈 칸 · `.act-slot.empty` 와 같은 문법 */
.sk-card.vacant { border-style: dashed; opacity: .55; }
/* 잠긴 빈 칸 — 가운데에 닫힌 자물쇠 [2026-09-29 사용자 지시 · SCREEN_DESIGN §6 · ADR-0425] — 탭 바 자물쇠와 같은 회색 · 칸 크기를 따라간다 */
.sk-card .sk-lock,
.tip-skills .sk-lock { display: inline-flex; width: 45%; height: 45%; color: var(--text-muted); }
.sk-card .sk-lock svg,
.tip-skills .sk-lock svg { width: 100%; height: 100%; }
/* 무기가 안 맞아 꺼진 칸 [2026-09-29 · R187 · SCREEN_DESIGN §6 · ADR-0446] — 그림은 서되 흑백으로 흐리다(「있지만 안 돈다」 — 빈 칸 · 자물쇠와 다른 뜻) ·
   툴팁은 이름 줄의 필요 무기 칩이 위험색이 된다(`.tip-chip.need.off` · ADR-0496 — ~~맨 위 한 줄 `.tip-need`~~) */
.sk-card.off .ico img { filter: grayscale(1); opacity: .45; }
/* 도서관 오른쪽 열 카드 [2026-09-29 · R179 · 도서관 탭 SCREEN_DESIGN §17 · ADR-0422 · 좌우 ADR-0595] — 가진 책 · 책 만들기 둘 다 위 줄 + 아이콘 칸(ADR-0570 · ADR-0573 — ~~책마다 한 줄 `.bk-row`~~) */
.bk-box { display: flex; flex-direction: column; gap: 14px; font-size: var(--fs-sm); overflow-y: auto; padding-right: 4px; }
.bk-sec { display: flex; flex-direction: column; gap: 6px; }
.bk-ico { position: relative; width: 38px; height: 38px; flex: none; background: var(--bg-input); border: 1px solid var(--border-dark); }
.bk-ico img { display: block; width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
.bk-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* 도서관 가진 책 읽기 줄의 스킬 레벨 `Lv.n` — 이름 뒤 (그림이 없는 줄 · ADR-0529). 그림이 있는 자리는 그림 오른쪽 아래 `.sk-lv` (ADR-0576) */
.bk-lv { flex: none; margin-left: 6px; color: var(--text-secondary); font-size: var(--fs-xs); font-variant-numeric: tabular-nums; }
.tr-adv-pts { margin-left: auto; font-variant-numeric: tabular-nums; }
/* 스킬 창 — 전직 포인트 줄 · 전직 판의 스킬 칸 · 가지 셋 */
.sk-adv-pts { text-align: center; font-variant-numeric: tabular-nums; }
.sk-adv-pts-l { font-size: var(--fs-xs); margin-left: 4px; }
.adv-board .adv-ico img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; pointer-events: none; }
/* 못 배우는 칸은 그림이 흐리다 — 다른 스킬을 배웠거나 전직 포인트가 없다(배운 칸은 포인트가 없어도 그대로) · 스킬 그림의 금테가 칸마다 같아 칸 테두리만으로는 안 갈린다 (ADR-0542) */
.adv-board .sk-cell.dim:not(.taken) .adv-ico img { opacity: .35; filter: grayscale(1); }
.adv-board .adv-slot { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: var(--fs-lg); color: var(--text-muted); pointer-events: none; }
/* 가지 칸은 제 열의 위 칸(스킬 → ② → ③ → ④)과 세로 선으로 잇는다 — 줄 사이(`.sk-grid` gap 14px) + 제 윗변 1px 을 건너 위 칸 아랫변에 닿는다 ·
   배운 스킬의 열은 칸이 또렷하고 선이 밝다 (2026-10-08 사용자 지시 「아래로 나열 · 선도 그어줘」 · ADR-0544) */
.adv-board .adv-node::before { content: ''; position: absolute; left: 50%; bottom: 100%; width: 2px; height: 15px; margin-left: -1px; background: var(--bronze-line); pointer-events: none; }
.adv-board .adv-node.on { opacity: 1; }
/* 가지 칸 그림 — 전직 스킬 그림과 같은 투톤이라 칠하지 않는다 · 번호는 오른쪽 아래 꼬리표로 물러난다(보류 칸은 그림 없이 번호만 가운데) (ADR-0547) */
.adv-board .adv-node-art { position: absolute; left: 12.5%; top: 12.5%; width: 75%; height: 75%; object-fit: contain; pointer-events: none; }
.adv-board .adv-node.has-art .adv-slot { inset: auto 3px 1px auto; font-size: var(--fs-xs); }
.adv-board .adv-node.on::before { background: var(--text-accent); }
.bk-err { flex: none; font-size: var(--fs-xs); }
/* 지금 가진 스킬 = 캐릭터 탭 액티브 카드 셋(`.sk-cards` 그대로 · 칸 아래 출처 · 소제목 없음 ADR-0589) · 찬 칸 그림 오른쪽 아래 `Lv.n`(`.sk-lv` · ADR-0576) —
   도서관 전직 패널 이름 줄 아래(`.tr-adv-cur` · 2026-10-12 ADR-0595 — ~~배우기 머리 `.bk-head`~~ ADR-0567)
   (2026-10-09 사용자 지시 「우리의 원래형태인 3가지가 나열되는 형태로」 · ADR-0578 — ~~찬 칸만 한 줄 `.bk-cur`~~ ADR-0567)
   `Lv.n` 은 캐릭터 탭 카드에도 선다 — 기준 칸(`position: relative`)은 `.sk-card` 본 규칙이 든다 (2026-10-21 · ADR-0701 — ~~`.sk-cards.lv`~~) */
.bk-empty { font-size: var(--fs-xs); }
.bk-cost { display: flex; gap: 10px; margin-left: auto; flex: none; color: var(--text-muted); font-size: var(--fs-xs); }
.bk-cost b { color: var(--text-primary); font-weight: 600; }
.bk-cost .down b { color: inherit; }
/* 가진 책 · 책 만들기 — 위 줄(상단의 사기 줄 `.td-buy` 를 빌린다 · 위에 서서 위 여백이 없다) · 그 아래 아이콘 칸(상단 아이콘 칸과 같은 정사각 60px · 가진 책은 오른쪽 아래 `×n` = `.inv-lv`)
   [2026-10-09 사용자 지시 「아이콘만 보이게 하고 눌렀을때 위에 가격」 · 「내가 가진 책도 아이콘 형태로」 · §17 · ADR-0570 · ADR-0573].
   줄 끝 버튼은 글자가 달라도(배우기 · 덮어쓰기 · 업그레이드 · 만들기) 폭이 같다 — 라벨 칸이라 px 이 아니라 em */
.td-buy.bk-buy { margin-top: 0; flex: none; }
.bk-buy .bk-cost { margin-left: 0; }
.bk-buy > .btn { flex: none; min-width: 5.5em; }
/* 칸 격자는 고른 테두리(`.td-picked` — 3px · 바깥 1px)만큼 안쪽 여백을 둔다 — 카드 본문이 스크롤 상자라 왼쪽 끝 칸의 테두리가 잘렸다 (2026-10-09 사용자 「왼쪽에 파란색 선 잘리는거」 · 3px 은 ADR-0926) */
.bk-grid { display: grid; grid-template-columns: repeat(auto-fill, 60px); gap: 8px 6px; padding: 4px; }
.bk-grid .inv-icon { width: 44px; height: 44px; }
.bk-grid .inv-icon img { display: block; width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 도서관 탭 패널 본문 [SCREEN_DESIGN §17 · ADR-0422] — 높이는 패널(박스)이 정한다 */
.bk-box.lib-body { flex: 1 1 auto; min-height: 0; }

/* ③ 아이템 — 열 수는 창 폭이 정한다. 데이터는 용량(INV_GRID.cap)만 지킨다 */
.inv-cells.wide { grid-template-columns: repeat(auto-fill, minmax(42px, 1fr)); }
.inv-filter { margin-bottom: 10px; }

/* ───────── 새 게임 (2026-08-24) ─────────
   게임 밖 화면이라 네비·자원을 접고 본문이 전폭을 쓴다. 로고와 언어 토글만 남는다 */

#app.pregame { grid-template-areas: "brand topbar" "main main"; }
#app.pregame .nav { display: none; }

/* 메뉴 — 켜면 먼저 선다 · 워드마크 아래 새 게임 · 불러오기가 세로로 (SCREEN_DESIGN §3 · ADR-0641 · app.js:renderMenu) */
.mn-wrap {
    height: 100%;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px;
}
/* 워드마크는 브랜드 칸과 같은 장르 글꼴 — 가장 굵은 단 */
.mn-logo {
    font-family: var(--font-display); font-weight: 900;
    font-size: calc(var(--fs-xl) * 3); letter-spacing: 8px; color: var(--text-primary);
    margin-bottom: 30px;
}
.mn-logo b { color: var(--text-accent); }
/* 브랜드 칸 마크업을 그대로 들어 워드마크 그림이 크게 선다 (ADR-0883) — 위 글꼴은 대체 글만 쓴다 */
.mn-logo img { display: block; height: 120px; }
/* 두 버튼은 같은 폭 — 글이 길면(영어) 같이 는다 */
.mn-btn { min-width: 15em; }
.mn-save { margin-top: 2px; text-align: center; font-size: var(--fs-xs); color: var(--text-muted); line-height: 1.5; }
.mn-save small { display: block; font-size: var(--fs-xs); }
.mn-save.down { color: var(--color-error); }

/* 첫 그리기 전의 셸 — 빈 브랜드 · 상단바 · 내비가 비치지 않게 숨긴다. 첫 `renderShell` 이 걷는다 (index.html · ADR-0349 · ADR-0633) */
#app.booting > .brand,
#app.booting > .topbar,
#app.booting > .nav { display: none; }

.ng-wrap {
    max-width: 1060px; margin: 0 auto;
    /* 위 81 = 옛 24 + 걷은 제목(「첫 파티」)이 차지하던 57 — 제목을 걷어도 카드는 제자리에 선다 (2026-10-16 사용자 지시) */
    padding: 81px 0 24px;
}
.ng-title { text-align: center; margin-bottom: 19px; }
.ng-title h1 {
    font-size: var(--fs-xl); font-weight: normal; letter-spacing: 2px;
    color: var(--text-primary); margin-bottom: 6px;
}
.ng-title p { font-size: var(--fs-sm); }

/* 세 장은 같은 무게로 놓인다 — 하나를 크게 하면 그쪽이 정답처럼 읽힌다 */
.ng-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
/* 시작 화면의 후보 카드는 **90%** 로 보인다 [2026-09-14 사용자 지시 · src/ui/README.md 크기 정책].
   `.ng-wrap` 은 게임 밖 화면이라 메인 배율(`.main { zoom: .9 }`)을 안 타서, 같은 카드가 선술집보다 한 단 크게 보였다.
   **줄 하나에만 건다** — 제목 · 이어하기 · 버튼은 그대로다. `max-width` 는 zoom 안의 설계 폭이라 보이는 폭은 954 이고,
   카드 설계 폭(343)이 안 바뀌어 초상 `44cqw` · 글자 · 막대가 **한 비율로** 준다. 자원 탭의 `.ng-row` 는 `.ng-wrap` 밖이라 안 걸리고,
   선술집 명단(`.tv-cands`)은 같은 폭 상한으로 이 크기에 맞춘다 */
.ng-wrap > .ng-row { zoom: .9; max-width: 1060px; margin: 0 auto; }

.ng-card {
    background: rgba(var(--surface-0-rgb), var(--panel-alpha));
    border: 1px solid var(--border-primary);
    border-top: 3px solid var(--border-secondary);
    padding: 14px 16px 13px;
    /* 초상이 **카드 폭**을 보게 하는 자리 (2026-09-10 · ADR-0076). 아래 .ng-head .hero-face 의 `cqw` 가 이걸 쓴다.
       `contain: layout` 이 함께 걸리지만 카드 안에 카드 밖을 기준으로 눕는 것이 없어 안전하다 —
       초상 위 겹침(.hero-face img)은 초상 안쪽이고, 툴팁(#tooltip)은 `#stage` 바로 아래라 카드의 자손이 아니다 */
    container-type: inline-size;
}
/* 이름 블록은 초상 **윗변에 맞추고**, 고유 스킬 칸은 **아랫변에 붙인다** (SCREEN_DESIGN §3 2026-09-03).
   가운데 정렬이면 이름이 내려앉아 스킬 칸이 설 자리가 없고, 스킬 칸을 글 흐름에 그냥 두면
   역할 줄이 두 줄이 되는 카드(영어 「Bow / Crossbow」)에서만 칸이 내려가 세 장의 높이가 어긋난다 */
.ng-head { display: flex; align-items: stretch; gap: 11px; margin-bottom: 10px; }
/* 후보 카드의 초상은 **카드에서 가장 큰 조각**이다 (2026-08-31 사용자 지시 · SCREEN_DESIGN §3) —
   시작 화면은 그림을 처음 보는 자리이고 고르는 근거의 절반이 인상이라, 아이콘 크기로는 얼굴이 안 읽힌다.
   고정 px 이 아니라 따라 자란다(폭 정책 — src/ui/README.md).
   ⚠ 기준은 **창이 아니라 카드**다 [개정 2026-09-10 · ADR-0076] — ~~`9.5vw`~~ 는 창을 봐서, 같은 `.ng-card` 인데도
   시작 화면(`.ng-wrap` 이 1060px 에서 자른다 → 카드 343px)과 선술집(패널 전폭 → 카드 378px)에서 **초상만 같은 137px** 이었다.
   카드는 10% 넓은데 얼굴은 그대로라 「카드에서 가장 큰 조각」이 선술집에서만 풀렸다. `cqw` 는 카드 안쪽 폭의 %라
   두 화면 모두 **44%** 로 같다(시작 136px · 선술 151px). 상한 152px 은 그대로 — 넓은 창에서 무한정 크지 않는다.
   **41%** 로 줄였다 [2026-10-23 · ADR-0734] — 오른쪽 열을 넓혀 영어 칩 셋(`Normal Gluttony Warrior`)이 한 줄에 서게 한다 */
.ng-head .hero-face { width: clamp(96px, 41cqw, 152px); height: clamp(96px, 41cqw, 152px); }
.ng-id { min-width: 0; display: flex; flex-direction: column; }
/* 정체성은 **두 줄**이다 — 칩 줄(등급 + 죄종) 위, 이름 아래 [개정 2026-09-08 사용자 지시].
   ~~이름 + 칩 둘을 한 줄에~~ (2026-09-01) 는 영어에서 이름을 상시로 잘랐다: 3열 카드의 좁은 폭에
   `Gluttony` 같은 긴 칩이 함께 서면 **줄어들 수 있는 것이 이름뿐**이었다(칩은 flex-shrink:0 이라 안 줄어든다).
   이름이 제 줄을 통째로 쓰면 말줄임이 거의 안 걸리고, §5 관전 카드가 09-07 에 간 길(신원 윗줄 · 이름 아랫줄)과
   문법이 같아진다. 칩 둘이 나란히 서는 것은 그대로다 (SCREEN_DESIGN §3) */
/* 칩이 셋(등급 · 종족 → 죄종 → 직업 · ADR-0724)이라 영어는 좁은 카드에서 줄이 모자란다(`Undead Gluttony Warrior` — 도감 카드 약 27px) —
   칩을 자르지 않고 **다음 줄로 접는다**. 한국어는 한 줄에 든다.
   영웅 카드는 영어도 **한 줄**이다 [2026-10-23 · ADR-0734] — 칩 줄 안에서만 칩 여백 · 간격을 6 → 4px 로 좁히고 초상을 41% 로 줄였다
   (가장 긴 Normal · Gluttony · Warrior 145px · 열 155px). 접기는 도감 몬스터 장(초상 112px 고정)의 안전망으로 남는다 */
.ng-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 3px 4px; line-height: 1.3; }
.ng-chips .tier-chip, .ng-chips .sin-chip, .ng-chips .cls-chip, .ng-chips .base-chip { flex: 0 0 auto; padding: 0 4px; }
/* 칩 줄과 이름 사이는 **살짝 띄운다** (2026-09-08 사용자 지시) — 붙어 있으면 두 줄이 한 덩어리로 읽혀
   「무엇인가(칩) / 누구인가(이름)」가 안 갈린다. 층을 가르는 최소값이라 4px 이고 그 이상은 카드가 길어진다 */
/* 레벨은 **이름 오른쪽**이다 [2026-10-23 사용자 지시 · ADR-0727] — 글자 아랫선을 맞추고, 긴 이름은 이름만 말줄임으로 준다(`Lv.n` 은 안 준다).
   도감 몬스터 장은 `.ng-lv` 가 없어 이름 혼자 선다 */
.ng-name { line-height: 1.3; min-width: 0; margin-top: 4px; display: flex; align-items: baseline; gap: 6px; }
/* 영웅 후보 카드는 **이름 + 무기군 덩어리가 칩 줄과 스킬 칸 사이 가운데**다 [2026-10-23 사용자 「이름을 좀 더 아래로 … 너무 높아서」 · ADR-0735] —
   위 여백 `auto` 가 스킬 칸의 `margin-top: auto` 와 남는 자리를 반씩 나눈다. 4px 은 padding 으로 남겨 최소를 지킨다.
   스킬 칸이 없으면 이름이 바닥까지 내려가므로 있을 때만 · 도감 몬스터 장(`.cx-cand`)은 칩 줄 바로 아래 그대로 */
.ng-card:not(.cx-cand) .ng-id:has(> .ng-skill) > .ng-name { margin-top: auto; padding-top: 4px; }
.ng-name > b {
    display: block; min-width: 0;
    font-weight: normal; font-size: var(--fs-lg);
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.ng-lv { flex: 0 0 auto; font-size: var(--fs-sm); color: var(--text-secondary); white-space: nowrap; }
/* 무기군 줄 — **이름 줄 바로 아래에 붙는다** [2026-09-18 사용자 지시 · ADR-0156]. 역할 이름은 걷었다 [2026-10-23 · ADR-0730] —
   `역할 · 무기군` 일 땐 영어 다섯 직업 중 셋이 두 줄로 접혔다. 무기군만이면 가장 긴 `Greatsword / Spear` 도 한 줄이다.
   열이 초상보다 짧으면 머리 높이는 늘 초상이 정해 세 장이 어긋나지 않는다 */
.ng-role { font-size: var(--fs-xs); line-height: 1.35; }
/* 영어만 **이름 · 직업 · 역할 줄 간격을 좁힌다** [2026-09-18 · ADR-0160] — 스킬 그림이 49px 로 커져, 역할이 두 줄인
   카드(다섯 직업 중 셋)는 이대로면 열이 초상보다 약 12px 길다. 칩 줄 · 이름 사이 4px 는 건드리지 않는다(09-08 지시).
   한국어는 역할이 한 줄이라 그림을 키워도 빈 자리가 남는다 — 좁히지 않는다 */
html[lang="en"] .ng-name { line-height: 1.1; }
html[lang="en"] .ng-role { line-height: 1.2; }
/* 고유 스킬 칸 — 네모 아이콘 + 이름. 능력치 막대 위·정체성 줄 아래다 (§3). 쿨은 툴팁이 들고 출처 글자(「영웅」)는 없다 (ADR-0163 · 0159).
   **칸은 나중에 들어올 스킬 이미지의 자리다** (2026-09-03 사용자 지시) — 위 여백 0 (ADR-0159).
   **그림 38px = 두 줄로 접힌 스킬 이름의 높이**(줄 상자 18.75px × 2) [2026-09-18 · ADR-0163] — 가장 긴 이름(프레이어 오브
   리제너레이션)에서도 글이 그림보다 크지 않다. 칸 높이는 글이 아니라 그림이 정한다.
   **그림 아랫변 = 초상 아랫변** [ADR-0156] — `margin-top: auto` 가 칸을 열 바닥으로 밀고, 열은 초상 높이로
   늘어난다(`.ng-head` stretch). 아래 정렬이라 글이 그림보다 커져도 그림이 선을 지킨다 */
.ng-skill { display: flex; align-items: flex-end; gap: 8px; margin-top: auto; min-width: 0; }
.ng-skill .ico {
    flex: 0 0 auto; width: 38px; height: 38px; display: grid; place-items: center; position: relative;   /* 고유 스킬 `Lv.n` 의 기준 칸 (ADR-0701) */
    background: var(--bg-secondary); border: 1px solid var(--border-dark); border-radius: 3px;
    font-size: var(--fs-xl); line-height: 1;
    overflow: hidden;   /* 그림이 들어오면 칸을 넘지 않는다 */
}
/* 그림이 칸을 통째로 채운다 — 2026-09-03 부터 실제로 그림이 들어온다 (SCREEN_DESIGN §2 · app.js:skillImg) */
.ng-skill .ico img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
.ng-skill .txt { min-width: 0; line-height: 1.25; }
.ng-skill b { font-weight: normal; font-size: var(--fs-sm); word-break: keep-all; }

.ng-line {
    display: flex; justify-content: space-between; align-items: baseline; gap: 8px;
    font-size: var(--fs-sm); color: var(--text-secondary); padding: 3px 0;
}
.ng-line b { font-weight: normal; color: var(--text-primary); }
.ng-line.sep { border-top: 1px solid var(--border-dark); margin-top: 9px; padding-top: 8px; }
.ng-card .attr-list { margin-top: 9px; padding-top: 9px; border-top: 1px solid var(--border-dark); }

/* 능력치 범례 — 시작 화면 첫 카드 왼쪽 빈자리 (SCREEN_DESIGN §3 · ADR-0943 · app.js:renderStart).
   첫 카드의 능력치 목록 안에 절대 위치로 서서 **그 목록의 높이를 일곱 등분**한다 — 목록의 줄은 모양이 같아 높이가 같으므로
   범례 줄이 막대 줄과 같은 높이에 선다(좌표를 재지 않는다). 위 여백 · 줄 틈은 목록의 것을 물려받는다.
   가로는 목록 왼쪽 변에서 카드 안쪽 여백 16 + 테두리 1 + 틈 28 만큼 바깥 — 머리의 아랫선이 목록 윗선과 같은 높이다 */
.attr-list:has(> .ng-legend) { position: relative; }
.ng-legend {
    position: absolute; top: 0; bottom: 0; right: calc(100% + 45px);
    padding-top: inherit; row-gap: inherit;
    display: grid; grid-template-columns: auto auto; grid-template-rows: repeat(7, 1fr);
    column-gap: 10px; align-items: center; white-space: nowrap;
}
.ng-lg-h {
    position: absolute; bottom: 100%; left: 0; right: 0;
    font-size: var(--fs-sm); color: var(--text-primary);
    padding-bottom: 5px; border-bottom: 1px solid var(--border-dark);
}
.ng-lg-r { display: contents; }
.ng-lg-r b { font-size: var(--fs-sm); color: var(--text-primary); text-align: right; }
.ng-lg-r span { font-size: var(--fs-sm); color: var(--text-muted); }

/* 카드 연장 칸 — 그 영웅의 직업 · 죄종 한 문장 (SCREEN_DESIGN §3 · ADR-0675 · app.js:startLines). 새 게임 카드만 든다.
   합계 줄 아래 구분선 뒤 — 머리와 능력치 막대 사이에 안 끼어 막대 읽기를 안 끊는다.
   이름은 **칩**이다 — 카드 머리의 등급 · 죄종 칩과 같은 규격(`.sin-chip`) · 그 직업 · 죄종 색 테두리 [2026-10-21 사용자 지적].
   맨 글자 이름은 문장의 주어로 붙어 읽혔다(「전사 적에게 붙어 …」). 칩 열은 두 칩 중 넓은 쪽에 맞추고 둘 다 그 폭으로 늘린다 —
   두 칩의 폭이 같고 두 문장이 같은 선에서 시작한다 */
.ng-ext {
    display: grid; grid-template-columns: max-content minmax(0, 1fr); align-items: baseline;
    column-gap: 10px; row-gap: 6px; font-size: var(--fs-sm); line-height: 1.4;
    margin-top: 9px; padding-top: 10px; border-top: 1px solid var(--border-dark);
}
.ng-tag {
    justify-self: stretch; text-align: center;
    font-size: var(--fs-xs); padding: 0 6px; line-height: 16px;
    border: 1px solid currentColor; border-radius: 2px;
    color: var(--text-secondary); white-space: nowrap;
}
.ng-tx { color: var(--text-secondary); word-break: keep-all; }

.ng-actions {
    display: flex; align-items: center; justify-content: center; gap: 10px;
    margin-top: 19px;
}
/* 뒤로가기 — 파티 고르기 화면 왼쪽 위 · 아이콘 + 글 (SCREEN_DESIGN §3 · ADR-0643 · app.js:renderStart).
   상자 없는 글 버튼이다 — 되돌릴 수 있는 이동이라 아래 버튼 줄과 무게를 가른다 · 올리면 상자가 비친다.
   자리는 메인 안쪽 여백(20px)의 왼쪽 위 — 게임 밖 화면(pregame)의 메인만 기준 칸이 된다 */
#app.pregame > .main { position: relative; }
.ng-back {
    position: absolute; left: 20px; top: 16px;
    display: inline-flex; align-items: center; gap: 6px;
    padding: 6px 12px 6px 8px; background: transparent; border: 1px solid transparent; border-radius: 3px;
    color: var(--text-secondary); font: inherit; font-size: var(--fs-md); cursor: pointer;
}
.ng-back:hover { color: var(--text-primary); border-color: var(--border-primary); background: rgba(var(--surface-0-rgb), var(--panel-alpha)); }
.ng-back svg { flex: 0 0 auto; }
.ng-count { font-size: var(--fs-xs); margin-right: 4px; }
.btn.lg { padding: 10px 26px; font-size: var(--fs-md); }

/* ───────── 프롤로그 (2026-09-03 · SCREEN_DESIGN §3-1) ─────────
   시작 화면과 같은 pregame 셸을 쓴다. 읽는 화면이라 폭을 좁히고 줄 사이를 넓힌다.
   본문의 줄바꿈은 i18n 문자열이 들고 있고 pre-line 이 편다 — 화면이 <br> 을 심지 않는다 */

.pro-wrap {
    max-width: 660px; height: 100%; margin: 0 auto;
    /* 아래 여백이 **버튼의 고정 자리**를 정한다 [2026-09-24 사용자 지시] — 키우면 글 칸이 줄고 버튼 · 쪽 번호가 올라간다 */
    padding: 16px 16px 96px;
    display: flex; flex-direction: column;
}
/* 맨 윗줄 — **지금 어디인가** 하나를 든다 (§3-1). 프롤로그 씬은 제목이 서고,
   Chapter 1 씬은 그 자리를 챕터 이름이 가져간다. 한 자리가 갈아입으므로 암전 뒤에 장이 넘어간 것이 읽힌다 */
.pro-top {
    margin-bottom: 10px; padding-bottom: 10px; text-align: center;
    border-bottom: 1px solid var(--border-dark);
    font-size: 16px; letter-spacing: 3px; color: var(--text-muted);
}
/* 쪽 번호 — 글 끝과 버튼 사이 [2026-09-24 사용자 지시]. 프롤로그 · 챕터가 제 묶음 안에서 센다 */
.pro-step {
    margin-top: 24px;
    font-size: var(--fs-md); letter-spacing: 3px; text-align: center;
}
.pro-h {
    font-size: var(--fs-lg); font-weight: normal; letter-spacing: 4px;
    color: var(--text-accent); text-align: center;
    margin: 8px 0 16px;
}
/* 씬마다 길이가 5줄~18줄로 크게 달라 **본문 칸이 남는 높이를 먹고 스스로 넘친다** —
   그래야 버튼이 어느 씬에서도 화면 안에 선다.
   **위 정렬이다** [2026-09-24 사용자 지시] — 가운데였을 때는 씬마다 첫 줄이 다른 높이에서 시작해
   넘길 때마다 글이 위아래로 튀었다. 위에 붙이면 **모든 씬의 첫 줄이 같은 자리**에서 시작한다.
   칸은 남는 높이를 **다 먹는다** — 그래서 쪽 번호와 버튼이 글 길이와 상관없이 **어느 씬에서도 같은 자리**에 선다.
   그 자리를 올리는 손잡이는 `.pro-wrap` 의 아래 여백 하나다.
   ⚠ 씬 3 · 4 · 5 는 칸을 넘어 아랫줄이 숨는다 — 간격을 좁혀 다 넣은 판을 사용자가 「너무 좁다」로 되돌린 상태다.
   나중에 다시 손본다 (2026-10-16 · ADR-0647 · SCREEN_DESIGN §3-1) */
.pro-body {
    flex: 1 1 auto; min-height: 0; overflow-y: auto;
    display: grid; align-content: start;
    white-space: pre-line;
    font-size: var(--fs-md); line-height: 1.85;
    color: var(--text-secondary); text-align: center;
}
/* 바알이 처음 입을 여는 줄 — 본문과 층이 다르다 */
.pro-q {
    margin-top: 16px; text-align: center;
    font-size: var(--fs-lg); font-style: italic; color: var(--text-primary);
}
/* 챕터가 열리는 암전 (§3-1) — 씬 4 가 어둠에 묻히고 Chapter 1 이 그 어둠에서 떠오른다.
   **`pro-out` 의 길이는 `app.js:PRO_FADE_MS` 와 같은 값이어야 한다** — 그 타이머가 끝나야 다음 씬을 그린다.
   떠오르는 쪽은 더 길게 — 꺼지는 것보다 켜지는 것이 느려야 장이 열리는 것으로 읽힌다 */
.pro-wrap.pro-out { animation: pro-out .45s ease-in forwards; }
.pro-wrap.pro-in  { animation: pro-in .75s ease-out; }
/* 어두워지는 동안은 안 눌린다 — 두 번 눌러 암전이 겹치지 않게 */
.pro-out .pro-actions { pointer-events: none; }
@keyframes pro-out { to   { opacity: 0; filter: brightness(0); } }
@keyframes pro-in  { from { opacity: 0; filter: brightness(0); } }
@media (prefers-reduced-motion: reduce) {
    .pro-wrap.pro-out, .pro-wrap.pro-in { animation: none; }
}
/* 버튼 셋은 **폭이 같다** [2026-09-24 사용자 지시] — 열 셋이 `1fr` 이라 가장 긴 라벨의 폭을 셋이 나눠 갖는다.
   줄은 가운데 서고 제 내용만큼만 넓다(`align-self`) — 고정 px 이 없어 영어에서도 안 깨진다 */
.pro-actions {
    align-self: center;
    display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: 10px;
    margin-top: 16px;
}
.pro-actions .btn { min-width: 96px; }

/* ───────── 초반 루프 실동작 (2026-08-25) ───────── */

/* 시작 화면 — 이어하기 */
.ng-continue {
    max-width: 760px; margin: 0 auto 16px;
    display: flex; align-items: center; justify-content: space-between; gap: 12px;
    border: 1px solid var(--border-secondary); background: rgba(var(--surface-0-rgb), var(--panel-alpha)); padding: 10px 14px;
}
.ng-continue .l { font-size: var(--fs-sm); color: var(--text-secondary); }
.ng-continue .l small { display: block; color: var(--text-muted); font-size: var(--fs-xs); }
.btn.danger { background: var(--danger-bg); border-color: var(--danger-line); color: var(--danger-fg); }
.btn.danger:hover { background: var(--danger-bg-hover); border-color: var(--color-error); }

/* 편성 — 누르는 줄 */
.party-slot.click { cursor: pointer; }
.party-slot.click:hover { border-color: var(--border-highlight); }
.party-slot .b-toggle { margin-left: auto; }

/* 반복 토글 */
.btn.toggle.on { background: var(--toggle-bg); border-color: var(--toggle-line); color: var(--toggle-fg); }

/* 부재중 정산 배너 */
/* 재접속 알림 — 반복 원정은 게임이 켜져 있는 동안만 (08-25). 꺼진 사이의 런은 마무리됐다는 배너 */
.notice-box {
    border: 1px solid var(--note-line); background: var(--note-bg); padding: 10px 12px; margin-bottom: 14px;
    display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
}
.notice-box .t { font-size: var(--fs-xs); color: var(--color-info); letter-spacing: 1px; }
.notice-box .b { font-size: var(--fs-sm); flex: 1; }
/* 원정 탭 맨 위에 **떠서** 선다 — 높이 0 의 자리에 알림을 띄워 아래 난이도 줄 · 챕터 탭 · 목록이 안 밀린다 · 그림자로 떠 보인다 (§4-1 · ADR-0881) */
.notice-float { position: relative; height: 0; z-index: 5; }
.notice-float > .notice-box { position: absolute; left: 0; right: 0; top: 0; margin-bottom: 0; box-shadow: 0 6px 16px rgba(0, 0, 0, .7); }

/* 리포트 — 패배·철수 */
.report-head .verdict.lose { color: var(--color-error); }
.report-head .verdict.retreat { color: var(--color-warning); }

/* 스테이지 띠 [2026-10-18 · SCREEN_DESIGN §4-2 「스테이지 띠」 · ADR-0663] — 런이 처음부터 보일 때 한 번, 아레나 가운데를 붓 자국 띠가
   왼쪽에서 펼쳐지며 들어와 머물다 오른쪽으로 빠져나간다. 띠 = 붓 한 획 그림을 **모양(mask)으로만** 쓰고 그 챕터의 죄종 색(`--si-sin`)을
   어둡게 섞어 칠한다 · 그림을 못 읽으면 곧은 띠(`.si-plain`). 덮개일 뿐이라 누름을 안 막는다 · 길이 `--si-ms` 는 배속을 탄 값(battle.js:stageIntro) */
.arena > .stage-intro {   /* `.arena > *` (z 1 · relative) 를 이기는 자리 — 카드 · 이펙트 위 · 버프 창(39) 아래 */
    position: absolute; left: 0; right: 0; top: 50%; height: 0; z-index: 20; pointer-events: none;
    animation: si-life var(--si-ms, 2000ms) linear forwards;   /* 끝나면 스스로 걷힌다(animationend) */
}
.stage-intro .si-band {
    position: absolute; left: 2%; right: 2%; top: 0; height: 124px;
    background: linear-gradient(90deg,
        color-mix(in srgb, var(--si-sin) 50%, #070505) 0%,
        color-mix(in srgb, var(--si-sin) 36%, #070505) 55%,
        color-mix(in srgb, var(--si-sin) 26%, #070505) 100%);
    -webkit-mask: url('../assets/art/fx/ui/stage_banner.webp') center / 100% 100% no-repeat;
            mask: url('../assets/art/fx/ui/stage_banner.webp') center / 100% 100% no-repeat;
    animation: si-band var(--si-ms, 2000ms) forwards;
}
.stage-intro.si-plain .si-band { -webkit-mask: none; mask: none; height: 88px; }
.stage-intro .si-text {
    position: absolute; left: 0; right: 0; top: 0; text-align: center; white-space: nowrap;
    color: #fff; text-shadow: 0 2px 6px rgba(0, 0, 0, .85);
    animation: si-text var(--si-ms, 2000ms) forwards;
}
.stage-intro .si-sub { font-size: var(--fs-md); font-weight: 600; letter-spacing: .08em; color: rgba(255, 255, 255, .9); }
.stage-intro .si-sub span + span::before { content: '·'; margin: 0 .55em; }
.stage-intro .si-diff { color: var(--color-warning); font-weight: 700; }
.stage-intro .si-name { font-size: 32px; font-weight: 800; letter-spacing: .04em; line-height: 1.15; margin-top: 2px; }
@keyframes si-life { from { opacity: 1; } to { opacity: 1; } }
/* 띠 — 왼쪽 끝부터 드러나며 밀려 들어온다(빠르게) → 머문다 → 오른쪽으로 쓸려 나간다(점점 빠르게) */
@keyframes si-band {
    0%   { clip-path: inset(0 100% 0 0); transform: translate(-8%, -50%); animation-timing-function: cubic-bezier(.12, .8, .3, 1); }
    20%  { clip-path: inset(0 0 0 0);    transform: translate(0, -50%); }
    76%  { clip-path: inset(0 0 0 0);    transform: translate(0, -50%); animation-timing-function: cubic-bezier(.65, 0, .9, .4); }
    100% { clip-path: inset(0 0 0 100%); transform: translate(8%, -50%); }
}
/* 글 — 띠가 반쯤 펼쳐진 뒤 왼쪽에서 미끄러져 들어오고, 띠보다 한발 먼저 오른쪽으로 사라진다 */
@keyframes si-text {
    0%, 10% { opacity: 0; transform: translate(-48px, -50%); animation-timing-function: cubic-bezier(.15, .8, .3, 1); }
    28%  { opacity: 1; transform: translate(0, -50%); }
    72%  { opacity: 1; transform: translate(0, -50%); animation-timing-function: cubic-bezier(.6, 0, .9, .4); }
    90%, 100% { opacity: 0; transform: translate(48px, -50%); }
}

/* 전투 결과 띠 — 아레나 위에 뜬다 */
.arena { position: relative; }
.battle-result {
    display: none; position: absolute; left: 50%; bottom: 12px; transform: translateX(-50%);
    z-index: 3; align-items: center; gap: 12px;
    /* 바닥은 불투명하다 (ADR-0212) — 2·1 진형이면 뒷줄 카드 아래 창 뱃지가 이 자리까지 내려온다. 층은 띠가 위라도
       바닥이 비치면 아래 아이콘이 글자와 겹쳐 보인다. 투명도 손잡이(--panel-alpha-soft)는 다른 판도 쓰므로 안 건드린다 */
    background: var(--bg-secondary); border: 1px solid var(--border-secondary); padding: 8px 14px;
    /* **한 줄로 선다** [2026-09-29 · ADR-0430] — 세기가 다음 칸 이름을 들어 길어졌다(「Again in 3s — Ch2-4 Threshold of the Abyss II」).
       `left: 50%` 인 절대 위치 상자는 폭이 아레나의 절반에서 접혀 나눔 배치에서 글과 버튼이 두 줄로 꺾였다 — 폭을 글에 맡기고 아레나 폭에서만 자른다 */
    width: max-content; max-width: calc(100% - 24px); white-space: nowrap;
}
.battle-result.show { display: flex; }
.battle-result .verdict { font-size: var(--fs-lg); letter-spacing: 1px; flex: 0 0 auto; }
.battle-result .b-next { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.battle-result .btn { flex: 0 0 auto; }
/* 신단 [2026-09-29 · SCREEN_DESIGN §4-2 「신단」 · ADR-0445] — 그림 + 이름 칩 하나를 헤드 · 결과 띠 · 리포트가 같이 쓴다 · 올리면 효과(title) */
.shrine-chip { display: inline-flex; align-items: center; gap: 4px; flex: 0 0 auto; white-space: nowrap; }
.shrine-chip img { width: 24px; height: 24px; object-fit: contain; }
.battle-result .b-shrine { display: inline-flex; align-items: center; gap: 6px; flex: 0 1 auto; min-width: 0; overflow: hidden; }
.bh-top .shrine-chip { margin-left: 8px; }
/* 신단 카드 [2026-09-29 사용자 지시 · ADR-0449] — 이긴 칸 뒤 적 진영에 몬스터 카드와 같은 틀로 선다. 윗변 · 효과 줄 = 이로운 창 칩과 같은 초록(적의 빨강이 아니다) */
.unit.shrine { border-top-color: var(--color-success); }
/* 효과 줄은 접힌다 — 오른쪽 열이 좁아 영어(「Cooldown Reduction 15%」)가 한 줄에 안 든다 · 남는 세로는 이름 위에 있다(열이 바닥 정렬) */
.shrine-fx { font-size: var(--fs-sm); line-height: 1.25; color: var(--color-success); text-align: right; }
/* 칸 그림 = 죄종 아이콘(ADR-0455) — 스킬 아이콘과 같은 규격이지만 획이 굵어 칸을 꽉 채우면 답답하다 → 칸 가운데에 작게 [2026-09-30 사용자 지시] */
.unit.shrine .cd-slot .cd-g { display: flex; align-items: center; justify-content: center; }
.unit.shrine .cd-slot .cd-g img { width: 72%; height: 72%; }
.pop.miss { color: var(--text-muted); }

/* 분해함이 떠 있는 동안 [2026-09-21 · ADR-0184 · 함 2026-10-20 ADR-0673] — 클릭이 **함에 올리기**가 되므로 칸 모양을 바꾼다.
   파괴가 아니라 고르기라 위험 색을 안 쓴다 — 실제 파괴는 [분해하기] 한 번이 한다. 함에 오른 칸은 흐린 빈 칸(`.gone`)이고 누르면 돌아온다 */
.inv-cells.picking .inv-cell.filled { border-style: dashed; cursor: pointer; }
.inv-cells.picking .inv-cell.cube-out { cursor: pointer; }
.inv-cell { position: relative; }
/* 페이퍼돌 착용 칸도 같은 자리 · 같은 모양이다 (ADR-0169) */
.inv-up, .pd-up { position: absolute; top: 1px; right: 2px; font-size: var(--fs-xs); color: var(--color-warning); }
/* 오른쪽 아래 = **아이템 레벨** [2026-09-18 · ADR-0168] — 오른쪽 위 `+n`(유저가 쌓은 것)과 대각으로 마주 본다.
   페이퍼돌 착용 칸도 같은 배지 둘(`+n` · `Lv.n`)을 단다 — ADR-0122 의 「글자 없음」을 그만큼 대체한다(ADR-0168 · 0169).
   아이콘이 칸 가운데라 그림이 모서리까지 번진다 — 글자를 **검은 테두리로 둘러** 그림 위에서도 읽게 한다.
   칸 배경색 그림자로는 모자랐다: 밝은 그림 위에서 글자가 묻혔다(2026-09-18 실측).
   **스킬 레벨 `.sk-lv` 도 같은 규칙**이다 — 스킬 그림 오른쪽 아래 (설명창 · 액티브 줄 · 전직 판 · 도서관 · ADR-0576) · **연구소 트리 노드 `.dp-lv-tag` 도**(ADR-0696 — 자리만 원 모서리로 옮긴다) */
.inv-lv, .pd-lv, .sk-lv, .dp-lv-tag {
    position: absolute; right: 3px; bottom: 2px;
    font-size: var(--fs-2xs); line-height: 1; color: var(--text-secondary);
    text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000;
    pointer-events: none;
}
/* 장착 대상이 못 끼는 장비(요구 레벨 미달 · R215) — 글자 · 자리는 그대로 색만 (ADR-0525) */
.inv-lv.no { color: var(--color-error); }
/* 왼쪽 두 모서리 [2026-09-21] — 위 = 고른 표시(ADR-0184) · 아래 = 자물쇠(ADR-0185).
   오른쪽 둘(`+n` · `Lv.n`)과 같은 문법으로 글자를 검은 테두리로 둘러 그림 위에서도 읽게 한다 */
.inv-check, .inv-lock {
    position: absolute; left: 2px;
    font-size: var(--fs-2xs); line-height: 1;
    text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000;
    pointer-events: none;
}
.inv-check { top: 1px; font-size: var(--fs-xs); color: var(--color-warning); font-weight: 700; }
.inv-lock { bottom: 2px; }
/* 스킬 도안 칸 배지 「도안」 — 리포트 획득 격자 · 상단 도안 칸 (§4-3 · §8-3 · ADR-0680 — ~~「책」~~ ADR-0420) — 체크 배지 자리 · 색은 정보색 */
.inv-check.bp-tag { color: var(--info-fg); font-size: var(--fs-2xs); }
.book-cell .inv-icon img { image-rendering: var(--face-render); }
/* 우편함 창 [ADR-0748] — 우편 한 통 = 카드 한 장(첨부 칸 · 이름 + 출처 · 받을 부대 + [받기]) · 카드 자리는 `--mail-cols` 줄 × `--mail-rows` 단이 늘 깔리고
   (`app.js:MAIL_SLOTS` · `MAIL_COLS` · ADR-0743) 넘치면 판 안에서 스크롤 · 카드 높이는 `--mail-h` 하나가 정한다 · 맨 아래 띠 = 개수 · [모두 받기]
   한 줄에 카드 한 장이라 판 폭은 카드 한 장 몫이다 (ADR-0989) */
.mail-modal { width: min(560px, 94%); }
.mail-body { display: flex; flex-direction: column; gap: 12px; }
.mail-grid {
    --mail-h: 66px; display: grid; gap: 8px;
    grid-template-columns: repeat(var(--mail-cols), minmax(0, 1fr)); grid-auto-rows: var(--mail-h);
    max-height: calc(var(--mail-rows) * (var(--mail-h) + 8px) - 8px); overflow-y: auto;
}
/* 카드 — 왼쪽 굵은 띠는 보상 색(경고색) · 인벤토리 칸과 같은 바탕 */
.mail-card {
    display: grid; grid-template-columns: 48px minmax(0, 1fr) auto; align-items: center; gap: 12px;
    padding: 0 10px 0 9px; background: var(--bg-tertiary);
    border: 1px solid var(--border-primary); border-left: 3px solid var(--color-warning);
}
.mail-card:hover { background: var(--surface-5); }
.mail-card.empty { display: flex; align-items: center; justify-content: center; background: transparent; border: 1px dashed var(--border-dark); }
.mail-card.empty img { width: 26px; height: 26px; object-fit: contain; opacity: .12; image-rendering: var(--face-render); }
.mail-att { width: 48px; height: 48px; box-sizing: border-box; cursor: default; }
.mail-att.filled:hover { background: var(--bg-tertiary); }
.mail-info { min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.mail-title, .mail-from { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mail-title { font-weight: bold; color: var(--text-primary); }
.mail-from { font-size: var(--fs-xs); color: var(--text-muted); }
.mail-side { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.mail-to { font-size: var(--fs-2xs); color: var(--text-secondary); }
.mail-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 12px; border-top: 1px solid var(--border-dark); }
.mail-count { font-size: var(--fs-sm); color: var(--text-muted); }
/* ───────── 창 레이어 (SCREEN_DESIGN §2 · §7) ─────────
   탭 위에 겹쳐 뜨는 판 하나. 툴팁(z-index 50)보다 아래에 둔다 — 창 안의 스킬 칸에도 툴팁이 떠야 한다.
   판은 자기 내용 폭을 쓰되 화면을 넘지 않는다(고정 px 금지 · ui/README 폭 정책). 세로가 모자라면 판 안에서만 스크롤한다 */
.modal-layer {
    position: fixed; inset: 0; z-index: 40;
    display: flex; align-items: center; justify-content: center; padding: 20px;
    background: rgba(var(--veil-rgb), .72);
}
/* ⚠ `display:flex` 는 브라우저 기본 `[hidden]{display:none}` 을 **이긴다** — 이 한 줄이 없으면 창이 닫혀 있어도
   어두운 판이 화면을 계속 덮는다. 재생기가 `hidden` 으로 여닫는 자리(.battle-log-wrap 등)와 같은 함정이다 */
.modal-layer[hidden] { display: none; }
.modal-box {
    display: flex; flex-direction: column; gap: 10px;
    max-width: 100%; max-height: 100%; overflow: auto;
    /* 14/16 → 12/14 [2026-09-09] — 스킬 창이 세로 예산 700 에서 몇 px 넘쳐 스크롤이 생겼다. 창 공통 규격이다 */
    padding: 12px 14px 14px;
    background: var(--bg-secondary); border: 1px solid var(--border-highlight);
    box-shadow: 0 12px 40px -8px #000;
}
/* 창 머리 — 왼쪽 제목 / 오른쪽 닫기. 닫는 길 셋 중 **눈에 보이는** 하나다 */
.modal-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.modal-head h2 { margin: 0; }
/* 이름 하나뿐인 창 머리 [2026-10-24 사용자 지시 「제목 크기 지금 보다 줄이고 아래에 선그어」 · §2 창 레이어 · ADR-0744] —
   이름 = 패널 제목(`.panel > h2`)과 같은 크기 · 머리 아래 판 전폭 선(출정 창 머리 선과 같은 색 · 닫기 X 까지 한 줄 — ADR-0288).
   머리를 갈아 끼우는 창(`head` — 출정 · 자동 분해 · 미니게임 · 연구소 등록)은 제 규칙을 든다 */
.modal-head.plain { padding-bottom: 8px; border-bottom: 1px solid var(--border-primary); }
.modal-head.plain h2 { font-size: var(--fs-md); }
/* 닫기 = **정사각 X** (2026-09-01 사용자 지시). 창이 여럿이 돼도 **모양도 자리도 같다** — 창마다 다르면
   닫는 법을 창마다 다시 배워야 한다. 글자가 아니라 글리프라 ko/en 에서 폭이 흔들리지 않는다(이름은 title 이 든다) */
.modal-x {
    flex: 0 0 auto; width: 28px; height: 28px; padding: 0;
    display: flex; align-items: center; justify-content: center;
    font-size: var(--fs-lg); line-height: 1;
}
/* 멈춤 창 (SCREEN_DESIGN §2-1) — 껍데기는 창 공통 그대로, 속만 여기서 */
.cl-frozen { display: flex; justify-content: center; padding: 8px 0 4px; }

/* ───────── 연구소 (SCREEN_DESIGN §8 · ADR-0678 · 짜임 ADR-0681 · 고른 칸 ADR-0674) ─────────
   왼쪽 트리(줄마다 한 행 — 줄 카드 + 영웅 칸 → 단계 노드 일자) + 오른쪽 고른 칸. **연구 하나 = 줄 하나 = 행 하나** — 줄이 늘면 행이 하나 더 선다.
   ~~줄 목록 · 단계 사다리~~(ADR-0669 · 0674) · ~~뿌리 · 줄기~~(ADR-0678)는 걷었다. 라벨이 드는 칸이라 고정 px 폭을 주지 않는다 (ui/README 폭 정책) */
/* 오른쪽 판 33%(옛 28%) — 고른 줄의 효과 표 · 하는 일 한 줄이 들 자리 (2026-10-30 사용자 「왼쪽칸 넓이를 조금만 줄이고 오른쪽칸 넓이를 조금만 더 늘리자」) */
.dp-wrap { display: grid; grid-template-columns: minmax(0, 1fr) minmax(300px, 33%); gap: 14px; }
/* 오른쪽 판의 큰 글씨(판 제목 · 소제목 · 지점 이름 · 지금 → 올린 뒤)는 왼쪽 「연구소」 판 제목과 같은 크기 — 오른쪽 판의 +2 를 안 탄다
   [2026-10-27 사용자 「오른쪽에 나오는 글씨가 너무 큰데 왼쪽에있는 연구소 크기로 줄여봐 일단 가장 큰 글씨들을」 · ADR-0924] */
.dp-wrap { --lab-title-fs: var(--fs-md); }
.dp-side > h2 { font-size: var(--lab-title-fs); }
/* 위 보기 전용 영웅 띠(ADR-0676)와의 사이 — 두 패널을 든 격자라 `.panel + .panel` 규칙이 안 걸린다 */
.hs-panel + .dp-wrap { margin-top: 14px; }
/* 트리 패널 — 머리(`h2` · 연구소 이름 · 오른쪽 작은 글씨 = 랭크 · 오프라인 최대) 아래 격자가 남는 세로를 다 받는다 */
.dp-tree { --dp-orb: 44px; --dp-link: 3px; --dp-off: var(--border-dark); --dp-on: var(--border-highlight); display: flex; flex-direction: column; min-height: 0; }
.dp-tree > h2 small { font-size: var(--fs-xs); font-weight: normal; color: var(--text-muted); }
/* 격자 — 열: 줄 카드 | 단계 노드 × n(개수는 CSV 표 — 렌더러가 `--dp-tiers` 로 준다) · 행: 줄마다 하나.
   **행 높이 = 격자 높이의 1/`--dp-fit`**(행 사이 틈을 뺀 몫) [2026-10-21 사용자 「연구 아이콘이 7개정도 들어갈 수 있도록」 · ADR-0682] — 줄 수에 안 흔들리고
   일곱 줄까지 스크롤 없이 선다 · 넘치면 격자만 세로로 스크롤한다(행은 같은 높이 그대로).
   칸 사이 가로 틈이 없다 — 선이 칸 가장자리에서 이어져야 한다. 노드는 원 하나가 칸 한가운데에 서서(아래 글 없음 · ADR-0696) **원 한가운데 = 칸 한가운데** — 선은 모두 칸 높이 50% 에 긋는다 */
.dp-tree-grid {
    --dp-fit: 7; --dp-row-gap: 4px;
    flex: 1 1 0; min-height: 0; overflow-y: auto; display: grid; column-gap: 0; row-gap: var(--dp-row-gap); align-content: start;
    padding: 4px 14px 4px 4px;   /* 고른 줄 카드의 겉 테두리(3px · 바깥 1px)가 스크롤 판 가장자리에서 안 잘린다 (ADR-0926) · 오른쪽 14 = 칸 오른쪽 끝에 붙은 마지막 원의 Lv 배지(−10) · 고른 테(5)가 안 잘린다 */
    grid-template-columns: minmax(330px, 40%) repeat(var(--dp-tiers), minmax(0, 1fr));   /* 카드 열 — 줄 그림 40 · 이름 `--fs-md` · 영웅 칸 셋(44 · 늘 최대 칸 수 — ADR-0702)이 영어 이름과 한 줄에 들도록 넓혔다 (2026-10-21) */
    grid-auto-rows: calc((100% - (var(--dp-fit) - 1) * var(--dp-row-gap)) / var(--dp-fit));
}
/* 단계 노드 — **원은 칸 오른쪽 끝에 붙는다** — 카드 → 첫 원 · 원 → 원의 빈 거리가 똑같이 「칸 폭 − 원」이다
   (2026-10-30 사용자 「왼쪽에 있는 아이콘들 거리가 동일하도록 · 지금은 맨왼쪽 메인과 거리가 가까움」 — ~~원이 칸 한가운데라 카드 → 첫 원이 반 칸~~).
   선은 칸 왼쪽 끝에서 원 한가운데까지 하나(::before · `in` — 앞 원 또는 카드와 잇는다 · 밝으면 이 노드가 열렸다) · 오른쪽 반 선(::after)은 원 뒤에 숨어 그리지 않는다 */
.dp-tree-cell {
    position: relative; min-width: 0; cursor: pointer;
    display: flex; align-items: center; justify-content: flex-end;
}
.dp-tree-cell::before, .dp-tree-cell::after { content: ''; position: absolute; top: calc(50% - var(--dp-link) / 2); width: calc(100% - var(--dp-orb) / 2); height: var(--dp-link); background: var(--dp-off); }
.dp-tree-cell::before { left: 0; }
.dp-tree-cell::after { display: none; }
.dp-tree-cell.in::before, .dp-tree-cell.out::after { background: var(--dp-on); }
.dp-tree-cell.end::after { display: none; }
.dp-tree-orb {
    position: relative; z-index: 1; width: var(--dp-orb); height: var(--dp-orb); border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    background: var(--bg-input); border: 2px solid var(--border-dark);
}
.dp-tree-orb img { width: 24px; height: 24px; object-fit: contain; }
.dp-tree-cell.open .dp-tree-orb { border-color: var(--border-highlight); background: var(--bg-card); }
.dp-tree-cell:not(.open) .dp-tree-orb img { opacity: .35; filter: grayscale(.8); }
.dp-tree-cell:hover .dp-tree-orb { border-color: var(--color-info); }
/* 고른 노드 — 원에 파란 겉 테두리(§5 「골랐다」와 같은 색) · 굵기 3px = 원정 장착 대상과 같다(§2 「고른 표시」 · ADR-0921) */
.dp-tree-cell.on .dp-tree-orb { outline: 3px solid var(--color-info); outline-offset: 2px; }
.dp-tree-orb .lock-ico { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: var(--text-muted); }
.dp-tree-orb .lock-ico svg { width: 18px; height: 18px; }
/* 레벨 배지 — 원 오른쪽 아래 모서리에 걸친다(원 안에 두면 34 원의 그림을 반쯤 가린다) · 글 모양은 `.sk-lv` 와 한 규칙 (ADR-0696) */
.dp-tree-orb .dp-lv-tag { right: -10px; bottom: -4px; z-index: 2; }
/* 연구 막대 — 원 바로 아래(원이 칸 한가운데에 남도록 띄워 둔다) · ~~위 `Lv n/최대` · 아래 값~~(ADR-0696 걷음) */
.dp-gauge.dp-tree-bar { position: absolute; left: calc(100% - var(--dp-orb) / 2); top: calc(50% + var(--dp-orb) / 2 + 5px); transform: translateX(-50%); width: min(70%, 60px); height: 3px; border: 0; }   /* 원 한가운데 아래 — 원이 칸 오른쪽 끝이다 */
/* 줄 카드 (ADR-0681) — 행의 머리 · 옛 줄 목록의 한 줄과 같은 테두리 상자(고른 줄 = 왼쪽 강조선). 위 = 줄 그림 · 이름 / 수색은 Lv · 닫힘 · 아래 = 영웅 칸(~~[미니게임]~~ 2026-10-21 숨김 · ADR-0682). 행 높이(일곱 줄 몫)에 들도록 작게 짠다.
   카드 오른쪽 가장자리가 칸 오른쪽 가장자리라 단계 1 의 왼쪽 반 선이 카드 테두리에 닿는다 */
/* 카드는 행 높이에서 위아래 6 씩만 뺀다 — 줄 하나가 한 덩어리로 읽힌다 · 행 간격(일곱 줄 몫)은 그대로
   (2026-10-21 사용자 「각 집단의 높이 상승」 → 「네모박스 약간씩만 줄이고」 · ADR-0696) */
.dp-tree-line { display: flex; align-items: stretch; min-width: 0; padding: 6px 0; }
.dp-card {
    width: 100%; display: flex; flex-direction: column; justify-content: center; padding: 6px 8px; cursor: pointer;   /* 한 줄 — 머리 줄이 영웅 칸까지 든다 (ADR-0683) · 세로 가운데 */
    background: var(--bg-card); border: 1px solid var(--border-primary); border-left: 3px solid var(--border-dark);
}
.dp-card:hover { background: var(--bg-tertiary); border-color: var(--border-secondary); }
.dp-card.on { border-left-color: var(--border-highlight); background: var(--bg-tertiary); }
/* 고른 줄(오른쪽이 등록 효과를 볼 때) — 노드 고르기와 같은 파란 겉 테두리 (ADR-0700) · 3px (ADR-0921) */
.dp-card.pick { outline: 3px solid var(--color-info); outline-offset: 1px; }
/* 고른 줄의 「등록 효과」 — 띠와 같은 영웅 카드(한 줄 셋까지 · 폭은 열이 나눠 갖는다) + 빈 칸 `+` · 아래 효과 숫자 (ADR-0700) */
.dp-side-fx { display: flex; flex-direction: column; gap: 10px; }
.dp-fx-heroes .hs-card { flex: 0 1 96px; min-width: 72px; }
.dp-fx-heroes .hs-card.empty { cursor: pointer; }
.dp-fx-heroes .hs-card.empty:hover { border-color: var(--border-highlight); color: var(--text-primary); }
/* 줄 그림 40 · 줄 이름 `--fs-md` — 행 머리로 읽히게 (2026-10-21 사용자 「채광, 채집 같은 글씨랑 아이콘 크기 더 크게」 → 「너무커 글씨 좀만 줄여」 — `--fs-lg` 에서 한 단 내렸다) */
.dp-card-h { display: flex; align-items: center; gap: 10px; min-width: 0; }
.dp-card-ico { flex: none; width: 40px; height: 40px; border-radius: 50%; object-fit: cover; }
.dp-card-ico.sq { border-radius: 2px; }   /* 수색 — 선술집 그림은 사각 그대로 (ADR-0672) */
.dp-card:not(.open) .dp-card-ico { filter: grayscale(.8); opacity: .5; }
.dp-card-n { flex: 0 1 auto; min-width: 2em; font-size: var(--fs-md); font-weight: bold; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* 잠긴 줄의 자물쇠 + 여는 조건(ADR-0959) — `--fs-xs` 에서 +2px (2026-10-30 사용자 「글씨 조금씩만 더 크게해 하나도안보여」) */
.dp-card-lv { flex: none; font-size: calc(var(--fs-xs) + 2px); color: var(--text-muted); }
/* 고른 칸이 제 패널로 선다 — 옛 「패널 안 오른쪽 열」의 왼쪽 가림선 · 들여쓰기를 걷는다 · 등록 영웅이 많으면 패널 안에서 내린다 */
.dp-wrap > .dp-side { margin-top: 0; border-left: 0; padding: 12px 16px; overflow-y: auto; }   /* `.panel + .panel` 의 위 여백도 — 트리와 나란히 선다 */
.dp-side-n i { font-style: normal; color: var(--text-muted); }
/* 산출 게이지 [2026-09-27 · §8 · 자리 2026-10-21 ADR-0678] — 노드 시간당 아래 막대 · 다음 1개까지 찬 비율. 폭은 앱 시계가 갈아 끼운다(`refreshDispatchBars`) */
.dp-gauge { display: block; width: 100%; height: 5px; background: var(--bg-input); border: 1px solid var(--border-dark); }
.dp-gauge > b { display: block; height: 100%; background: var(--color-success); }
/* 레벨 눈금 — 칸 수 = 지점 상한(`lab_node.csv:max_lv`) · 찬 칸 = 레벨 (고른 지점 머리) */
.dp-pips { display: flex; gap: 2px; }
.dp-pips i { display: block; width: 10px; height: 7px; background: var(--bg-input); border: 1px solid var(--border-dark); }
.dp-pips i.on { background: var(--color-success); border-color: var(--color-success); }

/* 고른 지점 — 오른쪽 열 · **늘어나지 않고 위에서부터** 머리 → 「다음 레벨」 → 지금 → 올린 뒤 · 걸리는 시간 → 재료 칸(건설 `.cn-mats` 그대로) + [연구] / [그만두기] → 레벨 목록 → 이 줄.
   글자는 건설 상세(`.cn-side`)처럼 한 벌 +2px — 크기 토큰을 여기서 다시 선언한다 (ADR-0674 · ADR-0684) · 섹션 사이 10 — 1600×800 에서 레벨 목록까지 스크롤 없이 (ADR-0694) */
.dp-side {
    --fs-xs: 14px; --fs-sm: 15px; --fs-md: 17px; --fs-lg: 20px;
    min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 10px;
    padding: 6px 2px 6px 20px; border-left: 1px solid var(--border-primary);
}
.dp-side-h { display: flex; align-items: center; gap: 16px; min-width: 0; }
.dp-side-orb {
    flex: none; width: 96px; height: 96px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
    background: var(--bg-card); border: 2px solid var(--border-highlight);
}
.dp-side-orb img { width: 70px; height: 70px; object-fit: contain; }
.dp-side-orb.sq { width: 120px; height: 80px; border-radius: 2px; overflow: hidden; }
.dp-side-orb.sq img { width: 100%; height: 100%; object-fit: cover; }
.dp-side-h.locked .dp-side-orb { border-color: var(--border-dark); background: var(--bg-input); }
.dp-side-h.locked .dp-side-orb img { opacity: .35; filter: grayscale(.8); }
.dp-side-t { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.dp-side-n { display: flex; gap: 6px; font-size: var(--lab-title-fs); font-weight: bold; color: var(--text-primary); }
.dp-side-y { font-size: var(--fs-sm); color: var(--text-secondary); }
.dp-side-lv { display: flex; align-items: center; gap: 8px; margin-top: 6px; font-size: var(--fs-xs); color: var(--text-secondary); }
.dp-side-next { display: flex; flex-direction: column; gap: 12px; }
.dp-side-sub { margin: 0; font-size: var(--lab-title-fs); }
.dp-side-rate { display: flex; align-items: baseline; gap: 10px; font-size: var(--lab-title-fs); }
.dp-side-rate .up { color: var(--color-success); }
.dp-side-arrow { color: var(--text-muted); }
/* 재료 칸 왼쪽 · [연구] 오른쪽 끝(바닥선) — 건설 「다음 랭크」 재료 줄과 같은 배치. 「보유/필요」 가 칸 폭을 넘으면 왼쪽으로 삐져나온다(ADR-0397) · 옆 칸과 안 겹치게 건설보다 넓게 띄운다 */
.dp-side-act { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; }
.dp-side-act .cn-mats { gap: 8px 22px; }
/* 레벨 목록 (ADR-0694) — 건설 랭크 목록(`.cn-rank`)의 글 문법: 상자 · 배지 없이 글 · 줄 사이 가는 선 · 오른 레벨 흰 글 + 초록 ✓ · 다음 레벨 옅은 붉은 바탕 · 그 뒤 흐림.
   **한 줄 높이 · 두 단**(단마다 위에서 아래로 — 행 수 `--dp-lv-rows` = 레벨 수의 절반 올림) · 줄어들지 않는다 — 「이 줄」이 길면 고른 지점 열 전체가 스크롤한다 */
.dp-lvl { flex: none; display: flex; flex-direction: column; gap: 6px; }
.dp-lvs {
    display: grid; grid-auto-flow: column; grid-template-rows: repeat(var(--dp-lv-rows, 5), auto); grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 16px;
}
.dp-lv {
    display: grid; grid-template-columns: 3em minmax(0, 1fr) auto; align-items: center; column-gap: 8px;
    padding: 1px 6px; font-size: var(--fs-xs); line-height: 1.3; border-bottom: 1px solid var(--border-dark);
}
.dp-lv.next { background: rgba(var(--accent-rgb), .07); font-weight: bold; }
.dp-lv.later { opacity: .6; }
.dp-lv-no { font-weight: bold; font-variant-numeric: tabular-nums; white-space: nowrap; color: var(--text-muted); }
.dp-lv.on .dp-lv-no, .dp-lv.next .dp-lv-no { color: var(--text-primary); }
.dp-lv-v { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text-primary); }
.dp-lv-ok { white-space: nowrap; color: var(--color-success); }
.dp-side-go { flex: none; min-width: 8em; padding: 8px 18px; }
.dp-side-end { display: flex; align-items: center; gap: 6px; font-size: var(--fs-sm); color: var(--text-muted); }
.dp-side-end .lock-ico { display: inline-flex; }
.dp-side-end .lock-ico svg { width: 1em; height: 1em; }
/* 영웅 칸 (ADR-0683 · 등록 ADR-0677) — 줄 카드 이름 오른쪽 · 얼굴 칸 = 띠 카드의 초상만 작게 · 빈 칸 `+` 는 띠의 빈 칸과 같은 점선. 많으면 카드 안에서 줄을 바꾼다 */
.dp-reg-row { flex: 1 0 auto; max-width: 100%; margin-left: auto; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 3px; }   /* 이름 오른쪽 · 카드 오른쪽 끝 — 이름이 먼저 줄어든다 (ADR-0683) */
.dp-reg-face {
    width: 44px; height: 44px; padding: 0; cursor: pointer; font: inherit;   /* 2026-10-21 사용자 「영웅 초상화 크기도 좀 크게」 → 「더키워봐」 — 24 → 32 → 44(카드 높이 안 끝 · ADR-0702) */
    background: var(--bg-input); border: 1px solid var(--border-dark);
}
.dp-reg-face:hover { border-color: var(--border-highlight); }
/* 지점 노드 · 고른 지점 머리의 그림 (ADR-0684) — 회색 단색 실루엣(`icons/lab/node/`)이라 어두운 원 위에 그대로 선다 · 원은 단계 노드와 같은 크기 */
.dp-node-orb img { width: 72%; height: 72%; }
.dp-side-orb.dp-node-orb img { width: 64px; height: 64px; }
/* 연구 중인 노드 — 원에 주황(진행 — `--color-progress`) 테두리 · 아래 진행 막대. 고른 표시(파랑 겉 테두리)와 겹쳐도 갈린다 */
.dp-tree-cell.doing .dp-tree-orb { border-color: var(--color-progress); }
.dp-gauge.res > b { background: var(--color-progress); }
/* 트리 머리의 「연구 중 …」 · 고른 지점의 진행 줄 · 다른 연구 안내 */
.dp-res-h { color: var(--color-progress); }
.dp-side-res { display: flex; align-items: center; gap: 12px; }
.dp-side-res .dp-gauge { flex: 1 1 auto; height: 8px; }
.dp-side-res .muted { flex: none; font-size: var(--fs-sm); }
/* 걸리는 시간 — 「지금 → 올린 뒤」 줄의 오른쪽 끝(아래 레벨 목록에 세로를 남긴다 · ADR-0694) */
.dp-side-time { margin-left: auto; font-size: var(--fs-sm); font-weight: normal; }
.dp-side-busy { font-size: var(--fs-sm); }
/* 「이 줄」 — 줄이 내는 것(재료 줄 = 열린 단계마다 그림 · 이름 · 시간당 + 게이지) · 등록 효과 */
.dp-side-line { display: flex; flex-direction: column; gap: 10px; }
/* 「이 줄」 목록 — 줄 사이 16 · 이름과 게이지 사이 4 (2026-10-27 사용자 「각 줄의 거리를 좀 띄워봐」) */
.dp-tiers { display: flex; flex-direction: column; gap: 16px; }
.dp-tier { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 8px; row-gap: 4px; align-items: center; font-size: var(--fs-sm); }
.dp-tier > img { grid-row: 1 / span 2; width: 28px; height: 28px; object-fit: contain; }
.dp-tier-n { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text-secondary); }
.dp-tier > b { color: var(--text-primary); }
.dp-tier > .dp-gauge { grid-column: 2 / span 2; height: 4px; }
/* 이름 | 미는 능력치 | 값 한 줄 — 고른 줄의 지금 내는 것 · 효과 표 (ADR-0971 — ~~`.dp-line-out` 한 줄 · `.dp-fx` 초록 토막 나열~~) · 0 인 효과는 흐림 */
.dp-kv { display: grid; grid-template-columns: minmax(0, 1fr) auto 72px; align-items: baseline; column-gap: 12px; font-size: var(--fs-sm); color: var(--text-secondary); }
.dp-kv-s { font-size: var(--fs-xs); color: var(--text-muted); }
.dp-kv-v { text-align: right; color: var(--text-primary); }
.dp-fx { display: flex; flex-direction: column; gap: 6px; }
/* 고른 줄 머리의 하는 일 한 줄 — 낱말 중간에서 안 끊는다 */
.dp-line-desc { font-size: var(--fs-sm); color: var(--text-primary); word-break: keep-all; }
.dp-fx .dp-kv-v { color: var(--color-success); }
.dp-kv.dim .dp-kv-n, .dp-fx .dp-kv.dim .dp-kv-v { color: var(--text-muted); }
.dp-reg-face .hero-face { width: 100%; height: 100%; border: 0; }
.dp-reg-face.empty { display: flex; align-items: center; justify-content: center; border-style: dashed; background: transparent; color: var(--text-muted); font-size: var(--fs-sm); }
/* 안 열린 칸 — 흐린 점선 칸 + 자물쇠 · 칸 수의 끝은 「등록 칸」 지점의 최대 (ADR-0702) · 누르면 그 지점을 고른다 */
.dp-reg-face.lock { opacity: .6; }
.dp-reg-face.lock svg { width: 16px; height: 16px; }
/* 영웅 띠의 잠긴 칸도 같은 그림이다 — 선술집 뒤 랭크가 여는 칸(§5 · ADR-0913) */
.dp-fx-heroes .hs-card.lock,
.hero-strip .hs-card.lock { opacity: .6; }
.dp-fx-heroes .hs-card.lock svg,
.hero-strip .hs-card.lock svg { width: 22px; height: 22px; }
/* 등록 창 — 로스터 카드가 띠와 같은 얼굴로 줄을 바꿔 가며 선다 · 이 줄의 카드는 띠의 「고른」 표시(`.hs-card.on`) 그대로 */
.modal-box.lr-modal { width: min(720px, 100%); }
.lr-grid { padding: 4px 2px 2px; }
.lr-grid .hs-card { flex: 0 0 120px; max-width: none; }
/* Resource minigames — painted scenes, native illustrated objects (2026-10-16). */
.modal-box.mg-modal { width: min(940px, 100%); padding: 16px; border-radius: 14px; border-color: var(--mg-line); background: var(--mg-ink); box-shadow: 0 24px 100px rgba(var(--shadow-rgb), .7); }
.mg-modal .modal-head { padding-bottom: 12px; margin-bottom: 0; border: 0; }
.mg-head { flex: 1; display: flex; align-items: center; justify-content: space-between; gap: 16px; min-width: 0; }
.mg-head h2 { font-size: var(--fs-md); color: var(--mg-cream); white-space: nowrap; letter-spacing: .03em; }
.mg-head .segmented { flex-wrap: wrap; }
.mg-field { --mg-accent: var(--mg-mint); position: relative; height: 540px; isolation: isolate; overflow: hidden; border-radius: 9px; border: 1px solid var(--mg-line); background: var(--mg-ink) var(--mg-scene) center / cover no-repeat; user-select: none; touch-action: none; color: var(--mg-cream); }
.mg-field.mg-gather { --mg-accent: var(--mg-sage); }
.mg-field.mg-log { --mg-accent: var(--mg-honey); }
.mg-field::before { content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none; background: linear-gradient(180deg, rgba(var(--mg-ink-rgb), .52), transparent 25%, transparent 75%, rgba(var(--mg-ink-rgb), .8)); }
.mg-field.shake { animation: fx-shake .25s; }
.mg-field button { -webkit-tap-highlight-color: transparent; }
.mg-field button:focus-visible { outline: 2px solid var(--mg-cream); outline-offset: 3px; }
.mg-cover::before { background: linear-gradient(90deg, rgba(var(--mg-ink-rgb), .42), rgba(var(--mg-ink-rgb), .72) 50%, rgba(var(--mg-ink-rgb), .42)); }
.mg-card { position: absolute; inset: 28px 16px 36px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 13px; text-align: center; }
.mg-eyebrow { color: var(--mg-accent); font-size: var(--fs-xs); letter-spacing: .2em; font-weight: 600; }
.mg-cover-art { width: 132px; height: 132px; margin: 0 0 -6px; filter: drop-shadow(0 8px 20px rgba(var(--shadow-rgb), .5)); }
.mg-cover-art svg { width: 100%; height: 100%; }
.mg-card h3 { margin: 0; color: var(--mg-cream); font-size: calc(var(--fs-xl) * 1.5); font-weight: 700; letter-spacing: -.035em; line-height: 1.25; }
.mg-sub { font-size: var(--fs-sm); line-height: 1.7; color: var(--mg-fog); max-width: 520px; }
.mg-rule-badges { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin: 2px 0 4px; font-size: var(--fs-xs); color: var(--mg-fog); }
.mg-rule-badges span { padding: 5px 10px; border: 1px solid var(--mg-line); border-radius: 20px; background: rgba(var(--mg-ink-rgb), .5); }
.mg-go.btn { display: flex; align-items: center; justify-content: space-between; gap: 36px; min-width: 180px; padding: 12px 22px; margin-top: 5px; border: 1px solid var(--mg-accent); border-radius: 5px; background: var(--mg-accent); color: var(--mg-ink); font-size: var(--fs-md); font-weight: 700; transition: transform .15s, filter .15s; }
.mg-go.btn:hover { background: var(--mg-accent); color: var(--mg-ink); filter: brightness(1.1); transform: translateY(-2px); }
.mg-reward-line { position: absolute; bottom: 16px; left: 20px; right: 20px; text-align: center; font-size: var(--fs-xs); color: var(--mg-fog); letter-spacing: .04em; }
.mg-reward-line b { color: var(--mg-cream); margin-left: 8px; }
.mg-got { display: flex; align-items: center; gap: 10px; color: var(--mg-accent); }
.mg-got img { width: 38px; height: 38px; object-fit: contain; }
.mg-got b { font-size: calc(var(--fs-xl) * 1.6); font-variant-numeric: tabular-nums; }
.mg-got span { font-size: var(--fs-md); color: var(--mg-cream); }
.mg-best { color: var(--mg-accent); font-size: var(--fs-xs); padding: 5px 14px; border: 1px solid var(--mg-line); border-radius: 20px; }
.mg-hud { position: absolute; left: 18px; right: 18px; top: 16px; z-index: 4; display: flex; align-items: center; gap: 18px; padding: 11px 16px; border: 1px solid var(--mg-line); border-radius: 7px; background: rgba(var(--mg-ink-rgb), .91); pointer-events: none; }
.mg-hud-title { display: flex; flex-direction: column; gap: 5px; min-width: 160px; }
.mg-hud-title small { font-size: var(--fs-xs); color: var(--mg-fog); }
.mg-lives { font-size: var(--fs-xs); color: var(--mg-rose); letter-spacing: .05em; }
.mg-combo { display: flex; flex-direction: column; gap: 2px; color: var(--mg-accent); text-align: center; flex: 1; }
.mg-combo b { font-size: var(--fs-lg); font-variant-numeric: tabular-nums; }
.mg-combo small { font-size: var(--fs-xs); }
.mg-items { display: flex; align-items: center; gap: 6px; }
.mg-items img { width: 28px; height: 28px; object-fit: contain; }
.mg-items b { font-size: var(--fs-xl); font-variant-numeric: tabular-nums; }
.mg-items small { color: var(--mg-fog); font-size: var(--fs-xs); }
.mg-clock { min-width: 58px; padding-left: 14px; border-left: 1px solid var(--mg-line); font-size: var(--fs-lg); font-variant-numeric: tabular-nums; text-align: right; }
.mg-time { position: absolute; top: 0; left: 0; right: 0; height: 3px; z-index: 5; background: rgba(var(--mg-ink-rgb), .8); pointer-events: none; }
.mg-time > b { display: block; height: 100%; background: var(--mg-accent); }
.mg-urgent .mg-time > b { background: var(--mg-rose); }
.mg-instruction { position: absolute; bottom: 0; left: 0; right: 0; padding: 14px 16px; z-index: 4; background: rgba(var(--mg-ink-rgb), .88); color: var(--mg-fog); text-align: center; font-size: var(--fs-xs); line-height: 1.5; pointer-events: none; }
.mg-ready { position: absolute; inset: 0; z-index: 8; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 8px; background: rgba(var(--mg-ink-rgb), .72); }
.mg-ready[hidden] { display: none; }
.mg-ready b { font-size: calc(var(--fs-xl) * 3); line-height: 1; color: var(--mg-accent); }
.mg-ready span { font-size: var(--fs-sm); letter-spacing: .15em; }
.mg-fx { position: absolute; inset: 0; z-index: 6; pointer-events: none; }
.mg-pop { position: absolute; transform: translate(-50%, -50%); font-weight: 700; font-size: var(--fs-lg); text-shadow: 0 2px 6px var(--mg-ink); white-space: nowrap; animation: mg-pop .75s ease-out forwards; }
.mg-pop.good { color: var(--mg-mint); }
.mg-pop.bad { color: var(--mg-rose); }
@keyframes mg-pop { from { opacity: 1; margin-top: 0; } to { opacity: 0; margin-top: -44px; } }
/* Mine: quiet sockets, short-lived illustrated veins; no repeated-hit UI. */
.mg-wall { position: absolute; left: 12%; right: 12%; top: 100px; bottom: 64px; display: grid; gap: 12px; }
.mg-cell { --target-color: var(--mg-mint); position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; border-radius: 12px; border: 1px solid var(--mg-line); background: rgba(var(--mg-ink-rgb), .35); cursor: crosshair; padding: 4px; color: var(--mg-fog); overflow: hidden; }
.mg-empty-mark { width: 5px; height: 5px; border-radius: 50%; background: var(--mg-line); }
.mg-cell.on { border-color: var(--target-color); background: rgba(var(--mg-ink-rgb), .73); animation: mg-appear .12s ease-out; }
.mg-cell.collected { animation: mg-collected .3s ease-out; }
@keyframes mg-collected { from { border-color: var(--mg-mint); box-shadow: inset 0 0 24px color-mix(in srgb, var(--mg-mint) 30%, transparent); } to { border-color: var(--mg-line); box-shadow: none; } }
.mg-cell.rare { --target-color: var(--mg-honey); }
.mg-cell.bad { --target-color: var(--mg-rose); }
.mg-cell.on:hover { background: color-mix(in srgb, var(--target-color) 12%, var(--mg-ink)); }
.mg-vein { display: block; width: 88px; height: 80px; max-height: calc(100% - 16px); pointer-events: none; }
.mg-vein svg { width: 100%; height: 100%; }
.mg-target-tag { font-size: var(--fs-2xs); color: var(--target-color); letter-spacing: .12em; pointer-events: none; }
.mg-left { position: absolute; left: 10%; bottom: 0; height: 3px; width: calc(var(--left, 1) * 80%); background: var(--target-color); pointer-events: none; }
@keyframes mg-appear { from { opacity: 0; transform: scale(.7); } to { opacity: 1; transform: scale(1); } }
/* Gather: one herb, hold/release gauge. The green target and white center are fixed per herb. */
.mg-pluck-stage { position: absolute; inset: 96px 16px 62px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; }
.mg-plant-halo { position: absolute; top: 8px; width: 240px; height: 240px; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, var(--mg-accent) 28%, transparent), transparent 68%); pointer-events: none; }
.mg-pluck-action { position: relative; z-index: 1; padding: 0; border: 0; background: transparent; cursor: grab; width: 180px; height: 190px; flex: 0 0 190px; }
.mg-pluck-action:disabled { cursor: default; }
.mg-plant-art { display: block; width: 100%; height: 100%; transform-origin: 50% 90%; transform: translateY(calc(var(--pull, 0) * -18px)) rotate(calc(var(--pull, 0) * -5deg)); transition: filter .12s; }
.mg-plant-art svg { width: 100%; height: 100%; filter: drop-shadow(0 6px 10px rgba(var(--shadow-rgb), .5)); pointer-events: none; }
.mg-pluck-stage.holding .mg-pluck-action { cursor: grabbing; }
.mg-pluck-stage.sweet .mg-plant-art { filter: drop-shadow(0 0 9px var(--mg-sage)); }
.mg-plant-label { z-index: 1; color: var(--mg-cream); font-size: var(--fs-xs); font-weight: 600; letter-spacing: .08em; padding: 5px 14px; border-radius: 20px; background: rgba(var(--mg-ink-rgb), .8); }
.mg-pluck-stage.bad .mg-plant-label { color: var(--mg-rose); }
.mg-pluck-stage.rare .mg-plant-label { color: var(--mg-mint); }
.mg-pull-panel { width: min(340px, 80%); padding: 14px 18px 12px; border: 1px solid var(--mg-line); border-radius: 8px; background: rgba(var(--mg-ink-rgb), .94); z-index: 1; }
.mg-pull-label { display: flex; justify-content: space-between; font-size: var(--fs-xs); color: var(--mg-fog); margin-bottom: 12px; }
.mg-pull-label b { color: var(--mg-cream); font-weight: 500; }
.sweet .mg-pull-label b { color: var(--mg-sage); }
.mg-pull-track { height: 16px; position: relative; background: var(--mg-track); border-radius: 3px; }
.mg-pull-zone, .mg-pull-perfect { position: absolute; top: 0; bottom: 0; background: var(--mg-sage); }
.mg-pull-perfect { background: var(--mg-cream); opacity: .7; }
.mg-pull-needle { position: absolute; top: -5px; bottom: -5px; width: 3px; background: var(--mg-cream); box-shadow: 0 0 0 1px var(--mg-ink); transform: translateX(-50%); border-radius: 2px; }
.mg-plant-life { margin-top: 12px; height: 2px; background: var(--mg-line); }
.mg-plant-life b { display: block; height: 100%; background: var(--mg-fog); }
.mg-pluck-stage.waiting .mg-pull-panel, .mg-pluck-stage.bad .mg-pull-track { opacity: .25; }
/* Timber: connected illustrated bark, readable incoming branches and two large controls. */
.mg-chop-area { position: absolute; inset: 88px 0 110px; cursor: pointer; }
.mg-tree { position: absolute; left: 50%; top: -3px; bottom: 0; width: 102px; transform: translateX(-50%); display: flex; flex-direction: column-reverse; }
.mg-seg { position: relative; flex: 1; min-height: 0; }
.mg-seg > svg { display: block; width: 100%; height: 100%; overflow: hidden; }
.mg-seg.gone { visibility: hidden; }
.mg-amber-knot { position: absolute; inset: 0; display: grid; place-items: center; color: var(--mg-honey); font-size: var(--fs-xl); text-shadow: 0 0 10px var(--mg-honey); }
.mg-branch { position: absolute; top: 28%; width: 128px; height: 50px; pointer-events: none; }
.mg-branch svg { width: 100%; height: 100%; }
.mg-branch.L { right: 88%; transform: scaleX(-1); }
.mg-branch.R { left: 88%; }
.mg-jack { position: absolute; bottom: -7px; height: 124px; width: 124px; pointer-events: none; }
.mg-jack svg { width: 100%; height: 100%; }
.mg-jack.L { right: calc(50% + 40px); }
.mg-jack.R { left: calc(50% + 40px); scale: -1 1; }
.mg-jack.swing { animation: mg-swing .14s ease-out; }
@keyframes mg-swing { 50% { transform: translateY(-5px) rotate(-9deg); } }
.mg-chop-control { position: absolute; bottom: 58px; display: flex; align-items: center; justify-content: center; gap: 12px; padding: 10px 20px; min-width: 170px; color: var(--mg-cream); border: 1px solid var(--mg-line); border-radius: 6px; background: rgba(var(--mg-ink-rgb), .88); cursor: pointer; }
.mg-chop-control.L { left: 12%; }.mg-chop-control.R { right: 12%; }
.mg-chop-control:hover { border-color: var(--mg-honey); background: var(--mg-ink); }
.mg-chop-control kbd { font-family: inherit; font-size: var(--fs-xs); color: var(--mg-honey); }
.mg-chop-control span { font-size: var(--fs-xs); }
@media (max-width: 650px) {
    .modal-box.mg-modal { padding: 10px; }
    .mg-head { flex-direction: column; align-items: flex-start; gap: 8px; }
    .mg-field { height: 520px; }
    .mg-card h3 { font-size: calc(var(--fs-xl) * 1.2); }
    .mg-hud { left: 8px; right: 8px; gap: 8px; padding: 10px; }
    .mg-hud-title { min-width: 100px; }.mg-items small { display: none; }
    .mg-clock { padding-left: 8px; min-width: 40px; }
    .mg-wall { left: 5%; right: 5%; gap: 8px; }
    .mg-chop-control { min-width: 0; padding: 12px; gap: 8px; }
    .mg-chop-control.L { left: 6%; }.mg-chop-control.R { right: 6%; }
    .mg-chop-control span { display: none; }
}
@media (prefers-reduced-motion: reduce) {
    .mg-cell.on, .mg-jack.swing, .mg-field.shake { animation: none; }
    .mg-pop { animation-duration: .1s; }.mg-go.btn { transition: none; }
}

/* 보관 칸 우클릭 메뉴 [2026-09-29 · SCREEN_DESIGN §6 「우클릭 메뉴」 · ADR-0451] — 옛 자원 자리 선택 창(2026-10-18 걷음)과 같은 틀 · 같은 층: 커서 자리(한 장 좌표 · `app.js:itemMenuPanel`)에 버튼 둘이
   세로로 선다. 깔개는 한 장 전체 — 바깥 클릭 · 우클릭이 닫기만 한다. 버튼 폭은 글자가 정하고 둘이 같은 폭이다(세로 줄 · `stretch`) */
.item-menu-back { position: fixed; inset: 0; z-index: 38; }
.item-menu {
    position: fixed; z-index: 39; display: flex; flex-direction: column; gap: 4px; padding: 6px;
    background: var(--bg-secondary); border: 1px solid var(--border-secondary);
    box-shadow: 0 6px 24px rgba(var(--shadow-rgb),.75);
}
.item-menu .btn { text-align: left; }
/* 표가 아직 없는 파견처(채집 · 벌목) — 두 줄 다 `—` 만 선다. 상자는 지우지 않는다 (§4-1) */

/* 미착수 탭 — 제목 옆 배지 하나로 「여긴 아직 없다」를 말한다 (SCREEN_DESIGN §1) */
.todo-badge { font-size: var(--fs-xs); color: var(--color-warning); border: 1px solid var(--color-warning); padding: 0 6px; margin-left: 6px; vertical-align: middle; }
.panel.todo .note-body { max-width: 70ch; }

/* 탐험 지도 — **세계지도 한 장 · 일곱 챕터가 구간** [개정 2026-10-08 사용자 지시 · SCREEN_DESIGN §8-4 · ADR-0537]
   지도 자체는 클릭을 안 받는다 — 누르는 것은 그 위의 **지점 아이콘**(`.ex-spot` · 2026-10-09 · ADR-0553)뿐이다
   ⚠ **`image-rendering` 을 아예 안 건다** — 스테이지·거점 배경(`--bg-render` · `#stage::before`)과 달리
      이건 신규 카툰 아트라 픽셀아트가 아니다. 보간을 꺼 두면 축소할 때 선이 끊긴다 (§5 얼굴 스타일에서 겪은 것과 같은 함정)
   **너비가 아니라 남는 세로에 맞춘다** — 그림이 3:2 라 전폭이면 세로가 넘쳐 미착수 안내를 밀어낸다.
   칸(`.ex-map-wrap` · 쌓인 판의 `.fill`)이 크기 컨테이너가 되고, 지도는 `cqw` · `cqh` 중 먼저 닿는 쪽에 맞춰 제 비(`--ex-ar` —
   `mock.js:EXPLORE_WORLD_SIZE` 를 렌더러가 넣는다)로 가장 크게 선다. 그림의 비를 칸 비(1600×800 에서 약 2.15:1)에 맞춰 그려
   칸을 가로로 가득 채운다(ADR-0540) — 칸 비가 조금 달라지는 자리(영어 미착수 안내가 길다)에서만 좌우가 조금 빈다 */
.ex-map-wrap { container-type: size; overflow: hidden; }
.ex-map {
    position: relative;
    width: min(100cqw, calc(100cqh * var(--ex-ar)));
    aspect-ratio: var(--ex-ar);
    margin: 0 auto;
    background-size: 100% 100%;
    border: 1px solid var(--border-secondary);
}
/* 안 열린 챕터 구간 — 그 구간의 땅(마스크)만 덮는 **빛 바랜 막**. 바다는 안 덮는다.
   통째 검은 막(`.lock-veil`)이 아니다 — 잠긴 땅의 생김새가 보여야 「다음에 갈 곳」이 읽힌다(처음엔 일곱 중 여섯이 잠겨 있다) */
/* 막 = 장마다 **미리 구운 조각 그림**(`mock.js:exploreLocked` · 그 장의 땅만 알파 · `scripts/build_explore_locked.py`) — 자리 · 크기(`tile` %)는 렌더러가 인라인으로 넣는다.
   **필터 · 마스크 · `backdrop-filter` 를 실행 중에 안 돌린다** [2026-10-09 실측 두 번 — `backdrop-filter` 는 아이콘이 빛날 때마다 다시 돌아 초당 10프레임 안팎 ·
   지도 전체에 거는 `filter` + 1536×714 마스크 여러 장은 화면이 모니터 크기로 커지면 탭을 열 때마다 큰 층을 다시 구워 늦게 켜졌다]. 색은 굽는 스크립트가 든다 */
.ex-veil { position: absolute; display: block; pointer-events: none; user-select: none; }
/* 자물쇠 + 왜 잠겼나 한 줄 — 구간의 자물쇠 자리(`at`)에 가운데를 맞춘다. 색 · 크기는 잠김 베일(`.lock-veil`)과 같다 */
.ex-lock {
    position: absolute; transform: translate(-50%, -50%);
    display: inline-flex; align-items: center; gap: 6px;
    padding: 4px 10px; white-space: nowrap;
    background: rgba(var(--veil-rgb), .82);
    border: 1px solid var(--border-dark);
    color: var(--text-muted); font-size: calc(var(--fs-sm) + 2px);
}
.ex-lock .lock-ico { display: inline-flex; }
.ex-lock .lock-ico svg { width: 1.1em; height: 1.1em; }
/* 지도 칸과 위 영웅 띠 사이 — `.panel + .panel` 규칙이 안 걸리는 자리다(지도 칸은 패널이 아니다) · 띠는 ADR-0556 · 아래 패널은 ADR-0558 로 걷혔다 */
.hs-panel + .ex-map-wrap { margin-top: 14px; }
/* 지점 아이콘 [2026-10-09 사용자 지시 · SCREEN_DESIGN §8-4 · ADR-0553] — 그림 원판(테두리 없음) + **땅 색 테두리**(`--ring` · 렌더러가 `EXPLORE_REGIONS[장].ring` 을 넣는다).
   테두리 = 버튼의 배경(안쪽 여백만큼 보인다) — 그래서 진행 막대 · 빛을 같은 자리에 얹는다. 바깥 검은 선은 지도의 굵은 외곽선과 같은 말투.
   크기는 **지도 폭의 %** — 지도와 같이 줄고 는다. 자리 `left` · `top` 은 아이콘 가운데(그림 크기 대비 % · `EXPLORE_REGIONS[장].spots`) */
.ex-spot {
    position: absolute; transform: translate(-50%, -50%);
    width: 4.2%; aspect-ratio: 1; padding: 0.36%;   /* 패딩의 %도 지도 폭 기준 — 테두리 굵기가 아이콘과 같이 준다 */
    border: 0; border-radius: 50%;
    background: var(--ring, #888);
    box-shadow: 0 0 0 2px #1b140e, 0 2px 6px rgba(0, 0, 0, .55);
    cursor: pointer; z-index: 2;
    transition: transform .12s ease;
    will-change: transform;   /* 아이콘마다 제 합성 층 — 빛 · 확대 · 진행 테두리가 바뀌어도 지도 · 막을 다시 칠하지 않는다 (2026-10-09 실측 — 같은 층이면 지도째 다시 칠해 렉) */
}
.ex-spot img { display: block; width: 100%; height: 100%; border-radius: 50%; pointer-events: none; }
.ex-spot:hover { transform: translate(-50%, -50%) scale(1.12); z-index: 3; }
/* 고른 지점 — 흰 겹테 */
.ex-spot.on { box-shadow: 0 0 0 2px #1b140e, 0 0 0 4px #ffffff, 0 2px 8px rgba(0, 0, 0, .6); z-index: 3; }
/* 나가 있음 — 테두리가 진행 막대: 찬 만큼 땅 색 · 나머지는 어둡게(`--p` = 0 ~ 1 · 앱 시계가 갈아 끼운다) */
.ex-spot.out { background: conic-gradient(var(--ring, #888) calc(var(--p, 0) * 1turn), rgba(20, 16, 12, .9) 0); }
/* 끝남 — 빛나는 테두리 + 오른쪽 위 「!」. 빛은 **고정 그림자를 단 겹의 투명도만** 움직인다 — 합성만으로 돈다
   (~~그림자 자체를 키프레임으로 움직이기~~ — 프레임마다 다시 칠해 렉 · 2026-10-09 실측) */
.ex-spot.done::before {
    content: ''; position: absolute; inset: 0; border-radius: 50%;
    box-shadow: 0 0 12px 4px rgba(248, 184, 48, .9);
    animation: ex-glow 1.4s ease-in-out infinite;
    will-change: opacity; pointer-events: none;
}
@keyframes ex-glow { 0%, 100% { opacity: .3; } 50% { opacity: 1; } }
.ex-spot.done.on::before { content: none; }
.ex-spot.done::after {
    content: '!'; position: absolute; top: -12%; right: -12%;
    width: 42%; aspect-ratio: 1; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    background: var(--color-warning); color: #1b140e; font-weight: 700; font-size: calc(var(--fs-sm) + 1px);
    box-shadow: 0 0 0 2px #1b140e;
}
/* 산출이 없는 지점(폐허 · 마차) — **그림만** 흐린 회색 · 테두리는 땅 색 그대로(어느 땅의 지점인지는 남는다). 누르면 지점 창이 「준비 중」을 찍는다 */
.ex-spot.pending img { filter: grayscale(1) brightness(.78); }
.ex-spot.pending:hover img { filter: grayscale(.6) brightness(.9); }

/* 지점 창 [2026-10-09 사용자 「맨 아래 카드를 없애고 지도를 키워」 · SCREEN_DESIGN §8-4 · ADR-0558] — 고른 아이콘 바로 옆에 지도 위로 뜬다.
   자리(`left`|`right` · `top`|`bottom` · 가운데면 `.mid`)는 렌더러가 아이콘 좌표로 넣는다 · 폭은 내용대로(라벨 칸이라 고정 px 이 아니다).
   **얼굴만 크고 글씨는 화면 본문 크기다** [같은 날 사용자 「영웅 얼굴 좀 더 크게」 → 「글씨는 줄여 · 다른 것들 참고하면서」 · ADR-0560] —
   틀은 자원 탭의 영웅 선택 창(`.dp-pick` — 불투명 바탕 · 굵은 머리 + 밑줄 · 같은 그림자)을 · 닫기는 창들과 같은 정사각 ×(`.modal-x`)를 · 버튼은 보통 `.btn` 을 그대로 쓴다.
   창 폭은 얼굴 줄이 정한다 — 지도 오른쪽 40% 문턱(`explorePop`) 바로 왼쪽 아이콘에서도 지도 칸 안에 든다 */
.ex-pop {
    position: absolute; z-index: 5;
    min-width: 360px; max-width: 520px;
    padding: 10px 12px 12px;
    display: flex; flex-direction: column; gap: 10px;
    background: var(--bg-secondary);
    border: 1px solid var(--border-secondary);
    box-shadow: 0 6px 24px rgba(var(--shadow-rgb), .75);
}
.ex-pop.mid { transform: translateY(-50%); }
.ex-head { display: flex; align-items: center; gap: 8px; padding-bottom: 6px; border-bottom: 1px solid var(--border-secondary); }
.ex-head .modal-x { margin-left: auto; }
.ex-head-ico {
    width: 28px; height: 28px; flex: 0 0 auto; padding: 2px; border-radius: 50%;
    background: var(--ring, #888); box-shadow: 0 0 0 1.5px #1b140e;
}
.ex-head-ico img { display: block; width: 100%; height: 100%; border-radius: 50%; }
.ex-head-name { font-weight: bold; color: var(--text-primary); white-space: nowrap; }
/* 두 줄 이야기 [2026-10-09 · ADR-0563] — 선술집 수색 이야기 줄(`.tv-story`)과 같은 말투: 왼쪽 가는 선 · 한 단 작은 글 · 흐린 색.
   **줄은 표가 끊는다**(셀의 `\n` → `pre-line`) [같은 날 사용자 「- 넣어 길게 해서 이상하게 나올 거면 2줄이 낫다」] — 창은 긴 줄만큼 넓어지고(최대 폭까지) 그 안에서 줄이 안 접힌다 */
.ex-story {
    white-space: pre-line;
    border-left: 2px solid var(--border-secondary); padding-left: 8px;
    font-size: var(--fs-sm); line-height: 1.55; color: var(--text-secondary); word-break: keep-all;
}
.ex-body { display: flex; flex-direction: column; gap: 10px; }
.ex-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.ex-sub { font-size: var(--fs-sm); font-variant-numeric: tabular-nums; }
.ex-note { font-size: var(--fs-sm); }
.ex-go, .ex-take { min-width: 84px; }
/* 편성 버튼 줄 — 대기 창 맨 위 · 출정 창 편성 칸과 같은 이름(「원정 중」 · 「탐험 중」 꼬리표 `.pt-run`) [2026-10-10 · ADR-0582] */
.ex-squads { display: flex; flex-wrap: wrap; gap: 6px; }
.ex-faces { display: flex; gap: 6px; }
.ex-face { display: inline-flex; border: 1px solid var(--border-secondary); border-top-width: 2px; }
.ex-face .hero-face { width: 84px; height: 84px; }
/* 빈 자리 — 고른 편성의 비어 있는 자리 · 읽기 전용 (자원 탭 빈 자리 `.dp-slot.empty` 와 같은 점선 · ADR-0582) */
.ex-face.empty {
    width: 84px; height: 84px; align-items: center; justify-content: center;
    border-style: dashed; color: var(--text-muted); font-size: var(--fs-lg);
}
.ex-bar { height: 8px; background: var(--bg-input); border: 1px solid var(--border-dark); }
.ex-bar i { display: block; height: 100%; background: var(--color-progress); }
/* 이야기 줄 — 나가 있는 동안 열린 줄만 아래로 쌓인다 · 수색 이야기(`.tv-story`)를 그대로 입고 한글은 낱말 단위로 접는다 [2026-10-10 · ADR-0583] */
.ex-log { word-break: keep-all; line-height: 1.5; }
.ex-loot { grid-template-columns: repeat(auto-fill, 52px); gap: 6px; }
.items-tools { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
/* 보관 도구 줄 — 이름(인벤토리는 + 부대 버튼)이 왼쪽, **버튼은 오른쪽 끝**으로 민다 — 빈 칸 하나가 민다 [2026-10-06 · SCREEN_DESIGN §6 · ADR-0523 · ADR-0524] */
.tools-push { margin-left: auto; }
/* 정렬 [2026-09-21 · ADR-0242 · ADR-0247] — [정렬] 오른쪽으로 기준 셋이 **차례로 미끄러져 나온다**. 움직임은 펼친 직후 한 번(`.anim` 을
   JS 가 첫 그리기에만 단다 — 통째로 다시 그리는 화면이라 늘 달면 관전 갱신마다 다시 미끄러진다). 접을 때는 움직임 없이 사라진다 */
.sort-tools, .sort-fold { display: flex; align-items: center; gap: 6px; }
/* 펼친 기준은 **[정렬] 바로 위**에 뜬다 [2026-10-06 · ADR-0523] — 인벤토리 도구 줄에 부대 버튼이 서며 줄 안에 펼칠 자리가 없어졌다
   (영어는 [등급순]부터 칸 밖으로 · 한국어도 [부위순]이 걸쳤다). 두 칸 다 [정렬]이 줄 오른쪽 끝이라 **오른쪽 끝을 [정렬]에 맞춘다** — 제 칸 밖으로 안 나간다(ADR-0524).
   위 패널의 아래쪽을 덮고 칸 격자는 안 가린다 */
.sort-tools { position: relative; }
.sort-fold {
    position: absolute; right: 0; bottom: calc(100% + 6px); z-index: 30; width: max-content;   /* 폭은 내용만큼 — 안 주면 [정렬] 폭에 묶여 한국어 글자가 세로로 꺾였다 */
    padding: 4px; background: var(--bg-secondary); border: 1px solid var(--border-secondary);
    box-shadow: 0 4px 14px rgba(var(--shadow-rgb), .6);
}
.sort-fold.anim > .btn { animation: sort-slide .22s ease-out both; }
.sort-fold.anim > .btn:nth-child(2) { animation-delay: .05s; }
.sort-fold.anim > .btn:nth-child(3) { animation-delay: .1s; }
@keyframes sort-slide {
    from { opacity: 0; transform: translateX(-14px); }
    to   { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) { .sort-fold.anim > .btn { animation: none; } }
/* 보관 도구 줄은 **한 줄을 지킨다** — 두 줄로 꺾이면 두 칸의 칸 줄이 어긋난다(위 `.bag-row`) */
.bag-row .items-tools { flex-wrap: nowrap; }
.bag-row .items-tools > * { flex-shrink: 0; }
/* 분해함 [2026-10-20 사용자 지시 「4x4 · 화면 가운데 · 아이템창 방해 x」 · SCREEN_DESIGN §6 · ADR-0673] — 보관 줄(`.bag-row`) **바로 위 · 박스 가로 가운데**.
   보관 칸은 안 덮고 위 패널(세부 옵션 · 관전 아레나 · 대장간 작업 칸)을 덮는다 — 칸을 눌러 올리는 손짓이 본체라 칸이 보여야 한다.
   왼쪽 = 필터 세 열(등급 · 레벨 · 베이스 — 누르면 바로 함에 오른다 · ADR-0695) · 오른쪽 = 6×4 격자(ADR-0934) + 가루 · [분해하기] · [취소]. 세 열을 세로로 둬 높이가 격자와 맞는다.
   격자 칸은 보관 칸과 같은 크기 — 보관 칸은 폭을 열 수로 나눈 1fr 이라(위 `.bag .inv-cells.wide`) 한 장(1600) 폭에서 나온 값을 박는다.
   필터 글자색(등급 색)은 JS 인라인이다 — 크래프트엔 `--rarity-*` 토큰이 없다 */
.bag-row { position: relative; }
.salv-cube {
    position: absolute; left: 50%; bottom: calc(100% + 10px); transform: translateX(-50%); z-index: 30; width: max-content;
    display: flex; flex-direction: column; gap: 8px;
    padding: 10px 12px 12px; background: var(--bg-secondary); border: 1px solid var(--border-secondary);
    box-shadow: 0 6px 20px rgba(var(--shadow-rgb), .65);
}
.salv-title { font-size: var(--fs-md); font-weight: bold; color: var(--text-primary); border-bottom: 1px solid var(--border-primary); padding-bottom: 5px; }
.salv-body { display: flex; gap: 16px; align-items: stretch; }
.salv-left { display: flex; flex-direction: column; justify-content: space-between; gap: 8px; }
.salv-filters { display: flex; gap: 10px; align-items: flex-start; }
.salv-col { display: flex; flex-direction: column; gap: 3px; }
.salv-col > .btn.sm { padding-top: 2px; padding-bottom: 2px; }
.salv-k { font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; }
.salv-right { display: flex; flex-direction: column; justify-content: space-between; gap: 8px; }
.salv-grid { display: grid; grid-template-columns: repeat(6, 50px); gap: 4px; }
.salv-foot { display: flex; align-items: center; gap: 6px; }
.salv-dust { margin-right: auto; padding-right: 8px; min-width: 0; font-size: var(--fs-sm); color: var(--text-secondary); white-space: normal; }
.pd-cell.filled { cursor: pointer; }
.pd-cell.filled:hover { background: var(--surface-7); }

/* 선술집 후보 — 시작 화면(.ng-row)과 **완전히 같은 카드**다 [개정 2026-09-08 사용자 지시 · SCREEN_DESIGN §3 · §8-1].
   ~~크기만 줄인다~~(2026-09-03)를 걷고 09-01 의 「완전히 같은 카드」로 돌아왔다 — 영웅을 고르는 일은 두 화면이 같고,
   초상이 그 판단의 절반이라 명단에서도 크게 읽혀야 한다. 그래서 이 블록에는 **크기를 줄이는 값이 하나도 없다**.
   ⚠ 대가는 세로다 — 카드가 ~120px 자라 **하한 1280×700 에서는 의뢰 줄이 접히고 패널이 스크롤된다**(src/ui/README 세로 예산).
   1440×900 에서는 명단 · 도구 줄 · 의뢰 줄이 한 화면에 다 선다 */
/* `align-items: start` — 카드가 **제 높이만 쓴다** [2026-09-10 사용자 지시 · ADR-0077]. 늘어나면 수색 결과가
   왔을 때(결과 카드는 버튼이 둘이라 후보보다 길다) 후보 카드 안쪽이 빈다 —
   테두리는 아래까지 내려오는데 속이 없어 「덜 그려졌다」로 읽힌다. 늘어나야 하는 둘만 아래에서 되돌린다 */
/* 명단 폭은 **시작 화면 카드 줄과 같은 1060px** 에서 자른다 [2026-09-14 사용자 지시 · src/ui/README.md 크기 정책].
   둘 다 배율 .9 아래라(선술집 = 메인 zoom · 시작 = `.ng-wrap > .ng-row` 의 zoom) 상한이 같으면 카드가 **보이는 크기까지 같다**.
   안 자르면 패널 전폭을 셋으로 나눠 선술집 카드만 한 단 컸다. 왼쪽에 붙인다 — 제목 · 도구 줄 · 의뢰 줄이 왼쪽에 선다 */
.tv-cands { display: grid; grid-template-columns: repeat(2, minmax(0, var(--tv-c))); gap: 14px; align-items: start; min-width: 0; }   /* 카드 폭 = 윗줄이 푼 `--tv-c` (아래 · ADR-0981) */
/* 명단 한 줄 — 격자(영웅 고용 패널을 채운다 · 수색은 옆 제 패널 · ADR-0978) */
.tv-row { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 10px; }
/* 윗줄 = 영웅 고용 | 수색 나란히 [2026-10-30 사용자 「영웅 고용이랑 오른쪽 수색 분리」 · 「맨 오른쪽도 수색에」 · SCREEN_DESIGN §8-1 · ADR-0978 · ADR-0981] — 같은 높이 · 제 내용 높이.
   영웅 고용 = 후보 카드 둘 · 수색 = 안내 칸(카드 하나) + 얼굴 칸 둘. 카드 폭(`--tv-c`)과 얼굴 칸(`--tv-face` = 명단 초상 — 초상도 이 값을 그린다)을 윗줄 폭(크기 컨테이너 · 100cqw)에서 푼다:
   윗줄 = 카드 셋 + 칸 둘 + 틈(카드 사이 14 · 패널 사이 14 · 카드 ↔ 칸 14 · 칸 사이 8) + 패널 여백 둘 · F = .41 × (C − 카드 여백) → C.
   카드 상한은 시작 화면 카드 줄과 같은 폭((1060 − 28) / 3) — 1600×800 에선 그보다 조금 좁다(약 2.5% — src/ui/README 크기 정책).
   **등록된 길이**(`@property`)라 패널에서 px 로 굳어 카드(제 크기 컨테이너) 안으로 그대로 내려간다. ⚠ 패널 · 카드 여백 · 초상 41% 가 바뀌면 같이 고친다 */
@property --tv-c { syntax: '<length>'; inherits: true; initial-value: 0px; }
@property --tv-face { syntax: '<length>'; inherits: true; initial-value: 0px; }
.c-tavern > .tv-top {
    --tv-k: .41;          /* 초상 = 카드 안쪽 폭의 41% (.ng-head .hero-face) */
    --tv-card-x: 34px;    /* 카드 좌우 여백 16 × 2 + 테두리 1 × 2 (.ng-card) */
    --tv-panel-x: 34px;   /* 패널 좌우 여백 16 × 2 + 테두리 1 × 2 (.panel) */
    container-type: inline-size;
    flex: 0 1 auto; min-height: 0; display: flex; gap: 14px;
}
/* 나란히 선 판 — 위 마진 0(`.panel + .panel` · 겉모양 규칙보다 세게 건다) · 박스가 모자라면 본문이 스크롤.
   두 값은 여기서 푼다 — 100cqw 가 윗줄(컨테이너)을 보는 자리다 */
.c-tavern > .tv-top > .panel {
    --tv-c: min(calc((1060px - 28px) / 3), calc((100cqw - 50px - 2 * var(--tv-panel-x) + 2 * var(--tv-k) * var(--tv-card-x)) / (3 + 2 * var(--tv-k))));
    --tv-face: clamp(96px, calc(var(--tv-k) * (var(--tv-c) - var(--tv-card-x))), 152px);
    display: flex; flex-direction: column; min-height: 0; margin-top: 0;
}
.c-tavern > .tv-top > .panel > .box-body { flex: 0 1 auto; }
.c-tavern > .tv-top > .tv-hire { flex: 1 1 0; min-width: 0; }
.c-tavern > .tv-top > .tv-search { flex: none; width: calc(var(--tv-c) + 14px + 2 * var(--tv-face) + 8px + var(--tv-panel-x)); }
.c-tavern .tv-top .ng-head .hero-face { width: var(--tv-face); height: var(--tv-face); }   /* 명단 · 수색 카드 초상 = 얼굴 칸 (같은 값) */
/* 수색 본문 = 안내 칸 | 얼굴 칸. 안내 칸은 숨긴 후보 카드(`.tv-ghost`) 위에 겹쳐 서서 후보 카드와 같은 높이다(명단 빈 칸과 같은 수 · ADR-0981) */
.tv-search-row { display: flex; align-items: flex-start; gap: 14px; }
.tv-search-cell { flex: none; width: var(--tv-c); display: grid; }
.tv-search-cell > * { grid-area: 1 / 1; min-width: 0; }
.tv-search-cell > .tv-ghost { visibility: hidden; }
/* 수색 칸 [2026-10-09 ADR-0574 · 2×2 2026-10-12 ADR-0593 · 2026-10-19 ADR-0671] — 두 칸씩 줄짓는다. **늘 선다**(빈 칸 포함).
   초상 칸은 정사각 · 테두리 = 등급 색(렌더러가 넣는다 — 명단 카드 윗선과 같은 색) · 아래 띠 = 출처(「찾아옴」 · 「마차」 — 떠나지 않아 시간이 없다).
   빈 칸은 명단 빈 칸과 같은 점선이다 */
.tv-join { display: flex; flex-direction: column; gap: 8px; }
.tv-join-grid { display: grid; grid-template-columns: repeat(2, var(--tv-face)); gap: 8px; }
.tv-join-slot {
    position: relative; display: block; width: 100%; aspect-ratio: 1; padding: 0; overflow: hidden;
    background: var(--bg-tertiary); border: 1px solid var(--border-secondary); border-top-width: 2px; cursor: pointer;
}
/* 테두리는 등급 색(인라인)이라 **안쪽 선**으로 「눌린다」를 보인다 — 겉선(`outline`)은 오른쪽 칸에서 박스 본문 끝에 걸려 오른쪽 변이 잘렸다
   [2026-10-12 사용자 「오른쪽 초상화는 hover 하면 오른쪽 회색선이 안 보임」]. 초상 · 시간 띠 위에 얹는다(눌림은 안 가로챈다) */
.tv-join-slot:not(.empty):hover::after { content: ''; position: absolute; inset: 0; border: 1px solid var(--border-highlight); pointer-events: none; }
.tv-join-slot .hero-face { width: 100%; height: 100%; border: 0; background: none; }
/* 빈 칸 · 안 열린 칸의 점선은 밝은 테두리 토큰 — 겉모양마다 바탕에 안 묻힌다(D2 Min 의 `--border-secondary` 는 바탕과 거의 같다 · ADR-0978) */
.tv-join-slot.empty { background: none; border: 1px dashed var(--border-highlight); cursor: default; }
/* 안 열린 칸 — 빈 칸과 같은 점선 + 가운데 닫힌 자물쇠만(회색 — 잠금 표시는 어디서나 회색 · ADR-0925) (§8-1 · ADR-0976 · ADR-0978) */
.tv-join-slot.locked {
    display: flex; align-items: center; justify-content: center;
    background: none; border: 1px dashed var(--border-highlight); cursor: default; color: var(--text-muted);
}
.tv-join-slot.locked .lock-ico { display: inline-flex; }
.tv-join-slot.locked .lock-ico svg { width: 22px; height: 22px; }
.lock-host .tv-join-slot.locked .lock-ico { visibility: hidden; }   /* 고용이 안 열려 패널이 잠김 베일 아래면 칸 자물쇠는 숨긴다 — 베일의 자물쇠와 겹쳐 읽힌다 */
.tv-join-left {
    position: absolute; left: 0; right: 0; bottom: 0; padding: 2px 0;
    background: rgba(var(--veil-rgb), .78); color: var(--text-primary);
    font-size: var(--fs-xs); text-align: center; white-space: nowrap; font-variant-numeric: tabular-nums;
}
/* 셋째 칸이 그 영웅의 카드를 든 동안 — 그 얼굴이 눌린 채다(hover 와 같은 안쪽 선 · 두께로 갈린다) (ADR-0624 · ADR-0671) */
.tv-join-slot.on::after, .tv-join-slot.on:hover::after { content: '';position: absolute; inset: 0; border: 2px solid var(--border-highlight); pointer-events: none; }
/* 막 온 얼굴이 처음 보일 때 한 번 스며 나온다 — 길이는 `app.js:JOIN_FRESH_MS` 와 같다(다시 그리면 흐른 만큼 당겨 이어 간다) */
.tv-join-slot.fresh { animation: tv-fresh .9s ease-out both; }
@keyframes tv-fresh { from { opacity: 0; transform: scale(.86); filter: brightness(1.8); } to { opacity: 1; transform: none; filter: none; } }
/* 크기를 정하던 값들(초상 clamp · 카드 패딩 · 이름 글씨 · 고유 스킬 칸 · 능력치 줄간격 · 아래 두 줄)은
   **2026-09-08 에 전부 삭제됐다** — 카드가 `.ng-card` 규격을 그대로 탄다. 남는 것은 명단 격자와
   선술집에만 있는 조각들(고용 버튼 · 빈 칸 · 수색 칸)뿐이다 */
/* 고용한 칸 — 빈 채로 남는다. 카드 자리를 지켜야 명단이 「줄었다」가 아니라 「비었다」로 읽힌다.
   그래서 격자의 `align-items: start` 를 **여기서만 되돌린다** — 빈 칸이 글자 높이로 쪼그라들면 자리가 사라진다.
   **높이는 숨긴 카드 한 장이 정한다** [2026-09-30 사용자 지시 · SCREEN_DESIGN §8-1] — 칸 안에 후보 카드를 안 보이게 깔고 글은 그 위에 얹는다.
   후보가 다 고용돼도 줄 높이가 카드 높이라 영웅 고용 패널 · 의뢰 줄의 높이가 안 바뀐다 */
.tv-cands .tv-empty { align-self: stretch; position: relative; border-style: dashed; background: none; }
.tv-cands .tv-empty > * { visibility: hidden; }
.tv-cands .tv-empty > .tv-empty-l {
    visibility: visible; position: absolute; inset: 0;
    display: flex; align-items: center; justify-content: center; text-align: center;
    color: var(--text-muted); font-size: var(--fs-sm);
}
.tv-cands .b-hire { width: 100%; margin-top: 7px; }
/* 후보 카드 바닥 줄 [고용] · [보관] — 줄(`.tv-res-btns`)이 위 여백을 들고 둘이 반씩 나눈다 (ADR-0897) */
.tv-cands .tv-res-btns > .b-hire { margin-top: 0; }
/* 수색 칸 — 안내 [2026-10-19 · SCREEN_DESIGN §8-1 · ADR-0671 — ~~수색 칸~~ 자리 그대로]. 후보 카드와 **같은 크기**다 —
   격자가 늘 3열이라(후보 2 + 이 칸) 폭은 저절로 같고, 높이는 같은 행의 카드가 정한다(`align-self: stretch`).
   제목 · 사양 · 레어 확률 · 상태 한 줄(다음 도착까지 — 앱 시계가 글자만 간다 · 멈춤 · 닫힘 · 지을 랭크) */
.tv-visit { align-self: stretch; display: flex; flex-direction: column; gap: 8px; }
.tv-visit-spec { font-size: var(--fs-sm); }
.tv-visit-odds { font-size: var(--fs-sm); color: var(--text-secondary); }
.tv-visit-state { font-size: var(--fs-sm); }
.tv-visit-state.warn { color: var(--color-warning); }
.tv-visit-next { font-size: var(--fs-md); font-variant-numeric: tabular-nums; }   /* 1초마다 갈려 숫자 폭을 고정한다 */
/* 고른 수색의 카드 — 셋째 칸 자리에 선다 · 명단 카드와 **같은 규격** · 버튼 둘이 [고용] 자리에 **한 줄로 나란히** —
   명단 카드의 [고용] 한 줄과 높이가 같아 영웅 고용 패널이 안 흔들린다(글이 길면 줄을 안 바꾸고 말줄임) (ADR-0624 · ADR-0671) */
.tv-res-btns { display: flex; gap: 6px; margin-top: 7px; }
.tv-res-btns > .btn { flex: 1 1 0; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* 이야기 줄 — 막마다 하나씩 열린다 (ADR-0062). 목록 기호를 안 쓴다: 항목이 아니라 문장이라
   점을 찍으면 「설정값 목록」으로 읽힌다. 새 줄이 아래에 쌓이므로 **왼쪽 선**이 하나로 묶는다 */
.tv-story {
    display: flex; flex-direction: column; gap: 5px;
    border-left: 2px solid var(--border-secondary); padding-left: 8px;
    font-size: var(--fs-sm); color: var(--text-secondary);
}
.tv-story p { margin: 0; }
.tv-tools { display: flex; align-items: center; gap: 10px; }
.tv-wait { color: var(--text-muted); font-variant-numeric: tabular-nums; }   /* 무료까지 남은 시간 — 1초마다 갈려 숫자 폭을 고정한다 */
/* 선술집은 **위아래 둘** — 위 영웅 고용(제 내용 높이) · 아랫줄(`.tv-low` = 의뢰 | 도박장 — 남는 세로를 받아 박스 끝까지)
   [2026-09-21 사용자 지시 「아예 카드로 만들어서 아래에 나오도록 분리」 · SCREEN_DESIGN §8-1 · ADR-0248]. 상점(ADR-0246)과 같은 쌓인 판이다.
   **의뢰는 안 줄어든다** — 게시판은 한 줄이 형태라(§14) 박스가 모자라면 영웅 고용가 줄어 제 본문(`.box-body`)이 스크롤한다.
   영웅 고용의 본문은 기본값(`flex: 1 1 0`)이면 제 높이를 못 잰다 — 내용 높이에서 시작해 줄기만 하게 `0 1 auto` 로 준다.
   카드 규격 자체는 .cm-board / .cm-card 가 그대로 든다 */
.tv-low > .panel { display: flex; flex-direction: column; min-height: 0; }
/* 아랫줄 = 의뢰 | 도박장 나란히 [2026-09-24 사용자 지시 · §8-1 · ADR-0322] — 남는 세로는 줄이 받고 두 패널은 stretch 로 같은 높이다.
   줄은 패널이 아니라 `.panel + .panel` 여백을 못 받는다 — 위 여백은 여기서 주고, 줄 안의 둘째 패널은 세로 여백을 끈다(`.cols` 와 같은 함정).
   폭은 4 : 1 — 도박장 칸이 의뢰 카드 한 장쯤이 된다 */
/* 명성 줄 — 높이 · 위아래 틈(제목 밑줄 ↔ 막대 = 막대 ↔ 카드 · 2026-10-30 사용자 「명성 바 위아래 여백 똑같이」) ·
   도박장 칸 윗변이 같은 값으로 의뢰 카드 윗변을 따른다 (§14 · ADR-0961) */
.c-tavern > .tv-low { flex: 1 0 auto; display: flex; gap: 14px; margin-top: 14px; --cm-fame-h: 16px; --cm-fame-pad: 11px; }
.tv-low > .tv-cm { flex: 4 1 0; min-width: 0; }
.tv-low > .tv-gb { flex: 1 1 0; min-width: 0; margin-top: 0; }
/* 카드는 패널 바닥까지 늘어난다 [2026-09-21 사용자 지시 「카드 높이를 키워서 아래에 딱 맞춰」 · §8-1] — 몸(`.cm-body` = 명성 줄 + 게시판)이 남는 세로를 받고
   그 안에서 게시판이 명성 줄 아래 남는 세로를 받는다(명성 줄만큼 카드가 낮다 · ADR-0958). 카드는 줄의 기본 stretch 로 그 높이를 탄다.
   늘어난 세로는 보상 줄의 `margin-top: auto` 가 받아 보상 · [수락]이 바닥에 붙는다 */
.tv-low > .tv-cm > .cm-body { flex: 1 1 auto; display: flex; flex-direction: column; min-height: 0; }
.cm-body > .cm-board { flex: 1 1 auto; }
/* 도박장 칸 — 의뢰 카드(.cm-card)와 같은 판 · 버튼이 바닥에 붙어 [수락]과 같은 바닥선에 선다. 속은 창이 든다.
   윗변은 의뢰 카드 윗변과 같다 — 의뢰의 명성 줄(높이 + 카드와의 틈 − 올라간 양)만큼 내려선다 · 안쪽 여백 · 줄 간격도 카드와 같다 (ADR-0961) */
.gb-cell {
    flex: 1 1 auto; display: flex; flex-direction: column; gap: 4px;
    padding: 7px 9px; background: var(--bg-card); border: 1px solid var(--border-dark);
}
.tv-low > .tv-gb > .gb-cell { margin-top: calc(var(--cm-fame-pad) - 8px + var(--cm-fame-h) + var(--cm-fame-pad)); }
/* 칸 가운데 = 심볼 일곱(죄종 일곱) 띠 — 남는 세로의 가운데에 선다(위아래 auto) · 바닥 = 「한 판 n G부터」 + [입장].
   그 한 줄은 의뢰 카드의 보상 줄(.cm-rew)과 같은 자리 · 같은 말투다 — 위 가는 선 · 작은 글 · 골드는 금색 (ADR-0601) */
.gb-sins {
    margin: auto 0; align-self: center; display: flex; gap: 2px;
    padding: 6px 7px; background: var(--gb-reel); border: 1px solid var(--border-dark);
}
.gb-sins .gb-art .gb-ico { width: 25px; height: 25px; }
.gb-from { padding-top: 5px; border-top: 1px solid var(--border-dark); font-size: var(--fs-xs); }
.gb-gold { color: var(--color-warning); }
.gb-go { align-self: stretch; }

/* 도박장 창 — 기계 한 대 [2026-09-24 · SCREEN_DESIGN §8-1 · ADR-0331 슬롯 · 2026-10-12 ADR-0601 배치].
   왼쪽 = 기계(잭팟 띠 · 판 · 계기판이 한 틀) + 조작 줄(판돈 · 버튼) | 오른쪽 = 배당표.
   틀은 자원 미니게임 판(.mg-field)과 같은 결이다 · **금색은 돈에만**(잭팟 · 골드 배당 · 받음+ · 맞은 라인) · 틀 · 칸 · 버튼은 무채색.
   숫자는 고정폭이라 판마다 자리가 안 흔들린다. 라벨이 드는 칸은 고정 px 이 아니라 minmax(ui/README 폭 정책) · 판의 칸 높이만 px 이다(릴 띠가 칸 하나씩 굴러야 해서) */
.modal-box.gb-modal { width: min(940px, 100%); }
.gb-box {
    --gb-cell-h: 96px; --gb-gap: 0px; --gb-bounce: 7px;
    display: grid; grid-template-columns: minmax(0, 1fr) minmax(220px, 260px); gap: 18px; font-variant-numeric: tabular-nums;
}
.gb-main { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
/* 기계 틀 — 모서리가 각지다(게임의 패널 · 칸이 다 그렇다 — 둥근 카드는 이 게임의 말투가 아니다 · ADR-0608).
   바깥 선 하나 + 안쪽 어두운 턱 한 줄이 무쇠 틀의 두께를 낸다 */
.gb-machine {
    display: flex; flex-direction: column; gap: 10px; padding: 10px;
    border: 1px solid var(--border-secondary); box-shadow: inset 0 0 0 3px var(--surface-0), inset 0 0 0 4px var(--border-dark);
    background: linear-gradient(180deg, var(--surface-7), var(--surface-1));
}
/* 잭팟 띠 — **명판 한 장**을 세로줄로 넷에 가른다(낱장 카드 넷이 아니다 · ADR-0608) · 위 이름 · 아래 지금 판돈의 골드. 그랜드(판이 다 차면)는 넓고 금빛 */
.gb-jp { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)) minmax(0, 1.5fr); background: var(--surface-0); border: 1px solid var(--border-primary); }
.gb-jp-c {
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; min-width: 0;
    padding: 6px 6px 7px; border-left: 1px solid var(--border-dark);
}
.gb-jp-c:first-child { border-left: 0; }
.gb-jp-k { font-size: var(--fs-xs); color: var(--text-muted); letter-spacing: .06em; white-space: nowrap; }
.gb-jp-k small { margin-left: 6px; font-size: var(--fs-xs); letter-spacing: 0; color: var(--text-muted); opacity: .8; }
:lang(en) .gb-jp-k { text-transform: uppercase; }
:lang(en) .gb-jp-k small { text-transform: none; }
.gb-jp-v { font-size: var(--fs-md); color: var(--color-warning); white-space: nowrap; }
.gb-jp-c.fill { background: var(--elite-bg); border-left-color: var(--elite-line); }
.gb-jp-c.fill .gb-jp-v { font-size: var(--fs-lg); }
/* 이번 판에 선 잭팟 — 칸이 금빛으로 찬다(맞은 라인 표지와 같은 「무엇이 섰나」) */
.gb-jp-c.hit { box-shadow: inset 0 0 0 1px var(--color-warning); background: color-mix(in srgb, var(--color-warning) 16%, var(--surface-0)); }
.gb-jp-c.hit .gb-jp-k { color: var(--text-primary); }
/* 판 창 — 가운데 판 · 양옆 라인 표지. 표지 줄은 판의 행과 같은 높이라 번호가 그 행 옆에 선다(위아래 1px = 판 테두리) */
.gb-window { display: grid; grid-template-columns: 22px minmax(0, 1fr) 22px; gap: 6px; }
.gb-gut { display: grid; grid-auto-rows: var(--gb-cell-h); padding: 1px 0; }
.gb-gut-row { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; }
.gb-mk {
    width: 22px; height: 18px; display: grid; place-items: center;
    font-size: var(--fs-xs); font-weight: bold; line-height: 1; color: var(--text-muted);
    background: var(--surface-0); border: 1px solid var(--border-primary);
}
.gb-mk.on { color: var(--surface-0); background: var(--color-warning); border-color: var(--color-warning); }
/* 판 — 칸은 테두리가 없고 **릴 사이에 가는 세로줄만** 선다(판 바탕이 그 줄이다 — 칸 · 릴 띠가 제 바탕으로 덮고 1px 틈만 남긴다).
   릴의 둥근 몸 — 위아래 가장자리가 어두워진다(칸 위 · 선 아래) */
.gb-reels { position: relative; min-width: 0; border: 1px solid var(--border-primary); background: var(--gb-reel-gap); }
.gb-reels::after {
    content: ''; position: absolute; inset: 0; z-index: 1; pointer-events: none;
    background: linear-gradient(180deg, rgba(var(--shadow-rgb), .6), rgba(var(--shadow-rgb), .1) 20%, transparent 34%, transparent 66%, rgba(var(--shadow-rgb), .1) 80%, rgba(var(--shadow-rgb), .6));
}
.gb-board {
    display: grid; grid-template-columns: repeat(var(--reels), minmax(0, 1fr)); grid-template-rows: repeat(var(--rows), var(--gb-cell-h));
    column-gap: 3px; row-gap: var(--gb-gap); background: var(--gb-reel-gap);
}
.gb-c {
    position: relative; overflow: hidden; min-width: 0;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
    background: var(--gb-reel); color: var(--text-secondary);
}
.gb-art { display: inline-flex; }
/* 심볼 그림(`icons/gamble/` · ADR-0608) — 512 원판(긴 변 0.88 · 중앙)을 칸 높이의 4/5 쯤으로 */
.gb-art .gb-ico { width: 78px; height: 78px; object-fit: contain; }
/* 코인 칸 — 그림을 줄이고 값을 든다(잭팟이면 그 위에 이름 · 금빛 바탕) */
.gb-c.coin .gb-ico { width: 50px; height: 50px; }
.gb-cname { font-size: var(--fs-xs); color: var(--elite-fg); letter-spacing: .08em; line-height: 1.1; }
:lang(en) .gb-cname { text-transform: uppercase; }
.gb-cval { font-size: var(--fs-sm); font-weight: bold; color: var(--color-warning); line-height: 1.2; white-space: nowrap; }
/* 코인 글은 릴 그늘(.gb-reels::after) 위에 선다 — 맨 위 · 맨 아래 행에서도 값이 흐려지지 않게 */
.gb-cname, .gb-cval { position: relative; z-index: 2; }
.gb-c.coin.k-jackpot { background: var(--elite-bg); box-shadow: inset 0 0 0 1px var(--elite-line); }
/* 맞은 라인 — 맞은 칸에 금빛이 옅게 깔리고 나머지 칸은 **그림만** 흐려진다(칸 바탕이 흐려지면 릴 사이 줄이 번진다) ·
   칸 중심을 잇는 선(.gb-lines)이 그 위에 그어진다. 판돈보다 적게 받은 판도 선은 그어진다 — 「어느 라인이 맞았나」라는 사실이다.
   당첨처럼 밝아지는 것은 계기판의 받음(+)뿐이다 (ADR-0331 · ADR-0601) */
.gb-c.win { background: color-mix(in srgb, var(--color-warning) 12%, var(--gb-reel)); }
.gb-board.has-win .gb-c:not(.win) > * { opacity: .32; }
.gb-lines { position: absolute; inset: 0; z-index: 2; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.gb-lines polyline {
    fill: none; stroke: var(--color-warning); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round;
    vector-effect: non-scaling-stroke; opacity: .85;
}
/* 새로 선 코인 — 튀어 오르며 선다(리스핀 재생 중에만 붙는다) */
.gb-c.fresh { box-shadow: inset 0 0 0 2px var(--color-warning); animation: gb-pop .32s ease-out both; }
@keyframes gb-pop { 0% { transform: scale(.45); opacity: .2; } 65% { transform: scale(1.1); opacity: 1; } 100% { transform: scale(1); } }
.gb-board.holding .gb-c:not(.coin) > * { opacity: .2; }
.gb-board.idle .gb-c > * { opacity: .3; }
/* 도는 판 — **릴마다 한 줄 띠**가 아래로 흐르다 왼쪽부터 멈춘다 [2026-09-24 사용자 「좌라락좌라락」 · ADR-0333].
   띠 = [결과 칸 · 채움 칸] 위에서 아래 순 — 채움 끝을 창에 걸고 시작(`--from`)해 결과 칸이 창에 닿으면(0) 멈춘다: **멈추는 곳이 결과**다.
   박자 — 70% 까지 같은 속도로 흐르고(거리의 82%) 속도를 이어받아 느려지며 `--gb-bounce` 만큼 더 내려갔다가 제자리(「탁」).
   `--n`(채움 칸 수) · `--dur`(이 릴이 도는 시간) · `--delay`(흐른 시간 — 다시 그려져도 이어서 돈다)는 렌더러가 릴마다 준다(`app.js:gbReel`) */
.gb-reel { position: relative; overflow: hidden; min-width: 0; background: var(--gb-reel); }
.gb-reel-strip {
    --from: calc(var(--n) * -1 * (var(--gb-cell-h) + var(--gb-gap)));
    display: flex; flex-direction: column; gap: var(--gb-gap);
    animation: gb-reel var(--dur) both, gb-reel-blur var(--dur) linear both;
    animation-delay: var(--delay, 0ms), var(--delay, 0ms);
}
.gb-reel-strip > .gb-c { flex: 0 0 var(--gb-cell-h); height: var(--gb-cell-h); }
@keyframes gb-reel {
    0% { transform: translateY(var(--from)); animation-timing-function: linear; }
    70% { transform: translateY(calc(var(--from) * .18)); animation-timing-function: cubic-bezier(.3, .43, .4, 1); }
    92% { transform: translateY(var(--gb-bounce)); animation-timing-function: ease-in-out; }
    100% { transform: translateY(0); }
}
/* 개발 장치 `?dev=gamble&spin=1&roll=ms` — 도는 판을 그 순간에 세운다(헤드리스가 흐르는 장면을 찍는 길 · SCREEN_DESIGN §10) */
.gb-board.freeze .gb-reel-strip { animation-play-state: paused; }
/* 흐르는 동안만 번진다 — 멈추기 직전에 또렷해져 멈춘 칸이 읽힌다 */
@keyframes gb-reel-blur { 0% { filter: blur(1px); } 8% { filter: blur(2px); } 70% { filter: blur(1.5px); } 88%, 100% { filter: blur(0); } }
/* 계기판 — 왼쪽 표지(맞은 라인 · 홀드 · n판) · 오른쪽 판돈 → 받음 → 순손익(위 작은 라벨 · 아래 큰 숫자 — 식처럼 왼쪽부터 읽힌다).
   받음 아래 줄(재료)은 비어도 자리를 지켜 판마다 계기판 높이가 안 흔들린다 */
.gb-meter {
    display: grid; grid-template-columns: minmax(0, 1fr) repeat(3, minmax(92px, auto)); align-items: start;
    padding: 9px 2px 1px; border-top: 1px solid var(--border-primary);
}
.gb-tag { align-self: center; min-width: 0; padding-left: 4px; font-size: var(--fs-sm); color: var(--color-warning); line-height: 1.4; }
.gb-m { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; padding: 0 12px; border-left: 1px solid var(--border-dark); }
.gb-m-k { font-size: var(--fs-xs); color: var(--text-muted); }
.gb-m-v { font-size: var(--fs-lg); color: var(--text-primary); white-space: nowrap; line-height: 1.25; }
.gb-m-sub { font-size: var(--fs-xs); color: var(--text-secondary); white-space: nowrap; }
.gb-meter.won .gb-m.got .gb-m-v { color: var(--color-warning); }
.gb-m.up .gb-m-v { color: var(--color-success); }
.gb-m.down .gb-m-v { color: var(--color-error); }
/* 조작 줄 — 왼쪽 판돈 단계 · 오른쪽 [n판 돌리기] [스핀](주 버튼이 줄 끝) */
.gb-ctl { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; }
.gb-stakes { display: flex; align-items: center; gap: 4px; }
.gb-stakes .gb-k { margin-right: 6px; font-size: var(--fs-sm); color: var(--text-muted); }
.btn.sm.gb-stake { padding: 6px 10px; white-space: nowrap; }
.gb-stake small { margin-right: 6px; color: var(--text-muted); }
.btn.sm.gb-stake.on { color: var(--text-primary); border-color: var(--text-accent); }
.btn.sm.gb-stake.on small { color: var(--text-secondary); }
.gb-acts { margin-left: auto; display: flex; gap: 6px; }
.gb-acts .btn { padding: 9px 16px; white-space: nowrap; }
.gb-acts .gb-spin { min-width: 10em; font-weight: bold; }
/* 배당표 — 라인 심볼마다 그림 · 이름 ×셋 · 받는 것(골드는 금색) · 그 아래 코인 줄. 줄은 가는 선으로 갈린다 */
.gb-pay { display: flex; flex-direction: column; min-width: 0; font-size: var(--fs-sm); }
.gb-pay-h { padding: 2px 0 7px; font-weight: bold; color: var(--text-primary); border-bottom: 1px solid var(--border-primary); }
.gb-pay-row { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 5px 0; border-bottom: 1px solid var(--border-dark); }
.gb-pay-row .gb-art .gb-ico { width: 28px; height: 28px; }
.gb-pname { min-width: 0; color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gb-pname small { margin-left: 5px; font-size: var(--fs-xs); color: var(--text-muted); }
.gb-pay-row b { font-weight: normal; color: var(--text-primary); white-space: nowrap; }
.gb-pay-row.coin { grid-template-columns: 28px minmax(0, 1fr); border-bottom: 0; }
.gb-pay-row.coin .gb-pname { white-space: normal; line-height: 1.35; }

/* 네비 맨 아래 — 시작 화면으로 (새 게임 / 이어하기) */
.nav .b-newgame { margin-top: auto; padding-left: 16px; color: var(--text-muted); font-size: var(--fs-sm); border-top: 1px solid var(--border-dark); }

/* 편성 줄 — 이름 줄 / 죄종·출정 아웃 줄 */
.party-slot .ps-main { flex: 1; min-width: 0; }
.party-slot .ps-name { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.party-slot .ps-leader { font-size: var(--fs-xs); margin-left: auto; }
.party-slot .ps-sub { display: flex; align-items: center; gap: 6px; margin-top: 4px; flex-wrap: wrap; }
.party-slot .ps-sub .injury-chip { margin-top: 0; white-space: nowrap; }
.party-slot .b-toggle { flex: 0 0 auto; }

/* ───────── 도움말 탭 (ADR-0946 · 주제별 폴더 ADR-0964 · 공용 폴더 ADR-0967) ─────────
   탭과 패널 모양은 대장간의 .fg-* 공용 규칙을 쓴다. 여기서는 폭과 본문 스크롤만 정한다. */
.help { width: 100%; min-width: 0; }
.help > .help-panel { min-width: 0; overflow: hidden; }
.help-panel > h2, .help-panel > .help-search { flex: none; }
.help-search { display: flex; align-items: center; gap: 9px; margin-bottom: 10px; }
.help-search label { flex: none; font-size: var(--fs-sm); color: var(--text-secondary); }
.help-search-input { flex: 1 1 300px; min-width: 0; max-width: 540px; font: inherit; font-size: var(--fs-sm); padding: 6px 10px; background: var(--bg-input); color: var(--text-primary); border: 1px solid var(--border-secondary); }
.help-search-count { font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap; }
.fg-tabs.help-tabs { width: 100%; max-width: 100%; min-width: 0; overflow-x: auto; overscroll-behavior-x: contain; }
.help-tabs > .help-tab { flex: none; }
.help-tab:focus-visible { outline: 2px solid var(--text-accent); outline-offset: -4px; }
.help-content { display: flex; flex-direction: column; flex: 1 1 0; min-height: 0; min-width: 0; }
.help-content > [hidden] { display: none; }
/* 본문(`.help-body`)은 박스 안에서 스크롤한다 — 제목 · 검색 · 폴더 탭은 서 있다 (ADR-0097). */
.help-body { min-width: 0; padding: 8px 12px 18px 0; overflow-wrap: anywhere; overscroll-behavior-y: contain; }
.help-body > [hidden] { display: none; }
.help-body > h3 {
    font-size: var(--fs-md); color: var(--text-primary); font-weight: bold;
    margin: 18px 0 0;
}
.help-body > h3:first-child { margin-top: 0; }
.help-body > h3 small { color: var(--text-muted); font-size: var(--fs-xs); margin-left: 7px; }
.help-body > .note-body { margin-top: 5px; font-size: var(--fs-sm); color: var(--text-secondary); }
.help-body > .note-body + .note-body { margin-top: 7px; }
.help-content > .help-empty { padding: 16px 0; font-size: var(--fs-sm); color: var(--text-secondary); }

/* ───────── 편성 탭 (2026-09-21 · SCREEN_DESIGN §15 · ADR-0192 ~ 0195 · 배치 ADR-0221 · 0260) ─────────
   캐릭터 탭과 같은 짜임 — 띠 패널(`.hs-panel` 공용)이 박스 밖 맨 위에 서고, 아래 박스 안은 맨 위 편성 고르개(ADR-0251) 아래로 **두 열**이다:
   왼쪽 열(내용 폭) = 진형 · 그 아래 물약 · 오른쪽 열(남는 폭 전부) = 파티 전술(칸이 세로 목록 · ADR-0260).
   넘치면 박스(`.page-stack > .fill`)가 스크롤한다. 두 열 사이는 세로 가림선 하나 · 진형 ↔ 물약 사이는 여백이 가른다 */
/* 두 열 사이 가림선은 **박스 아래 여백 위까지** 내려간다 [2026-09-21 사용자 지시 「가운데 선은 맨 아래까지 쭉」 → 「맨 아래와 닿으면 안 됨」] —
   두 열 판(`.pt-mid`)이 고르개 아래 남는 세로를 다 받고(줄지는 않는다 — 넘치면 박스가 스크롤한다), 박스의 아래 여백이 선과 아랫변을 뗀다.
   여백은 박스의 좌우 여백과 같게 한 단 늘렸다 — 선 끝이 아랫변에 거의 붙어 닿은 것처럼 보이지 않게 */
.pt-body { display: flex; flex-direction: column; gap: 22px; padding-bottom: 16px; }
.pt-mid { flex: 1 0 auto; display: flex; align-items: stretch; gap: 26px; }
/* 진형 ↔ 물약 사이는 여백만 — 고르개 아래 간격보다 넓게 떼어 물약이 제 묶음으로 읽힌다 [2026-09-21 사용자 지시 「Potions 조금만 아래로」] */
/* 두 여백은 진형의 모양 버튼 열(`.fm-side`)도 읽는다 — 버튼 열의 위아래 빈자리를 맞추는 데 쓴다 (ADR-0577) */
.pt-left { --pt-left-gap: 36px; --fm-head-gap: 28px; flex: none; display: flex; flex-direction: column; gap: var(--pt-left-gap); }
.pt-mid > .pt-tactics { flex: 1 1 0; min-width: 0; padding-left: 26px; border-left: 1px solid var(--border-secondary); }
/* 칸 이름 셋(진형 · 물약 · 파티 전술)은 **소제목**이다 [2026-09-21 사용자 지시 · ADR-0256] — 모양은 `.panel > h2, .sub-h` 한 규칙이 든다
   (캐릭터 탭 「장비」와 같다 · ADR-0241). 여기는 자리만: **제 줄에 서고 밑줄이 칸을 연다**(ADR-0240) — 밑줄은 칸 폭만큼이고
   내용(진형 보드 · 물약 칸 · 전술 진척)은 그 아래에서만 시작한다. 진형 · 파티 전술 두 이름 줄이 같은 높이라 밑줄 둘이 한 선에 선다 */
/* 밑줄 아래 내용까지의 간격 — 14 → 20 [2026-09-21 사용자 지시 「Formation 아래도 글씨랑 너무 가까워」].
   진형만 한 단 더 뗀다(20 → 28) [같은 날 「영웅 카드랑 정렬 바꾸는 거 좀만 더 아래로」] — 보드 · 템플릿 아이콘이 밑줄에 붙어 보였다 */
.pt-body .sub-h { margin: 0 0 20px; white-space: nowrap; }
.pt-body .fm-box > .sub-h { margin-bottom: var(--fm-head-gap); }
/* 소제목 옆 `?` 표시 — 글씨 바로 오른쪽 · **올리면** 설명 툴팁 (ADR-0464). 누르는 자리가 아니라 손가락 커서를 안 준다.
   줄 높이를 안 밀게 글씨보다 작은 원이다 — 「진형」 · 「파티 전술」 밑줄이 한 선에 서야 한다(ADR-0256).
   툴팁은 폭을 묶어 문장이 몇 줄로 접힌다 */
.q-btn {
    width: 16px; height: 16px; margin-left: 8px; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center; vertical-align: middle; flex-shrink: 0;
    border: 1px solid var(--border-secondary); background: var(--bg-tertiary);
    font-size: var(--fs-xs); font-weight: normal; line-height: 1; color: var(--text-secondary);
}
.q-btn:hover { border-color: var(--border-highlight); color: var(--text-primary); }
.q-btn:focus-visible { outline: 2px solid var(--border-highlight); outline-offset: 2px; color: var(--text-primary); }
.tip-card.q-tip { max-width: 300px; }
.tip-card.q-tip .tip-effect-summary { white-space: normal; word-break: keep-all; }   /* 한글이 낱말 가운데서 안 끊긴다 */
/* 편성 고르개 — **박스의 첫 줄** (ADR-0251 — 진형 칸 안에서 올렸다). 아래 셋(진형 · 물약 · 전술)을 전부 가르므로 셋 위에 한 줄로 선다 */
.pt-body > .pt-pick { flex-wrap: nowrap; }
/* 물약 — 칸은 아레나 칸(`.p-slot`)과 같은 생김새 · 여기서는 끌어다 놓는 자리라 한 단 크다 */
.pt-potion-row { display: flex; align-items: center; gap: 30px; flex-wrap: wrap; }
/* 칸 줄 + 기준 줄 — 기준 줄이 칸 줄 왼쪽 끝에 맞춰 바로 아래 선다 (§15 · ADR-0942) */
.pt-potion-left { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; }
.pt-use { display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); color: var(--text-secondary); }
.pt-use-btn { padding: 0 6px; min-width: 0; }
.pt-use-val { font-variant-numeric: tabular-nums; }
.pt-potion .pt-slot { width: 44px; height: 44px; cursor: pointer; touch-action: none; }
.pt-potion .pt-lock { width: 44px; height: 44px; cursor: pointer; }   /* 안 열린 칸 — 같은 크기 · 누르면 여는 건물 랭크 플래시 (ADR-0716) */
.pt-potion .pt-slot:not(.full) { cursor: default; }
/* 모자람 — 재고보다 많이 넣은 칸. 막지 않고 흐리게 세운다(런에서 빈 채 시작한다 · ADR-0195) */
.pt-potion .pt-slot.short { opacity: .4; border-style: dashed; }
.pt-potion .pt-slot.drag { opacity: .35; }
.pt-stock { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-size: var(--fs-xs); color: var(--text-secondary); }
.pt-stock .p-stock { cursor: pointer; touch-action: none; }
.pt-stock .p-stock .p-slot { width: 36px; height: 36px; }
.pt-stock .p-stock.zero { opacity: .45; }
.pt-stock .p-stock.drag { opacity: .35; }
/* 파티 전술 칸은 **세로 목록**이다 [2026-09-21 사용자 지시 · ADR-0260] — 칸 하나가 한 행 · 행 수는 칸 수(`tactic_slot.csv` 행 수).
   세로줄 넷(켜짐 · 등급 | 조건 + 카운터 | 효과 | 리롤 — 칸 번호는 안 적는다 · ADR-0261)은 **목록이 들고** 행은 그것을 빌린다(subgrid) — 모든 행에서 같은 자리에 서야
   일곱 칸을 위에서 아래로 훑어 견준다. 조건 · 효과는 글이 길면 **그 행 안에서** 줄을 바꾼다(칸 폭은 안 준다 — 행이 높아진다).
   글자는 연구 노드(`.rs-cell` 공용)보다 한 단 작다(--fs-xs). 행 높이는 위아래 여백이 준다 — 오른쪽 열 아래가 남아
   한 단 키웠다 [2026-09-21 사용자 지시 「좀만 더 키워보자」] · 일곱 행이 오른쪽 열 안에 드는 것은 그대로 지킨다 */
/* 세로줄 여섯 — 등급 · 켜짐 | 조건 | 카운터 | 효과 | 리더 보너스 | 잠금 · **전부 왼쪽 정렬** [2026-10-24 사용자 「다같이 칸 맞춰서 왼쪽정렬」 · ADR-0757].
   **칸은 전부 내용 폭**(조건은 열 폭의 일부까지 — 넘치면 줄을 바꾼다)이고 **남는 폭은 칸 사이에 고르게** 나눈다 — 한 칸이 다 먹으면
   행이 왼쪽 · 오른쪽 두 덩어리로 갈린다 [2026-10-24 사용자 「왼쪽 오른쪽 너무 극명하게 나뉘었잖아」 · ADR-0758] */
.pt-tactics .rs-grid { grid-template-columns: max-content fit-content(42%) max-content max-content max-content max-content; justify-content: space-between; gap: 8px 10px; }
.pt-tactics .rs-cond { justify-content: flex-start; }
.pt-tactics .rs-cnt-c, .pt-tactics .rs-eff, .pt-tactics .rs-lead { justify-self: start; white-space: nowrap; }
.pt-tactics .rs-cnt-c { font-size: calc(var(--fs-xs) + 1px); }
/* 리더 보너스 칸 — 효과 오른쪽 (§15 · ADR-0757) · 더하면 성공색 · 빼면 오류색 · 0 · 곡선을 안 받는 칸(「—」)은 흐림 */
.pt-tactics .rs-lead { font-size: calc(var(--fs-xs) + 1px); color: var(--text-secondary); }
.pt-tactics .rs-lead.up { color: var(--color-success); }
.pt-tactics .rs-lead.down { color: var(--color-error); }
.pt-tactics .rs-lead.muted { color: var(--text-muted); }
/* 「추가 버프」 — 「파티 전술」 소제목 줄 오른쪽 끝 · 올리면 받는 보너스 툴팁 (ADR-0757) */
.pt-tactics > .sub-h { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.rs-buff-btn {
    font-size: var(--fs-xs); font-weight: normal; color: var(--text-secondary); cursor: help;
    border: 1px solid var(--border-secondary); border-radius: 3px; padding: 1px 7px;
}
.rs-buff-btn:hover { color: var(--text-primary); border-color: var(--border-highlight); }
.pt-tactics .rs-cell { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; padding: 11px 12px; column-gap: normal; }   /* 목록의 칸 사이(gap + 고르게 나눈 폭)를 그대로 — 공용 `.rs-cell` 의 gap 5px 이 덮으면 열 이름 줄과 어긋난다 (ADR-0763) */
.pt-tactics .rs-top { gap: 6px; }
.pt-tactics .rs-state { margin-left: 0; min-width: 3ch; }   /* 맨 왼쪽 (2026-09-27) — On · Off 글자 폭이 달라도 등급 칩이 같은 자리에 선다 */
.pt-tactics .rs-roll { margin-top: 0; justify-self: end; }
.pt-tactics .rs-lock { grid-column: 1 / -1; margin-top: 0; }   /* 잠긴 행은 여는 조건 한 줄 — 첫 세로줄부터 선다 (ADR-0261) */
/* 전체 리롤 — 진척 줄 오른쪽 끝 (§15 · ADR-0763 · ~~진척 줄 아래 리롤 줄~~) */
.pt-tactics .rs-head .rs-roll { margin-left: auto; align-self: center; }
/* 열 이름 줄 — 칸 목록과 같은 격자(subgrid) · 좌우 여백 = 칸 행의 여백 + 테두리 1px · 잠금만 오른쪽 끝 (ADR-0763) */
.pt-tactics .rs-colh {
    grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: end;
    padding: 0 13px; font-size: var(--fs-xs); color: var(--text-muted); white-space: nowrap;
}
.pt-tactics .rs-colh .c-lock { justify-self: end; }
/* 잠금 토글 — 행의 넷째 칸. 잠근 칸은 버튼이 강조되고 행 왼쪽에 경고색 선이 선다 (`.locked` = 안 열린 칸과는 다른 말이다) */
.pt-tactics .rs-pin { justify-self: end; }
.rs-pin.on { color: var(--text-primary); border-color: var(--border-highlight); }
/* 자물쇠 아이콘 (2026-09-27) — 열린 자물쇠는 흐리게 · 닫힌 자물쇠는 경고색(행 왼쪽 선과 같은 색) */
.rs-pin { display: inline-flex; align-items: center; justify-content: center; padding: 3px 6px; color: var(--text-muted); }
.rs-pin.on { color: var(--color-warning); }
.rs-pin-ico { display: block; }
.rs-cell.held { box-shadow: inset 3px 0 0 var(--color-warning); }
.pt-tactics .rs-cond, .pt-tactics .rs-eff, .pt-tactics .rs-lock { font-size: calc(var(--fs-xs) + 1px); }   /* 한 단 아래 +1px (2026-09-27 사용자 지시) */
/* 잠긴 행 — 왼쪽에 닫힌 자물쇠(`lockIcon` · 회색 · ADR-0925) + 여는 조건 한 줄 */
.pt-tactics .rs-lock { display: flex; align-items: center; gap: 6px; }
.pt-tactics .rs-lock .rs-pin-ico { width: 1.1em; height: 1.1em; flex: none; }
/* 「원정 중」 — 도는 원정의 편성 번호에 붙는다. 영웅 띠의 「원정 중」(`.hs-doing.exp`)과 같은 색 */
.pt-run { margin-left: 6px; font-size: var(--fs-2xs); color: var(--color-warning); }
/* 출정 창의 편성 고르개 (SCREEN_DESIGN §4-1 · ADR-0193) — 버튼 세로 · 초상 셋. 초상은 진형 · 적 구성 칸과 같은 한 변이라 적 구성과 마주 선다 */
/* 틈은 초상 사이 틈(7)과 같다 · 버튼 기둥 폭도 초상 한 변이라 **영웅 셋이 적 구성 둘째 ~ 넷째 칸 바로 아래**에 선다 [2026-09-21 · ADR-0283] —
   옛 판은 기둥이 글자 폭(6em)에 틈 18 이라 초상이 적 칸과 어긋나 섰다 */
.pk-row { display: flex; align-items: flex-start; gap: 7px; }
/* 버튼 기둥은 **초상 한 변**(`--fm-slot`) 높이다 [2026-09-21 사용자 지시 · ADR-0283].
   버튼 하나 = 기둥을 **편성이 다 열렸을 때의 개수**(`--pk-n` — 렌더러가 `limitsOf` 에 다 지은 랭크를 물어 넣는다)로 나눈 높이다
   [2026-09-29 사용자 지시 「파티 개수가 1개여도 3개일 때처럼의 높이로」 · ADR-0442] — 다 열리면 위아래가 초상과 딱 떨어지고,
   덜 열렸으면 버튼이 위에서부터 서고 아래가 빈다. 옛 식(`flex: 1 1 0` — 지금 개수로 나눔)은 편성 하나일 때 버튼 하나가 초상 높이로 섰다 */
.pk-btns { display: flex; flex-direction: column; gap: 7px; flex: 0 0 var(--fm-slot); width: var(--fm-slot); height: var(--fm-slot); }
.pk-btns .btn { min-width: 0; text-align: left; flex: 0 0 calc((var(--fm-slot) - 7px * (var(--pk-n, 1) - 1)) / var(--pk-n, 1)); min-height: 0; padding-top: 0; padding-bottom: 0; }
.pk-faces { display: flex; gap: 7px; }
.pk-face {
    position: relative; overflow: hidden; flex: 0 0 auto;
    width: var(--fm-slot); height: var(--fm-slot);
    background: var(--bg-tertiary); border: 1px solid var(--border-dark); border-top: 3px solid var(--border-secondary);
}
/* 빈 자리 — 진형 빈 칸과 같은 점선. 셋만큼 자리를 늘 잡아 창이 편성마다 넓어졌다 좁아졌다 하지 않는다 */
.pk-face.empty { border: 1px dashed var(--border-secondary); background: var(--bg-secondary); }
.pk-face .hero-face { width: 100%; height: 100%; border: 0; background: var(--bg-input); }

/* ───────── 연구 탭 — 파티 전술 (2026-08-30 · SCREEN_DESIGN §13) ─────────
   칸 수는 `tactic_slot.csv` 행 수다 — 격자는 행 수에 맞춰 접히고 잠긴 칸도 자리를 지킨다.
   칸 폭은 고정 px 이 아니라 `minmax()` — 영어 조건 문장이 한국어보다 길다 (src/ui/README 폭 정책) */
.rs-head {
    display: flex; align-items: baseline; gap: 18px; flex-wrap: wrap;
    font-size: var(--fs-sm); color: var(--text-secondary);
    padding-bottom: 9px; margin-bottom: 11px; border-bottom: 1px solid var(--border-dark);
}
.rs-head b { color: var(--text-primary); font-size: var(--fs-md); }

.rs-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 8px; }

.rs-cell {
    display: flex; flex-direction: column; gap: 5px; min-width: 0;
    padding: 9px 10px 10px;
    background: var(--bg-tertiary); border: 1px solid var(--border-primary);
}
/* 켜짐/꺼짐이 칸의 첫인상 — 켜진 칸만 테두리가 산다 (죄종 색은 쓰지 않는다, 전술은 파티 것이다) */
.rs-cell.on { background: var(--surface-1); border-color: var(--border-highlight); }
.rs-cell.off { opacity: .82; }
.rs-cell.locked {
    opacity: .6; background: rgba(var(--tint-rgb), .015);
    border-style: dashed; justify-content: flex-start;
}

.rs-top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.rs-no { font-size: var(--fs-xs); color: var(--text-muted); }
.rs-state { font-size: var(--fs-xs); color: var(--text-muted); margin-left: auto; }
/* 전술 옵션 등급 — 색은 아이템 희귀도에서 빌리되 축은 별개다 (SCREEN_DESIGN §13-2 · tactic_card_design §5-5) */
.rs-grade {
    font-size: var(--fs-xs); padding: 0 5px; border-radius: 3px;
    border: 1px solid currentColor; color: var(--text-muted);
}
.rs-grade.magic { color: var(--rarity-magic); }
.rs-grade.rare { color: var(--rarity-rare); }
.rs-cell.on .rs-state { color: var(--color-success); }
.rs-cell.off .rs-state { color: var(--color-error); }   /* Off 는 빨강 (2026-09-27 사용자 지시 · §15) */

.rs-cond {
    display: flex; align-items: baseline; justify-content: space-between; gap: 8px;
    font-size: var(--fs-sm); color: var(--text-secondary); word-break: keep-all;
}
/* 조건 카운터 「지금 / 필요」 — 안 보이면 조건이 함정이 된다 (tactic_card_design §4) */
.rs-cnt { flex: none; font-size: var(--fs-xs); color: var(--text-muted); }
.rs-cell.on .rs-cnt { color: var(--color-info); }
.rs-eff { font-size: var(--fs-sm); color: var(--color-info); }
.rs-lock { font-size: var(--fs-sm); color: var(--text-muted); margin-top: 4px; }
.rs-cond .no { color: var(--color-error); }   /* 건설 비용 중 모자란 재화 (§13 · R137) */
.rs-roll { align-self: flex-start; margin-top: 3px; }

/* 도서관 — **영웅 띠 아래 두 열**(SCREEN_DESIGN §17 · ADR-0567 — ~~훈련장 탭~~ 은 걷혔다) — 왼쪽 = 전직 패널 · 오른쪽 열 = 스킬 업그레이드 · 스킬 북 제작 카드가 위아래
   (2026-10-12 사용자 지시 「전직을 왼쪽, 가진책 기본 책 만들기를 오른쪽으로」 · ADR-0595).
   왼쪽 = 위 영웅 띠 카드 7칸 — 오른쪽 끝이 띠 일곱째 칸의 오른쪽 끝에 맞는다 · 오른쪽 열이 나머지 (2026-10-27 사용자 지시 「전직창 가로 길이를 위의 캐릭터카드 7칸까지」 ·
   ADR-0852 — ~~3 : 2~~ ADR-0538). 13px = 띠 패널 테두리 1 + 안 여백 12(`.hs-panel`) · 칸은 늘 상한 폭이다(로스터 상한을 다 채워도 띠 폭 안에 든다).
   열마다 띠 아래 남는 세로까지 서고 넘치면 제 본문이 스크롤한다 */
.c-train-band { grid-template-columns: calc(13px + 7 * var(--hs-card-max) + 6 * var(--hs-gap)) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); min-height: 0; }
.c-train-band > .panel, .lib-col > .panel { display: flex; flex-direction: column; min-height: 0; }
.lib-col { display: flex; flex-direction: column; gap: 14px; min-height: 0; }
/* 스킬 업그레이드(위) · 스킬 북 제작(아래)은 **높이가 같다** — 남는 세로를 반씩 나누고 넘치면 제 본문이 스크롤한다
   (2026-10-12 사용자 지시 「높이 같게」 · ADR-0598 — ~~제작 카드는 제 내용 높이~~ ADR-0573) */
.lib-col > .panel { flex: 1 1 0; }
.lib-col > .panel + .panel { margin-top: 0; }
/* 전직 패널 (§17 · R16) — 고른 영웅 줄 · 지금 가진 스킬(카드 셋 · ADR-0595) · 갈래 자리 = 갈래 셋(전직 전 · 전직 후 — 전직한 갈래는 주황 테두리) · 막대(전직하는 중) */
/* 세로 — 이름 줄 · 지금 가진 스킬(ADR-0595) 아래 **갈래 자리가 남는 세로를 받고 카드 셋이 그것을 나눠 채운다**(사이도 조금 띄운다).
   카드는 제 내용보다 작아지지 않는다(`1fr` = 내용 이상) — 모자라면 본문이 스크롤한다 [2026-10-12 사용자 「맨 아래 박스 아래선이 짤림」 →
   「카드들의 높이를 약간씩 늘리고 사이 거리도 약간 늘려서 아래공간 다 써봐」 · ADR-0607]. 스킬 설명 칸을 넓혀 영어에서도 한 줄에 든다 */
.tr-adv-body { display: flex; flex-direction: column; }
.tr-adv-main { flex: 1 0 auto; display: flex; flex-direction: column; }
.tr-adv-hero { display: flex; align-items: baseline; gap: 10px; margin-bottom: 6px; }
.tr-adv-cur { display: flex; align-items: flex-start; gap: 16px; margin-bottom: 8px; }   /* 스킬 왼쪽 · 골드와 [전직] 오른쪽 끝, 같은 높이(ADR-1000) · 아래 갈래 자리만 잠김 베일(ADR-0595) */
.tr-adv-cur > .sk-cards { flex: 1 1 auto; min-width: 0; }
.tr-adv-actions { display: flex; align-items: center; gap: 12px; margin-left: auto; flex: none; }
.tr-adv-hero b { color: var(--text-primary); }
.tr-adv-hero .no { color: var(--color-warning); }
/* 갈래는 세로로 쌓인다 · 갈래마다 가로로 긴 카드 = 왼쪽 칸(갈래 이름 + 설명) | 오른쪽 스킬 줄 셋 (ADR-0402 · ADR-0403) */
/* 왼쪽 1 : 오른쪽 4 — **스킬 설명은 한 줄**이다. 갈래 설명이 몇 줄 더 접히는 대신 설명 칸이 넓다 · 말줄임은 안 쓴다
   (2026-10-27 사용자 지시 「전직스킬 모든 설명이 1줄을 넘어가지 않도록」 · ADR-0852 — ~~2 : 5~~) */
/* 갈래 카드 셋은 **높이가 같다** — 가장 긴 카드에 맞춘다(설명이 두 줄로 접힌 스킬이 한 카드만 늘리지 않게 · 2026-10-08 사용자 지시 · ADR-0538) */
/* 갈래는 **테두리 · 바탕이 없고 갈래마다 위에 가로 구분선 하나**(패널 제목 밑줄과 같은 선) — 빈 간격 없이 선이 셋을 나눈다
   (2026-10-25 사용자 지시 「네모낳게 둘러쳐있는데 사이 구분선으로 깔끔하게」 · ADR-0783 — ~~카드 테두리 · 사이 10px~~ ADR-0402 · ADR-0607).
   첫 갈래 위에도 선다 — 지금 가진 스킬과 갈래 셋 사이 (같은 날 「광전사 위에도 선하나」 · ADR-0784 — ~~갈래 사이만~~ ADR-0783) */
.tr-adv-row { flex: 1 0 auto; display: grid; grid-auto-rows: 1fr; }
.tr-adv-branch { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 4fr); gap: 12px; padding: 4px 10px; border-top: 1px solid var(--border-primary); }
/* 전직 전 — 카드를 눌러 갈래를 고른다(ADR-0536) · 고른 것은 파란 테두리(아래 `.pick`) · 올리면 바탕이 조금 밝다(테두리가 없다 · ADR-0783) */
.tr-adv-branch.can-pick { cursor: pointer; }
.tr-adv-branch.can-pick:hover { background: var(--surface-5); }
/* 고른 테두리는 카드 **안쪽**에 그린다 — 카드가 스크롤 본문(`.box-body` · overflow)의 양 끝에 붙어 바깥 테두리는 잘렸다 (ADR-0538) */
.tr-adv-branch.pick { outline: 3px solid var(--color-info); outline-offset: -3px; }   /* 카드 안쪽에 선다 — 띄움 = 굵기 (ADR-0926) */
/* 전직 후 — 갈래 셋이 그대로 서고 **전직한 갈래만 주황 테두리**(같은 안쪽 자리 · 나머지 둘은 평소 카드 · 누를 것이 없다) (2026-10-12 사용자 지시 · ADR-0592) */
.tr-adv-branch.done { outline: 2px solid var(--color-chosen); outline-offset: -2px; }
.tr-adv-go { flex: none; font-weight: normal; }   /* 스킬 줄 오른쪽 끝 · 골드 바로 오른쪽 (ADR-1000) */
.tr-adv-bh { display: flex; flex-direction: column; justify-content: center; gap: 4px; }
.tr-adv-bdesc { font-size: var(--fs-xs); color: var(--text-muted); line-height: 1.5; }
.tr-adv-bh b { color: var(--text-primary); }
.tr-adv-sks { display: flex; flex-direction: column; justify-content: center; gap: 2px; min-width: 0; }   /* 키를 맞춰 남는 세로는 위아래로 나눈다 */
.tr-adv-sk { display: flex; align-items: center; gap: 8px; min-width: 0; }
.tr-adv-ico { position: relative; flex: none; width: 32px; height: 32px; display: grid; place-items: center; background: var(--bg-input); border: 1px solid var(--border-dark); }
.tr-adv-ico img, .tr-adv-ico .sk-noart { width: 100%; height: 100%; object-fit: contain; }
.tr-adv-tx { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.tr-adv-nm { font-weight: 500; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tr-adv-desc { font-size: var(--fs-xs); color: var(--text-muted); line-height: 1.3; }
.tr-adv-act { flex: none; display: flex; align-items: center; gap: 6px; }
.tr-adv-got { color: var(--text-accent); font-size: var(--fs-xs); }
.tr-adv-work { display: flex; flex-direction: column; gap: 6px; max-width: 420px; }
.tr-adv-bar { position: relative; display: block; height: 6px; background: var(--bg-input); }
.tr-adv-bar > b { position: absolute; inset: 0 auto 0 0; background: var(--color-progress); }
.tr-adv-why { margin-top: 8px; }

/* 건설 — **부지 격자 | 상세** (SCREEN_DESIGN §13-1 · ADR-0304 — ADR-0302 의 가로 카드 줄을 대체).
   두 열이 박스 끝까지 서고 **각 열이 제 안에서** 스크롤한다 — 상세가 길어도 부지 격자는 안 밀린다.
   상세 폭은 `minmax()` — 영어 조건 문장이 한국어보다 길다 (src/ui/README 폭 정책) */
.cn-work {
    flex: 1 1 0; min-height: 0;
    /* 부지 | 상세가 폭을 거의 반씩 · 사이를 넉넉히 (2026-09-24 사용자 지시 「왼쪽이 너무 답답해 보여」 — ~~상세 1.25 · 간격 12~~ ADR-0326).
       **상세는 반에서 100px 좁고** 오른쪽 끝이 판에 붙는다 · 왼쪽 열은 나머지 전부이고 **부지 격자가 그 열을 채운다**(`.cn-lots` 의 폭 — 상세와의 사이 `--cn-gap` 만 남긴다 · ADR-0747)
       (2026-09-24 사용자 지시 「오른쪽 넓이를 줄여」 → 「더 줄여」 → 「100px 까지」 → 「그림 가로를 살짝만」 → 가운데에 세워 본 뒤 「다시 왼쪽에 맞춰」) */
    display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, calc((100% - 24px) / 2 - 100px)); grid-template-rows: minmax(0, 1fr); gap: 0;
}
/* 박스 — 한 장의 남는 세로를 다 받는다(`.page-stack > .fill` · 영웅 띠는 없다 — ADR-0354). 안은 두 열 */
/* **부지 둘레는 한 값(`--cn-gap` 22)** — 박스 위 · 왼쪽 여백 · 칸 사이 · 줄 사이 · 상세와의 사이가 같다 (2026-10-24 사용자 지시 「위랑 왼쪽이 너무 좁은데」 · ADR-0747).
   위 여백은 상세에도 걸려 두 열의 윗변이 같다 · 오른쪽 · 아래는 패널 여백 그대로(상세가 판 오른쪽 끝에 붙는다).
   22 가 상한이다 — 값이 1 늘면 상세 머리(아래 `.cn-head`)와 위 여백이 1 씩 먹어 랭크 목록이 2 준다 · 23 이면 선술집(두 줄 랭크 넷)의 목록이 스크롤한다 (1600×800 실측) */
.cn-box { --cn-gap: 22px; display: flex; flex-direction: column; padding-top: var(--cn-gap); padding-left: var(--cn-gap); }
/* 부지 판 = 제목 띠 + 격자 (ADR-0919) · 판의 폭 = 왼쪽 열 − 칸 사이 하나 — 남는 폭이 상세와의 사이다 · 격자는 띠 아래 남는 세로에서 스크롤한다 */
.cn-work > .cn-lotbox { width: calc(100% - var(--cn-gap)); justify-self: start; display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.cn-lotbox > .cn-lots { flex: 1 1 0; }
/* 제목 띠 — 두 판 맨 위 (ADR-0919). 모양은 판 제목 규칙(`.panel > h2, .sub-h`) · **글자는 상세의 +2 를 안 탄다**(다른 탭 판 제목과 같은 크기 — 그래서 두 띠의 높이가 같다).
   띠 아래 틈(`--cn-title-gap`)도 두 판이 같다 — 상세 그림 윗변 · 두 소제목이 부지 줄과 맞는 자리(§13-1 「높이」)가 띠만큼 같이 내려간다 */
/*   띠 아래 틈 22 = 부지 둘레(칸 사이 · 줄 사이 · 판 여백)와 같은 값 [2026-10-27 사용자 「건물들 맨위 위치를 조금만 더 내려줘」] ·
     상세 소제목(다음 랭크 · {건물} 랭크)도 띠 글자와 같은 크기다(`--cn-title-fs` — 상세의 +2 를 안 탄다 · 사용자 「맨 위의 제목과 동일한 크기로」 · ADR-0923) */
.cn-box { --cn-title-gap: 22px; --cn-title-fs: var(--fs-md); }
.cn-side .cn-sub { font-size: var(--cn-title-fs); }
.cn-title { flex: none; display: flex; align-items: baseline; justify-content: space-between; gap: 10px; min-width: 0; margin: 0 0 var(--cn-title-gap); white-space: nowrap; }
.cn-title-name { overflow: hidden; text-overflow: ellipsis; }
.cn-title-state { flex: none; font-size: var(--fs-xs); color: var(--color-progress); }
.cn-title:not(.on) .cn-title-state { color: var(--text-muted); }
/*   상세 띠는 상세 상자의 위 · 옆 안쪽 끝까지(부지 띠와 같은 높이) · 아래 틈은 상자 위 여백(12 − 테두리 1)만큼 더 — 그림이 부지 첫 줄보다 12 아래인 자리 그대로 띠만큼 내려간다 */
.cn-side > .cn-title { margin: -12px -14px calc(var(--cn-title-gap) + 11px); padding-left: 14px; padding-right: 14px; }
/* 부지 — 건물 하나가 네모 하나 · **한 줄에 3개**(3열 · 폭은 열이 나눠 갖는다 · 2026-09-24 사용자 지시 · ADR-0326) · **높이는 148 고정** (2026-09-23 사용자 지시 「세로는 고정」).
   **격자는 늘 3 × 4 = 12칸** — 빈 칸은 빈 부지(`.cn-lot.empty`)가 채운다. **칸 사이 · 줄 사이 = `--cn-gap`** — 네 줄(148 × 4 + 22 × 3 = 658)이 격자 세로(한 장 기준 767)에 들고 아래는 빈다
   (2026-10-24 사용자 지시 「그림별 거리를 조금만 더」 · 「5번째 칸 없애고 세로끼리도 좀만 더」 · ADR-0745 · ADR-0747). 건물이 12를 넘으면 줄이 늘고 격자가 스크롤한다 */
.cn-lots {
    display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-rows: 148px; align-content: start; gap: var(--cn-gap);
    overflow-y: auto; min-height: 0;
}
.cn-lot {
    position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; min-width: 0;
    padding: 8px 6px; font: inherit; color: var(--text-primary); text-align: center; cursor: pointer;
    background: var(--bg-tertiary); border: 1px dashed var(--border-primary);
}
.cn-lot:hover { border-color: var(--border-highlight); }
.cn-lot.on { background: var(--surface-1); border-style: solid; border-color: var(--border-secondary); }
.cn-lot.locked { opacity: .55; }
/* 고른 부지 — 파란 3px 테두리가 칸 테두리를 대신한다 · 굵어진 몫만큼 안쪽 여백을 줄인다(그림 부지는 여백이 없어 테가 그림 끝을 덮는다) (§2 「고른 표시」 · ADR-0927) */
.cn-lot.pick { border: 3px solid var(--color-info); padding: 6px 4px; opacity: 1; }
/* 빈 부지 — 건물이 없는 칸. 점선 네모만 · 누르지 않는다 (2026-09-24 사용자 지시 — 격자를 15칸으로 채운다) */
.cn-lot.empty { background: transparent; cursor: default; }
.cn-lot.empty:hover { border-color: var(--border-primary); }
/* 지금 지을 수 있다 — 모서리 점 하나(글 없이). 조건 · 재화가 다 맞는 건물만 (`next.err` 없음) */
.cn-lot.ready::after {
    content: ''; position: absolute; top: 6px; right: 6px; width: 7px; height: 7px; border-radius: 50%;
    background: var(--color-success);
}
.cn-lot .rs-art { height: 38px; align-items: center; }
.cn-lot-foot { display: flex; flex-direction: column; align-items: center; gap: 5px; width: 100%; }
.cn-lot-name { font-size: var(--fs-sm); line-height: 1.2; }
/* 그림 부지 — 그림이 네모를 꽉 채운다(`cover` · 3:2 네모라 4:3 그림의 위아래가 조금 잘린다) · 이름 · 막대는 아래 어두운 띠 위에 선다 (2026-09-23 사용자 지시).
   안 지은 부지는 그림 위에 베일을 한 겹 더 얹어 어둡다 — 지었나가 그림에서도 읽힌다 */
.cn-lot.has-img { justify-content: flex-end; padding: 0; overflow: hidden; background: var(--lot-img) center 40% / cover no-repeat, var(--bg-tertiary); }
.cn-lot.has-img:not(.on) { background: linear-gradient(rgba(var(--veil-rgb), .55), rgba(var(--veil-rgb), .55)), var(--lot-img) center 40% / cover no-repeat, var(--bg-tertiary); }
.cn-lot.has-img .cn-lot-foot { padding: 18px 6px 8px; background: linear-gradient(to top, rgba(var(--veil-rgb), .92) 50%, rgba(var(--veil-rgb), 0)); }
.cn-lot.has-img .cn-lot-name { text-shadow: 0 1px 2px rgba(var(--shadow-rgb), .9); }
.cn-lot.has-img.ready::after { z-index: 1; box-shadow: 0 0 0 2px rgba(var(--shadow-rgb), .8); }
/* 랭크 눈금 = 진행 막대 — 최대 랭크만큼 칸 · 지은 만큼 주황으로 찬다. 부지에선 막대가 숫자(n / 최대)를 대신한다 (2026-09-23 사용자 지시).
   **칸 하나의 크기가 모든 건물에서 같다** — 막대 길이가 랭크 수(2 ~ 9)를 따른다 (ADR-0313). 칸이 자리보다 많으면 줄어든다(넘치지 않는다) */
.cn-pips { display: flex; gap: 3px; max-width: 100%; }
.cn-pips span { flex: 0 1 auto; width: 16px; min-width: 3px; height: 7px; background: var(--border-primary); }   /* 폭은 `width` 로 — 빈 칸의 `flex-basis` 는 막대의 제 폭(가운데 정렬의 기준)에 안 잡힌다 */
.cn-pips span.on { background: var(--color-progress); }
.cn-lot .cn-pips { margin-top: 3px; }
/* 상세 — 고른 건물 하나. 위에서 아래로 셋 — 머리 · 「다음 랭크」 · 「{건물} 랭크」 목록 (ADR-0323).
   머리와 다음 랭크는 서 있고 **랭크 목록만** 스크롤한다 */
/* 글자는 상세 안에서만 한 벌 +2px — 크기 토큰을 여기서 다시 선언해 안쪽 규칙(`--fs-*`)과 소제목(`.sub-h`)이 다 따라간다 (2026-09-27 사용자 지시 「오른쪽 탭 글씨 2px 씩 키워」) */
.cn-side > :not(.cn-title) { --fs-xs: 14px; --fs-sm: 15px; --fs-md: 17px; --fs-lg: 20px; }   /* 제목 띠는 빼고 — 다른 판 제목과 같은 크기 (ADR-0919) */
.cn-side {
    display: flex; flex-direction: column; min-width: 0; min-height: 0; overflow: hidden;
    padding: 12px 14px;
    background: var(--bg-secondary); border: 1px solid var(--border-primary);
}
/* 머리 — 그림(부지와 같은 그림 · 3:2) + 바로 아래 눈금 · 이름 · 상태 한 줄(미건설 · n랭크 · 최대 랭크) · 기능 칸(ADR-0383). 안 지었으면 그림이 어둡고 테두리가 점선.
   **그림 + 눈금 = 127** — 그림 114 + 틈 6 + 눈금 7 (아래 문장의 127 은 이 합이다).
   **그림 + 눈금 127 = 아래 두 소제목의 글자 윗선이 부지 둘째 줄 네모의 윗변(148 + 22)에 서는 값** (2026-09-24 사용자 지시 · 한 장 실측 · 줄 사이 9 때 114 → 22 에서 127 (ADR-0747) — 둘째 줄 윗변이 움직인 만큼 같이 움직인다).
   머리 높이는 그림이 정한다 — 부지 네모 높이 · 줄 사이 · `.cn-side` 위 여백 · `.cn-head` 아래 여백 · `.sub-h` 위 여백이 바뀌면 다시 잰다 */
.cn-head { flex: none; display: flex; align-items: flex-start; gap: 16px; margin-bottom: 12px; --cn-thumb-h: 114px; --cn-head-h: 127px; }
.cn-thumb-col { flex: none; display: flex; flex-direction: column; gap: 6px; }
.cn-thumb {
    flex: none; width: calc(var(--cn-thumb-h) * 1.5); height: var(--cn-thumb-h); display: flex; align-items: center; justify-content: center;
    background: var(--bg-tertiary) center 40% / cover no-repeat; border: 1px solid var(--border-secondary);
}
.cn-head:not(.on) .cn-thumb { border-style: dashed; border-color: var(--border-primary); filter: brightness(.55); }
.cn-thumb .rs-art { height: 72px; }
/* 그림 오른쪽 한 영역 — 기능 목록 · 높이는 그림 + 눈금 (ADR-0386 · 이름 · 상태는 위 제목 띠 — ADR-0919) */
.cn-head-info { flex: 1 1 0; min-width: 0; height: var(--cn-head-h); display: flex; flex-direction: column; gap: 8px; }
/* 기능 목록 — 이름 줄 아래 · 소제목 · 테두리 · 바탕 없이 두 단 · 넘치면 제 안에서 스크롤 (ADR-0386) */
.cn-cur { flex: 1 1 0; min-height: 0; overflow-y: auto; }
.cn-cur .cn-eff-t { display: block; columns: 2; column-gap: 20px; color: var(--text-secondary); }
.cn-cur .cn-desc { break-inside: avoid; padding: 1px 0; }
/* 절 제목 — 게임의 소제목(`.sub-h` — 굵은 글 · 아래 선) 그대로 · 자리 여백만 */
.cn-sub { flex: none; margin-bottom: 8px; }
/* 건물 실루엣 — 그림(`mock.js:BUILDING_IMAGES`)이 없는 건물의 폴백(`mock.js:BUILDING_ART` 의 SVG). 채움은 글자색을 따라 테마를 탄다 */
.rs-art { display: flex; justify-content: center; align-items: flex-end; height: 58px; color: var(--text-secondary); }
.rs-art svg { height: 100%; width: auto; fill: currentColor; }
/* 「다음 랭크」 — 여는 것 · 조건 전부 · 재료 칸 · [건설]. 짓는 결정에 필요한 것이 한 자리에 모인다 (ADR-0323) */
/* 머리 아래는 한 열 — 「다음 랭크」 위 · 「{건물} 랭크」 목록 아래 · 목록만 스크롤한다 (ADR-0388) */
.cn-next .cn-sub { margin-bottom: 0; }
.cn-next { flex: none; display: flex; flex-direction: column; gap: 8px; margin-bottom: 0; }   /* 아래 여백 0 — 랭크 목록을 위로 올려 2.2줄 칸 일곱이 바닥 안에 든다 (2026-09-28 · ~~18~~) */   /* 머리 아래 위 칸 (ADR-0388) */
/* 「다음 랭크」 높이 고정 — 가장 긴 판(대장간 IV: 여는 것 4줄 + 조건 한 줄)에 맞춘다 · 그래서 「{건물} 랭크」 소제목이 건물 · 랭크와 상관없이 늘 같은 자리다 (2026-09-28 사용자 지시 「다음 랭크의 최종 하단을 확정」 · 1600×800 실측). 여는 것이 더 길어지면 다시 잰다 */
.cn-next { min-height: 204px; }
/* 「n랭크」 아래 여는 것 설명 — 한 줄에 한 문장 · 상자 없이 글이다 (ADR-0324 · ADR-0325).
   **소제목 아래 글은 전부 `--fs-xs`** — 소제목(`--fs-md` 굵게)보다 눈에 띄게 작다 · 강조는 색 · 굵기가 든다 (2026-09-24 사용자 지시 「부제목보다 크거나 비슷하면 … 더 작아야 해」 · ~~`--fs-md` · `--fs-sm`~~) */
.cn-next-top { display: flex; flex-direction: column; gap: 3px; }
.cn-next-top .cn-rno { align-self: flex-start; color: var(--text-accent); }
.cn-next-top.pending .cn-rno { color: var(--text-muted); }
.cn-reqs { display: flex; flex-wrap: wrap; gap: 3px 14px; font-size: var(--fs-xs); }
.cn-req.ok { color: var(--color-success); }
.cn-req.no { color: var(--color-warning); }
.cn-next-end { font-size: var(--fs-xs); color: var(--text-muted); }
/* 재료 칸 — 재화 그림 칸(한 변 52) · 오른쪽 아래 필요 수량 · 칸 아래 이름과 「보유 n」. 모자라면 칸 테 · 수량 · 보유가 붉다.
   그림(`img`) = 제작 재료는 단계 아이콘(`mock.js:materialIcon`) · 골드 · 가루는 `mock.js:RES_ART` · 낙인만 ⚠ 임시 실루엣(`svg` — 색은 재화 종류 `.res-*` 가 준다) */
.cn-mats { display: flex; flex-wrap: wrap; gap: 8px 10px; }
.cn-matw { display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 60px; }
.cn-mat {
    position: relative; width: 52px; height: 52px; display: flex; align-items: center; justify-content: center;
    background: var(--bg-input); border: 1px solid var(--border-secondary); border-radius: 2px;
}
.cn-mat svg { width: 32px; height: 32px; margin-bottom: 6px; fill: currentColor; }
.cn-mat img { display: block; width: 34px; height: 34px; margin-bottom: 6px; object-fit: contain; }
.cn-mat-n {
    position: absolute; right: 3px; bottom: 1px; font-size: var(--fs-xs); font-weight: bold; line-height: 1.2;
    color: var(--text-primary); font-variant-numeric: tabular-nums; text-shadow: 0 1px 2px rgba(var(--shadow-rgb), 1);
}
.cn-mat-name { font-size: var(--fs-xs); line-height: 1.2; color: var(--text-secondary); white-space: nowrap; }
.cn-mat-n { white-space: nowrap; }   /* 「보유/필요」 가 칸 폭을 넘으면 왼쪽으로 삐져나온다 (ADR-0397) */
.cn-matw.no .cn-mat { border-color: var(--color-error); }
.cn-matw.no .cn-mat-n { color: var(--color-error); }
.res-gold { color: var(--color-warning); }
.res-dust { color: var(--text-secondary); }
.res-stigma { color: var(--text-accent); }
.res-ore { color: var(--color-info); }
.res-wood { color: var(--color-progress); }
.res-herb { color: var(--color-success); }
/* [건설] — 작은 주 버튼 · 글자 한 단 작고 폭은 글자만큼 · 왼쪽에 붙는다 (2026-09-24 사용자 지시 「건설 버튼 크기랑 글씨 좀 줄여」 · ~~폭 꽉 채움~~) */
/* 재료 칸 줄 — 재료가 왼쪽 · [건설]이 오른쪽 끝(바닥선 정렬) (ADR-0388) */
/* 「다음 랭크」 두 열 — 왼쪽 글(남은 폭) · 오른쪽 재료 칸 + [건설](글 폭만큼 · 위 정렬) (ADR-0391) */
.cn-next-body { display: flex; align-items: flex-start; gap: 24px; }
.cn-next-main { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 8px; }
.cn-act { flex: none; display: flex; align-items: flex-end; gap: 16px; }
.cn-go { flex: none; min-width: 96px; padding: 3px 18px; font-size: var(--fs-sm); }
/* 랭크 목록 = **글 목록** — 배지 · 태그 · 표 · 칸 상자 없이 글이고 묶음 사이는 가는 선 하나 (ADR-0324).
   **한 묶음 높이 = 글 두 줄** (2026-09-27 사용자 지시 · ADR-0392 — 1600×800 에서 모든 랭크가 한 화면에) · 그래도 넘으면 목록이 스크롤한다 ·
   글이 두 줄을 넘으면 묶음이 제 높이만큼 는다(자르지 않는다). 묶음은 세 세로줄 — 「n랭크」 · 여는 것 글 · 「✓」 · 「준비 중」 — **효과만**이고 조건은 올리면 뜨는 툴팁이 든다(ADR-0347).
   ⚠ 높이는 묶음의 `min-height` 로 준다 — 격자 행으로 주면 행이 글만큼 안 늘어나 겹쳤다(2026-09-24) */
.cn-ranks {
    flex: 1 1 0; min-height: 0; overflow-y: auto;
    display: flex; flex-direction: column;
}
/* 상태는 글자색과 오른쪽 끝 글자가 말한다 — 지음 흰 글씨 + 「✓」(목록의 주황은 조건만 — ADR-0330) · 다음 흰 굵은 글 + 옅은 붉은 바탕 · 그 뒤 · 준비 중 흐림 */
.cn-rank {
    flex: 0 0 auto; font-size: var(--fs-xs); min-height: calc(2 * 1.4em + 9px);   /* 글 두 줄(줄 높이 1.4 · 2026-09-28 사용자 지시 — 일곱 랭크가 목록 바닥까지 찬다 · 박스 위 여백 · 머리가 부지 둘레 22 를 따라 커져 2.2 에서 줄였다 · ADR-0747) + 위아래 여백 8 + 아래 선 1 (ADR-0392) · 늘이지 않는다 — 랭크가 적으면 목록 아래가 빈다 (ADR-0398) */
    display: grid; grid-template-columns: max-content minmax(0, 1fr) auto; align-items: center;
    column-gap: 14px; padding: 4px 8px; line-height: 1.4;
    border-bottom: 1px solid var(--border-dark);
}
.cn-rank.next { background: rgba(var(--accent-rgb), .07); }
/* 그 뒤 · 준비 중 랭크는 줄째 흐리다 — 목록에 조건이 없어 주황을 살릴 까닭이 없다 (ADR-0347 — ~~조건만 빼고 흐림 · ADR-0328~~) */
.cn-rank.later, .cn-rank.pending { opacity: .6; }
/* 조건 툴팁 — 조건 줄뿐 · 「다음 랭크」 의 `.cn-req` 표기 그대로(✓ 초록 · ✗ 경고색) · 폭은 내용만큼 (ADR-0347) */
.tip-card.cn-req-tip { width: auto; max-width: 280px; display: flex; flex-direction: column; gap: 3px; font-size: var(--fs-xs); }
.cn-rno { grid-column: 1; font-size: var(--fs-xs); font-weight: bold; font-variant-numeric: tabular-nums; white-space: nowrap; color: var(--text-muted); }
.cn-rank.on .cn-rno, .cn-rank.next .cn-rno { color: var(--text-primary); }
/* 로마 숫자 자리 — 숫자마다 폭이 달라(I ↔ VIII) 자리를 가장 넓은 숫자(VIII)만큼 잡는다 · 그래야 여는 것 글이 줄끼리 맞는다.
   숫자 글자는 언어가 바뀌어도 같아 `em` 하나로 된다(라벨 칸 고정 폭 금지는 언어마다 길이가 다른 글의 몫 — src/ui/README) (2026-09-24 사용자 지시 「로마자로」) */
.cn-rn { display: inline-block; min-width: 1.55em; }   /* VIII 이 1.52em(12px 굵게 18.2 · 실측) */
/* 여는 것 설명 — 여는 것마다 한 문장 · 한 줄에 하나(`.cn-desc`). 준비 중인 것은 흐린 문장 + 꼬리 (ADR-0325) */
.cn-eff-t { grid-column: 2; min-width: 0; display: flex; flex-direction: column; gap: 1px; font-size: var(--fs-xs); color: var(--text-primary); word-break: keep-all; }
.cn-desc.soon { color: var(--text-muted); }
/* 오른쪽 끝 — 「✓」(초록 글자) · 「준비 중」(흐린 글자) */
.cn-state { grid-column: 3; font-size: var(--fs-xs); white-space: nowrap; color: var(--text-muted); }
.cn-rank.on .cn-state { color: var(--color-success); }

/* ───────── 대장간 (SCREEN_DESIGN §8-2) ─────────
   상점과 같은 세로 3단(ADR-0366) — 띠 / 왼쪽 장비 패널 · 오른쪽 대장간 열(작업 탭 + 패널) / 아이템창. 강화 패널은 열 전폭이다. 2단 격자는 §4-1 편성 패널과 같은 문법이고
   좁아지면 세로로 접힌다 — 라벨 칸에 고정 px 을 주지 않는다 (src/ui/README.md 폭 정책) */
.fg-col { border: 1px solid var(--border-dark); background: var(--bg-input); border-radius: 3px; padding: 8px; min-width: 0; }
/* 강화 대상으로 고른 칸 — 기존 크기의 바깥 선. 별도 선은 #stage 직속이라 스크롤 경계에도 잘리지 않는다 */
.pd-cell.sel, .inv-cell.sel, .forge-selection-outline { outline: 3px solid var(--text-accent); outline-offset: 1px; }
/* 인벤토리 패널 위 · 정렬/분해 판(30), 우클릭 메뉴(38/39), 창(40), 옵션 툴팁(50/51) 아래 */
.forge-selection-outline { position: absolute; z-index: 29; pointer-events: none; }
/* 강화 칸 (§8-2) — 세 칸: 왼쪽 **아이템 카드**(hover 툴팁 카드 그대로 · ADR-0979) | 가운데 **빈 칸**(⚠ 시험 중 · ADR-0979) |
   오른쪽 **작업**(단계 눈금 · 지금 › 다음 · 성공 확률 · 재료 칸 + [강화] · ADR-0973). 패널 끝까지 서고 칸마다 내용이 세로 가운데다 */
.fg-up, .fg-up-empty { height: 100%; min-height: 0; border: 1px solid var(--border-dark); background: var(--bg-card); border-radius: 2px; }
/* 글자는 작업 칸 · 빈 상태 안에서만 한 벌 크다 — 건설 상세(`.cn-side`)와 같은 규칙. 아이템 카드는 툴팁 그대로라 안 탄다 */
.fg-up-work, .fg-up-empty { --fs-2xs: 11px; --fs-xs: 14px; --fs-sm: 15px; --fs-md: 17px; --fs-lg: 20px; }
/* 왼쪽 칸 폭 = 카드 폭(`max-content`) · 작업 칸이 40%(재료 칸 줄 + [강화] 한 줄 · ADR-0973) · 가운데가 남는 폭 */
.fg-up { display: grid; grid-template-columns: max-content minmax(0, 1fr) minmax(320px, 40%); }
/* 아이템 칸 — 옵션을 hover 툴팁과 같은 꼴로 나열한다(`tip-card` 의 내용 규칙 · 창 테두리 · 그림자는 없다) · 위에서부터 · 길면 이 칸만 스크롤 ·
   오른쪽 가름선 하나 (ADR-0979) */
.fg-up-tipcol { padding: 6px 4px; min-height: 0; overflow-y: auto; border-right: 1px solid var(--border-dark); }
/* 폭 · 글씨 = hover 툴팁 — 메인 배율(0.9)을 되돌려 툴팁 카드 폭(`.tip-card`) 그대로 보인다 */
.tip-card.fg-up-card { zoom: calc(1 / .9); }
/* 머리 — 그림이 왼쪽 위에 작게(희귀도 색 테두리 · 렌더러가 `border-color` 를 준다) · 오른쪽에 툴팁의 머리글 줄 · 이름 */
.fg-up-hd { display: flex; align-items: stretch; gap: 10px; margin-bottom: 8px; }
.fg-up-ic { position: relative; flex: none; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; padding: 4px;
    border: 1px solid var(--border-secondary); border-radius: 2px; background: var(--bg-tertiary); font-size: 24px; }
.fg-up-ic img { width: 100%; height: 100%; object-fit: contain; image-rendering: var(--face-render); }
/* 그림 오른쪽 — 위 = 종류 · 레벨(오른쪽 위 · 머리글 줄의 빈 글 자리는 그대로 왼쪽) · 아래 = 이름(그림 아랫변에 맞춘다) [2026-10-30 사용자 지시] */
.fg-up-hdtx { flex: 1; min-width: 0; display: flex; flex-direction: column; justify-content: space-between; }
.fg-up-hdtx .tip-head { margin-bottom: 0; line-height: 1.2; }
.fg-up-card .fg-up-hdtx .tip-name { margin: 0; line-height: 1.2; }   /* 툴팁의 「머리글 줄 + 이름」 아래 여백(8)을 걷어 이름 아랫변 = 그림 아랫변 */
/* 가운데 빈 칸 — 아무것도 안 그린다(가름선도 없다 · ⚠ 시험 중) */
.fg-up-mid { min-width: 0; }
.fg-up-empty, .fg-up-none { display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: var(--fs-md); }
.fg-up-none { flex: 1; }
/* 세로 여백은 영어에서 재료 칸 + 버튼이 두 줄이 돼도 칸 안에 들 만큼 (재료 이름이 길다 · ADR-0973) */
.fg-up-work { display: flex; flex-direction: column; justify-content: center; gap: 14px; padding: 12px 26px; min-width: 0; }
/* ① 단계 눈금 — 찬 칸 = 지금 · 다음 칸은 테두리만 밝다. 색은 건설 랭크 눈금(`.cn-pips`)과 같은 진행 주황 */
.fg-up-th { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 8px; font-size: var(--fs-sm); color: var(--text-secondary); }
.fg-up-th b { font-size: var(--fs-md); color: var(--text-primary); font-variant-numeric: tabular-nums; }   /* `+n` · 아래 비교 줄 값 = 한 단 작게(lg → md · 2026-10-30 사용자 「글씨크기좀 줄여라」) */
.fg-up-th small { font-size: var(--fs-sm); font-weight: normal; color: var(--text-muted); }
.fg-up-pips { display: flex; gap: 4px; }
.fg-up-pips i { flex: 1; height: 14px; background: var(--bg-tertiary); border: 1px solid var(--border-primary); }
.fg-up-pips i.on { background: var(--color-progress); border-color: var(--color-progress); }
.fg-up-pips i.next { border-color: var(--color-progress); }
/* 지금 상한 너머 칸 = 잠긴 칸 — 바탕을 비우고 가운데 회색 자물쇠(ADR-0925) · 칸 높이 안에 든다 (SCREEN_DESIGN §8-2 · ADR-0968) */
.fg-up-pips i.lock { display: flex; align-items: center; justify-content: center; background: transparent; border-color: var(--border-dark); }
.fg-up-pips i.lock svg { width: 10px; height: 10px; }
/* ② 지금 › 다음 · ③ 성공 확률 — 「이름 · 값」 줄 둘을 위아래 가름선 한 쌍이 묶는다. 다음은 초록 · 상한이면 지금만 서고 확률 줄은 빠진다 (ADR-0973) */
.fg-up-rows { padding: 4px 0; border-top: 1px solid var(--border-dark); border-bottom: 1px solid var(--border-dark); }
.fg-up-cmp { display: flex; align-items: baseline; gap: 14px; padding: 4px 0; }
.fg-up-cmp .lab { min-width: 0; margin-right: auto; font-size: var(--fs-sm); color: var(--text-secondary); }
.fg-up-cmp b { font-size: var(--fs-md); font-variant-numeric: tabular-nums; }
.fg-up-cmp i { font-style: normal; font-size: var(--fs-md); color: var(--text-muted); }
.fg-up-cmp .nx { color: var(--color-success); }
.fg-up-cmp .nx.same { color: var(--text-muted); }   /* 다음이 지금과 같다 — 반올림이 한 단계를 먹었다 · 오른다고 읽히지 않게 */
/* ④ 재료 칸(건설 · 연구소와 같은 `.cn-mats` — `matTile`) + [강화] — 칸 줄은 왼쪽 · 버튼은 오른쪽 끝 아래에 맞춘다(연구소 상세 `.dp-side-act` 와 같다 · ADR-0973).
   영어 재료 이름이 길어 칸 줄이 접혀도 버튼은 제자리 · 상한이면 칸이 빠지고 버튼만 오른쪽 끝 */
.fg-up-act { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 6px 14px; }
/*   칸 줄은 접지 않는다 — 한 줄에 안 들면 버튼이 다음 줄 오른쪽 끝으로 내려간다(영어) · 칸 줄이 열 폭보다 넓을 때만 칸이 접힌다 */
.fg-up-act .cn-mats { flex: none; max-width: 100%; }
/*   이름은 칸 아래 두 줄까지 접힌다(영어 「Lowest-Grade Iron Ore」 — 한 줄이면 칸 줄째 접혀 버튼 아래로 밀렸다) · 한국어는 한 줄에 든다 */
.fg-up-act .cn-matw { max-width: 96px; }
.fg-up-act .cn-mat-name { white-space: normal; text-align: center; }
.fg-up-act > .btn { flex: none; margin-left: auto; }
.fg-pact .fg-cost.no { color: var(--color-error); }
/* ~~강화 연출(`.fg-anim` 묶음 · ADR-0626)~~ — ADR-0737 이 연출을 걷은 뒤 남아 있던 규칙을 걷었다 (ADR-0973) */
/* 제작 칸 (§8-2 · R96 · ADR-0230 · ADR-0263) — 위 고르개 줄(부위 · 물약 — 강화 필터와 같은 가로 줄) + 레벨 줄 + 종류 목록 · 또는 물약 */
.fg-make { display: flex; flex-direction: column; gap: 6px; }
.fg-make .segmented { flex-wrap: wrap; }
/* 부위 고르개 칸 그림 (§8-2) — 제작 부위 줄 · 강화 필터가 장비칸 빈 칸의 부위 실루엣(`mock.slotArt`)을 든다.
   제작 줄 끝의 물약 칸은 물약 빈 칸의 병 실루엣(ADR-0219). 고른 칸만 진하고 나머지는 옅다 — 테두리와 함께 「지금 고른 것」을 말한다 */
.btn .seg-slot { display: block; width: 40px; height: 40px; object-fit: contain; opacity: .65; image-rendering: var(--face-render); }
.btn.on .seg-slot, .btn:hover .seg-slot { opacity: 1; }
/* 제작 — 부위 줄 · 레벨 줄의 칸은 **같은 폭**이다 [사용자 지시 「위 아이콘과 사이 공간까지 같게」] — 그림 40 + `.btn.sm` 좌우 여백 · 테두리.
   두 줄 다 폭을 박아야 한다 — 한쪽이 내용 폭이면 소수점 차이가 칸마다 쌓여 끝(물약 칸)에서 어긋난다. 레벨 라벨(`Lv70`)은 두 언어가 같아 넘치지 않는다 */
.fg-make > .segmented > .btn { width: calc(40px + 2 * 8px + 2 * 1px); flex: 0 0 auto; text-align: center; }
.fg-make > .segmented > .btn .seg-slot { margin: 0 auto; }
/* 종류 목록 (ADR-0263) — 줄 = 그림 · 이름 · 필요 재료 칸 셋 · [만들기] 가 **왼쪽부터 붙어** 선다(재료는 이름 바로 오른쪽).
   목록 하나가 격자이고 줄은 그 열을 물려받는다(subgrid) — 이름 열 폭 = 가장 긴 이름이라 재료 칸 · 버튼이 줄끼리 세로로 맞는다.
   이름 열은 글 길이를 따른다(라벨 칸에 고정 px 금지 · src/ui/README.md) · 남는 폭은 맨 끝 빈 열이 먹는다 */
/* 재료 칸 · 그림은 한 변(40) 안에 든다 [사용자 지시 「한 칸이 아이콘 크기와 비슷하게」].
   **줄 높이는 목록이 패널 맨 아래에 닿게 나눈다** [사용자 지시] — 목록이 남는 세로를 받고(flex 1) 그것을 `--kind-rows` 줄로 똑같이 가른다.
   `--kind-rows` = 그 레벨에서 줄이 가장 많은 부위의 줄 수(렌더러가 넣는다 — 지금은 무기) — 줄이 적은 부위도 줄 높이가 같고 아래가 빈다.
   가르면 줄이 너무 낮아지는 좁은 화면이면 한 변 + 여백(48)에서 멈추고 목록이 스크롤한다 */
.fg-kinds { display: grid; grid-template-columns: 40px max-content auto auto minmax(0, 1fr); gap: 3px 14px;
    flex: 1 1 auto; min-height: 0; grid-template-rows: repeat(var(--kind-rows, 1), minmax(48px, 1fr)); align-content: start; }
.fg-kind { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center;
    border: 1px solid var(--border-dark); background: var(--bg-input); padding: 3px 9px; border-radius: 2px; }
.fg-kind .fg-kname { font-size: var(--fs-md); white-space: nowrap; padding-left: 12px; }   /* 그림과 이름 사이는 열 간격보다 더 띄운다 [사용자 지시] */
.fg-kmats { display: flex; gap: 6px; }
/* 재료 칸 — 그림 한 변(40) 높이의 상자 안에 두 줄: 재료 이름(재료 아트가 없다) · `보유/필요`.
   폭은 이름을 따른다(한 줄 · 고정 px 금지) — 한 레벨의 줄들은 같은 재료라 열이 저절로 맞는다 */
.fg-kmat { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
    height: 40px; min-width: 52px; padding: 0 6px;
    background: var(--bg-tertiary); border: 1px solid var(--border-dark); border-radius: 2px; }
.fg-kmat-ic { font-size: var(--fs-xs); line-height: 1.2; color: var(--text-secondary); white-space: nowrap; }
.fg-kmat b { font-weight: normal; font-size: var(--fs-xs); line-height: 1.2; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.fg-kmat.no b { color: var(--color-error); }
.fg-kerr { font-size: var(--fs-xs); color: var(--color-error); }

/* ───────── 상점 (SCREEN_DESIGN §8-3 · ADR-0223 · ADR-0243 · ADR-0246) — 상단 패널(아이콘 칸 · 제목 줄 [교체]) · 특수상단 패널 ───────── */
/* 칸 격자 — 칸은 인벤토리 칸(.inv-cell)을 그대로 쓰고 아래에 가격이 선다. **한 줄 6칸** — 장비의 무기 줄과 같은 폭이라
   재료 탭으로 바꿔도 격자 폭이 안 흔들린다 · 칸 60px · 그림 44px 는 **왼쪽 장비칸(`.pd-cell`) 크기**다(사용자 지시 「왼쪽 장비수준으로」 · ADR-0370)
   (가격은 숫자 + G 라 언어 길이 배수를 안 탄다 — 라벨 칸의 고정 px 금지와 부딪히지 않는다 · src/ui/README 폭 정책) */
/* 격자와 사기 줄을 한 폭으로 묶는다 — 줄이 격자 폭을 따라간다 */
.td-goods { display: grid; grid-template-columns: max-content; max-width: 100%; }
/* 상단 목록은 **패널 가운데**에 선다 [2026-09-30 사용자 지시 · §8-3] — 칸 + 사기 줄 한 덩어리의 위아래 · 좌우 여백이 같다.
   `margin: auto` 라 세로가 모자라면 위에 붙고 본문이 스크롤한다(가운데 정렬처럼 위가 잘리지 않는다).
   위 4px — 제목 아래 여백(8)과 패널 아래 안여백 + 테두리(11 + 1)의 차이를 메워 **제목 밑줄 ~ 칸 = 사기 줄 ~ 패널 아랫변**이 되고,
   넘쳐서 위에 붙을 때도 맨 윗줄 고른 칸의 겉 테두리(2px + 1px)가 안 잘린다 */
.td-body { display: flex; padding-top: 4px; }
.td-body > .td-goods { margin: auto; }
.td-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 60px)); gap: 8px 6px; }
/* 장비 — **같은 부위끼리 붙은 묶음**이 한 줄에 셋씩 — 부위 일곱이 **세 줄**로 선다(무기 줄 + 셋 · 셋 · 사용자 지시 「3줄로」 · ADR-0370).
   **묶음 사이도 칸 사이와 같다**(무기 묶음 안의 간격 — 사용자 지시 「아이템별 거리를 무기랑 똑같이」 · ADR-0376) — 방어구가 부위마다 한 칸일 때 칸끼리 떨어져 보였다.
   묶음 안의 칸 수는 CSS 가 아니라 `balance.csv:shop_equip_per_slot` 이 정한다 — 한 줄로 흐른다 */
.td-grid.grouped { grid-template-columns: repeat(3, max-content); gap: 8px 6px; }
/* 무기는 **한 묶음으로 맨 윗줄을 혼자 쓴다**(사용자 지시 「무기도 3개만」 · ADR-0362) — 칸 간격은 아래 줄과 같다 */
.td-group { display: grid; grid-auto-flow: column; grid-auto-columns: 60px; gap: 6px; }
.td-group[data-part="weapon"] { grid-column: 1 / -1; }
/* 장비 탭 두 열 — 왼쪽 장비 3 × 3 · **간격** · 오른쪽 열(맨 위 물약 셋 · 그 아래 스킬 도안 셋) [2026-09-29 사용자 지시 · ADR-0424 · 2026-10-30 ADR-0952 · §8-3].
   간격은 09-28 물약 자리의 것(「왼쪽 장비들과 일정 범위 떨어져서」) · 오른쪽 열의 줄 간격은 장비 격자의 줄 간격과 같아 줄이 나란하다 */
.td-split { display: flex; align-items: flex-start; gap: 36px; }
.td-side { display: flex; flex-direction: column; gap: 8px; }
.td-slot { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.td-slot .inv-icon { width: 44px; height: 44px; }
/* 안 열린 줄의 칸 [2026-10-30 · ADR-0952] — 빈 칸 + 가운데 **회색** 닫힌 자물쇠(영웅 띠 · 물약 칸의 잠긴 칸과 같은 그림 · ADR-0913 · 0925) · 점선 · 옅게 · 누르는 자리가 아니다 */
.inv-cell.td-lock { border-style: dashed; color: var(--text-muted); opacity: .6; cursor: default; }
.inv-cell.td-lock .rs-pin-ico { width: 22px; height: 22px; }
/* 고른 칸 — 영웅 띠 · 관전 유닛 카드와 같은 **파란 겉 테두리**(§5). 테두리 색은 희귀도가 들고 있어 그 바깥에 선다 */
.inv-cell.td-picked { outline: 3px solid var(--color-info); outline-offset: 1px; }
/* 칸 아래 가격 — 칸 안 ilvl(`.inv-lv` 2xs)보다 크게 11px(사용자 지시 「골드 표기 글씨 더 키워」 → 「11로 조금 줄여」) · 특수상단의 작은 칸도 같다 */
.td-price { font-size: 11px; color: var(--color-warning); text-align: center; white-space: nowrap; }
.td-price.no { color: var(--color-error); }
/* 사기 줄 — 고른 것의 이름 · 가격 · [사기]. 고른 것이 없으면 `—` 와 꺼진 버튼 */
.td-buy { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 6px 9px;
    border: 1px solid var(--border-dark); background: var(--bg-input); border-radius: 2px; font-size: var(--fs-xs); }
.td-buy-n { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.td-buy .td-price { font-size: var(--fs-xs); }
/* 물약 수 고르기 ×n — 고른 수는 강조색 테두리 + 밝은 글자(공용 `.btn.sm.on` 은 한 단 밝아질 뿐이라 안 갈린다 · 도감 · 대장간 탭과 같은 처방 · 2026-10-23) */
.td-buy .btn.sm.on { color: var(--text-primary); border-color: var(--text-accent); }
/* 상점은 영웅 띠 / 구매 · 판매 · 보조 열 / 아이템창의 세로 3단이다.
   장비창 없이 구매와 판매를 같은 폭·높이로 나란히 두고, 오른쪽 보조 열도 같은 폭을 쓴다. */
.c-shop-band { grid-template-columns: repeat(3, minmax(0, 1fr)); min-height: 0; }
.c-shop-band > .panel { display: flex; flex-direction: column; min-height: 0; }
/* 장비와 소모품 사이의 여백을 줄여 구매 목록 전체가 한 열 안에 들어간다. */
.c-shop .td-split { gap: 24px; }
/* 상점 오른쪽 보조 열 — 위 교역소 · 아래 특수상단이 **높이를 반씩** 나눈다(ADR-0960).
   도서관 오른쪽 열(`.lib-col`)과 같은 짜임 — 넘치면 제 본문이 스크롤한다 */
.c-shop-stack { display: flex; flex-direction: column; gap: 14px; min-height: 0; }
.c-shop-stack > .panel { display: flex; flex-direction: column; flex: 1 1 0; min-height: 0; }
.c-shop-stack > .panel + .panel { margin-top: 0; }
/* 판매 합계와 실행 버튼은 목록 스크롤 밖에 남는다. */
.td-sale-body { padding: 4px; }
.td-sale-grid { display: grid; grid-template-columns: repeat(auto-fill, 60px); gap: 8px 6px; }
.td-sale-grid .inv-cell { width: 60px; height: 60px; }
.td-sale-empty { display: flex; align-items: center; justify-content: center; min-height: 100%; font-size: var(--fs-xs); text-align: center; }
.td-sale-total { flex: none; }
/* 교역소 물건 칸 — 칸 수만큼 한 줄(상단 칸과 같은 크기 · `?` 만 — ADR-0960) */
.td-grid.td-post { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: 60px; }
/* 특수상단의 상인 카드 — **한 줄로 납작하게** 선다(사용자 지시 「특수상단을 일단 좀 줄여」 · ADR-0235) — 왼쪽 이름 · 남은 시간 / 오른쪽 작은 칸 셋(ADR-0782) */
.td-card { display: inline-flex; align-items: center; gap: 14px; max-width: 100%;
    padding: 7px 10px; background: var(--bg-card); border: 1px solid var(--border-secondary); }
.td-card-h { display: flex; flex-direction: column; gap: 2px; font-size: var(--fs-sm); white-space: nowrap; }
.td-card-h b { font-weight: 500; }
/* 작은 칸 — 모양은 상단 칸 그대로, 크기만 줄인다 */
.td-card .td-grid { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: 40px; gap: 6px; }
/* 물건 칸 — 물건이 미정이라 빈 칸 가운데에 `?` 하나만 선다 · 누르는 자리가 아니다 (§8-3 · ADR-0782) */
.td-unknown { color: var(--text-muted); font-size: var(--fs-md); cursor: default; user-select: none; }
/* 남은 시간 — **정보**다. 재촉 연출(빨강 · 깜빡임 · 강조)을 붙이지 않는다 (기획 §2-6 방치형 계약) */
.td-clock { color: var(--text-muted); font-size: var(--fs-xs); }
/* 상단 제목 줄 오른쪽 끝 — 무료까지 남은 시간 + [교체] 한 덩이 (§8-3 · ADR-0648). 남은 시간은 제목의 굵기를 안 받는다 */
.td-roll { display: inline-flex; align-items: center; gap: 10px; white-space: nowrap; }
.td-roll .tv-wait, .td-roll .td-roll-who { font-size: var(--fs-xs); font-weight: normal; }
/* 의뢰 게시판 (SCREEN_DESIGN §14) — **가로 한 줄**(`commission_board_cards` 장까지 · ADR-0322). 좁아져도 격자로 접지 않는다:
   한 줄이 이 화면의 형태라 접는 순간 형태가 사라진다. 그래서 `flex-wrap: nowrap`.
   카드 폭은 라벨이 드는 칸이므로 고정 px 이 아니라 clamp — 영어가 길어져도 안 깨진다 (ui/README 폭 정책) */
.cm-board {
    display: flex; flex-wrap: nowrap; gap: 6px;
}
.cm-card {
    /* 카드가 **줄을 나눠 갖는다** — 폭을 고정하면 좁은 창에서 마지막 장이 스크롤 뒤로 밀려
       한 줄이 깨진다. `1 1 0` + `min-width: 0` 이라 선 카드가 언제나 한 줄에 선다 */
    flex: 1 1 0; min-width: 0;
    display: flex; flex-direction: column; gap: 4px;
    padding: 7px 9px;   /* 위아래가 좌우보다 얇다 — 명성 막대 줄(위)만큼 카드가 낮아져도 1600×800 에서 영웅 고용 패널이 안 눌린다 (ADR-0958) */
    background: var(--bg-card); border: 1px solid var(--border-dark);
    /* 굵은 윗변 = 의뢰 등급 색 — 아래 규칙이 카드 안 등급 칩(`g-<grade>`)을 보고 정한다 (§14 · ADR-0892 · ADR-0974) */
    border-top: 3px solid var(--border-dark);
}
/* 윗변은 **의뢰 등급 색**(아이템 희귀도 색 · 등급 칩과 같다) [2026-10-27 사용자 「레어같은 난이도색으로」 · ADR-0892] —
   자리는 윗변이다 — 같은 탭 영웅 후보 카드(`.ng-card`)의 등급 색 윗변과 같다 [2026-10-30 사용자 「등급바를 위로」 · ADR-0974].
   종류(처치 · 수집)는 배지 글자가 든다 */
.cm-card:has(> .cm-kind .g-normal) { border-top-color: var(--rarity-normal); }
.cm-card:has(> .cm-kind .g-magic) { border-top-color: var(--rarity-magic); }
.cm-card:has(> .cm-kind .g-rare) { border-top-color: var(--rarity-rare); }
/* 카드 글씨는 토큰 한 단씩 올라 있다 — 설명 줄이 빠진 세로가 받는다 (ADR-0225) */
.cm-kind { font-size: var(--fs-md); }
.cm-goal { font-size: var(--fs-sm); line-height: 1.35; word-break: keep-all; }
.cm-rew {
    display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap;
    margin-top: auto; padding-top: 5px; border-top: 1px solid var(--border-dark);
    font-size: var(--fs-xs);
}
.cm-gold { color: var(--color-warning); }
.cm-go { align-self: stretch; }
/* 카드 바닥 버튼은 키가 크다 [2026-10-12 사용자 지시 「의뢰 수락버튼 높이를 좀 더 키우고」 · §14] — 위아래 여백만 공용 `.btn` 의 7px 로(글씨는 `.btn.sm` 그대로).
   [수락] · [수령] · [포기]가 한 자리를 번갈아 쓰므로 셋 다 같은 키 · 옆 도박장 [입장](.gb-go)도 같은 바닥선이라 같은 키다.
   ⚠ `.btn.sm.cm-go` 로 건다 — 한 단(`.cm-go`)이면 `.btn.sm { padding }`(클래스 둘)에 진다(`.go-tree` 와 같은 사정) */
.btn.sm.cm-go, .btn.sm.gb-go { padding-top: 7px; padding-bottom: 7px; }
/* 의뢰 등급 칩 — 아이템 희귀도의 색 · 이름 사다리 그대로(같은 말이 두 색이 되지 않게 · ADR-0352) */
.cm-grade { margin-left: 6px; padding: 0 5px; font-size: var(--fs-xs); border: 1px solid currentColor; border-radius: 2px; white-space: nowrap; }
.cm-grade.g-normal { color: var(--rarity-normal); }
.cm-grade.g-magic { color: var(--rarity-magic); }
.cm-grade.g-rare { color: var(--rarity-rare); }
/* 진행 중 카드 — 제자리에서 테두리가 선다(왼쪽 · 오른쪽 · 아래 — 윗변은 등급 색 그대로 · ADR-0974) · 다 채우면 막대가 성공 색 (§14 · ADR-0352) */
.cm-card.taken { border-left-color: var(--border-highlight); border-right-color: var(--border-highlight); border-bottom-color: var(--border-highlight); }
.cm-card.done { border-left-color: var(--color-success); border-right-color: var(--color-success); border-bottom-color: var(--color-success); }
.cm-prog { display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); color: var(--text-muted); }
.cm-prog .bar { flex: 1 1 auto; min-width: 0; }
.cm-card.done .cm-prog .bar > i { background: var(--color-success); }
/* 패널 제목 옆 — 받은 수 / 받을 수 (값은 늘 찍는다 · §4-1) */
.cm-slots { margin-left: 8px; font-size: var(--fs-xs); font-weight: normal; color: var(--text-muted); }
/* 명성 막대 한 줄 — 게시판 위 · 「명성 Lv n」 · 막대(남는 폭 전부 · 경험치 막대 색) — 이번 레벨 기준 숫자는 **막대 가운데에 겹친다** (§14 · ADR-0958 · ADR-0961).
   줄 높이는 `--cm-fame-h`(`.tv-low`) — 도박장 칸이 같은 값만큼 내려선다. 글자는 찬 쪽 · 빈 쪽 어디서나 읽히게 밝은 색 + 어두운 그림자 */
.cm-fame { display: flex; align-items: center; gap: 10px; height: var(--cm-fame-h); margin: calc(var(--cm-fame-pad) - 8px) 0 var(--cm-fame-pad); }   /* 위 = 제목 밑줄에서 `--cm-fame-pad`(제목 아래 마진 8 을 뺀다) · 아래 = 카드까지 같은 값 */
.cm-fame-lv { font-size: var(--fs-sm); line-height: 1; white-space: nowrap; }
.cm-fame .bar { position: relative; flex: 1 1 auto; min-width: 0; height: 100%; }
.cm-fame-n {
    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
    font-size: var(--fs-xs); line-height: 1; color: var(--text-primary); white-space: nowrap; font-variant-numeric: tabular-nums;
    text-shadow: 0 0 2px #000, 0 0 3px #000;
}
/* 게시판이 안 열렸을 때 — 빈 카드 틀이 자리를 잡고 그 위에 잠김 베일(.lock-veil) */
.cm-card.ghost { min-height: 96px; }

/* 잠김 베일 (SCREEN_DESIGN §13-1) — 통째로 잠긴 칸의 내용물 위에 검은 반투명 막 + 🔒 + 「선술집 n랭크 필요」.
   부모 `.lock-host` 가 기준 상자다 · 베일이 누름을 막는다 */
.lock-host { position: relative; }
.lock-veil {
    position: absolute; inset: 0; z-index: 2;
    display: flex; align-items: center; justify-content: center; gap: 8px;
    padding: 8px; text-align: center; word-break: keep-all;
    background: rgba(var(--veil-rgb), .88);
    color: var(--text-muted); font-size: calc(var(--fs-sm) + 2px);   /* 회색 — 잠금 표시는 어디서나 회색 (ADR-0925) */
}
/* 자물쇠 = `lockIcon` SVG(전술 칸과 같은 그림) */
.lock-veil .lock-ico { display: inline-flex; }
.lock-veil .lock-ico svg { width: 1.1em; height: 1.1em; }

/* 상인이 없을 때 — 카드 대신 한 줄이 자리를 지킨다(「지금 없다」와 「고장났다」가 갈려야 한다 · §4-1) */
.td-away { display: inline-block; padding: 7px 9px; border: 1px solid var(--border-dark); background: var(--bg-secondary); border-radius: 2px; }

/* 대장간은 **상점과 같은 세로 3단**(`.char-stack` — 띠 / 가운데 단 / 아이템창 · ADR-0366). 가운데 단 = 왼쪽 영웅 장비 · 오른쪽 대장간 열.
   장비 칸 폭은 상점 · 캐릭터 탭 첫 칸과 같다. 대장간 열은 작업 탭(제 높이) 아래 패널(`.fill`)이 남는 세로를 받아 제 본문이 스크롤한다 */
.c-forge-band { grid-template-columns: minmax(0, calc((100% - 3 * 14px) / 4)) minmax(0, 1fr); min-height: 0; }
.c-forge-band > .panel { display: flex; flex-direction: column; min-height: 0; overflow-y: auto; }
.c-forge-col { min-height: 0; }
/* 대장간 — 강화 · 제작 · 합성 · 크래프트 중 고른 하나만 편다 · 작업 탭은 패널 윗변에 붙은 폴더 탭(`.fg-tabs` — 원정 난이도 탭과 한 규칙) (SCREEN_DESIGN §8-2 · ADR-0142 · ADR-0281 · ADR-0963) */
.fg-split { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; align-items: start; }
/* 박스 안에서는 고른 작업이 박스 끝까지 선다 (ADR-0097) — 넘치면 그 영역이 스크롤한다 */
.fg-split.box-body { align-items: stretch; }
/* 작업은 탭 박스 안에 **바로** 선다 — 박스 안에 테두리를 한 겹 더 두르지 않는다 [2026-09-21 사용자 지시] */
.fg-box { min-width: 0; }
.fg-box .fg-col { background: var(--bg-card); border: 1px solid var(--border-dark); border-radius: 2px; }
/* 제작은 상자 없이 선다 [사용자 지시 「Smith 안의 큰 박스 삭제」] — 고르개 줄 · 레벨 줄 · 종류 목록이 패널 안에 바로 선다.
   박스 끝까지 높이를 받아(`height: 100%`) 종류 목록이 남는 세로를 채운다(아래 `.fg-kinds`) · 강화의 목록 · 작업 패널 상자는 그대로다 */
.fg-box .fg-col.fg-make { background: none; border: 0; border-radius: 0; padding: 0; height: 100%; }
/* 물약 — 제작 고르개 줄의 물약 칸을 고르면 제작 칸 안에 선다 (R103 · ADR-0219). 머리 줄(**재고** — 관전과 같은 `.p-slot` 그림 + 개수 · R124 · 칸은 편성 탭) + 단계 줄 */
.fg-potion { display: flex; flex-direction: column; gap: 4px; }
/* 대장간 합성 [2026-10-27 · SCREEN_DESIGN §8-2 · ADR-0856] — 줄마다 한 행 · 재료 칸(재료 탭 칸)과 단(비용 · 버튼)이 번갈아 선다 · 단의 점선 화살표가 왼쪽 칸 → 오른쪽 칸을 잇는다 */
.fg-box .fg-col.sy-ladder { display: flex; flex-direction: column; gap: 14px; }
.sy-row { display: flex; align-items: center; gap: 6px; }
.sy-row > .mat-cell { flex: 0 0 52px; width: 52px; }
.sy-step { position: relative; flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 10px; }
.sy-step::before { content: ''; position: absolute; left: 2px; right: 6px; top: 50%; border-top: 1px dashed var(--border-secondary); }
.sy-step::after {
    content: ''; position: absolute; right: 2px; top: calc(50% - 4px);
    border: 4px solid transparent; border-right-width: 0; border-left-color: var(--border-secondary);
}
.sy-cost { display: flex; gap: 8px; font-size: var(--fs-sm); color: var(--text-secondary); white-space: nowrap; }
.sy-cost .no { color: var(--color-error); }
.sy-act { display: flex; gap: 4px; }
.sy-act .btn { white-space: nowrap; }
.fg-poth { display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); color: var(--text-secondary);
    padding-bottom: 6px; margin-bottom: 2px; border-bottom: 1px solid var(--border-dark); }
.fg-prow { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 8px; align-items: center;
    padding: 4px 6px; border: 1px solid var(--border-dark); border-radius: 2px;
    background: var(--bg-input); font-size: var(--fs-xs); }
.fg-prow.has { border-color: var(--border-highlight); }
.fg-prow.locked { opacity: .55; }
.fg-prow .fg-ph { color: var(--text-secondary); }
.fg-pact { display: flex; align-items: center; gap: 6px; }
.fg-ptag { color: var(--text-accent); font-size: var(--fs-2xs); }
.fg-ptag.muted { color: var(--text-muted); }
/* 재고 한 칸 — 그림(아레나와 같은 `.p-slot`) + 개수 `×n`. 편성 탭의 「가진 물약」도 이것을 쓴다 (R124) */
.p-stock { display: inline-flex; align-items: center; gap: 2px; }
.p-stock b { font-weight: normal; font-size: var(--fs-xs); color: var(--text-primary); font-variant-numeric: tabular-nums; }


/* ───────── 실험실 (SCREEN_DESIGN §18 · ADR-0580 · ADR-0610) ─────────
   개발 장치 — 걷어내려면 이 섹션째 지운다. 왼쪽 조건 · 오른쪽 결과가 박스 높이를 나눠 갖고 각 열이 따로 스크롤한다 */
.lab-item { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 16px; min-height: 0; overflow: hidden; }
.lab-cond, .lab-out { display: flex; flex-direction: column; gap: 8px; min-height: 0; overflow-y: auto; }
.lab-row { display: grid; grid-template-columns: minmax(6em, max-content) minmax(0, 1fr); align-items: center; gap: 10px; }
.lab-row.top { align-items: start; }
.lab-h { color: var(--text-muted); font-size: var(--fs-xs); white-space: nowrap; }
/* 몬스터 — 장소마다 한 줄: 장소 이름 + 칩(얼굴 + 이름) · 보스 이름은 강조색 */
.lab-places { display: flex; flex-direction: column; gap: 6px; }
.lab-place { display: grid; grid-template-columns: minmax(7em, max-content) minmax(0, 1fr); gap: 8px; align-items: center; }
.lab-place-name { font-size: var(--fs-xs); color: var(--text-secondary); white-space: nowrap; }
.lab-chips { display: flex; flex-wrap: wrap; gap: 4px; }
.lab-mon {
    display: inline-flex; align-items: center; gap: 5px; padding: 2px 9px 2px 2px;
    background: var(--bg-input); border: 1px solid var(--border-dark); border-radius: 15px;
    color: var(--text-secondary); font: inherit; font-size: var(--fs-xs); cursor: pointer;
}
.lab-mon:hover { border-color: var(--border-secondary); color: var(--text-primary); }
.lab-mon.on { border-color: var(--text-accent); color: var(--text-primary); }
.lab-mon.boss .lab-mon-name { color: var(--text-accent); }
.lab-lv { display: inline-flex; align-items: center; gap: 6px; }
.lab-lv-n { min-width: 2.5em; text-align: center; font-variant-numeric: tabular-nums; }
/* 조건 줄 — 로직이 낸 값(`monsterGearSpec`). 언제나 입는 부위는 밝게 · 확률로 입는 부위는 흐린 점선 칸 + 그 단의 확률 (ADR-0610) */
.lab-spec { display: flex; flex-direction: column; gap: 6px; padding: 8px 10px; border: 1px solid var(--border-dark); background: var(--bg-secondary); }
.lab-parts { display: inline-flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.lab-part {
    display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px;
    background: var(--bg-input); border: 1px solid var(--border-secondary);
}
.lab-part img { width: 26px; height: 26px; object-fit: contain; image-rendering: var(--face-render); }
.lab-part.opt { opacity: .45; border-style: dashed; }
.lab-chance { margin-left: 4px; color: var(--text-secondary); font-size: var(--fs-xs); font-variant-numeric: tabular-nums; }
.lab-foot { display: flex; gap: 8px; margin-top: auto; padding-top: 6px; }
/* 결과 — 마지막 드롭 카드(툴팁과 같은 카드 · 배경 · 테두리는 툴팁 몫이라 여기서 준다) · 그 아래 기록 칸(탐험 결과 칸과 같은 한 변) */
.lab-card { flex: none; }
.lab-card .tip-card { background: var(--bg-card); border: 1px solid var(--border-secondary); }
.lab-log-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: var(--fs-xs); }
.lab-log { grid-template-columns: repeat(auto-fill, 52px); gap: 6px; align-content: start; }

/* ───────── 겉모양 비교 — D2 Min (임시 · 2026-10-26 사용자 지시 · SCREEN_DESIGN §10-5 · ADR-0791) ─────────
   `⚙` 설정 탭 마지막 줄 `Skin` 이 `<html data-skin="d2min">` 을 걸면 화면을 **컨셉 17번(「최소화한 디아블로 2」)의 부품**으로 입힌다 —
   부품 다섯 장은 그 그림에서 잘라 낸 것이다(`src/assets/art/skins/source/cut_d2min_parts.py`):
     frame  = 패널 둘레의 두 겹 돌 테두리(9-slice · slice 11) · btn = 버튼의 밝은 턱(9-slice · slice 4) · slot = 파인 칸 한 칸
     chrome = 밝은 돌 결(상단바 · 제목 띠 · 버튼 · 고른 탭) · fill = 어두운 돌 결(패널 · 탭 열 · 카드)
   테두리는 `border-image` 로 그려 테두리 두께 · 여백을 안 바꾼다(그림 폭은 `border-image-width` · 바깥으로는 `-outset`).
   제목 띠는 음의 여백 = 같은 양의 안쪽 여백이라 글자 자리가 그대로다. 바뀌는 자리는 둘이다 — 탭 열(틀 안으로 버튼이 8px 들어간다) ·
   게임 화면 메인의 여백(사방 4px — 판이 상단바 · 탭 열 틀과 한 장 끝에 맞붙는다 · ADR-0792 · 0793) · 판과 판 사이(모두 8px · ADR-0794 · 0795).
   뜻이 있는 선(희귀도 · 등급 · 진영 · 고른 표시 · 경고 · 주 행동)은 다른 토큰 · 더 구체적인 규칙이라 그대로 선다.
   ⚠ 규칙은 모두 `:where(:root[data-skin="d2min"])` 로 감싼다 — 감싼 부분은 강도 0 이라 각 규칙이 바꾸는 기본 규칙과 같은 강도로 서고
     파일 끝이라 그것만 이긴다. 걷어낼 때는 이 절 · devcompare.js 의 Skin 줄 · `assets/art/skins/` 를 지운다 */
:root[data-skin="d2min"] {
    --sk-frame: url('../assets/art/skins/d2min_frame.webp');
    --sk-btn: url('../assets/art/skins/d2min_btn.webp');
    --sk-slot: url('../assets/art/skins/d2min_slot.webp');
    --sk-chrome: url('../assets/art/skins/d2min_chrome.webp');
    --sk-fill: url('../assets/art/skins/d2min_fill.webp');
    --sk-ground: #050505;
    --sk-lip: rgba(168, 160, 148, .30);   /* 돌 턱의 밝은 줄 — 컨셉의 테두리 밝은 쪽과 같은 결 */
    /* 중립 회색 선 → 홈 색 (판 사이 틈으로 읽힌다) */
    --border-primary: #070707;
    --border-secondary: #0a0a0a;
    --border-dark: #060606;
    --border-highlight: #6a6660;
    --bg-secondary: #0f0f0f;
    --bg-card: #0f0f0f;
    --bg-tertiary: #161616;
    --bg-input: #080808;
    --art-opacity: .03;
}

/* 바탕 — 판들 사이 틈 */
:where(:root[data-skin="d2min"]) #stage { background: linear-gradient(rgba(0, 0, 0, .6), rgba(0, 0, 0, .6)), var(--sk-fill), var(--sk-ground); }

/* 셸 — 상단바 · 브랜드는 밝은 돌, 탭 열은 어두운 돌. 셋 다 두 겹 돌 테두리를 두른다 */
:where(:root[data-skin="d2min"]) .brand,
:where(:root[data-skin="d2min"]) .topbar { background: var(--sk-chrome), #1a1a1a; }
:where(:root[data-skin="d2min"]) .nav { background: var(--sk-fill), #0f0f0f; }
:where(:root[data-skin="d2min"]) .brand,
:where(:root[data-skin="d2min"]) .topbar,
:where(:root[data-skin="d2min"]) .nav { border-image: var(--sk-frame) 11 / 9px / 0 round; }
/* 탭 — 틀 안으로 8px 들인다(글자 자리는 그대로) · 탭 사이 구분선 없음(「새 게임」 위 줄도 — 두께는 남아 자리가 그대로 · ADR-0836) · 고른 탭 = 밝은 돌판 + 턱 (왼쪽 빨간 띠는 그대로) */
:where(:root[data-skin="d2min"]) .nav button { margin: 0 8px; padding-left: 23px; padding-right: 8px; }
:where(:root[data-skin="d2min"]) .nav .b-newgame { border-top-color: transparent; }
:where(:root[data-skin="d2min"]) .nav button:hover { background: rgba(255, 255, 255, .03); }
:where(:root[data-skin="d2min"]) .nav button.on { background: var(--sk-chrome), #1c1c1c; box-shadow: inset 0 0 0 1px var(--sk-lip), inset 0 2px 0 rgba(255, 255, 255, .05), 0 1px 3px rgba(0, 0, 0, .8); }
:where(:root[data-skin="d2min"]) .nav button.todo::after { right: 12px; }

/* 패널 — 어두운 돌 + 두 겹 돌 테두리(바깥으로 4px 나간다 — 글자와 안 겹친다) */
:where(:root[data-skin="d2min"]) .panel {
    background: var(--sk-fill), #0f0f0f;
    border-image: var(--sk-frame) 11 / 11px / 4px round;
    box-shadow: 0 6px 16px rgba(0, 0, 0, .7);
}
/* 메인 여백 = 패널 테두리가 바깥으로 나간 4px(사방) — 판의 돌 테두리가 상단바 · 탭 열 틀과 한 장 끝에 맞붙어
   틈이 상단바 줄(브랜드 ↔ 상단바)과 같다 · 박스 아랫변은 「새 게임」 대신 탭 열 틀 아랫변에 맞는다 (2026-10-26 사용자 지시 · ADR-0792 · 0793) */
:where(:root[data-skin="d2min"]) #app:not(.pregame) > .main { padding: 4px; }
/* 상단바 줄 = 62px — 탐험 지도 판의 위아래 여백이 좌우와 같아지는 높이. 줄어든 메인 세로는 남는 세로를 받는 판(1fr · fill)이 내고
   영웅 띠 · 창고 · 인벤토리 줄은 내용 높이라 그대로다 · 게임 밖 화면은 48px 그대로 (ADR-0831) */
:where(:root[data-skin="d2min"]) #app:not(.pregame) { grid-template-rows: 62px 1fr; }
/* 상단바 줄의 버튼 · 글씨 = 모두 높이 가운데 (ADR-0841) — 상단바 위 여백 1px 이 아래 테두리 1px 와 맞서 내용 가운데 = 돌 틀 가운데 ·
   자원 줄은 버튼(30px)에 맞춰 늘어나 글씨 칸이 위에 붙었다 — 글씨 칸만 가운데로 세우고 줄 높이를 버튼 글씨와 같게(줄째 세우면 버튼이 줄어든다) ·
   브랜드 워드마크는 그림이라 그림 상자 = 보이는 높이 — 위 여백 없이 가운데 (ADR-0883) */
:where(:root[data-skin="d2min"]) #app:not(.pregame) > .topbar { padding-top: 1px; }
:where(:root[data-skin="d2min"]) #app:not(.pregame) .topbar > .resources > span { align-self: center; line-height: normal; }
/* 브랜드 그림 높이 = 돌 틀(위아래 9px) 안 — 게임 화면 줄 62px → 40px · 게임 밖 화면 줄 48px → 28px (ADR-0883) */
:where(:root[data-skin="d2min"]) #app:not(.pregame) > .brand img { height: 40px; }
:where(:root[data-skin="d2min"]) #app.pregame > .brand img { height: 28px; }
/* 판 사이 = 두 판이 바깥으로 나간 4px × 2 — 테두리가 맞닿아 셸 판끼리의 틈과 같다. 기본이 14px 인 자리(간격 · 위 마진)를 모두 고친다 (ADR-0794 · 0795) */
:where(:root[data-skin="d2min"]) .bt-page,
:where(:root[data-skin="d2min"]) .char-stack,
:where(:root[data-skin="d2min"]) .main .cols:not(.panel .cols),
:where(:root[data-skin="d2min"]) .bag-row,
:where(:root[data-skin="d2min"]) .tdm,
:where(:root[data-skin="d2min"]) .lib-col,
:where(:root[data-skin="d2min"]) .dp-wrap,
:where(:root[data-skin="d2min"]) .c-tavern > .tv-low { gap: 8px; }
:where(:root[data-skin="d2min"]) .panel + .panel,
:where(:root[data-skin="d2min"]) .hs-panel + .dp-wrap,
:where(:root[data-skin="d2min"]) .c-tavern > .tv-low { margin-top: 8px; }
/* ⚠ 나란히 선 판의 위 마진 0 — 기본 규칙이 위 줄과 같은 강도라 파일 끝인 위 줄이 덮는다. 같은 0 을 여기서 다시 건다 */
:where(:root[data-skin="d2min"]) .dp-wrap > .dp-side,
:where(:root[data-skin="d2min"]) .tv-low > .tv-gb { margin-top: 0; }
/* ── 판 밖에 남았던 것 — 박스 · 돌 처리 (ADR-0799) ──
   탐험 지도 = 판. 지도 칸(`.ex-map-wrap`)에 돌 테두리 · 어두운 돌 바탕을 두르고 지도는 그 안 가운데 선다(안쪽 여백 = 테두리가 안으로 들어온 만큼).
   지도 칸은 `overflow: hidden` 이라 지도에 테두리를 걸면 바깥으로 나간 4px 가 잘린다 — 그래서 칸에 건다. 위 영웅 띠와는 판 사이 8px */
:where(:root[data-skin="d2min"]) .hs-panel + .ex-map-wrap { margin-top: 8px; }
:where(:root[data-skin="d2min"]) .ex-map-wrap {
    display: flex; align-items: center; justify-content: center; padding: 7px;
    background: var(--sk-fill), #0f0f0f; border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 11px / 4px round;
}
/* 판 위에 뜨는 작은 창(탐험 지점 창 · 분해함 · 종 알림 판과 말풍선) — 툴팁 · 창과 같은 돌판 + 테두리 (ADR-0988) */
:where(:root[data-skin="d2min"]) .ex-pop,
:where(:root[data-skin="d2min"]) .salv-cube,
:where(:root[data-skin="d2min"]) .notification-panel,
:where(:root[data-skin="d2min"]) .notification-bubble { background: var(--sk-fill), #0f0f0f; border-image: var(--sk-frame) 11 / 11px / 3px round; }
/* 판 밖 탭 줄(도감 · 실험실) — 상단바처럼 돌 테두리 띠 안에 선다. 줄은 메인 배율을 되돌린 자리(zoom 1/.9)라
   테두리 값에 .9 를 곱해 판과 같은 굵기 · 아래 틈 7.2px = 판 사이(8 × .9) */
:where(:root[data-skin="d2min"]) .cx-tabs {
    padding: 7px 8px; margin-bottom: 7.2px;
    background: var(--sk-fill), #0f0f0f; border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 9.9px / 3.6px round;
}
/* 대장간 작업 탭 = 편성 고르개와 같은 폴더 탭 (ADR-0963 · 0847 · 0872 · 0876) — 띠 없이 작업 판의 돌 테두리 바깥 끝(선반)에 앉는다.
   줄 아래 마진 4 = 판 테두리가 위로 나간 몫 — 탭 밑변이 테두리 바깥 끝에 닿는다(열에 간격이 없다 · 편성은 판 사이 8 − 4) · 선 긋던 틈 · 남은 자리는 안 선다(판이 제 테두리를 두른다 — 윗변도 되살린다) ·
   넷이 같은 폭(가장 넓은 탭 — 격자 칸 1fr) · 고른 탭은 같은 모양이 위로 솟고(아래 맞춤이라 위로만 큰다) 글씨가 밝다 */
:where(:root[data-skin="d2min"]) .fg-tabs { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; width: max-content; align-items: end; gap: 3px; margin: 0 0 4px; padding: 0 12px; }
:where(:root[data-skin="d2min"]) .fg-tabs .fg-gap { display: none; }
:where(:root[data-skin="d2min"]) .fg-tab,
:where(:root[data-skin="d2min"]) .fg-tab.on {
    text-align: center; font-size: var(--fs-sm); font-weight: normal;   /* 글씨는 편성 · 도감 폴더 탭(작은 버튼)과 같다 — `Now` 의 난이도 탭 굵기를 안 물려받는다 */
    padding: 6.5px 24px; border: 1px solid transparent; border-bottom-width: 0; border-image: var(--sk-btn) 4 / 4px 4px 0 / 0 stretch;
    background: var(--sk-fill), #121212; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04); color: var(--text-secondary);
}
:where(:root[data-skin="d2min"]) .fg-tab:not(.on):not(:disabled):hover { color: var(--text-primary); border-color: transparent; }
:where(:root[data-skin="d2min"]) .fg-tab.on { padding: 9px 24px; color: #f2ece2; }
:where(:root[data-skin="d2min"]) .panel.fg-panel { border-top: 1px solid var(--border-primary); }
/* 종 알림 판의 폴더 탭 — 판 폭을 셋이 나눠 갖는다(영어 이름도 판 안 · 넘치면 말줄임) · 탭은 아래 본문 윗변에 앉는다 (ADR-0988) */
:where(:root[data-skin="d2min"]) .notification-folders.fg-tabs { width: auto; grid-auto-columns: minmax(0, 1fr); margin: 0; padding: 0 8px; }
:where(:root[data-skin="d2min"]) .notification-folders .fg-tab { padding-left: 8px; padding-right: 8px; }
:where(:root[data-skin="d2min"]) .notification-list { border-top: 1px solid var(--border-primary); }
/* 원정 난이도 탭 줄 — 띠 없이 판 밖에 그대로 선다(감싸던 돌 테두리 띠를 걷었다 · ADR-0830).
   탭 줄의 밑선(틈 · 남은 자리)은 안 긋는다 — 아래 목록 판이 제 테두리를 두른다 (ADR-0800) */
:where(:root[data-skin="d2min"]) .diff-tabs { align-items: center; }
:where(:root[data-skin="d2min"]) .diff-tabs .dt-gap:first-child { display: none; }
:where(:root[data-skin="d2min"]) .diff-tabs .dt-gap,
:where(:root[data-skin="d2min"]) .diff-tabs .dt-fill { border-bottom-color: transparent; }
:where(:root[data-skin="d2min"]) .diff-tabs .dt-report { margin-right: 0; padding: 6px 18px; font-size: var(--fs-md); }   /* 한 단 큰 버튼 — 여백은 상단바 부대 칸과 같다 (ADR-0864) */
/*   단계 화살표 — 「노말 › 나이트메어 › 헬」 글자만 선다(바탕 · 턱 · 테두리 없음). 글씨는 모두 17 — 고른 단은 흰 글씨 · 나머지는 어두운 글씨(ADR-0863) ·
     잠긴 단은 자물쇠 + 흐림(기본 규칙) · 마우스를 올리면 밝아진다. 탭 사이 틈이 화살표를 든다.
     줄 높이는 옛 버튼 줄(35)을 지켜 아래 목록 판이 제자리다 (ADR-0837).
     줄은 31 내려선다 — 글자 위(상단바 틀 아랫변까지)와 아래(솟은 고른 챕터 탭 윗변까지)가 같은 자리다(판은 맨 아래라 안 움직인다) ·
     첫 글자 왼끝은 Ch1 탭 왼끝(판 테두리 1 + 탭 줄 12)에서 16 안쪽이다 — 25 = 13 + 16 − 탭 안쪽 여백 4 (ADR-0839 · 0846 · 0854 · 0862) */
:where(:root[data-skin="d2min"]) .diff-tabs { min-height: 35px; margin-top: 31px; padding-left: 25px; }
/*   재접속 알림(맨 위에 떠서 선다 · ADR-0881)은 가운데가 이 줄 가운데(31 + 35/2)에 선다 — 떠 있는 동안 줄을 반만이 아니라 통째로 덮는다 · 두 줄이 돼도 가운데가 따라간다 */
:where(:root[data-skin="d2min"]) .notice-float > .notice-box { top: 48.5px; transform: translateY(-50%); }
:where(:root[data-skin="d2min"]) .diff-tabs .dt-gap:not(:first-child) { flex: 0 0 auto; align-self: center; display: inline-flex; align-items: center; padding: 0 10px; }
:where(:root[data-skin="d2min"]) .diff-tabs .dt-gap:not(:first-child)::before { content: '\203A'; color: #5d574f; font-size: 22px; line-height: 1; }
:where(:root[data-skin="d2min"]) .diff-tab { padding: 2px 4px; border: 0; border-image: none; background: none; box-shadow: none; font-size: 17px; color: #7d776e; }   /* 고른 단도 같은 크기 (ADR-0854 · 0863) */
:where(:root[data-skin="d2min"]) .diff-tab:not(.on):not(:disabled):hover { color: #dedad4; }
:where(:root[data-skin="d2min"]) .diff-tab.on { padding: 2px 4px; border: 0; background: none; font-size: 17px; color: #f2ece2; }
/* 게임 밖 — 새 게임 후보 셋 · 프롤로그 글도 판 안에 선다. 새 게임 판은 옛 위 여백 81 을 바깥 57 + 안 24 로 나눠 카드가 제자리다.
   후보 카드는 카드 모양(어두운 돌 + 턱 한 줄 · 윗변 희귀도 색은 그대로). 메뉴(워드마크 · 버튼 둘)는 표지라 판을 안 두른다 */
:where(:root[data-skin="d2min"]) .ng-wrap,
:where(:root[data-skin="d2min"]) .pro-wrap { background: var(--sk-fill), #0f0f0f; border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 11px / 4px round; }
:where(:root[data-skin="d2min"]) .ng-wrap { margin-top: 57px; padding: 24px 16px; }
/* 능력치 범례는 판 테두리 **밖**에 선다(뒤로가기처럼 · ADR-0943) — 판 안 카드 줄 옆 여백이 53(.9 배율 안에서 59)이라 범례가 테두리를 가로지른다 */
:where(:root[data-skin="d2min"]) .ng-legend { right: calc(100% + 45px + 59px); }
:where(:root[data-skin="d2min"]) .ng-card { background: var(--sk-fill), #121212; box-shadow: inset 0 0 0 1px var(--sk-lip), 0 3px 8px rgba(0, 0, 0, .7); }
/* 원정 목록 판 — 기본은 테두리가 없어(난이도 탭 줄이 윗선 · ADR-0785) 위 규칙보다 강한 `border: none` 이 돌 테두리를 걷었다.
   다른 판과 같은 테두리를 다시 두른다(위 여백은 아래 「챕터 줄은 목록 판 바깥 위」 묶음이 정한다) */
:where(:root[data-skin="d2min"]) .panel.diff-panel { border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 11px / 4px round; margin-top: 8px; }
/* 장소 줄 바탕은 `Now` 색 그대로 — 줄 · 그림 앞 그라데이션(app.js 인라인)이 `--bg-tertiary`(고른 줄은 `--bg-card`)를 쓰는데 위 토큰이 한 단 밝혀 회색이 됐다.
   줄에서만 토큰을 `Now` 값으로 되돌린다. 잠긴 줄은 줄째 반투명이라 판 바탕이 비친다 — 목록 판 안쪽도 `Now` 처럼 검정(테두리는 돌) (ADR-0800) */
:where(:root[data-skin="d2min"]) .panel.diff-panel { background: var(--surface-0); }
/* 원정 챕터 = 폴더 탭 — 탭은 어두운 돌 + 버튼 턱(밑변 없음) · 누르면 그 장의 탭이 위로 솟고 장이 넘어간다.
   선반 · 자리는 아래 「챕터 줄은 목록 판 바깥 위」 묶음이 정한다 (ADR-0801 · 0802 · 0809 · 0817) */
:where(:root[data-skin="d2min"]) .diff-panel > .sub-bar { align-items: flex-end; border-bottom: 2px solid var(--sk-lip); box-shadow: 0 1px 0 rgba(0, 0, 0, .8); }
:where(:root[data-skin="d2min"]) .diff-panel > .sub-bar > .segmented { flex: 1 1 auto; flex-wrap: nowrap; align-items: flex-end; gap: 3px; padding-left: 6px; }
/*   일곱 장이 줄 폭을 **같은 폭으로** 나눈다 — 글자가 그 폭보다 긴 장(영어)만 제 글자 폭까지 넓어지고 나머지가 그만큼 준다(줄어드는 하한 = 글자 폭) (ADR-0807) */
:where(:root[data-skin="d2min"]) .diff-panel > .sub-bar .btn {
    flex: 1 1 0; display: inline-flex; align-items: center; justify-content: center; white-space: nowrap; font-size: 14px; font-weight: 700;   /* 위 난이도 탭과 같은 굵기 · 크기는 1px 작다(글씨 단계 13 · 15 사이 · ADR-0825) */
    padding: 8px 10px 7px; border: 1px solid transparent; border-bottom-width: 0; border-image: var(--sk-btn) 4 / 4px 4px 0 / 0 stretch;
    background: var(--sk-fill), #121212; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04);
}
/*   고른 장 = 안 고른 탭과 **같은 모양**이 위로 10 솟는다 — 바탕 · 턱 · 밝기는 안 바꾼다. 위아래 여백을 5 씩 더해 글자는 가운데를 따라 5 오른다.
     장 색 테두리(렌더러 인라인)는 턱 그림(`border-image`)이 대신 그려 안 보인다 (ADR-0817) */
:where(:root[data-skin="d2min"]) .diff-panel > .sub-bar .btn.on {
    position: relative; z-index: 1; margin-bottom: 0; padding: 13px 10px 12px;
    border-width: 1px 1px 0; border-image: var(--sk-btn) 4 / 4px 4px 0 / 0 stretch;
    background: var(--sk-fill), #121212; filter: none; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04);
}
/*   챕터 줄은 목록 판 **바깥 위**에 선다 — 판의 돌 테두리 바깥 끝이 선반이고 모든 탭이 그 위에 앉는다. 고른 장의 탭은 **위로만** 커진다(판 안으로 안 내려온다).
     렌더러는 줄을 판 안에 넣는다 — 판에서 띄워(absolute) 판 위로 올린다. 판 위 여백 74 = 틈 + 탭 줄(= 솟은 고른 탭 높이) + 판 테두리 4 —
     탭 글씨 · 솟음을 줄이거나 난이도 띠를 걷어도 판 위 여백은 그대로이고 틈이 받는다 · 띠를 걷은 뒤 판째 24 더 내려선다(맨 아래까지는 안 간다) ·
     난이도 줄이 내려선 만큼 여백이 줄어든 뒤 판째 8 더 내려선다 (ADR-0809 · 0811 · 0812 · 0817 · 0819 · 0825 · 0826 · 0830 · 0833 · 0839 · 0854 · 0858) */
:where(:root[data-skin="d2min"]) .panel.diff-panel { position: relative; margin-top: 74px; padding-top: 19px; }   /* 위 여백 19 = 아래(줄 마진 8 + 판 여백 11) — 첫 장소 줄과 테두리 사이가 마지막 줄 아래와 같다 (ADR-0821) */
/*   목록 판은 메인 맨 아래에 붙는다 — 목록 판을 품은 메인만 세로 줄이 되고 남는 세로는 난이도 줄 아래(`auto`)가 받는다. 위 판 위 여백 74 는 그 틈의 최소다 ·
     내용이 메인보다 길면 틈이 74 로 줄고 메인이 스크롤된다 — 그래서 두 줄 다 안 줄어든다 (ADR-0859) */
:where(:root[data-skin="d2min"]) #app:not(.pregame) > .main:has(> .diff-panel) { display: flex; flex-direction: column; }
:where(:root[data-skin="d2min"]) .main > .diff-tabs { flex-shrink: 0; margin-bottom: auto; }
:where(:root[data-skin="d2min"]) .main > .panel.diff-panel { flex-shrink: 0; }
/*   장소 줄은 한 단 높다 — 109 → 118(화면 98 → 106px). 그림은 `cover` 라 위아래로 더 보이고, 맨 아래에 붙은 판은 위로 커진다 (ADR-0861) */
:where(:root[data-skin="d2min"]) .diff-panel .zone { min-height: 118px; }
:where(:root[data-skin="d2min"]) .diff-panel > .sub-bar { position: absolute; left: 12px; right: 12px; bottom: calc(100% + 5px); margin: 0; border-bottom: 0; box-shadow: none; }
:where(:root[data-skin="d2min"]) .diff-panel > .sub-bar > .segmented { padding-left: 0; }
:where(:root[data-skin="d2min"]) .zone { --bg-tertiary: var(--surface-1); --bg-card: var(--surface-0); --border-secondary: #4e4e4e; --border-highlight: #707070; }   /* 왼쪽 띠 · 올린 줄 테두리도 `Now` 값(맨 위 :root) */
/* 패널 제목 = 밝은 돌 띠 — 틀 안쪽 끝(7px)까지 넓힌다. 음의 여백만큼 안쪽 여백을 줘 글자 자리는 그대로다 */
:where(:root[data-skin="d2min"]) .panel > h2 {
    margin: -4px -10px 8px; padding: 4px 10px 5px;
    background: var(--sk-chrome), #1a1a1a;
    border-bottom-color: #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .04);
}
:where(:root[data-skin="d2min"]) .sub-h {
    margin-left: -8px; margin-right: -8px; padding-left: 8px; padding-right: 8px;
    background: var(--sk-chrome), #1a1a1a;
    border-bottom-color: #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .04);
}
/* 창고 · 인벤토리의 이름 줄(제목이 아니라 버튼과 한 줄인 도구 줄)도 같은 띠 — 위 · 옆은 패널 제목 띠와 같다.
   보관 칸은 남는 높이가 없어(칸 격자가 바로 아래) 띠 위아래 여백 4 + 홈 줄 1 + 격자까지 3 을 원래 아래 여백 8 안에서 나눈다 — 격자 자리 · 칸 크기 그대로 (ADR-0838) */
:where(:root[data-skin="d2min"]) .panel.bag > .items-tools {
    margin: -4px -10px 3px; padding: 4px 10px;
    background: var(--sk-chrome), #1a1a1a;
    border-bottom: 1px solid #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .04);
}

/* 버튼 — 밝은 돌 + 턱(9-slice). 고른 버튼 · 주 행동 · 상태 색 버튼은 턱을 걷어 제 테두리 색을 보인다 */
:where(:root[data-skin="d2min"]) .btn { background: var(--sk-chrome), #181818; border-image: var(--sk-btn) 4 / 4px / 0 stretch; color: #dedad4; box-shadow: inset 0 0 0 1px rgba(168, 160, 148, .16), 0 1px 2px rgba(0, 0, 0, .8); }
:where(:root[data-skin="d2min"]) .btn:hover { filter: brightness(1.25); }
:where(:root[data-skin="d2min"]) .btn.on,
:where(:root[data-skin="d2min"]) .btn.primary { border-image: none; }
:where(:root[data-skin="d2min"]) .btn.sm.on { background: var(--sk-chrome), #262626; box-shadow: inset 0 0 0 1px var(--sk-lip); color: #fff; }

/* 파인 칸 — 컨셉의 빈 칸 그림을 칸 크기로 늘린다. 찬 칸도 그 홈에 앉는다 · 장비 칸의 희귀도 선은 그림의 회색선 위에 선다(아래) */
:where(:root[data-skin="d2min"]) .inv-cell,
:where(:root[data-skin="d2min"]) .inv-cell.filled,
:where(:root[data-skin="d2min"]) .pd-cell,
:where(:root[data-skin="d2min"]) .pd-cell.filled,
:where(:root[data-skin="d2min"]) .sk-card,
:where(:root[data-skin="d2min"]) .tip-skills .tip-skill,
:where(:root[data-skin="d2min"]) .mon-sk .sk-ico,
:where(:root[data-skin="d2min"]) .cx-cand .ng-skill .sk-ico,
:where(:root[data-skin="d2min"]) .cd-slot,
:where(:root[data-skin="d2min"]) .p-slot,
:where(:root[data-skin="d2min"]) .fm-cell,
:where(:root[data-skin="d2min"]) .hs-card.empty,
:where(:root[data-skin="d2min"]) .cn-lot.empty { background: var(--sk-slot) center / 100% 100% no-repeat, #080808; box-shadow: none; }
/* 빈 자리의 점선은 칸 그림이 대신한다 */
:where(:root[data-skin="d2min"]) .inv-cell:not(.filled):not(.box),
:where(:root[data-skin="d2min"]) .pd-cell:not(.filled),
:where(:root[data-skin="d2min"]) .p-slot:not(.full),
:where(:root[data-skin="d2min"]) .fm-cell:not(.filled),
:where(:root[data-skin="d2min"]) .hs-card.empty,
:where(:root[data-skin="d2min"]) .cn-lot.empty { border-color: transparent; }
/* 큰 빈 칸(영웅 띠 빈 자리 · 빈 부지 · 진형 빈 칸)은 칸 그림을 통째로 늘리면 1~2px 선이 몇 배로 번진다 — 9-slice 로 바깥 6px(모든 스킨의 칸 테두리가 그 안이다)는
   원본 픽셀 그대로 두고 가운데만 늘린다 (ADR-0798 · 0804) */
:where(:root[data-skin="d2min"]) .hs-card.empty,
:where(:root[data-skin="d2min"]) .cn-lot.empty,
:where(:root[data-skin="d2min"]) .fm-cell:not(.filled) { background: #080808; border-image: var(--sk-slot) 6 fill / 6px stretch; }
:where(:root[data-skin="d2min"]) .inv-cell.filled:hover,
:where(:root[data-skin="d2min"]) .pd-cell:hover,
:where(:root[data-skin="d2min"]) .pd-cell.filled:hover { filter: brightness(1.35); }
/* 스킬 그림이 든 칸 — 관전 카드 스킬 칸 · 창고 스킬북 칸 — 은 칸 그림을 걷는다(회색 네모가 없다).
   그림 크기 · 칸 여백 · 테두리는 `Now` 그대로다 — 테두리는 홈 색이라 줄로 안 보인다. 빈 칸 · 자물쇠 칸은 그대로 (ADR-0840 · 0843 · 0844).
   관전 칸의 발동(`.fire`)은 제 바탕을 그대로 둔다 · 신단 효과 칸(72% 그림)은 스킬 칸이 아니라 뺀다 */
/* 액티브 스킬 칸(캐릭터 탭 · 도서관 · 영웅 툴팁 · 도감 몬스터)은 찬 칸도 회색 네모 위에 앉고, 그림이 네모 안쪽으로 살짝 작다 — 칸 여백 3 → 6.
   칸 그림의 회색 선은 칸 폭의 3/47 자리라 여백 3 이면 그림이 선에 닿았다 (ADR-0870 · 0882) */
:where(:root[data-skin="d2min"]) .sk-card:not(.vacant),
:where(:root[data-skin="d2min"]) .tip-skills .tip-skill:not(.vacant),
:where(:root[data-skin="d2min"]) .mon-sk .sk-ico,
:where(:root[data-skin="d2min"]) .cx-cand .ng-skill .sk-ico { padding: 6px; }
/* 도감 상세 툴팁도 목록 · 캐릭터창과 같은 네모 홈 — 후보 카드의 둥근 모서리를 여기서만 푼다 (ADR-1013) */
:where(:root[data-skin="d2min"]) .cx-cand .ng-skill .sk-ico { border-radius: 0; }
:where(:root[data-skin="d2min"]) .unit:not(.shrine) .cd-slot:not(.empty):not(.fire),
:where(:root[data-skin="d2min"]) .stash-books > .book-cell { background-image: none; }
/* 장비 칸의 희귀도 선 — 아이템이 든 칸은 칸 그림을 걷고(회색 네모가 없다) 선이 **칸 바깥 끝**에 붙는다 · 굵기 = 칸 폭 × 1.82/47
   (2026-10-26 사용자 지시 · ADR-0806 · 0810 · 0816 · 0822).
   굵기는 칸 크기에 비례한다 — 1600×800 에서 가방 · 창고 칸(46.4px) 1.8px · 장착 칸(54px) 2.1px (ADR-0822 「가방/창고 기준 1.8px」).
   칸 테두리 두께는 0 — 칸 크기는 그대로(border-box)고 칸 안쪽이 칸 끝까지 넓어진다. 계산된 테두리 색(인라인 `border-color`)은 남아 선이 물려받는다.
   선 = 칸보다 사방 1px 큰 판 두 장(::before · ::after)의 굵은 테두리(6px — 선이 그 안에 든다)를 ㄱ자 경로(clip-path)로 자른 것 —
   ::before = 위 + 왼쪽 · ::after = 오른쪽 + 아래, 두 조각은 모서리에서 겹친다. 선의 바깥 끝(칸 끝 = 판의 1px 안)과 안쪽 끝(칸 끝 + 선 굵기)을 모두 경로가 정한다.
   ⚠ 이렇게 된 까닭(2026-10-26 실측) — 굵기를 `cqw` 로 재면 메인 배율(.9) 아래에서 배율을 두 번 먹어 10% 얇았다 ·
     구멍을 마스크(그라디언트 · 그림)로 뚫으면 크기가 정수 px 로 반올림돼 1.8 · 1.9 모두 2px 로 그려졌다 ·
     판 끝을 칸 끝에 두면 판이 픽셀에 맞춰 반올림될 때 칸 끝의 선이 변마다 0 ~ 0.4px 깎였다 ·
     구멍 뚫린 고리를 경로 하나로 그리면 바깥 · 안쪽을 잇는 이음매가 모서리에 검은 점으로 남았다.
   칸 안 맨 아래 층이라 구석 글자(`+n` · `Lv.n`)가 그 위에 선다. 바탕은 그림 안쪽과 같은 #080808.
   스킨 키트(D2 Min 을 재질만 바꿔 다시 그린 것)도 칸이 같은 자리 · 크기라 같은 선을 받는다 (ADR-0901) */
:where(:root[data-skin="d2min"]) .inv-cell.filled[style*="border-color"],
:where(:root[data-skin="d2min"]) .pd-cell.filled[style*="border-color"] {
    --rare-line: calc(100% * 1.82 / 47);   /* 선 굵기 — 레벨 글자 자리에서 100% 는 칸 폭이다 */
    background-image: none; border-width: 0; isolation: isolate;
}
:where(:root[data-skin="d2min"]) .inv-cell.filled[style*="border-color"]::before,
:where(:root[data-skin="d2min"]) .inv-cell.filled[style*="border-color"]::after,
:where(:root[data-skin="d2min"]) .pd-cell.filled[style*="border-color"]::before,
:where(:root[data-skin="d2min"]) .pd-cell.filled[style*="border-color"]::after {
    --in: calc(1px + (100% - 2px) * 1.82 / 47);   /* 판 안에서 선의 안쪽 끝 — 100% 는 칸 + 2px 다 */
    content: ''; position: absolute; z-index: -1; inset: -1px; pointer-events: none;
    border-width: 6px; border-style: inherit; border-color: inherit;
}
:where(:root[data-skin="d2min"]) .inv-cell.filled[style*="border-color"]::before,
:where(:root[data-skin="d2min"]) .pd-cell.filled[style*="border-color"]::before {
    clip-path: polygon(1px 1px, calc(100% - 1px) 1px, calc(100% - 1px) var(--in), var(--in) var(--in), var(--in) calc(100% - 1px), 1px calc(100% - 1px));
}
:where(:root[data-skin="d2min"]) .inv-cell.filled[style*="border-color"]::after,
:where(:root[data-skin="d2min"]) .pd-cell.filled[style*="border-color"]::after {
    clip-path: polygon(calc(100% - 1px) 1px, calc(100% - 1px) calc(100% - 1px), 1px calc(100% - 1px), 1px calc(100% - var(--in)), calc(100% - var(--in)) calc(100% - var(--in)), calc(100% - var(--in)) 1px);
}
/* 레벨 글자(`Lv.n`)는 선 안쪽 — 선 굵기만큼 들인 뒤 기본 여백(오른쪽 3px · 아래 2px)을 둔다. 칸은 정사각이라 아래도 같은 비율이다 (ADR-0818 · 0822) */
:where(:root[data-skin="d2min"]) .inv-cell.filled[style*="border-color"] > .inv-lv,
:where(:root[data-skin="d2min"]) .pd-cell.filled[style*="border-color"] > .pd-lv { right: calc(var(--rare-line) + 3px); bottom: calc(var(--rare-line) + 2px); }
:where(:root[data-skin="d2min"]) .bar { background: #050505; box-shadow: inset 0 1px 2px rgba(0, 0, 0, .9), 0 1px 0 rgba(255, 255, 255, .04); }

/* 카드 — 영웅 띠 · 관전 · 전술 칸 · 건설 부지: 어두운 돌 + 턱 한 줄 (윗변 등급 · 진영 색 · 부지 그림은 그대로) */
:where(:root[data-skin="d2min"]) .hs-card,
:where(:root[data-skin="d2min"]) .unit,
:where(:root[data-skin="d2min"]) .rs-cell { background: var(--sk-fill), #121212; }
:where(:root[data-skin="d2min"]) .hs-card,
:where(:root[data-skin="d2min"]) .unit,
:where(:root[data-skin="d2min"]) .rs-cell,
:where(:root[data-skin="d2min"]) .cn-lot { box-shadow: inset 0 0 0 1px var(--sk-lip), 0 3px 8px rgba(0, 0, 0, .7); }

/* 편성 탭 — 박스 하나를 판 셋(진형 · 물약 | 파티 전술)으로 나눈다 · 판 사이 8px · 세로 가림선 없음 (ADR-0815).
   박스는 판을 걷고 스크롤 자리로만 남는다. 박스가 `overflow-y: auto` 라 안의 판 테두리(바깥 4px)가 잘리지 않게 안쪽 여백 4px 을 두고,
   그만큼 바깥으로 넓혀(음의 마진) 판 바깥 끝이 옛 박스 테두리 바깥 끝과 같다 */
:where(:root[data-skin="d2min"]) .panel.pt-body { background: none; border: 0; border-image: none; box-shadow: none; margin: 4px -4px -4px; padding: 4px; gap: 8px; }
/* 편성 고르개 = 폴더 탭 — 원정 챕터 줄과 같은 모양(어두운 돌 + 버튼 턱 · 밑변 없음). 띠 없이 판 셋의 돌 테두리 바깥 끝(선반)에 앉는다 —
   줄 아래 마진 −4 = 판 테두리가 위로 나간 몫 · 솟은 탭 위는 영웅 띠와 판 사이만큼 띄운다 · 탭 폭은 글자 폭(셋 이하라 줄을 안 나눈다) (ADR-0847) */
:where(:root[data-skin="d2min"]) .pt-body > .pt-pick { align-items: flex-end; gap: 3px; margin: 4px 0 -4px; padding: 0 12px; background: none; border: 0; border-image: none; box-shadow: none; }
:where(:root[data-skin="d2min"]) .pt-mid { gap: 8px; }
/* 모양 버튼 열의 위아래 빈자리(ADR-0577)는 「끝 버튼 ↔ 물약 이름」이었는데 물약이 다른 판으로 나갔다 —
   아래 빈자리 = 진형 판 안쪽 아랫변까지(판 아래 여백 11 − 테두리가 안으로 든 7) */
:where(:root[data-skin="d2min"]) .pt-left { gap: 8px; --pt-left-gap: 4px; }
:where(:root[data-skin="d2min"]) .pt-left > .fm-box,
:where(:root[data-skin="d2min"]) .pt-left > .pt-potion,
:where(:root[data-skin="d2min"]) .pt-mid > .pt-tactics {
    padding: 10px 16px 11px;
    background: var(--sk-fill), #0f0f0f; border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 11px / 4px round; box-shadow: 0 6px 16px rgba(0, 0, 0, .7);
}
:where(:root[data-skin="d2min"]) .pt-left > .pt-potion { flex: 1 1 auto; }   /* 왼쪽 열의 남는 세로 — 아랫변이 파티 전술 판과 맞는다 */
/* 소제목 띠 = 패널 제목 띠(위)와 같은 자리 — 판 테두리 안쪽 끝까지 */
:where(:root[data-skin="d2min"]) .pt-body .sub-h { margin: -4px -10px 20px; padding: 4px 10px 5px; }
/* 상단바 부대 칸 · 편성 고르개 = 큰 버튼 — 글씨는 작은 버튼 그대로 · 여백만 키운다 (ADR-0824 · 0828) ·
   편성 고르개는 폴더 탭 얼굴 — 고른 편성은 같은 모양이 위로 5 솟고(위아래 여백 +2.5) 글씨가 밝다 (ADR-0847 · 0869) */
:where(:root[data-skin="d2min"]) .tab-seg .btn.sm.seg-party { padding: 6px 18px; }
:where(:root[data-skin="d2min"]) .pt-body > .pt-pick .btn.sm {
    padding: 6.5px 24px; border: 1px solid transparent; border-bottom-width: 0; border-image: var(--sk-btn) 4 / 4px 4px 0 / 0 stretch;
    background: var(--sk-fill), #121212; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04); color: var(--text-secondary);
}
:where(:root[data-skin="d2min"]) .pt-body > .pt-pick .btn.sm.on { padding: 9px 24px; color: #f2ece2; }   /* 탭 높이는 한 단 낮다 — 안 고른 6.5 · 고른 9 (ADR-0876) */
/*   탭 셋은 같은 폭 — 가장 넓은 탭(보통 자물쇠가 든 Party III · 「원정 중」이 붙으면 그 탭)에 맞춘다. 줄을 제 내용 폭의 격자로 세우고 칸을 1fr 로 나누면
     칸이 모두 가장 넓은 칸의 폭이 된다 · 고정 px 이 아니라 언어 · 상태로 글자가 길어져도 안 넘친다 · 솟은 탭은 아래 맞춤이라 위로만 큰다 (ADR-0872) */
:where(:root[data-skin="d2min"]) .pt-body > .pt-pick { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; width: max-content; align-items: end; }
:where(:root[data-skin="d2min"]) .pt-body > .pt-pick .btn.sm { justify-content: center; text-align: center; }

/* 도서관 전직 갈래 — 구분선 대신 갈래마다 어두운 박스(판에 파인 홈) · 사이 8px. 고른 · 전직한 갈래의 안쪽 테두리는 그대로 위에 선다 ·
   올린 바탕은 기본(`--surface-5`)이 박스와 거의 같은 검정이라 한 단 덜 어둡게 따로 건다 (ADR-0834) */
:where(:root[data-skin="d2min"]) .tr-adv-row { gap: 8px; }
:where(:root[data-skin="d2min"]) .tr-adv-branch { border: 1px solid #050505; background: rgba(0, 0, 0, .5); box-shadow: inset 0 1px 6px rgba(0, 0, 0, .8), 0 1px 0 rgba(255, 255, 255, .04); }
:where(:root[data-skin="d2min"]) .tr-adv-branch.can-pick:hover { background: rgba(0, 0, 0, .25); }

/* 스킬 창(§7) — 마스터리 판 셋 = 다른 판과 같은 돌판 · 창 안 판 사이 8px (ADR-0865).
   판 머리 = 패널 제목 띠 — 테두리 안쪽 끝(7px)까지 넓고 왼쪽 「스킬 포인트」 띠와 같은 34px · 같은 줄(판 위 여백 10 − 4) ·
   판 색은 띠 아랫줄 2px 로 남는다(돌 테두리가 옛 테두리 · 윗변 3px 을 덮는다) · 띠 아래 ↔ 첫 줄 = 칸 사이 19 — 격자가 그만큼 올라선다 */
:where(:root[data-skin="d2min"]) .cols.c-skill { gap: 8px; }
:where(:root[data-skin="d2min"]) .c-skill > .sk-box { background: var(--sk-fill), #0f0f0f; border-image: var(--sk-frame) 11 / 11px / 4px round; box-shadow: 0 6px 16px rgba(0, 0, 0, .7); }
:where(:root[data-skin="d2min"]) .c-skill .sk-box-head {
    box-sizing: border-box; min-height: 34px; align-items: center; align-content: center;
    margin: -4px -13px 19px; padding: 0 13px;
    background: var(--sk-chrome), #1a1a1a; border-bottom: 1px solid #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .04);
}
:where(:root[data-skin="d2min"]) .c-skill .sk-box-head .sk-head-icon { align-self: center; }
:where(:root[data-skin="d2min"]) .c-skill .mastery-colored > .sk-box-head { border-bottom: 2px solid var(--mastery-color); }
/*   칸 = 빈 칸 그림 — 판 색 · 청동 테두리와 미작성 칸 점선은 걷는다 · 올려도 그림 그대로(누를 수 있는 칸만 한 단 밝다).
     찍은 칸(1랭크 이상)은 회색 네모를 지우고 판 색 선 2px(테두리 1 + 안쪽 1)이 칸 바깥 끝에 붙는다 — 장비 칸의 든 칸과 같은 말이다 ·
     전직 판의 스킬 칸은 스킬 그림이 든 칸이라 회색 네모만 지운다(ADR-0843 · 0844) · 가지 칸 사이 세로 선은 그대로.
     ⚠ 기본 규칙의 판 색 테두리(`.sk-box.mastery-colored .sk-cell.icon-only`)가 강도 4 라 `.sk-grid` 를 끼워 같은 강도로 선다 */
:where(:root[data-skin="d2min"]) .c-skill .sk-box .sk-grid .sk-cell,
:where(:root[data-skin="d2min"]) .c-skill .sk-box .sk-grid .sk-cell:hover { background: var(--sk-slot) center / 100% 100% no-repeat, #080808; border-color: transparent; box-shadow: none; }
:where(:root[data-skin="d2min"]) .c-skill .sk-box .sk-grid .sk-cell.can:hover { filter: brightness(1.35); }
:where(:root[data-skin="d2min"]) .c-skill .mastery-colored .sk-grid .sk-cell.taken,
:where(:root[data-skin="d2min"]) .c-skill .mastery-colored .sk-grid .sk-cell.taken:hover { background: #080808; border-color: var(--mastery-color); box-shadow: inset 0 0 0 1px var(--mastery-color); }
:where(:root[data-skin="d2min"]) .c-skill .adv-board .sk-grid .sk-cell[data-advskill],
:where(:root[data-skin="d2min"]) .c-skill .adv-board .sk-grid .sk-cell[data-advskill]:hover { background-image: none; }
/*   구석 글자(필요 레벨 · 랭크) — 바탕 상자를 걷고 장비 칸 구석 글자처럼 검은 테두리로 두른다. 자리(칸 끝 + 4)는 선 2px 안쪽이라 그대로 */
:where(:root[data-skin="d2min"]) .c-skill .sk-icon-lock,
:where(:root[data-skin="d2min"]) .c-skill .sk-icon-rank { background: none; text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000; }
/*   액티브 줄 = 도서관 전직 갈래와 같은 어두운 홈 박스(ADR-0834) · 빈 줄은 점선을 걷고 박스는 그대로 — 글만 흐리다 */
:where(:root[data-skin="d2min"]) .c-skill .act-slot { border: 1px solid #050505; background: rgba(0, 0, 0, .5); box-shadow: inset 0 1px 6px rgba(0, 0, 0, .8), 0 1px 0 rgba(255, 255, 255, .04); }
:where(:root[data-skin="d2min"]) .c-skill .act-slot.empty { opacity: 1; }
:where(:root[data-skin="d2min"]) .c-skill .act-slot.empty > * { opacity: .55; }

/* 건설 탭(§13-1) — 박스 하나를 판 둘(부지 | 상세)로 나눈다 · 판 사이 8px (ADR-0875 · 편성 탭 ADR-0815 와 같은 길).
   박스는 판을 걷고 스크롤 자리로만 남는다 — `overflow-y: auto`(`.page-stack > .fill`)라 안 판의 테두리(바깥 4px)가 잘리지 않게
   안쪽 여백 4 를 두고 그만큼 바깥으로 넓힌다. 상세 폭은 그대로(옛 박스 여백 40 을 빼고 잰 값) · 남는 폭은 부지 판이 받는다 */
:where(:root[data-skin="d2min"]) .panel.cn-box { background: none; border: 0; border-image: none; box-shadow: none; margin: -4px; padding: 4px; }
:where(:root[data-skin="d2min"]) .cn-work { gap: 8px; grid-template-columns: minmax(0, 1fr) minmax(0, calc((100% - 64px) / 2 - 100px)); }
:where(:root[data-skin="d2min"]) .cn-work > .cn-lotbox,
:where(:root[data-skin="d2min"]) .cn-side {
    background: var(--sk-fill), #0f0f0f; border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 11px / 4px round; box-shadow: 0 6px 16px rgba(0, 0, 0, .7);
}
/*   부지 판 안 여백 = 부지 둘레 22 사방(칸 사이 · 줄 사이와 같다) */
:where(:root[data-skin="d2min"]) .cn-work > .cn-lotbox { width: auto; justify-self: stretch; padding: var(--cn-gap); }
/*   제목 띠 = 판 틀 안쪽 끝(테두리 끝 + 7)까지 밝은 돌 띠 — 판 제목(`.panel > h2`)과 같은 띠 · 같은 안쪽 여백(위 4 · 옆 10 · 아래 5) ·
     두 판 모두 띠 아래 틈이 같아 그림 윗변 = 부지 첫 줄 윗변이 그대로다 (ADR-0919) */
:where(:root[data-skin="d2min"]) .cn-lotbox > .cn-title { margin: -16px -16px var(--cn-title-gap); padding: 4px 10px 5px; }
:where(:root[data-skin="d2min"]) .cn-side > .cn-title { margin: -16px -8px var(--cn-title-gap); padding: 4px 10px 5px; }
/*   상세 판 위 여백 22 — 그림 윗변 = 부지 첫 줄 윗변. 옛 자리보다 13 올라선 만큼 그림이 커져(114 → 127)
     두 소제목의 글자 윗선은 부지 둘째 줄 윗변 그대로다(§13-1 · 그림 + 눈금 = 127 + 6 + 7) */
:where(:root[data-skin="d2min"]) .cn-side { padding-top: var(--cn-gap); }
:where(:root[data-skin="d2min"]) .cn-head { --cn-thumb-h: 127px; --cn-head-h: 140px; }
/*   부지 · 상세 그림 = 모두 빈 칸 그림의 테(9-slice 6 · 가운데는 비운다) 안에 그림 — 지었나는 그림 위 베일(안 지음)이 말한다 (ADR-0888).
     그림 끝은 **테의 회색 선 안쪽 검정 = 바깥 검정 + 2** 인 자리다. 칸 그림의 선은 변마다 자리가 달라(바깥 검정 · 선 = 왼 3·1 · 위 2·2 · 오른 1·2 · 아래 1·2)
     그림 끝 = 칸 끝에서 왼 9 · 위 8 · 오른 6 · 아래 6 — 테두리 1 을 뺀 안쪽 여백이다(`--cn-in-*` · 안팎 같던 7 · 6 · 4 · 4 에서 2 씩 더 들였다 · ADR-0894).
     그림 · 베일 · 이름 띠는 안쪽 여백 안(content-box)에 그리고 여백은 안쪽 그림자 넷이 칸 그림 안쪽 색으로 변마다 칠한다(퍼짐 하나로 칠하면 얇은 변에서 그림을 덮는다) ·
     상세 그림은 크기 그대로(border-box). 고른 부지는 붉은 테(2)가 홈 테를 대신하고 그림 자리는 같다 · 초록 점은 그림 모서리 안쪽 · 올리면 한 단 밝다 */
:where(:root[data-skin="d2min"]) .cn-lot:not(.empty),
:where(:root[data-skin="d2min"]) .cn-head .cn-thumb {
    --cn-in-t: 7px; --cn-in-r: 6px; --cn-in-b: 5px; --cn-in-l: 7px;   /* 왼 · 오른은 회색 선 사이 가운데(왼 선 끝 4 · 오른 선 끝 3 → 왼 = 오른 + 1 · 합 13) — ADR-0898 */
    border-color: transparent; border-image: var(--sk-slot) 6 / 6px stretch;
    padding: var(--cn-in-t) var(--cn-in-r) var(--cn-in-b) var(--cn-in-l); background-origin: content-box; background-clip: content-box;
    box-shadow: inset 0 var(--cn-in-t) 0 #080808, inset calc(-1 * var(--cn-in-r)) 0 0 #080808, inset 0 calc(-1 * var(--cn-in-b)) 0 #080808, inset var(--cn-in-l) 0 0 #080808;
}
:where(:root[data-skin="d2min"]) .cn-head .cn-thumb { box-sizing: border-box; }
/*   그림은 그림 칸을 **꽉 채운다**(`cover` — 가로는 그림 전부) · 회색 선 → 그림 거리가 네 변 모두 약 4 다 (ADR-0899).
     그림 칸이 옛 칸보다 가로로 길어 위아래가 조금 더 잘리는데, **위끝은 `Now` 와 같은 자리**에서 자르고(지붕 · 깃발이 그대로) 더 잘리는 몫은 아래 이름 띠 밑이 받는다 —
     세로 자리 = 위끝이 `Now` 와 같아지는 값(부지 34% · 상세 31% — `Now` 의 칸 · 그림 크기로 잰 값 · 칸 크기가 바뀌면 다시 잰다).
     옛 「통째로 줄여 가로 가운데」(ADR-0896)는 양옆에 검은 띠가 남아 양옆이 잘려 보였다 */
:where(:root[data-skin="d2min"]) .cn-lot.has-img:not(.empty),
:where(:root[data-skin="d2min"]) .cn-head .cn-thumb {
    background-color: #080808; background-size: cover; background-position: center var(--cn-pic-y);
    background-origin: content-box; background-clip: content-box;   /* ⚠ 안 지은 부지의 베일 규칙(`.cn-lot.has-img:not(.on)` · 강도 3)이 줄임말로 이 둘을 되돌린다 — 같은 강도인 여기서 다시 건다 */
}
:where(:root[data-skin="d2min"]) .cn-lot.has-img:not(.empty) { --cn-pic-y: 34%; }
:where(:root[data-skin="d2min"]) .cn-head .cn-thumb { --cn-pic-y: 31%; }
:where(:root[data-skin="d2min"]) .cn-lot.pick:not(.empty) { --cn-in-t: 5px; --cn-in-r: 4px; --cn-in-b: 3px; --cn-in-l: 5px; border-color: var(--color-info); border-image: none; }   /* 파란 3px (ADR-0927) */
:where(:root[data-skin="d2min"]) .cn-lot.ready:not(.empty)::after { top: 13px; right: 12px; }   /* 그림 모서리에서 6 안쪽 — 그림 위끝 = 칸 끝 + 8 · 오른끝 = 칸 끝 + 7 */
:where(:root[data-skin="d2min"]) .cn-lot.pick.ready:not(.empty)::after { top: 11px; right: 10px; }   /* 고른 부지 — 테두리가 2 굵어진 만큼 되돌려 그림 모서리에서 같은 자리 */
:where(:root[data-skin="d2min"]) .cn-lot:not(.empty):hover { filter: brightness(1.2); }
/*   랭크 눈금의 안 찬 칸 = 턱 줄 색 테두리만(속은 비었다) — 회색 칸이 홈 색이 되어 막대가 지은 칸만 남았다 · 찬 칸은 주황 그대로 */
:where(:root[data-skin="d2min"]) .cn-pips span { background: transparent; box-shadow: inset 0 0 0 1px rgba(168, 160, 148, .45); }   /* 턱 줄 색(.30)은 돌 바탕 위 상세 눈금에서 흐려 한 단 밝다 */
:where(:root[data-skin="d2min"]) .cn-pips span.on { box-shadow: none; }
/*   재료 칸 = 빈 칸 그림(창고의 재료 칸과 같다 · 모자란 칸의 붉은 테는 그대로) · 랭크 줄 사이 = 홈 줄(제목 띠 아랫줄과 같다) */
:where(:root[data-skin="d2min"]) .cn-mat { background: var(--sk-slot) center / 100% 100% no-repeat, #080808; border-color: transparent; }
/*   칸 그림 안의 재화 그림은 한 단 작다(34 → 28 · 실루엣 32 → 26) — 칸 그림의 안쪽 회색 네모에 닿고 수량 글자와 겹쳤다 (ADR-0877) */
:where(:root[data-skin="d2min"]) .cn-mat img { width: 28px; height: 28px; }
:where(:root[data-skin="d2min"]) .cn-mat svg { width: 26px; height: 26px; }
:where(:root[data-skin="d2min"]) .cn-rank { border-bottom-color: #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .05); }

/* 도감(§9 · §9-1) — 다른 탭의 D2 Min 부품을 그대로 쓴다 · 새 부품은 없다 (ADR-0904).
   판 위 고르개 줄(챕터 · 무기/방어구/물약 · 일반/전직 · 그림체 · 죄종/직업/전직) = 편성 고르개와 같은 폴더 탭 — 판 바깥 윗변(선반)에 앉는다.
   렌더러는 줄을 판 안 첫 줄로 넣는다 — 판에서 띄워(absolute) 판 위로 올리고(원정 챕터 줄과 같은 길 · ADR-0809) 판은 그만큼 내려선다.
   판 위 여백 43 = 위 탭 줄과의 사이 8(편성과 같다 — 위 줄 아래 마진 8 + 4) + 솟은 탭 높이 35 + 판 테두리 4 − 위 줄 아래 마진 8 */
:where(:root[data-skin="d2min"]) .panel.cx-box:has(> .sub-bar) { position: relative; margin-top: 43px; }
:where(:root[data-skin="d2min"]) .cx-box > .sub-bar { position: absolute; left: 12px; right: 12px; bottom: calc(100% + 5px); margin: 0; align-items: flex-end; }
/*   탭 = 어두운 돌 + 버튼 턱(밑변 없음) · 같은 폭(가장 넓은 탭) · 고른 탭은 같은 모양이 위로 5 솟고 글씨가 밝다 (ADR-0847 · 0869 · 0872 · 0876).
     챕터 탭 글자는 죄종 색 그대로(렌더러 인라인 — 장 색 테두리는 턱 그림이 덮는다) · 상단바 크기로 되돌리던 배율(`.cx-ch-seg`)은 안 탄다 — 다섯 세그먼트의 탭이 같은 크기 */
:where(:root[data-skin="d2min"]) .cx-box > .sub-bar > .segmented { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; width: max-content; align-items: end; gap: 3px; zoom: 1; }
:where(:root[data-skin="d2min"]) .cx-box > .sub-bar > .segmented .btn.sm {
    text-align: center; white-space: nowrap;
    padding: 6.5px 24px; border: 1px solid transparent; border-bottom-width: 0; border-image: var(--sk-btn) 4 / 4px 4px 0 / 0 stretch;
    background: var(--sk-fill), #121212; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04); color: var(--text-secondary);
}
:where(:root[data-skin="d2min"]) .cx-box > .sub-bar > .segmented .btn.sm.on { padding: 9px 24px; color: #f2ece2; }
/*   줄의 나머지(죄종 · 일반/정예 · 얼굴 스타일 / ▶ 전부 재생)는 같은 줄 오른쪽 끝 · 버튼 그대로 */
:where(:root[data-skin="d2min"]) .cx-box > .sub-bar > :not(.segmented) { margin-left: auto; align-self: flex-end; margin-bottom: 4px; }
/*   스테이지 이름 줄 밑선 = 홈 줄 · 몬스터 카드 = 어두운 돌 + 턱 한 줄(영웅 카드와 같은 말 — 카드 줄이 가로 스크롤 칸이라 바깥 그림자는 잘려 안 건다) ·
     초상 원 테 = 턱 줄 색(홈 색이라 안 보였다 · 보스 붉은 테 · 아트 없는 원의 죄종 색 테는 그대로) ·
     안 켜진 레벨 핍 = 턱 줄 색 테두리만(건설 랭크 눈금과 같다 · §9 「안 켜진 레벨 핍도 보인다」 — 홈 색이라 안 보였다) */
:where(:root[data-skin="d2min"]) .cs-head { border-bottom-color: #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .05); }
:where(:root[data-skin="d2min"]) .mon-card { background: var(--sk-fill), #121212; box-shadow: inset 0 0 0 1px var(--sk-lip); }
:where(:root[data-skin="d2min"]) .mon-card .face:not(.boss) { border-color: var(--sk-lip); }
:where(:root[data-skin="d2min"]) .pips .pip { background: transparent; border-color: rgba(168, 160, 148, .45); }
/*   툴팁의 가름선(머리글 아랫선 · 단계 줄 가로선 · 레벨 | 보정 세로선 · 스킬 툴팁 두 장 사이) = 홈 줄 — 홈 색 토큰이라 안 보였다(§9 「칸은 선으로 가른다」) */
:where(:root[data-skin="d2min"]) .cx-tip-h { border-bottom-color: #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .05); }
:where(:root[data-skin="d2min"]) .cx-step { border-top-color: #050505; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05); }
:where(:root[data-skin="d2min"]) .cx-step:first-child { box-shadow: none; }
:where(:root[data-skin="d2min"]) .cx-step-b { border-left-color: #050505; box-shadow: inset 1px 0 0 rgba(255, 255, 255, .05); }
:where(:root[data-skin="d2min"]) .tip-card.cx-sk-tip { border-left-color: #050505; box-shadow: inset 1px 0 0 rgba(255, 255, 255, .05); }
/*   자산 묶음 상자(캐릭터 · 아이템 · 스킬 · 이펙트) = 판에 파인 어두운 홈 박스(도서관 전직 갈래와 같다 · ADR-0834) */
:where(:root[data-skin="d2min"]) .ix-group { background: rgba(0, 0, 0, .5); border-color: #050505; box-shadow: inset 0 1px 6px rgba(0, 0, 0, .8), 0 1px 0 rgba(255, 255, 255, .04); }
/*   타일(캐릭터 · 아이템) = 바탕 · 테두리 없이 그림 칸에 빈 칸 그림의 테(9-slice 6)를 **바깥으로** 두른다 — 칸 안에 깔면 초상이 테를 덮는다 ·
     그림 크기 그대로 · 테가 바깥으로 나간 5 만큼 이름 줄이 내려선다. 전직 스킬 타일(조밀)은 일반 스킬 타일처럼 그림만(전직 색 바탕 그대로) */
:where(:root[data-skin="d2min"]) .ix-grid > .ix-tile { background: none; border-color: transparent; }
:where(:root[data-skin="d2min"]) .ix-body:not(.dense) .ix-grid > .ix-tile > .ix-art { margin-bottom: 5px; border-color: transparent; border-image: var(--sk-slot) 6 / 6px / 5px stretch; }
/*   마스터리 세그먼트 판 = 스킬 창 마스터리 판과 같다(ADR-0865) — 돌판 · 판 사이 8 · 머리 = 밝은 돌 띠(테두리 안쪽 끝까지 · 판 색은 띠 아랫줄 2px) ·
     칸 = 빈 칸 그림(판 색 테두리를 걷는다 — 도감 판은 찍은 칸이 없다) · 구석 글자는 바탕 없이 검은 테두리 글자 · 전직 판의 스킬 칸은 회색 네모를 지운다.
     판 목록이 스크롤 칸이라 판 테두리(바깥 4)가 안 잘리게 위 여백 4 */
:where(:root[data-skin="d2min"]) .codex-mastery-grid { gap: 8px; padding-top: 4px; }
:where(:root[data-skin="d2min"]) .codex-mastery-grid > .sk-box { background: var(--sk-fill), #0f0f0f; border-image: var(--sk-frame) 11 / 11px / 4px round; box-shadow: 0 6px 16px rgba(0, 0, 0, .7); }
:where(:root[data-skin="d2min"]) .codex-mastery-grid .sk-box-head {
    box-sizing: border-box; min-height: 34px; align-items: center; align-content: center;
    margin: -4px -5px 14px; padding: 0 5px;
    background: var(--sk-chrome), #1a1a1a; border-bottom: 1px solid #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .04);
}
:where(:root[data-skin="d2min"]) .codex-mastery-grid .mastery-colored > .sk-box-head { border-bottom: 2px solid var(--mastery-color); }
:where(:root[data-skin="d2min"]) .codex-mastery-grid .sk-box .sk-grid .sk-cell,
:where(:root[data-skin="d2min"]) .codex-mastery-grid .sk-box .sk-grid .sk-cell:hover { background: var(--sk-slot) center / 100% 100% no-repeat, #080808; border-color: transparent; box-shadow: none; }
:where(:root[data-skin="d2min"]) .codex-mastery-grid .adv-board .sk-grid .sk-cell[data-advskill] { background-image: none; }
:where(:root[data-skin="d2min"]) .codex-mastery-grid .sk-icon-lock,
:where(:root[data-skin="d2min"]) .codex-mastery-grid .sk-icon-rank { background: none; text-shadow: 0 1px 1px #000, 0 -1px 1px #000, 1px 0 1px #000, -1px 0 1px #000, 0 0 3px #000; }

/* 연구소 탭(§8) — 크기는 「트리 격자에 일곱 줄이 든다」에서 낸다 (2026-10-27 사용자 지시 · ADR-0903).
   행 = (격자 높이 − 6 × 행 사이 8) ÷ 7 — 1600×800 에서 격자 599 → 행 78.8 · 카드가 행을 꽉 채운다(옛 카드 위아래 6 을 걷는다 · 카드 사이 = 원정 장소 줄 사이 8).
   **한 행의 네모는 모두 56**(행의 71% · 위아래 11) — 줄 그림 · 영웅 칸 · 지점 칸이 한 띠다. 카드 안 폭 368 = 그림 56 + 틈 10 + 영어 줄 이름(가장 길던 `Visiting Heroes` 108 로 쟀다) + 틈 10 + 칸 셋 176(56 × 3 + 4 × 2) 이 한 줄에 든다.
   카드 열은 격자의 40% 가 하한이고 **내용 폭까지 넓어진다** — 상태 한 마디(「닫힘」 · `Closed`)가 이름 옆에 서면 영어 카드가 40% 를 넘는다(이름이 말줄임되지 않는다 · 지점 열이 그만큼 준다) */
:where(:root[data-skin="d2min"]) .dp-tree { --dp-orb: 56px; --dp-off: #050505; }
:where(:root[data-skin="d2min"]) .dp-tree-grid { --dp-row-gap: 8px; grid-template-columns: minmax(40%, max-content) repeat(var(--dp-tiers), minmax(0, 1fr)); }
:where(:root[data-skin="d2min"]) .dp-tree-line { padding: 0; }
/*   줄 카드 = 카드 문법(어두운 돌 + 턱 한 줄 + 그림자) · 고른 줄의 왼쪽 띠(기본 규칙) · 파란 겉 테두리는 그대로 · 올리면 · 고르면 한 단 밝다 */
:where(:root[data-skin="d2min"]) .dp-card { background: var(--sk-fill), #121212; box-shadow: inset 0 0 0 1px var(--sk-lip), 0 3px 8px rgba(0, 0, 0, .7); }
:where(:root[data-skin="d2min"]) .dp-card.on { background: linear-gradient(rgba(255, 255, 255, .05), rgba(255, 255, 255, .05)), var(--sk-fill), #121212; }
:where(:root[data-skin="d2min"]) .dp-card:hover { background: linear-gradient(rgba(255, 255, 255, .03), rgba(255, 255, 255, .03)), var(--sk-fill), #121212; }
/*   줄 그림 = 빈 칸 그림의 테 안(원을 걷는다) — 그림 자리는 건설 부지 그림과 같다(칸 끝에서 위 8 · 좌우 회색 선 사이 가운데 · 아래 6 · ADR-0894 · 0898).
     테는 그림 바깥 여백에만 그린다(가운데 `fill` 없음 — 그림이 칸 안을 덮는다) · 도박장 코인은 원 그림이라 자르지 않는다 */
:where(:root[data-skin="d2min"]) .dp-card-ico,
:where(:root[data-skin="d2min"]) .dp-card-ico.sq {
    width: 56px; height: 56px; border-radius: 0; padding: 7px 6px 5px 7px;
    background: #080808; border: 1px solid transparent; border-image: var(--sk-slot) 6 / 6px stretch;
}
:where(:root[data-skin="d2min"]) .dp-card-ico:not(.sq) { object-fit: contain; }
/*   영웅 칸 56 — 얼굴 칸은 턱 줄 테두리 · 빈 칸 `+` · 자물쇠 칸 = 빈 칸 그림 9-slice(영웅 띠 빈 자리와 같다) · 칸째 흐리지 않고 자물쇠만 옅게 (ADR-0850 과 같은 까닭) */
:where(:root[data-skin="d2min"]) .dp-reg-row { gap: 4px; }
:where(:root[data-skin="d2min"]) .dp-reg-face { width: 56px; height: 56px; background: #080808; border-color: var(--sk-lip); }
:where(:root[data-skin="d2min"]) .dp-reg-face.empty { background: #080808; border-color: transparent; border-image: var(--sk-slot) 6 fill / 6px stretch; font-size: var(--fs-lg); }
:where(:root[data-skin="d2min"]) .dp-reg-face.empty:hover { filter: brightness(1.35); }
:where(:root[data-skin="d2min"]) .dp-reg-face.lock,
:where(:root[data-skin="d2min"]) .dp-fx-heroes .hs-card.lock,
:where(:root[data-skin="d2min"]) .hero-strip .hs-card.lock { opacity: 1; }
:where(:root[data-skin="d2min"]) .dp-reg-face.lock svg { width: 18px; height: 18px; opacity: .6; }
:where(:root[data-skin="d2min"]) .dp-fx-heroes .hs-card.lock svg,
:where(:root[data-skin="d2min"]) .hero-strip .hs-card.lock svg { opacity: .6; }
/*   지점 = 빈 칸 그림 네모 56(원을 걷는다) · 그림 40(56 × .72) · 잠김은 흐린 그림 + 자물쇠 그대로 · `Lv.n` 은 칸 안 오른쪽 아래(회색 선 3.6 안쪽 — 장비 칸 레벨 글자와 같은 자리) ·
     연구 중 = 회색 네모를 지우고 주황 선 2px(테두리 1 + 안쪽 1)이 칸 바깥 끝 — 스킬 창 찍은 칸과 같은 말 (ADR-0865) · 고른 지점의 파란 겉 테두리는 그대로 ·
     ⚠ 기본 규칙의 열린 노드(`.dp-tree-cell.open .dp-tree-orb`)가 강도 3 이라 같은 선택자로 다시 건다 */
:where(:root[data-skin="d2min"]) .dp-tree-orb,
:where(:root[data-skin="d2min"]) .dp-tree-cell.open .dp-tree-orb { border-radius: 0; border: 0; background: var(--sk-slot) center / 100% 100% no-repeat, #080808; }
:where(:root[data-skin="d2min"]) .dp-tree-cell.doing .dp-tree-orb { background: #080808; border: 1px solid var(--color-progress); box-shadow: inset 0 0 0 1px var(--color-progress); }
:where(:root[data-skin="d2min"]) .dp-tree-cell:hover .dp-tree-orb { filter: brightness(1.35); }
:where(:root[data-skin="d2min"]) .dp-tree-orb.dp-node-orb img { width: 40px; height: 40px; }
:where(:root[data-skin="d2min"]) .dp-tree-orb .lock-ico svg { width: 20px; height: 20px; }
:where(:root[data-skin="d2min"]) .dp-tree-orb .dp-lv-tag { right: 6px; bottom: 5px; }
/*   노드 사이 선 — 꺼진 선은 홈 줄(검정 + 아래 밝은 1px · 제목 띠 아랫줄과 같다) · 켜진 선은 밝은 돌 색 그대로 */
:where(:root[data-skin="d2min"]) .dp-tree-cell:not(.in)::before,
:where(:root[data-skin="d2min"]) .dp-tree-cell:not(.out)::after { box-shadow: 0 1px 0 rgba(255, 255, 255, .05); }
/*   오른쪽 판 제목 띠 = 트리 판 제목 띠와 같은 줄 · 같은 높이 — 판 위 여백 12 → 10(다른 판과 같다) · 글자는 한 벌 +2px(17) 그대로 두고 줄 높이만 트리 띠(15 × 1.6 = 24)에 맞춘다 */
:where(:root[data-skin="d2min"]) .dp-wrap > .dp-side { padding-top: 10px; }
:where(:root[data-skin="d2min"]) .dp-side > h2 { line-height: 24px; }
/*   오른쪽 머리 그림 = 빈 칸 그림의 테 안 — 지점 96 네모(9-slice · 테두리 6 은 원본 그대로 · ADR-0798) · 줄 그림 120×80 은 줄 카드 그림과 같은 그림 자리 */
:where(:root[data-skin="d2min"]) .dp-side-orb { border-radius: 0; border: 1px solid transparent; border-image: var(--sk-slot) 6 fill / 6px stretch; background: #080808; }
:where(:root[data-skin="d2min"]) .dp-side-orb.sq { border-radius: 0; padding: 7px 6px 5px 7px; border-image: var(--sk-slot) 6 / 6px stretch; }
/*   Lv 눈금의 안 찬 칸 = 턱 줄 색 테두리만(건설 랭크 눈금과 같다 · 찬 칸 초록 그대로) · 게이지 = 홈 막대(`.bar` 와 같다) · 레벨 목록 줄 사이 = 홈 줄(건설 랭크 줄과 같다) */
:where(:root[data-skin="d2min"]) .dp-pips i { background: transparent; border-color: rgba(168, 160, 148, .45); }
:where(:root[data-skin="d2min"]) .dp-gauge { background: #050505; border-color: #050505; box-shadow: inset 0 1px 2px rgba(0, 0, 0, .9), 0 1px 0 rgba(255, 255, 255, .04); }
:where(:root[data-skin="d2min"]) .dp-lv { border-bottom-color: #050505; box-shadow: 0 1px 0 rgba(255, 255, 255, .05); }
/*   「이 줄」 재료 그림 = 빈 칸 그림 칸 40 안의 28(재료 칸 그림과 같은 크기) */
:where(:root[data-skin="d2min"]) .dp-tier { grid-template-columns: 40px minmax(0, 1fr) auto; }
:where(:root[data-skin="d2min"]) .dp-tier > img { width: 40px; height: 40px; padding: 6px; background: var(--sk-slot) center / 100% 100% no-repeat, #080808; }

/* 관전 물약 띠의 안 열린 칸 = 창고 빈 칸과 같은 빈 칸 그림 — 띠의 반투명 바닥(`.b-belt .p-slot`)이 칸 그림을 덮었다 ·
   칸째 옅게(.7) 하면 그림의 회색 네모도 흐려져 자물쇠만 옅게 둔다 (ADR-0850) */
:where(:root[data-skin="d2min"]) .b-belt .p-slot.locked { background: var(--sk-slot) center / 100% 100% no-repeat, #080808; opacity: 1; }
:where(:root[data-skin="d2min"]) .b-belt .p-slot.locked .rs-pin-ico { opacity: .7; }
/* 열린 칸은 빈 칸 그림의 **테두리만** 칸 맨 위에 한 겹 — 회색 선이 물약 그림을 덮는다 · 바닥(반투명 · 빨간 반투명)은 그대로 ·
   9-slice 바깥 6px 원본 그대로라 선 굵기가 안 번진다 · 찬 칸의 1px 테두리는 걷는다(겹선) [2026-10-27 사용자 지시 · ADR-0915] */
:where(:root[data-skin="d2min"]) .b-belt .p-slot { position: relative; }
:where(:root[data-skin="d2min"]) .b-belt .p-slot.full { border-color: transparent; }
/* 물약 없이 시작한 빨간 칸도 같은 틀 — 빨간 점선을 걷고 속만 빨갛다 · 바깥 1px 은 찬 칸과 같은 어두운 바닥(빨강이 비치지 않게) (ADR-0920) */
:where(:root[data-skin="d2min"]) .b-belt .p-slot.none { border-style: solid; border-color: rgba(var(--veil-rgb), .85); background-clip: padding-box; }
/*   테두리는 **회색 선까지만** 자른다(위 · 왼 4 · 아래 · 오른 3 — `d2min_slot.webp` 의 선이 그 안쪽 끝이다) — 6 으로 자르면 선 안쪽의 불투명 검은 띠가
     바닥을 가려 빨간 속이 선에서 떨어진 작은 네모로 섰다(왼 · 위 2px · 오른 · 아래 3px 틈) · 이제 바닥(반투명 · 빨강)이 선까지 꽉 찬다 [2026-10-29 사용자 지시 · ADR-0939] */
:where(:root[data-skin="d2min"]) .b-belt .p-slot:not(.locked)::after {
    content: ''; position: absolute; inset: 0; pointer-events: none;
    border-style: solid; border-image: var(--sk-slot) 4 3 3 4 / 4px 3px 3px 4px stretch;
}

/* 전장 — 판에 파인 넓은 홈 · 툴팁 · 창 — 패널과 같은 돌판 + 테두리 */
:where(:root[data-skin="d2min"]) .arena { box-shadow: inset 0 2px 12px rgba(0, 0, 0, .9); }
:where(:root[data-skin="d2min"]) .tooltip,
:where(:root[data-skin="d2min"]) .modal-box { background: var(--sk-fill), #0f0f0f; border-image: var(--sk-frame) 11 / 11px / 3px round; }
/*   아이템 비교 두 장 — 툴팁 상자를 걷고 카드가 상자를 들어(ADR-0337) 위 돌판이 안 먹고 `Now` 의 검정 + 회색 선이 남았다 · 카드마다 한 장 툴팁과 같은 돌판 */
:where(:root[data-skin="d2min"]) .tooltip:has(> .tip-compare > .tip-vs) > .tip-compare > .tip-card { background: var(--sk-fill), #0f0f0f; border-image: var(--sk-frame) 11 / 11px / 3px round; }

/* 출정 창(§4-1) — 선 대신 면 (2026-10-27 사용자 지시 「스테이지 클릭하면 나오는 UI 좀 잘 다듬어줘」 · ADR-0902).
   머리 = **장소 그림 띠** — 창 돌 테두리 안쪽 끝까지 · 바탕은 목록 줄과 같은 그 장소 그림(`--dw-bg` · 왼쪽은 어둡게 흐려진다) ·
   아랫줄 2px 장 색(`--ch` · 스킬 창 판 머리의 판 색 줄과 같은 말) + 그 줄에서 오르는 장 색 기운.
   속 = 가림막 · 세로선 대신 **판 여섯** — 적 구성 · 이야기 / 편성 · 파티 전술 · 물약 + 자동 분해 · 출정 방식이 각자 돌판(판 사이 8)이고
   칸 이름은 판 머리 띠(테두리 안쪽 끝까지 · 편성 탭 판과 같은 띠)다. 격자 · 칸 · 열 맞춤(전술이 이야기와 같은 세로줄)은 그대로다.
   창 여백 19 = 판 테두리 바깥(4) ↔ 창 테두리 안쪽 끝(8) 틈 8 · 판 안 여백 16 = 머리 글자와 판 속 글자가 한 세로줄 */
:where(:root[data-skin="d2min"]) .modal-box.depart-box { --dw-gap: 8px; padding: 7px 19px 19px; gap: 12px; }
:where(:root[data-skin="d2min"]) .modal-box.depart-box > .modal-head {
    margin: 0 -11px; padding: 18px 12px 16px 28px; border-bottom: 2px solid var(--ch, var(--text-accent));
    background:
        linear-gradient(0deg, color-mix(in srgb, var(--ch, transparent) 22%, transparent), transparent 55%),
        linear-gradient(90deg, rgba(12, 12, 12, .97) 0%, rgba(12, 12, 12, .9) 32%, rgba(12, 12, 12, .5) 62%, rgba(12, 12, 12, .2) 100%),
        var(--dw-bg, none) center 69.3% / cover no-repeat,
        var(--sk-chrome), #1a1a1a;
    box-shadow: 0 1px 0 rgba(0, 0, 0, .8);
}
:where(:root[data-skin="d2min"]) .depart-box .dw-title { text-shadow: 0 1px 2px #000, 0 0 6px #000; }
:where(:root[data-skin="d2min"]) .depart-box .dw-title small { color: var(--text-secondary); }
/*   판 여섯 — 격자 틈 8 · 아래 줄 오른쪽 칸(전술 · 물약 · 출정 방식)도 판 사이 8 · 한 줄의 판은 높이가 같다(stretch) */
:where(:root[data-skin="d2min"]) .depart-box .dw-body { gap: 8px; }
:where(:root[data-skin="d2min"]) .depart-box .dw-body > *,
:where(:root[data-skin="d2min"]) .depart-box .dw-body > .dw-c2,
:where(:root[data-skin="d2min"]) .depart-box .dw-body > .dw-r2 { margin: 0; padding: 0; border: 0; }
:where(:root[data-skin="d2min"]) .depart-box .dw-prep,
:where(:root[data-skin="d2min"]) .depart-box .dw-load { gap: 8px; align-items: stretch; }
:where(:root[data-skin="d2min"]) .depart-box .dw-body > .foe-box,
:where(:root[data-skin="d2min"]) .depart-box .dw-body > .dw-story,
:where(:root[data-skin="d2min"]) .depart-box .dw-body > .dw-block,
:where(:root[data-skin="d2min"]) .depart-box .dw-prep .dw-tac,
:where(:root[data-skin="d2min"]) .depart-box .dw-prep .dw-col,
:where(:root[data-skin="d2min"]) .depart-box .dw-prep .fp-side {
    padding: 10px 16px 16px;
    background: var(--sk-fill), #0f0f0f; border: 1px solid var(--border-primary); border-image: var(--sk-frame) 11 / 11px / 4px round; box-shadow: 0 6px 16px rgba(0, 0, 0, .7);
}
/*   전술 판이 아래 줄 오른쪽 칸의 남는 폭을 받는다 · 출정 방식 판 폭 = 옛 내용 폭(17em · 상한 260) + 판 여백 */
:where(:root[data-skin="d2min"]) .depart-box .dw-prep .dw-tac { flex: 1 1 auto; }
:where(:root[data-skin="d2min"]) .depart-box .dw-prep .fp-side { flex: 0 0 calc(clamp(240px, 17em, 260px) + 34px); }
/*   칸 이름 = 판 머리 띠 — 판 테두리 안쪽 끝까지(편성 탭 판의 띠와 같은 자리) · 띠 아래 ↔ 내용 14 */
:where(:root[data-skin="d2min"]) .depart-box .sub-h { margin: -4px -10px 14px; padding: 4px 10px 5px; }
:where(:root[data-skin="d2min"]) .depart-box .fp-side .sub-h { margin-bottom: 4px; }   /* 판 `gap` 10 이 더해져 14 */
:where(:root[data-skin="d2min"]) .depart-box .dw-col { gap: 16px; }
:where(:root[data-skin="d2min"]) .depart-box .dw-story-text { color: #d6d0c6; }
/*   초상 아래 스킬 칸 — 빈 칸 = 빈 칸 그림(관전 카드 스킬 칸과 같다) · 찬 칸은 그림만 */
:where(:root[data-skin="d2min"]) .depart-box .dw-sk-cell { background: #080808; border-color: transparent; }
:where(:root[data-skin="d2min"]) .depart-box .dw-sk-cell.empty { background: var(--sk-slot) center / 100% 100% no-repeat, #080808; border-style: solid; border-color: transparent; }
/*   자동 분해 작은 칸 — 보존 칸 테두리가 홈 색이라 격자가 안 보였다 · 턱 줄 색으로 */
:where(:root[data-skin="d2min"]) .asv-dot { background: #080808; border-color: rgba(168, 160, 148, .38); }
/*   출발 칸의 고른 칸 = 장 색 테두리 */
:where(:root[data-skin="d2min"]) .depart-box .btn.sm.cp-btn.on { border-color: var(--ch, var(--text-accent)); color: #fff; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ch, transparent) 45%, transparent), 0 0 8px color-mix(in srgb, var(--ch, transparent) 35%, transparent); }

/* 원정 목록 — 장 색 (2026-10-27 사용자 지시 「각 챕터별로 UI에 색을 집어넣어 챕터 느낌이 살도록」 · ADR-0902).
   고른 장의 죄종 색(`--ch` · 렌더러가 목록 판에 건다)이 ③ 장소 줄의 왼쪽 면(그림 앞 그라데이션 색) ④ 고른 줄 · 올린 줄 테두리 ⑤ 판 안쪽 위의 옅은 기운에 밴다.
   장소 줄 왼쪽 띠 · 죄종 칩 · 탭 글자는 원래 장 색 그대로. 챕터 탭에는 색을 안 넣는다 — ① 판 위 기운(챕터 탭 뒤) · 글자 번짐은 위에서 비추는 빛으로 읽혀
   탭이 입체로 떠 보였고(ADR-0905), ② 고른 탭 면도 안 고른 탭과 같은 돌 바탕이다(위 「원정 챕터 = 폴더 탭」 묶음 · ADR-0906) */
:where(:root[data-skin="d2min"]) .panel.diff-panel { background: radial-gradient(ellipse 70% 220px at 50% 0, color-mix(in srgb, var(--ch, transparent) 9%, transparent), transparent), var(--surface-0); }
:where(:root[data-skin="d2min"]) .diff-panel .zone {
    --bg-tertiary: color-mix(in srgb, var(--ch, #040404) 8%, #040404);
    --border-highlight: color-mix(in srgb, var(--ch, #707070) 60%, #707070);
}

/* ───────── 겉모양 비교 — 스킨 키트 200 (임시 · 2026-10-27 사용자 지시 · SCREEN_DESIGN §10-5 · ADR-0901 · 200 만 남김 ADR-0970) ─────────
   `Skin` 줄의 번호 버튼이 `<html data-skin="d2min" data-skin-parts="<번호>">` 를 건다 — 키트는 **D2 Min 그림을 재질만 바꿔 다시 그린 것**이라
   부품이 D2 Min 과 같은 다섯 장 · 같은 자리 · 같은 크기다. 그래서 위 「D2 Min」 절이 모든 규칙을 들고, 여기는 부품 변수만 덮는다.
   토큰 덩어리는 `:root` 가 아니라 내용물 상자(메인 · 툴팁 · 창 · 플래시)에 선다 — 변수는 물려받으므로 그 안만 키트 것이 되고
   상단바 · 브랜드 · 왼쪽 탭 열 · `⚙` 판 · 판 사이 바탕은 `:root` 의 D2 Min 값 그대로다(ADR-0866 의 길).
   부품은 `src/assets/art/skins/source/cut_skin_repaints.py` 가 자른 것 · 토큰 덩어리는 그 스크립트 `--css` 가 찍은 것이다.
   걷어낼 때는 이 절 · devcompare.js 의 `KIT_SKINS` · `assets/art/skins/k*_*` · `skins/source/repaint_*` 를 지운다 */
:root[data-skin="d2min"][data-skin-parts="200"] :is(#app > .main, #tooltip, #modal, #toast) {   /* 200 Keep Timber — dark timber frames held by small iron corner brackets */
    --sk-frame: url('../assets/art/skins/k200_frame.webp'); --sk-btn: url('../assets/art/skins/k200_btn.webp'); --sk-slot: url('../assets/art/skins/k200_slot.webp');
    --sk-chrome: url('../assets/art/skins/k200_chrome.webp'); --sk-fill: url('../assets/art/skins/k200_fill.webp'); --sk-lip: rgba(70, 55, 46, .30);
}
